# ========== 统一工具调用执行函数 ==========
def execute_parsed_tool_calls(tool_calls: List, workspace: Path, session_id: str = None) -> Dict:
    """
    执行从统一解析器解析出的工具调用
    
    Args:
        tool_calls: ToolCall 对象列表
        workspace: 工作目录
        session_id: 会话ID
    
    Returns:
        执行结果字典
    """
    from tool_executor import ToolExecutor
    
    executor = ToolExecutor(workspace, safe_mode=True, session_id=session_id)
    results = []
    
    for tc in tool_calls:
        try:
            result = executor.execute(tc.name, tc.arguments)
            results.append({
                'tool': tc.name,
                'arguments': tc.arguments,
                'success': result.get('success', False),
                'output': result.get('output', ''),
                'error': result.get('error', ''),
                'raw_format': getattr(tc, 'raw_format', 'auto')
            })
            logger.info(f"[UnifiedExecutor] 执行工具 {tc.name}: {'成功' if result.get('success') else '失败'}")
        except Exception as e:
            results.append({
                'tool': tc.name,
                'arguments': tc.arguments,
                'success': False,
                'output': '',
                'error': str(e),
                'raw_format': getattr(tc, 'raw_format', 'auto')
            })
            logger.error(f"[UnifiedExecutor] 执行工具 {tc.name} 失败: {e}")
    
    return {
        'executed': [r for r in results if r['success']],
        'failed': [r for r in results if not r['success']],
        'outputs': [r['output'] for r in results if r['success']],
        'errors': [r['error'] for r in results if r['error']]
    }


def parse_model_output_for_tools(output: str, model_name: str = None) -> Dict:
    """
    解析模型输出中的工具调用（用于多轮工具调用场景）
    
    Args:
        output: 模型输出的文本
        model_name: 模型名称（用于选择解析器）
    
    Returns:
        解析结果字典
    """
    parse_result = TOOL_CALL_ROUTER.parse(output, model_name=model_name)
    
    return {
        'has_tool_calls': parse_result.has_tool_calls,
        'tool_calls': parse_result.tool_calls,
        'detected_format': parse_result.detected_format,
        'confidence': parse_result.confidence,
        'raw_text': parse_result.raw_text
    }

