@asynccontextmanager
async def lifespan(app: FastAPI):
    """应用生命周期管理"""
    # MCP: Connect to configured MCP servers
    try:
        from tools.mcp_client import get_mcp_manager
        from tools import refresh_mcp_tools
        _mcp_mgr = get_mcp_manager()
        _mcp_mgr.load_config(WORKSPACE)
        _mcp_errors = await _mcp_mgr.connect_all()
        if _mcp_errors:
            for _srv, _err in _mcp_errors.items():
                logger.warning(f"[MCP] Failed to connect '{_srv}': {_err}")
        refresh_mcp_tools()
        _mcp_tool_count = _mcp_mgr.get_tool_count()
        _mcp_res_count = _mcp_mgr.get_resource_count()
        if _mcp_tool_count or _mcp_res_count:
            logger.info(f"[MCP] Ready: {_mcp_tool_count} tools, {_mcp_res_count} resources from {len(_mcp_mgr.connections)} server(s)")
    except Exception as e:
        logger.warning(f"[MCP] Initialization skipped: {e}")

    # 启动时验证任务配置
    try:
        sys.path.insert(0, str(WORKSPACE))
        from tools.task_config_manager import validate_tasks_on_startup
        result = validate_tasks_on_startup()
        if result.get("fixes"):
            logger.info(f"[启动] 任务配置自动修复: {len(result['fixes'])} 项")
        if result.get("errors"):
            logger.warning(f"[启动] 任务配置问题: {result['errors']}")
    except Exception as e:
        logger.warning(f"[启动] 任务配置验证跳过: {e}")

    try:
        cleanup_result = cleanup_orphaned_tempfiles(WORKSPACE)
        if cleanup_result.get("removed"):
            logger.info(f"[启动] 已清理事务残留文件: {len(cleanup_result['removed'])} 个")
        if cleanup_result.get("failed"):
            logger.warning(f"[启动] 事务残留文件清理失败: {cleanup_result['failed']}")
    except Exception as e:
        logger.warning(f"[启动] 事务残留文件清理跳过: {e}")
    
    # Startup
    asyncio.create_task(run_scheduled_tasks())
    logger.info("[定时任务] 调度器已启动")
    
    # 自动启动任务调度器进程
    await auto_start_task_scheduler()
    
    yield
    # Shutdown: disconnect MCP servers
    try:
        from tools.mcp_client import get_mcp_manager
        await get_mcp_manager().shutdown()
    except Exception as e:
        logger.warning(f"[MCP] Shutdown error: {e}")

