def _build_frontend_tool_result_payload(event: dict[str, Any]) -> dict[str, Any]:
    tool_name = event.get("tool_name") or event.get("name", "unknown")
    success = event.get("success", False)
    output_text = (event.get("content") or event.get("output", ""))[:2000]
    change_set = event.get("change_set")
    if event.get("elapsed_ms") is not None:
        elapsed_ms = round(float(event.get("elapsed_ms") or 0))
    else:
        raw_elapsed = float(event.get("elapsed") or 0)
        elapsed_ms = round(raw_elapsed * 1000)
    return {
        "type": "tool_result",
        "name": tool_name,
        "output": output_text,
        "success": success,
        "elapsed_ms": elapsed_ms,
        "turn": event.get("turn", 0),
        "change_set": change_set,
    }


