def save_stream_state(session_id: str, stream_state: dict) -> None:
    if session_id not in sessions:
        sessions[session_id] = {"history": []}
    sessions[session_id]["stream_state"] = stream_state
    payload = load_session_payload(session_id)
    payload.update({
        "session_id": session_id,
        "stream_state": stream_state,
        "saved_at": datetime.now().isoformat()
    })
    save_session_payload(session_id, payload)


def load_stream_state(session_id: str) -> dict | None:
    if session_id in sessions and sessions[session_id].get("stream_state") is not None:
        return sessions[session_id].get("stream_state")
    payload = load_session_payload(session_id)
    return payload.get("stream_state")


def set_stop_requested(session_id: str, value: bool = True) -> None:
    if session_id not in sessions:
        sessions[session_id] = {"history": []}
    if value:
        sessions[session_id]["stop_requested"] = True
    else:
        sessions[session_id].pop("stop_requested", None)


def is_stop_requested(session_id: str) -> bool:
    return sessions.get(session_id, {}).get("stop_requested", False)


def stop_stream_process(session_id: str) -> bool:
    process = stream_processes.get(session_id)
    stopped_local = False
    if process and process.poll() is None:
        try:
            process.terminate()
            process.wait(timeout=5)
            stopped_local = True
        except Exception:
            try:
                process.kill()
                stopped_local = True
            except Exception:
                pass
    # 尝试终止远程 Ollama
    stopped_remote = kill_remote_ollama()
    logger.info(f"停止结果: local={stopped_local}, remote={stopped_remote}")
    return stopped_local or stopped_remote


def load_cli_history_entries() -> list:
    if not CLI_SESSION_FILE.exists():
        return []
    entries = []
    with CLI_SESSION_FILE.open("r", encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith('{"_type"'):
                continue
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                continue
            if entry.get("role") in {"user", "assistant"}:
                entries.append(entry)
    return entries


def build_history_from_cli(entries: list, keyword: str, max_pairs: int = 1) -> list:
    history = []
    used_indices = set()
    if not keyword:
        return history
    for idx, entry in enumerate(entries):
        content = entry.get("content", "")
        if keyword not in content:
            continue
        if entry.get("role") == "assistant":
            if idx - 1 >= 0 and entries[idx - 1].get("role") == "user":
                used_indices.update({idx - 1, idx})
        else:
            used_indices.add(idx)
            if idx + 1 < len(entries) and entries[idx + 1].get("role") == "assistant":
                used_indices.add(idx + 1)
        if len(used_indices) // 2 >= max_pairs:
            break
    for idx in sorted(used_indices):
        entry = entries[idx]
        history.append({
            "role": entry.get("role"),
            "content": entry.get("content", ""),
            "time": entry.get("timestamp") or datetime.now().isoformat()
        })
    return history


def clone_history_value(value):
    if isinstance(value, dict):
        return {key: clone_history_value(val) for key, val in value.items()}
    if isinstance(value, list):
        return [clone_history_value(item) for item in value]
    return value


def normalize_history_payload(history_payload: list) -> list:
    normalized = []
    for item in history_payload:
        if not isinstance(item, dict):
            continue
        role = item.get("role")
        content = item.get("content")
        if not role or content is None:
            continue
        entry = {
            "role": role,
            "content": content,
            "time": item.get("time") or datetime.now().isoformat()
        }
        attachments = item.get("attachments")
        if attachments:
            entry["attachments"] = attachments
        for key in ("change_sets", "approval_pending", "pending_change_set_ids", "final_answer", "thinking_trace", "elapsed_ms", "llama_stats"):
            if key in item and item.get(key) is not None:
                entry[key] = clone_history_value(item.get(key))
        normalized.append(entry)
    return normalized


def build_attachment_context(attachments: list) -> str:
    if not attachments:
        return ""
    lines = []
    for attachment in attachments:
        if not isinstance(attachment, dict):
            continue
        name = attachment.get("name", "attachment")
        size = attachment.get("size")
        url = attachment.get("url", "")
        content = attachment.get("content")
        meta = f"{name}"
        if size:
            meta += f" ({size} bytes)"
        if url:
            if url.startswith("/uploads/"):
                relative = url[len("/uploads/"):].lstrip("/")
                meta += f" | saved at: {UPLOADS_DIR / relative}"
            else:
                meta += f" | url: {url}"
        lines.append(meta)
        if content:
            lines.append(f"---\n{content[:4000]}\n---")
    return "\n".join(lines)


def sanitize_filename(filename: str) -> str:
    if not filename:
        return "attachment"
    name = os.path.basename(filename)
    cleaned = re.sub(r"[^A-Za-z0-9._-]+", "_", name).strip("._")
    return cleaned or "attachment"


def persist_attachments(attachments: list, session_id: str | None = None) -> list:
    if not attachments:
        return []
    target_dir = UPLOADS_DIR
    if session_id:
        safe_session = sanitize_filename(session_id)
        target_dir = UPLOADS_DIR / safe_session
        target_dir.mkdir(parents=True, exist_ok=True)
    persisted = []
    for attachment in attachments:
        if not isinstance(attachment, dict):
            continue
        item = dict(attachment)
        url = item.get("url") or ""
        data_url = item.get("dataUrl") or ""
        content = item.get("content")
        if url and not url.startswith("blob:"):
            persisted.append(item)
            continue
        saved = False
        if data_url.startswith("data:") and ";base64," in data_url:
            header, encoded = data_url.split(",", 1)
            mime = header.split(";")[0].replace("data:", "")
            original_name = sanitize_filename(item.get("name") or "attachment")
            base_name = Path(original_name).stem or "attachment"
            ext = Path(original_name).suffix
            if not ext:
                ext = mimetypes.guess_extension(mime) or ""
            filename = f"{int(time.time())}_{base_name}{ext}"
            file_path = target_dir / filename
            try:
                with open(file_path, "wb") as handle:
                    handle.write(base64.b64decode(encoded))
                relative_path = file_path.relative_to(UPLOADS_DIR)
                item["url"] = f"/uploads/{relative_path.as_posix()}"
                saved = True
            except Exception as exc:
                logger.error(f"保存附件失败: {exc}")
        if not saved and content:
            original_name = sanitize_filename(item.get("name") or "attachment.txt")
            filename = f"{int(time.time())}_{original_name}"
            file_path = target_dir / filename
            try:
                with open(file_path, "w", encoding="utf-8") as handle:
                    handle.write(content)
                relative_path = file_path.relative_to(UPLOADS_DIR)
                item["url"] = f"/uploads/{relative_path.as_posix()}"
            except Exception as exc:
                logger.error(f"保存文本附件失败: {exc}")
        persisted.append(item)
    return persisted


IMAGE_EXTENSIONS = {".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp"}


def is_image_attachment(attachment: dict) -> bool:
    if not attachment:
        return False
    mime = attachment.get("type") or ""
    if mime.startswith("image/"):
        return True
    data_url = attachment.get("dataUrl") or ""
    if data_url.startswith("data:image/"):
        return True
    url = attachment.get("url") or ""
    ext = Path(url.split("?")[0]).suffix.lower()
    return ext in IMAGE_EXTENSIONS


def resolve_attachment_path(attachment: dict) -> Path | None:
    url = attachment.get("url") or ""
    if url.startswith("/uploads/"):
        relative = url[len("/uploads/"):].lstrip("/")
        return UPLOADS_DIR / relative
    if "/uploads/" in url:
        try:
            suffix = url.split("/uploads/")[-1]
            return UPLOADS_DIR / suffix
        except Exception:
            return None
    return None


def run_vision_helper(image_path: Path, prompt: str) -> str | None:
    try:
        result = subprocess.run(
            [PYTHON, str(WORKSPACE / "vision_helper.py"), str(image_path), prompt],
            capture_output=True,
            text=True,
            timeout=180
        )
        output = (result.stdout or "").strip()
        if output:
            return output
        error = (result.stderr or "").strip()
        return error or None
    except Exception as exc:
        logger.error(f"视觉分析失败: {exc}")
        return None


def build_vision_context(attachments: list, prompt: str) -> str:
    if not attachments:
        return ""
    lines = []
    for attachment in attachments:
        if not is_image_attachment(attachment):
            continue
        image_path = resolve_attachment_path(attachment)
        if not image_path or not image_path.exists():
            continue
        analysis = run_vision_helper(image_path, prompt)
        if not analysis:
            continue
        name = attachment.get("name") or image_path.name
        lines.append(f"[{name}]\n{analysis}")
    return "\n\n".join(lines)


def inject_attachments_into_context(message: str, attachments: list) -> str:
    attachment_context = build_attachment_context(attachments)
    if not attachment_context:
        return message
    return f"{message}\n\n[Attachments]\n{attachment_context}"


def finalize_session(session_id: str, message: str, response: str, history: list, full_response: list, line_count: int, attachments: list | None = None,
                     final_answer: dict | None = None, approval_pending: bool = False,
                     pending_change_set_ids: list | None = None) -> None:
    entry = {"role": "user", "content": message, "time": datetime.now().isoformat()}
    if attachments:
        entry["attachments"] = attachments
    history.append(entry)
    transcript_markdown = "\n".join(full_response).strip() if full_response else ""
    assistant_entry = {"role": "assistant", "content": response, "time": datetime.now().isoformat()}
    if final_answer:
        assistant_entry["final_answer"] = clone_history_value(final_answer)
    if transcript_markdown:
        assistant_entry["agentic_transcript"] = transcript_markdown
        assistant_entry["full_response_markdown"] = transcript_markdown
    pending_ids = [item for item in (pending_change_set_ids or []) if item]
    if approval_pending or pending_ids:
        pending_change_sets = list_pending_change_sets(session_id=session_id)
        if pending_ids:
            pending_id_set = set(pending_ids)
            pending_change_sets = [item for item in pending_change_sets if item.get("id") in pending_id_set]
        if pending_change_sets:
            assistant_entry["change_sets"] = clone_history_value(pending_change_sets)
            assistant_entry["pending_change_set_ids"] = [item.get("id") for item in pending_change_sets if item.get("id")]
            assistant_entry["approval_pending"] = True
        elif pending_ids:
            assistant_entry["pending_change_set_ids"] = pending_ids
            assistant_entry["approval_pending"] = True
    history.append(assistant_entry)
    save_session_history(session_id, history)
    if len(history) > 50:
        sessions[session_id]["history"] = history[-50:]
    logger.info(
        "[ApprovalDiag] finalize_session session=%s assistant_len=%s history_len=%s assistant_keys=%s",
        session_id,
        len(response or ""),
        len(history),
        sorted(assistant_entry.keys()),
    )
    log_resources(f"完成处理 session={session_id}, lines={line_count}")
    logger.info(f"流式处理完成: session={session_id}, 输出行数={line_count}")
    log_to_reflection("assistant", '\n'.join(full_response))


async def finalize_after_disconnect(process, session_id: str, message: str, full_message: str,
                                    history: list, full_output: list, full_response: list, line_count: int,
                                    attachments: list | None = None) -> None:
    try:
        if is_stop_requested(session_id):
            if process and process.poll() is None:
                try:
                    process.terminate()
                    process.wait(timeout=5)
                except Exception:
                    try:
                        process.kill()
                    except Exception:
                        pass
            # 终止远程 Ollama
            kill_remote_ollama()
            save_stream_state(session_id, {
                "task_id": f"stream_{session_id}_{int(time.time())}",
                "status": "stopped",
                "content": "\n".join(full_response),
                "last_update": datetime.now().isoformat(),
                "lines": line_count
            })
            return
        stdout = ""
        if process:
            try:
                stdout, _ = process.communicate(timeout=1800)
            except Exception:
                try:
                    stdout = process.stdout.read() if process.stdout else ""
                except Exception:
                    stdout = ""
        if stdout:
            for line in stdout.split('\n'):
                if line.strip():
                    clean_line = clean_ansi(line)
                    full_output.append(clean_line)
                    full_response.append(clean_line)
        output_text = '\n'.join(full_output)
        response = extract_response(output_text, full_message)
        finalize_session(session_id, message, response, history, full_response, line_count, attachments)
        save_stream_state(session_id, {
            "task_id": f"stream_{session_id}_{int(time.time())}",
            "status": "done",
            "content": response,
            "last_update": datetime.now().isoformat(),
            "lines": line_count
        })
    except Exception as exc:
        logger.error(f"断开后完成处理失败: session={session_id}, error={exc}")

