def validate_message(message: str) -> bool:
    """验证消息内容安全 - 完全禁用长度检查"""
    # 只检查危险控制字符，允许任意长度
    dangerous_chars = re.compile(r'[\x00-\x08\x0b\x0c\x0e-\x1f]')
    return not dangerous_chars.search(message)

