from server_state import clean_ansi


def _resolve_stream_model(env: dict[str, str]) -> str:
    """Resolve model used by direct LiteLLM streaming path."""
    model = env.get("NANOBOT_AGENTS__DEFAULTS__MODEL")
    if model:
        return model
    try:
        config_path = Path.home() / ".nanobot" / "config.json"
        if config_path.exists():
            data = json.loads(config_path.read_text(encoding="utf-8"))
            configured = data.get("agents", {}).get("defaults", {}).get("model")
            if configured:
                return configured
    except Exception as e:
        logger.warning(f"[StreamModel] 读取默认模型失败: {e}")
    return "openai/qwen3.5:35b"


async def stream_llm_tokens(
    message_text: str,
    env: dict[str, str],
    stream_stats: dict[str, Any] | None = None,
) -> AsyncGenerator[str, None]:
    """Yield token deltas from LiteLLM stream=True."""
    try:
        from litellm import acompletion
    except ModuleNotFoundError:
        py_ver = f"python{sys.version_info.major}.{sys.version_info.minor}"
        venv_site = VENV / "lib" / py_ver / "site-packages"
        if venv_site.exists() and str(venv_site) not in sys.path:
            sys.path.insert(0, str(venv_site))
        from litellm import acompletion

    model = _resolve_stream_model(env)
    max_tokens = int(env.get("NANOBOT_AGENTS__DEFAULTS__MAX_TOKENS", "16384"))
    temperature = float(env.get("NANOBOT_AGENTS__DEFAULTS__TEMPERATURE", "0.7"))

    api_key = env.get("OPENAI_API_KEY")
    api_base = env.get("OPENAI_API_BASE")
    if not api_key or not api_base:
        try:
            config_path = Path.home() / ".nanobot" / "config.json"
            if config_path.exists():
                cfg = json.loads(config_path.read_text(encoding="utf-8"))
                provider_name = model.split("/", 1)[0] if "/" in model else model
                if provider_name == "ollama_chat":
                    provider_name = "ollama"
                provider_cfg = cfg.get("providers", {}).get(provider_name, {})
                if not api_key:
                    api_key = provider_cfg.get("apiKey")
                if not api_base:
                    api_base = provider_cfg.get("apiBase")
        except Exception as e:
            logger.warning(f"[TokenStream] 读取 provider 配置失败: {e}")

    kwargs: dict[str, Any] = {
        "model": model,
        "messages": [{"role": "user", "content": message_text}],
        "max_tokens": max(1, max_tokens),
        "temperature": temperature,
        "stream": True,
        "stream_options": {"include_usage": True},
    }

    timeout = env.get("REQUEST_TIMEOUT")
    if timeout:
        kwargs["timeout"] = float(timeout)

    if api_key:
        kwargs["api_key"] = api_key
    if api_base:
        kwargs["api_base"] = api_base

    model_lower = model.lower()
    if "ollama" in model_lower or "ollama_chat" in model_lower:
        kwargs["num_ctx"] = int(env.get("OLLAMA_NUM_CTX", "8192"))
        kwargs["keep_alive"] = "60m"

    stream = await acompletion(**kwargs)
    async for chunk in stream:
        delta_text = None
        usage_obj = None

        if isinstance(chunk, dict):
            choices = chunk.get("choices") or []
            usage_obj = chunk.get("usage")
            if choices:
                delta = choices[0].get("delta") or {}
                delta_text = delta.get("content")
        else:
            choices = getattr(chunk, "choices", None) or []
            usage_obj = getattr(chunk, "usage", None)
            if choices:
                delta_obj = getattr(choices[0], "delta", None)
                if isinstance(delta_obj, dict):
                    delta_text = delta_obj.get("content")
                elif delta_obj is not None:
                    delta_text = getattr(delta_obj, "content", None)

        if usage_obj is not None and stream_stats is not None:
            if isinstance(usage_obj, dict):
                prompt_tokens = usage_obj.get("prompt_tokens")
                completion_tokens = usage_obj.get("completion_tokens")
                total_tokens = usage_obj.get("total_tokens")
            else:
                prompt_tokens = getattr(usage_obj, "prompt_tokens", None)
                completion_tokens = getattr(usage_obj, "completion_tokens", None)
                total_tokens = getattr(usage_obj, "total_tokens", None)

            if prompt_tokens is not None:
                stream_stats["prompt_tokens"] = int(prompt_tokens)
            if completion_tokens is not None:
                stream_stats["completion_tokens"] = int(completion_tokens)
            if total_tokens is not None:
                stream_stats["total_tokens"] = int(total_tokens)

        if delta_text:
            yield clean_ansi(delta_text)


# 导入高级HTML净化器（优先bleach，回退正则）
try:
    from html_sanitizer import sanitize_html_advanced, get_sanitizer
    ADVANCED_SANITIZER_AVAILABLE = True
except ImportError as e:
    ADVANCED_SANITIZER_AVAILABLE = False
    print(f"⚠️ 高级净化器不可用: {e}")


def sanitize_html_content(content: str) -> str:
    """
    净化HTML内容，防止XSS攻击
    优先使用高级净化器（bleach），否则回退到正则
    """
    if not content:
        return content
    
    # 尝试使用高级净化器
    if ADVANCED_SANITIZER_AVAILABLE:
        try:
            return sanitize_html_advanced(content, use_bleach=True)
        except Exception as e:
            logger.error(f"高级净化器失败: {e}")
    
    # 回退到内置正则净化（保留原有实现）
    return _sanitize_html_content_regex(content)


def _sanitize_html_content_regex(content: str) -> str:
    """内置正则净化（作为回退）"""
    if not content:
        return content
    
    sanitized = content
    
    # 1. 移除危险标签
    dangerous_tags = [
        (r'<object[^>]*>.*?</object>', ''),
        (r'<embed[^>]*>.*?</embed>', ''),
        (r'<iframe[^>]*>.*?</iframe>', ''),
        (r'<script[^>]*>.*?</script>', ''),
        (r'<form[^>]*>.*?</form>', ''),
        (r'<input[^>]*>', ''),
        (r'<button[^>]*>.*?</button>', ''),
        (r'<textarea[^>]*>.*?</textarea>', ''),
        (r'<select[^>]*>.*?</select>', ''),
        (r'<applet[^>]*>.*?</applet>', ''),
        (r'<link[^>]*>', ''),
        (r'<meta[^>]*>', ''),
        (r'<base[^>]*>', ''),
    ]
    
    for pattern, replacement in dangerous_tags:
        sanitized = re.sub(pattern, replacement, sanitized, 
                         flags=re.IGNORECASE | re.DOTALL)
    
    # 2. 移除CSS表达式 (IE XSS向量)
    sanitized = re.sub(
        r'expression\s*\([^)]*\)', 
        '[removed]', 
        sanitized, 
        flags=re.IGNORECASE
    )
    
    # 3. 移除javascript: 协议
    sanitized = re.sub(
        r'javascript:\s*[^\s"\']*',
        'blocked:',
        sanitized,
        flags=re.IGNORECASE
    )
    
    # 3.5 移除 url(javascript:...) - CSS中的XSS向量
    sanitized = re.sub(
        r'url\s*\(\s*["\']?javascript:[^\)]+\)',
        'url(blocked:)',
        sanitized,
        flags=re.IGNORECASE
    )
    
    # 4. 移除data:text/html 和 data:image/svg
    sanitized = re.sub(
        r'data:(?:text/html|image/svg)[^\s"\']*',
        'blocked:',
        sanitized,
        flags=re.IGNORECASE
    )
    
    # 5. 移除vbscript: 协议
    sanitized = re.sub(
        r'vbscript:\s*[^\s"\']*',
        'blocked:',
        sanitized,
        flags=re.IGNORECASE
    )
    
    # 6. 移除事件处理器
    sanitized = re.sub(
        r'\s+on\w+\s*=\s*["\'][^"\']*["\']',
        '',
        sanitized,
        flags=re.IGNORECASE
    )
    
    # 7. 移除危险属性 (srcdoc, action等)
    sanitized = re.sub(
        r'\s+(srcdoc|action)\s*=\s*["\'][^"\']*["\']',
        '',
        sanitized,
        flags=re.IGNORECASE
    )
    
    # 8. HTML实体转义
    html_escapes = {
        '&': '&amp;',
        '<': '&lt;',
        '>': '&gt;',
        '"': '&quot;',
        "'": '&#x27;',
    }
    
    for char, entity in html_escapes.items():
        sanitized = sanitized.replace(char, entity)
    
    return sanitized


def extract_response(output: str, message: str) -> str:
    """从 agent 输出中提取响应内容，保留完整 Markdown 结构。
    
    设计原则（对齐 llama.cpp 原生输出）：
    1. 保留空行 — 空行是 Markdown 段落/代码块分隔的关键
    2. 不做行级去重 — 代码中重复行（如 }, return）是合法的
    3. 只过滤 nanobot CLI 的 UI 装饰（logo/提示），不过滤模型内容
    4. 保留 <thinking> 标签内容的过滤（这是前端渲染负责的）
    """
    lines = output.split('\n')
    response_lines = []
    in_thinking = False
    skip_header = True  # 跳过 nanobot CLI 的前导装饰行
    
    for raw_line in lines:
        stripped = raw_line.strip()
        
        # 跳过 nanobot CLI 装饰行（仅在输出开头）
        if skip_header:
            if not stripped:
                continue
            # nanobot CLI logo 和交互提示
            if '🐈' in stripped:
                continue
            if 'Interactive mode' in stripped or 'type exit' in stripped.lower():
                continue
            # 一旦遇到第一行实际内容，停止跳过
            skip_header = False
        
        # 终止标记
        if stripped.startswith('You:') or stripped == 'Goodbye!':
            break
        
        # 过滤 <thinking>...</thinking> 块（可能跨多行）
        if '<thinking>' in stripped:
            in_thinking = True
        if in_thinking:
            if '</thinking>' in stripped:
                in_thinking = False
            continue
        
        # 保留所有行（包括空行 — Markdown 段落分隔需要）
        response_lines.append(raw_line)
    
    # 移除首尾空行，但保留内部空行
    result = '\n'.join(response_lines)
    result = result.strip()
    return result if result else output.strip()

