@app.get("/static/artifacts/{filename:path}")
async def get_artifact(filename: str):
    """获取artifacts文件，处理旧会话引用"""
    from fastapi.responses import Response
    from urllib.parse import unquote
    import base64
    
    # URL解码文件名
    decoded_name = unquote(filename)
    
    # 直接使用解码后的文件名查找
    artifact_path = ARTIFACTS_DIR / decoded_name
    
    if artifact_path.exists():
        return FileResponse(artifact_path)
    
    # 尝试查找相似文件（忽略空格差异）
    import glob
    # 替换空格为通配符查找
    pattern = str(ARTIFACTS_DIR / decoded_name.replace(" ", "*"))
    matches = glob.glob(pattern)
    if matches:
        return FileResponse(matches[0])
    
    # 如果文件不存在，返回透明占位图（避免404错误）
    if decoded_name.endswith('.svg') or filename.endswith('.svg'):
        return HTMLResponse(content='<svg xmlns="http://www.w3.org/2000/svg" width="1" height="1"/>', media_type="image/svg+xml")
    elif decoded_name.endswith(('.png', '.jpg', '.jpeg', '.gif')) or filename.endswith(('.png', '.jpg', '.jpeg', '.gif')):
        transparent_pixel = base64.b64decode('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==')
        return Response(content=transparent_pixel, media_type="image/png")
    
    # 其他类型文件返回空响应
    return Response(content=b'', status_code=204)

