_METRICS_AUTH_FAILURES = 0
_METRICS_AUTH_LOCK = __import__('threading').Lock()

# Register auth-metrics callbacks so tools/shell_execute.py can snapshot
# auth_failures without importing server_final (avoids circular import).
try:
    from tools.shell_execute import register_auth_metrics_callbacks

    def _get_auth_failures():
        with _METRICS_AUTH_LOCK:
            return _METRICS_AUTH_FAILURES

    def _set_auth_failures(val):
        global _METRICS_AUTH_FAILURES
        with _METRICS_AUTH_LOCK:
            _METRICS_AUTH_FAILURES = val

    register_auth_metrics_callbacks(_get_auth_failures, _set_auth_failures)
except Exception:
    pass


def _sanitize_ip(ip: str) -> str:
    """Sanitize IP for logging per NANOBOT_METRICS_LOG_IP policy (full/prefix/hash/none)."""
    policy = os.environ.get("NANOBOT_METRICS_LOG_IP", "hash").lower()
    if policy == "none":
        return "[redacted]"
    if policy == "hash":
        return "ip_" + hmac.new(b"nanobot-ip-salt", ip.encode(), "sha256").hexdigest()[:12]
    if policy == "prefix" and "." in ip:
        parts = ip.split(".")
        return f"{parts[0]}.{parts[1]}.*.*"
    if policy == "prefix" and ":" in ip:
        return ip.rsplit(":", 4)[0] + "::*"
    return ip


def _validate_metrics_token(auth_header: str) -> bool:
    """Check Bearer token against NANOBOT_METRICS_TOKEN (supports comma-separated multi-token)."""
    raw = os.environ.get("NANOBOT_METRICS_TOKEN", "")
    if not raw:
        return False
    if not auth_header.startswith("Bearer "):
        return False
    provided = auth_header[7:]
    for tok in raw.split(","):
        tok = tok.strip()
        if tok and hmac.compare_digest(provided, tok):
            return True
    return False


def _record_auth_failure() -> None:
    """Thread-safe increment of metrics auth failure counter."""
    global _METRICS_AUTH_FAILURES
    with _METRICS_AUTH_LOCK:
        _METRICS_AUTH_FAILURES += 1


# Emit startup warning if metrics token is not configured
if not os.environ.get("NANOBOT_METRICS_TOKEN", ""):
    logging.getLogger("nanobot.metrics").warning(
        "[Metrics] NANOBOT_METRICS_TOKEN not set — /api/metrics endpoint is DISABLED. "
        "Set this env var to enable Prometheus scraping."
    )


@app.get("/api/metrics")
async def prometheus_metrics(request: Request):
    """Expose security and lock metrics in Prometheus text exposition format.

    Requires Bearer token set via NANOBOT_METRICS_TOKEN env var (comma-separated for rotation).
    If the env var is unset, the endpoint is disabled (403).
    Prometheus scrape_configs example::

        - job_name: 'nanobot'
          bearer_token: '<your-token>'
          static_configs:
            - targets: ['localhost:8080']
          metrics_path: '/api/metrics'
    """
    if not os.environ.get("NANOBOT_METRICS_TOKEN", ""):
        return Response(content="metrics endpoint disabled: set NANOBOT_METRICS_TOKEN", status_code=403)
    if not _validate_metrics_token(request.headers.get("authorization", "")):
        _record_auth_failure()
        _client = _sanitize_ip(request.client.host if request.client else "unknown")
        logging.getLogger("nanobot.metrics").warning(
            "[Metrics] auth failure from %s (total=%d)", _client, _METRICS_AUTH_FAILURES
        )
        return Response(content="unauthorized", status_code=401)
    from task_store import get_lock_metrics
    from sandbox_executor import get_security_metrics
    from tools.shell_execute import get_shell_metrics
    lm = get_lock_metrics()
    sm = get_security_metrics()
    em = get_shell_metrics()
    lines = [
        "# HELP nanobot_lock_successes Total successful task_store lock acquisitions.",
        "# TYPE nanobot_lock_successes counter",
        f"nanobot_lock_successes {lm.get('lock_successes', 0)}",
        "# HELP nanobot_lock_retries Total task_store lock retry attempts.",
        "# TYPE nanobot_lock_retries counter",
        f"nanobot_lock_retries {lm.get('lock_retries', 0)}",
        "# HELP nanobot_lock_failures Total task_store lock failures.",
        "# TYPE nanobot_lock_failures counter",
        f"nanobot_lock_failures {lm.get('lock_failures', 0)}",
        "# HELP nanobot_seccomp_successes Total successful seccomp verifications.",
        "# TYPE nanobot_seccomp_successes counter",
        f"nanobot_seccomp_successes {sm.get('seccomp_successes', 0)}",
        "# HELP nanobot_seccomp_retries Total seccomp verification retry attempts.",
        "# TYPE nanobot_seccomp_retries counter",
        f"nanobot_seccomp_retries {sm.get('seccomp_retries', 0)}",
        "# HELP nanobot_seccomp_permanent_failures Total permanent seccomp failures.",
        "# TYPE nanobot_seccomp_permanent_failures counter",
        f"nanobot_seccomp_permanent_failures {sm.get('seccomp_permanent_failures', 0)}",
        "# HELP nanobot_seccomp_transient_failures Total transient seccomp failures.",
        "# TYPE nanobot_seccomp_transient_failures counter",
        f"nanobot_seccomp_transient_failures {sm.get('seccomp_transient_failures', 0)}",
        "# HELP nanobot_shell_total Total shell_execute invocations.",
        "# TYPE nanobot_shell_total counter",
        f"nanobot_shell_total {em.get('shell_total', 0)}",
        "# HELP nanobot_shell_errors Total shell_execute error results.",
        "# TYPE nanobot_shell_errors counter",
        f"nanobot_shell_errors {em.get('shell_errors', 0)}",
        "# HELP nanobot_shell_blocked Total shell_execute blocked commands.",
        "# TYPE nanobot_shell_blocked counter",
        f"nanobot_shell_blocked {em.get('shell_blocked', 0)}",
        "# HELP nanobot_shell_latency_ms Shell command execution latency in milliseconds.",
        "# TYPE nanobot_shell_latency_ms histogram",
    ]
    # Histogram buckets — cumulative counts
    buckets = em.get("shell_latency_ms_buckets", [])
    _cumulative = 0
    for bound, count in buckets:
        _cumulative += count
        lines.append(f'nanobot_shell_latency_ms_bucket{{le="{bound}"}} {_cumulative}')
    lines.append(f'nanobot_shell_latency_ms_bucket{{le="+Inf"}} {em.get("shell_latency_ms_count", 0)}')
    lines.append(f'nanobot_shell_latency_ms_sum {em.get("shell_latency_ms_sum", 0):.1f}')
    lines.append(f'nanobot_shell_latency_ms_count {em.get("shell_latency_ms_count", 0)}')
    lines.append("# HELP nanobot_metrics_auth_failures_total Total failed /metrics auth attempts.")
    lines.append("# TYPE nanobot_metrics_auth_failures_total counter")
    with _METRICS_AUTH_LOCK:
        lines.append(f"nanobot_metrics_auth_failures_total {_METRICS_AUTH_FAILURES}")
    from tools.shell_execute import _SNAPSHOT_FAILURES, _PROCESS_START_TIME
    lines.append("# HELP nanobot_snapshot_failures_total Total metrics snapshot write failures.")
    lines.append("# TYPE nanobot_snapshot_failures_total counter")
    lines.append(f"nanobot_snapshot_failures_total {_SNAPSHOT_FAILURES}")
    lines.append("# HELP nanobot_process_start_timestamp Unix timestamp when the process started.")
    lines.append("# TYPE nanobot_process_start_timestamp gauge")
    lines.append(f"nanobot_process_start_timestamp {_PROCESS_START_TIME:.0f}")
    # Mailbox observability counters
    try:
        from services.agent_mailbox import get_mailbox
        _mb_stats = get_mailbox().get_stats()
        lines.append("# HELP nanobot_mailbox_sent_total Total messages sent to agent mailboxes.")
        lines.append("# TYPE nanobot_mailbox_sent_total counter")
        lines.append(f"nanobot_mailbox_sent_total {_mb_stats['sent_total']}")
        lines.append("# HELP nanobot_mailbox_delivered_total Total messages delivered (ACK'd) from agent mailboxes.")
        lines.append("# TYPE nanobot_mailbox_delivered_total counter")
        lines.append(f"nanobot_mailbox_delivered_total {_mb_stats['delivered_total']}")
        lines.append("# HELP nanobot_mailbox_discarded_total Total messages discarded due to inbox overflow.")
        lines.append("# TYPE nanobot_mailbox_discarded_total counter")
        lines.append(f"nanobot_mailbox_discarded_total {_mb_stats['discarded_total']}")
        lines.append("# HELP nanobot_mailbox_pending Current number of pending mailbox messages.")
        lines.append("# TYPE nanobot_mailbox_pending gauge")
        lines.append(f"nanobot_mailbox_pending {_mb_stats['pending']}")
        lines.append("# HELP nanobot_mailbox_recovery_loops Total save-failure recovery restore attempts.")
        lines.append("# TYPE nanobot_mailbox_recovery_loops counter")
        lines.append(f"nanobot_mailbox_recovery_loops {_mb_stats.get('recovery_loops', 0)}")
        lines.append("# HELP nanobot_mailbox_dead_letters_total Total dead-letter notifications sent.")
        lines.append("# TYPE nanobot_mailbox_dead_letters_total counter")
        lines.append(f"nanobot_mailbox_dead_letters_total {_mb_stats.get('dead_letters_total', 0)}")
        lines.append("# HELP nanobot_mailbox_failed_deliveries_dropped Failed-delivery records lost to FIFO cap.")
        lines.append("# TYPE nanobot_mailbox_failed_deliveries_dropped counter")
        lines.append(f"nanobot_mailbox_failed_deliveries_dropped {_mb_stats.get('failed_deliveries_dropped', 0)}")
        lines.append("# HELP nanobot_mailbox_delivery_failures_queried Times agents queried their delivery failures.")
        lines.append("# TYPE nanobot_mailbox_delivery_failures_queried counter")
        lines.append(f"nanobot_mailbox_delivery_failures_queried {_mb_stats.get('delivery_failures_queried', 0)}")
        lines.append("# HELP nanobot_mailbox_snapshot_slow_count Snapshots exceeding latency threshold.")
        lines.append("# TYPE nanobot_mailbox_snapshot_slow_count counter")
        lines.append(f"nanobot_mailbox_snapshot_slow_count {_mb_stats.get('snapshot_slow_count', 0)}")
    except Exception:
        pass  # mailbox not initialized yet — skip silently
    # CTO-audit: Hint re-read observability counter (context prompt effectiveness)
    try:
        from agentic_loop import _HINT_REREAD_COUNT
        lines.append("# HELP nanobot_hint_reread_count Cumulative file re-reads of already-hinted paths in current session.")
        lines.append("# TYPE nanobot_hint_reread_count gauge")
        lines.append(f"nanobot_hint_reread_count {_HINT_REREAD_COUNT}")
    except Exception:
        pass
    # CW1: Token-weighted microcompact eviction observability
    try:
        from agentic_loop import _CW1_EVICTIONS_TOTAL, _CW1_TOKENS_FREED_TOTAL
        lines.append("# HELP nanobot_cw1_evictions_total Cumulative tool results evicted by CW1 token-weighted microcompact.")
        lines.append("# TYPE nanobot_cw1_evictions_total counter")
        lines.append(f"nanobot_cw1_evictions_total {_CW1_EVICTIONS_TOTAL}")
        lines.append("# HELP nanobot_cw1_tokens_freed_total Estimated tokens freed by CW1 evictions.")
        lines.append("# TYPE nanobot_cw1_tokens_freed_total counter")
        lines.append(f"nanobot_cw1_tokens_freed_total {_CW1_TOKENS_FREED_TOTAL}")
    except Exception:
        pass
    # CW2: Pre-flight token guard observability (split: normal vs fallback)
    try:
        from compact_engine import _CW2_NORMAL_TRIMS_TOTAL, _CW2_FALLBACK_TRIMS_TOTAL
        lines.append("# HELP nanobot_cw2_normal_trims_total CW2 normal 30% batch truncation events.")
        lines.append("# TYPE nanobot_cw2_normal_trims_total counter")
        lines.append(f"nanobot_cw2_normal_trims_total {_CW2_NORMAL_TRIMS_TOTAL}")
        lines.append("# HELP nanobot_cw2_fallback_trims_total CW2 emergency fallback truncation events.")
        lines.append("# TYPE nanobot_cw2_fallback_trims_total counter")
        lines.append(f"nanobot_cw2_fallback_trims_total {_CW2_FALLBACK_TRIMS_TOTAL}")
    except Exception:
        pass
    lines.append("")
    return Response(content="\n".join(lines), media_type="text/plain; version=0.0.4; charset=utf-8")


