# 嵌入缓存
EMBEDDING_CACHE = {}  # {hash: embedding}
RESPONSE_CACHE = {}   # {hash: response}

# 质量评分系统
from quality_scorer import QualityScorer, QualityScore
QUALITY_SCORER = QualityScorer(WORKSPACE)

# 自动改进系统
