def get_cache_key(message: str) -> str:
    """生成缓存键"""
    import hashlib
    return hashlib.md5(message.encode()).hexdigest()[:16]

@app.post("/api/chat/snn/a/stream")
async def chat_snn_a_stream(request: Request):
    """深度脉冲A流式输出"""
    data = await request.json()
    message = data.get("message", "").strip()
    session_id = data.get("session_id", "snn_a_default")
    
    if not message:
        raise HTTPException(400, "Message is required")
    
    if _snn_mod.SNN_PROCESSOR is None:
        init_snn_processor()
    
    if not _snn_mod.SNN_ENABLED or _snn_mod.SNN_PROCESSOR is None:
        async def error_stream():
            yield f"data: {json.dumps({'error': 'SNN系统未就绪'})}\n\n"
        return StreamingResponse(error_stream(), media_type="text/event-stream")
    
    # 检查缓存
    cache_key = get_cache_key(message)
    if cache_key in RESPONSE_CACHE:
        cached = RESPONSE_CACHE[cache_key]
        async def cached_stream():
            yield f"data: {json.dumps({'type': 'cached', 'response': cached['response'], 'snn_stats': cached['stats']})}\n\n"
            yield "data: [DONE]\n\n"
        return StreamingResponse(cached_stream(), media_type="text/event-stream")
    
    async def generate_stream():
        try:
            import time
            start_time = time.time()
            
            # 真实工具列表
            REAL_TOOLS = """
## 🔧 真实可用工具列表

你是一个SNN-LLM混合架构系统，你可以调用以下**真实工具**：

⚠️ **重要规则**：
- 你**必须**通过文本描述请求执行工具，系统会自动检测并执行
- **禁止**直接调用 web_fetch、curl 或其他外部工具
- 所有敏感操作（网络访问、文件读写、命令执行）都需要用户审批
- 当需要执行敏感操作时，系统会弹窗请求用户授权

可用工具：

1. **shell_execute** - 执行Shell命令
   - 用法: "执行命令: ls -la" 或 "运行: pwd"
   - 安全限制: 禁止rm -rf, mkfs等危险命令
   - ⚠️ 需要用户授权

2. **file_read** - 读取文件内容
   - 用法: "读取文件 config.json" 或 "查看 README.md"
   - ⚠️ 需要用户授权
   
3. **file_write** - 写入文件
   - 用法: "写入文件 test.txt，内容: hello"
   - ⚠️ 需要用户授权
   
4. **file_list** - 列出目录内容
   - 用法: "查看当前目录" 或 "列出 files 文件夹"
   
5. **http_request** - 发送HTTP请求
   - 用法: "获取网页 https://example.com"
   - 安全限制: 禁止访问内网地址
   - ⚠️ 需要用户授权
   
6. **code_execute** - 执行Python代码
   - 用法: "计算 2+2" 或 "运行代码: print('hello')"
   - 安全限制: 禁止os.system, subprocess等
   - ⚠️ 需要用户授权

**权限审批流程**：
当用户请求涉及敏感操作时，系统会：
1. 弹窗通知用户，显示操作详情
2. 等待用户选择：拒绝/本次允许/会话允许/始终允许
3. 根据用户决策执行或拒绝操作

请用自然语言描述你想执行的操作，不要尝试直接调用工具函数。
"""
            
            # SNN预处理 - 添加异常保护
            try:
                enhanced_message = REAL_TOOLS + "\n\n用户问题: " + message
                result = _snn_mod.SNN_PROCESSOR.process(enhanced_message, verbose=False, apply_feedback=False)
                
                snn_stats = {
                    "enabled": True,
                    "spikes": int(result.snn_spikes),
                    "attention": float(result.attention_score),
                    "semantic_shift": float(result.semantic_shift),
                    "processing_time": time.time() - start_time
                }
            except Exception as e:
                logger.error(f"SNN预处理失败: {e}", exc_info=True)
                # 使用默认统计
                snn_stats = {
                    "enabled": True,
                    "spikes": 0,
                    "attention": 0.5,
                    "semantic_shift": 0.0,
                    "processing_time": time.time() - start_time,
                    "error": str(e)
                }
                # 创建默认结果对象
                class DefaultResult:
                    def __init__(self):
                        self.snn_spikes = 0
                        self.attention_score = 0.5
                        self.semantic_shift = 0.0
                        self.decoded_embedding = None
                result = DefaultResult()
            
            # 发送SNN统计
            yield f"data: {json.dumps({'type': 'snn_stats', 'stats': snn_stats})}\n\n"
            
            # 工具执行（传递session_id用于权限管理）
            from tool_executor import analyze_and_execute_tools
            tool_result = analyze_and_execute_tools(
                message=message,
                snn_result=result,
                workspace=WORKSPACE,
                safe_mode=True,
                session_id=session_id
            )
            
            tools_used = tool_result['tools_executed']
            tool_outputs = tool_result['tool_outputs']
            
            # 日志记录工具执行
            if tools_used:
                logger.info(f"🔧 工具执行: {tools_used}")
                for output in tool_outputs:
                    logger.info(f"   输出: {output[:200]}...")
            
            # 发送工具执行状态
            if tools_used:
                yield f"data: {json.dumps({'type': 'tools', 'tools': tools_used, 'outputs': tool_outputs})}\n\n"
            
            # 流式生成响应
            llm = _snn_mod.SNN_PROCESSOR.llm
            
            try:
                # 获取改进建议（从历史问题中学习）
                improvement_hints = ""
                improver = get_auto_improver()
                if improver:
                    improvement_hints = improver.get_recent_hints(limit=3)
                
                # 构建prompt（包含工具结果和改进建议）
                if tools_used:
                    tool_context = "\n\n".join([
                        f"[工具执行结果]\n{output}" 
                        for output in tool_outputs
                    ])
                    prompt = _snn_mod.SNN_PROCESSOR._build_enhanced_prompt(
                        f"{message}\n\n{tool_context}\n\n请基于工具执行结果回答。", 
                        result.snn_spikes, result.attention_score, 
                        result.semantic_shift, result.decoded_embedding,
                        improvement_hints
                    )
                else:
                    prompt = _snn_mod.SNN_PROCESSOR._build_enhanced_prompt(
                        message, result.snn_spikes, result.attention_score, 
                        result.semantic_shift, result.decoded_embedding,
                        improvement_hints
                    )
                
                full_response = []
                stream_gen = llm.generate(prompt, stream=True)
                
                for chunk in stream_gen:
                    full_response.append(chunk)
                    yield f"data: {json.dumps({'type': 'chunk', 'content': chunk})}\n\n"
                
                response_text = ''.join(full_response)
            except Exception as e:
                logger.error(f"LLM流式生成失败: {e}", exc_info=True)
                response_text = f"抱歉，生成响应时出错: {str(e)}。请检查Ollama服务是否正常运行。"
                yield f"data: {json.dumps({'type': 'error', 'content': response_text})}\n\n"
            
            # 如果执行了工具，在响应前添加工具标识
            if tools_used:
                tool_prefix = f"🔧 已执行工具: {', '.join(tools_used)}\n\n"
                response_text = tool_prefix + response_text
            
            # 质量评分
            quality_score = QUALITY_SCORER.auto_score(
                question=message,
                response=response_text,
                snn_spikes=result.snn_spikes,
                attention=result.attention_score,
                processing_time=snn_stats['processing_time']
            )
            
            # 自动改进分析
            improver = get_auto_improver()
            if improver:
                analysis = improver.analyze_response(response_text, quality_score.overall_score, message)
                if analysis['needs_improvement']:
                    # 记录问题
                    improver.record_improvement(analysis, 0.0)
                    for issue in analysis['issues']:
                        logger.warning(f"[自动改进] {issue['severity']}: {issue['detail']}")
                    # 发送改进提示
                    yield f"data: {json.dumps({'type': 'improvement', 'issues': analysis['issues']})}\n\n"
            
            # 工作记忆更新
            CONTEXT_MANAGER.add_turn('user', message, importance=quality_score.relevance_score)
            CONTEXT_MANAGER.add_turn('assistant', response_text[:500], importance=quality_score.overall_score)
            
            # 缓存结果
            RESPONSE_CACHE[cache_key] = {
                'response': response_text,
                'stats': snn_stats,
                'tools': tools_used,
                'quality_score': quality_score.overall_score
            }
            
            # 发送质量评分
            yield f"data: {json.dumps({'type': 'quality', 'score': quality_score.overall_score, 'details': {'length': quality_score.length_score, 'structure': quality_score.structure_score, 'relevance': quality_score.relevance_score}})}\n\n"
            
            yield "data: [DONE]\n\n"
            
        except Exception as e:
            logger.error(f"流式处理失败: {e}", exc_info=True)
            yield f"data: {json.dumps({'error': str(e)})}\n\n"
    
    return StreamingResponse(generate_stream(), media_type="text/event-stream")

