# ========== 限流中间件 ==========

import uuid

REQUEST_TRACKING = {}  # request_id -> {path, start_time, client_ip}

# ========== API响应缓存 ==========
from functools import wraps
import hashlib

API_CACHE = {}  # cache_key -> {data, timestamp, ttl}
CACHE_CONFIG = {
    "default_ttl": 60,  # 默认缓存60秒
    "max_size": 1000,   # 最大缓存条目
    "enabled": True
}

def get_cache_key(path: str, params: dict = None) -> str:
    """生成缓存键"""
    key_data = path
    if params:
        key_data += json.dumps(params, sort_keys=True)
    return hashlib.md5(key_data.encode()).hexdigest()[:16]

def cache_response(ttl: int = 60):
    """API响应缓存装饰器"""
    def decorator(func):
        @wraps(func)
        async def wrapper(*args, **kwargs):
            if not CACHE_CONFIG["enabled"]:
                return await func(*args, **kwargs)
            
            # 生成缓存键
            request = None
            for arg in args:
                if isinstance(arg, Request):
                    request = arg
                    break
            
            cache_key = get_cache_key(
                request.url.path if request else func.__name__,
                dict(request.query_params) if request else None
            )
            
            # 检查缓存
            now = time.time()
            if cache_key in API_CACHE:
                cached = API_CACHE[cache_key]
                if now - cached["timestamp"] < cached["ttl"]:
                    cached["hits"] = cached.get("hits", 0) + 1
                    return cached["data"]
            
            # 执行函数
            result = await func(*args, **kwargs)
            
            # 存储缓存
            if len(API_CACHE) >= CACHE_CONFIG["max_size"]:
                # 清理最旧的缓存
                oldest_key = min(API_CACHE.keys(), key=lambda k: API_CACHE[k]["timestamp"])
                API_CACHE.pop(oldest_key)
            
            API_CACHE[cache_key] = {
                "data": result,
                "timestamp": now,
                "ttl": ttl,
                "hits": 0
            }
            
            return result
        return wrapper
    return decorator

@app.get("/api/cache/stats")
async def get_cache_stats():
    """获取缓存统计"""
    now = time.time()
    valid_count = sum(1 for c in API_CACHE.values() if now - c["timestamp"] < c["ttl"])
    total_hits = sum(c.get("hits", 0) for c in API_CACHE.values())
    
    return {
        "success": True,
        "enabled": CACHE_CONFIG["enabled"],
        "total_entries": len(API_CACHE),
        "valid_entries": valid_count,
        "total_hits": total_hits,
        "max_size": CACHE_CONFIG["max_size"],
        "default_ttl": CACHE_CONFIG["default_ttl"]
    }

@app.post("/api/cache/clear")
async def clear_cache():
    """清除缓存"""
    API_CACHE.clear()
    return {"success": True, "message": "缓存已清除"}

@app.post("/api/cache/config")
async def set_cache_config(request: Request):
    """设置缓存配置"""
    data = await request.json()
    if "enabled" in data:
        CACHE_CONFIG["enabled"] = data["enabled"]
    if "ttl" in data:
        CACHE_CONFIG["default_ttl"] = data["ttl"]
    if "max_size" in data:
        CACHE_CONFIG["max_size"] = data["max_size"]
    return {"success": True, "config": CACHE_CONFIG}

