import yaml

CONFIG_PATH = Path.home() / "nanobot_v2" / "config.yaml"
RUNTIME_CONFIG = {
    "last_loaded": None,
    "config": {}
}

def load_config() -> dict:
    """加载配置文件"""
    try:
        if CONFIG_PATH.exists():
            with open(CONFIG_PATH, 'r', encoding='utf-8') as f:
                config = yaml.safe_load(f) or {}
            RUNTIME_CONFIG["last_loaded"] = datetime.now().isoformat()
            RUNTIME_CONFIG["config"] = config
            return config
    except Exception as e:
        logging.error(f"加载配置失败: {e}")
    return {}

@app.get("/api/config")
async def get_config():
    """获取当前配置"""
    if not RUNTIME_CONFIG["config"]:
        load_config()
    return {
        "success": True,
        "config_path": str(CONFIG_PATH),
        "last_loaded": RUNTIME_CONFIG["last_loaded"],
        "config": RUNTIME_CONFIG["config"]
    }

@app.post("/api/config/reload")
async def reload_config():
    """热重载配置"""
    old_config = RUNTIME_CONFIG["config"].copy()
    new_config = load_config()
    
    # 检测变更
    changes = []
    for key in set(list(old_config.keys()) + list(new_config.keys())):
        old_val = old_config.get(key)
        new_val = new_config.get(key)
        if old_val != new_val:
            changes.append({
                "key": key,
                "old": old_val,
                "new": new_val
            })
    
    return {
        "success": True,
        "message": "配置已重载",
        "changes": changes if changes else None,
        "config": new_config
    }

@app.post("/api/config/update")
async def update_config(request: Request):
    """更新配置项"""
    data = await request.json()
    
    # 加载当前配置
    config = load_config()
    
    # 更新配置
    updated_keys = []
    for key, value in data.items():
        if key in config:
            config[key] = value
            updated_keys.append(key)
    
    # 保存配置
    try:
        with open(CONFIG_PATH, 'w', encoding='utf-8') as f:
            yaml.dump(config, f, allow_unicode=True, default_flow_style=False)
        
        RUNTIME_CONFIG["config"] = config
        RUNTIME_CONFIG["last_loaded"] = datetime.now().isoformat()
        
        return {
            "success": True,
            "message": f"已更新 {len(updated_keys)} 个配置项",
            "updated_keys": updated_keys
        }
    except Exception as e:
        return {"success": False, "error": str(e)}

# ========== 请求审计日志 ==========

AUDIT_LOG = []  # 审计日志记录
AUDIT_CONFIG = {
    "enabled": True,
    "max_entries": 1000,  # 最大记录数
    "sensitive_paths": ["/api/chat", "/api/config", "/api/backup"],  # 敏感路径
    "exclude_paths": ["/health", "/api/status", "/api/docs"]  # 排除路径
}

def add_audit_entry(request_id: str, request: Request, response_status: int, duration_ms: float):
    """添加审计日志条目"""
    if not AUDIT_CONFIG["enabled"]:
        return
    
    path = request.url.path
    
    # 检查排除路径
    for exclude in AUDIT_CONFIG["exclude_paths"]:
        if exclude in path:
            return
    
    entry = {
        "request_id": request_id,
        "timestamp": datetime.now().isoformat(),
        "method": request.method,
        "path": path,
        "client_ip": request.client.host if request.client else "unknown",
        "user_agent": request.headers.get("user-agent", ""),
        "status_code": response_status,
        "duration_ms": duration_ms,
        "sensitive": any(s in path for s in AUDIT_CONFIG["sensitive_paths"])
    }
    
    AUDIT_LOG.append(entry)
    
    # 清理旧记录
    while len(AUDIT_LOG) > AUDIT_CONFIG["max_entries"]:
        AUDIT_LOG.pop(0)

@app.get("/api/audit/logs")
async def get_audit_logs(limit: int = 50):
    """获取审计日志"""
    return {
        "success": True,
        "total_entries": len(AUDIT_LOG),
        "logs": AUDIT_LOG[-limit:] if limit else AUDIT_LOG
    }

@app.get("/api/audit/stats")
async def get_audit_stats():
    """获取审计统计"""
    now = datetime.now()
    
    # 统计最近1小时的请求
    hour_ago = (now - timedelta(hours=1)).isoformat()
    recent = [e for e in AUDIT_LOG if e["timestamp"] > hour_ago]
    
    # 按路径统计
    path_counts = {}
    for e in recent:
        path_counts[e["path"]] = path_counts.get(e["path"], 0) + 1
    
    # 按状态码统计
    status_counts = {}
    for e in recent:
        status_counts[str(e["status_code"])] = status_counts.get(str(e["status_code"]), 0) + 1
    
    # 敏感操作统计
    sensitive_ops = [e for e in recent if e.get("sensitive")]
    
    return {
        "success": True,
        "enabled": AUDIT_CONFIG["enabled"],
        "total_entries": len(AUDIT_LOG),
        "last_hour": {
            "requests": len(recent),
            "by_path": path_counts,
            "by_status": status_counts,
            "sensitive_operations": len(sensitive_ops)
        }
    }

