# 延迟导入FixEngine，避免启动时加载
_fix_engine = None

def _get_fix_engine(force_reload=False):
    """获取FixEngine实例（延迟加载，支持重新加载）"""
    global _fix_engine
    
    if force_reload or _fix_engine is None:
        # 添加patches目录到路径
        patches_dir = Path(__file__).parent.parent / "patches"
        if str(patches_dir) not in sys.path:
            sys.path.insert(0, str(patches_dir))
        
        # 如果需要重新加载，先清除模块缓存
        if force_reload and 'fix_engine' in sys.modules:
            import importlib
            importlib.reload(sys.modules['fix_engine'])
            _fix_engine = None
        
        from fix_engine import FixEngine
        workspace = Path(__file__).parent.parent
        _fix_engine = FixEngine(workspace)
    
    return _fix_engine

