# ========== 任务调度器 API ==========


def _normalize_task_update_payload(event: Dict[str, Any]) -> Dict[str, Any]:
    """Normalize task_update events into a stable payload schema.

    The frontend expects a root task plus the complete child task list on every
    push so it can render a real task status bar, progress indicator, and
    verification conclusion consistently.
    """
    root_task = event.get("root_task") or event.get("task") or {}
    if not isinstance(root_task, dict):
        root_task = {}

    child_tasks = event.get("child_tasks")
    if child_tasks is None:
        child_tasks = event.get("tasks", [])
    if not isinstance(child_tasks, list):
        child_tasks = list(child_tasks) if child_tasks else []

    def _state(task: Dict[str, Any]) -> str:
        return str(task.get("state") or task.get("status") or "").strip().lower()

    def _task_text(task: Dict[str, Any]) -> str:
        parts = [
            str(task.get("result_summary") or ""),
            str(task.get("blocked_reason") or ""),
        ]
        metadata = task.get("metadata") if isinstance(task.get("metadata"), dict) else {}
        if metadata:
            parts.extend([
                str(metadata.get("verdict") or ""),
                str(metadata.get("result") or ""),
            ])
        return "\n".join(part for part in parts if part)

    def _extract_verdict(task: Dict[str, Any]) -> str:
        import re

        text = _task_text(task)
        match = re.search(r"VERDICT:\s*(PASS|FAIL|PARTIAL)", text, flags=re.IGNORECASE)
        if match:
            return match.group(1).upper()
        text_upper = text.upper()
        for verdict in ("PASS", "FAIL", "PARTIAL"):
            if verdict in text_upper:
                return verdict
        state = _state(task)
        if state == "completed":
            return "PASS"
        if state in {"failed", "blocked"}:
            return "FAIL"
        return ""

    counts = {
        "total": len(child_tasks),
        "created": sum(1 for task in child_tasks if _state(task) == "created"),
        "planned": sum(1 for task in child_tasks if _state(task) == "planned"),
        "in_progress": sum(1 for task in child_tasks if _state(task) == "in_progress"),
        "waiting_approval": sum(1 for task in child_tasks if _state(task) == "waiting_approval"),
        "verifying": sum(1 for task in child_tasks if _state(task) == "verifying"),
        "completed": sum(1 for task in child_tasks if _state(task) == "completed"),
        "failed": sum(1 for task in child_tasks if _state(task) in {"failed", "blocked", "cancelled"}),
    }

    completed_steps = counts["completed"]
    total_steps = counts["total"]
    if total_steps <= 0:
        total_steps = len(root_task.get("steps", []) or []) if isinstance(root_task, dict) else 0
    progress_percent = int((completed_steps / total_steps) * 100) if total_steps > 0 else (100 if _state(root_task) == "completed" else 0)

    verify_task = None
    for task in reversed(child_tasks):
        title = str(task.get("title") or task.get("name") or "")
        metadata = task.get("metadata") if isinstance(task.get("metadata"), dict) else {}
        if metadata.get("agent_type") == "verify" or "verify" in title.lower() or "验证" in title:
            verify_task = task
            break

    verification = {
        "task_id": verify_task.get("id") if verify_task else "",
        "state": _state(verify_task) if verify_task else "",
        "verdict": _extract_verdict(verify_task) if verify_task else "",
        "summary": str((verify_task or {}).get("result_summary") or (verify_task or {}).get("blocked_reason") or "").strip(),
    }

    payload: Dict[str, Any] = {
        "type": "task_update",
        "schema_version": 1,
        "root_task": root_task,
        "child_tasks": child_tasks,
        "tasks": child_tasks,
        "task": root_task,
        "counts": counts,
        "progress": {
            "completed": completed_steps,
            "total": total_steps,
            "percent": progress_percent,
        },
        "verification": verification,
    }

    for key in ("session_id", "workspace", "source", "summary", "updated_at", "status"):
        if key in event:
            payload[key] = event[key]

    return payload


def _resolve_chat_task_id(session_id: str, message: str, mode: str) -> str:
    """Resolve the active root task id for a chat request.

    This is used to surface the task id in SSE response headers so browser
    devtools can show which task the current stream belongs to.
    """
    try:
        from task_store import ensure_root_task_for_message

        root_task = ensure_root_task_for_message(
            WORKSPACE,
            session_id,
            message,
            owner="main_agent",
            metadata={
                "source": "chat_stream",
                "mode": mode,
            },
        )
        return str(root_task.id) if root_task else ""
    except Exception as exc:
        logger.debug("[ChatStream] Failed to resolve active task id for %s: %s", session_id, exc)
        return ""

@app.get("/api/tasks/status")
async def get_tasks_status():
    """获取任务调度器状态和任务列表"""
    try:
        workspace = Path.home() / ".nanobot" / "workspace"
        tasks_file = workspace / "scheduled_tasks.json"

        tasks = read_tasks_file(tasks_file)

        # 检查调度器是否运行（使用psutil替代subprocess避免安全拦截器警告）
        scheduler_running = False
        try:
            for proc in psutil.process_iter(['pid', 'name', 'cmdline']):
                try:
                    cmdline = proc.info.get('cmdline', [])
                    if cmdline and any('scheduler.py' in str(c) for c in cmdline):
                        scheduler_running = True
                        break
                except (psutil.NoSuchProcess, psutil.AccessDenied):
                    pass
        except Exception as e:
            print(f"[TasksAPI] 检查调度器进程失败: {e}")

        enrich_tasks(tasks, scheduler_running)

        return {
            "success": True,
            "scheduler_running": scheduler_running,
            "tasks": tasks,
        }

    except Exception as e:
        print(f"[TasksAPI] 获取任务状态失败: {e}")
        return {
            "success": False,
            "error": str(e),
            "scheduler_running": False,
            "tasks": []
        }

@app.get("/api/task/{task_id}/debug")
async def debug_task(task_id: str):
    """Return a complete debug snapshot for a task, including its subtree and state history."""
    try:
        from task_store import find_task_record

        found = find_task_record(task_id, WORKSPACE)
        if found is None:
            raise HTTPException(status_code=404, detail=f"Task not found: {task_id}")

        store, task = found
        task_tree = store.build_task_tree(task.id) or {"task": task.to_dict(), "children": []}
        child_tasks = [child.to_dict() for child in store.get_children(task.id)]
        history = [dict(entry) for entry in (task.state_history or []) if isinstance(entry, dict)]

        return {
            "success": True,
            "task_id": task.id,
            "session_id": store.session_id,
            "workspace": str(store.workspace),
            "task": task.to_dict(),
            "task_tree": task_tree,
            "child_tasks": child_tasks,
            "state_history": history,
            "history_count": len(history),
            "child_count": len(child_tasks),
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("[TaskDebug] Failed to build debug snapshot for %s", task_id)
        raise HTTPException(status_code=500, detail=f"Failed to build task debug snapshot: {e}")


def _is_nanobot_debug_mode_enabled() -> bool:
    return str(os.getenv("NANOBOT_DEBUG_MODE", "")).strip().lower() in {"1", "true", "yes", "on"}


@app.post("/api/task/{task_id}/transition")
async def manual_task_transition(task_id: str, request: Request):
    """Manually transition a task state in debug mode only."""
    if not _is_nanobot_debug_mode_enabled():
        raise HTTPException(status_code=404, detail="Not Found")

    try:
        body = await request.json()
    except Exception:
        raise HTTPException(status_code=400, detail="Invalid JSON body")

    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="Request body must be a JSON object")

    new_state = str(body.get("state") or "").strip()
    reason = str(body.get("reason") or "manual override").strip() or "manual override"
    if not new_state:
        raise HTTPException(status_code=400, detail="Field 'state' is required")

    try:
        from task_store import find_task_record

        found = find_task_record(task_id, WORKSPACE)
        if found is None:
            raise HTTPException(status_code=404, detail=f"Task not found: {task_id}")

        store, _task = found
        updated_task = store.transition(task_id, new_state, source="manual_api", reason=reason)
        return {
            "success": True,
            "task_id": updated_task.id,
            "state": updated_task.state,
            "reason": reason,
            "state_history": [dict(entry) for entry in (updated_task.state_history or []) if isinstance(entry, dict)],
        }
    except HTTPException:
        raise
    except Exception as e:
        logger.exception("[TaskTransition] Failed to transition task %s", task_id)
        raise HTTPException(status_code=500, detail=f"Failed to transition task: {e}")

@app.post("/api/tasks/scheduler/start")
async def start_task_scheduler():
    """启动任务调度器"""
    try:
        import subprocess
        import os
        
        workspace = Path.home() / ".nanobot" / "workspace"
        scheduler_script = workspace / "scheduler.py"
        
        # 检查调度器脚本是否存在
        if not scheduler_script.exists():
            # 创建基本的调度器脚本
            scheduler_code = '''#!/usr/bin/env python3
import json
import time
from datetime import datetime, timedelta
from pathlib import Path

def run_scheduler():
    workspace = Path.home() / ".nanobot" / "workspace"
    tasks_file = workspace / "scheduled_tasks.json"
    
    while True:
        try:
            if tasks_file.exists():
                with open(tasks_file, 'r', encoding='utf-8') as f:
                    data = json.load(f)
                    tasks = data.get('tasks', [])
                
                now = datetime.now()
                for task in tasks:
                    if task.get('status') == 'pending' and task.get('next_run'):
                        next_run = datetime.fromisoformat(task['next_run'].replace('Z', '+00:00'))
                        if now >= next_run:
                            # 执行任务（简化版：只更新状态，实际应调用相应命令）
                            task['last_run'] = now.isoformat()
                            task['status'] = 'completed'
                            # 重新计算下次执行时间
                            if task.get('schedule_type') == 'daily':
                                task['next_run'] = (now + timedelta(days=1)).isoformat()
                            elif task.get('interval_seconds'):
                                task['next_run'] = (now + timedelta(seconds=task['interval_seconds'])).isoformat()
                
                # 保存更新后的任务
                with open(tasks_file, 'w', encoding='utf-8') as f:
                    json.dump({'tasks': tasks}, f, ensure_ascii=False, indent=2)
        except Exception as e:
            print(f"[Scheduler] Error: {e}")
        
        time.sleep(60)  # 每分钟检查一次

if __name__ == "__main__":
    run_scheduler()
'''
            scheduler_script.write_text(scheduler_code, encoding='utf-8')
            scheduler_script.chmod(0o755)
        
        # 启动调度器进程
        try:
            process = subprocess.Popen(
                ['python3', str(scheduler_script)],
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                cwd=str(workspace),
                start_new_session=True
            )
            
            # 等待一下确认进程启动
            time.sleep(1)
            
            if process.poll() is None:  # 进程仍在运行
                return {
                    "success": True,
                    "message": "任务调度器已启动",
                    "pid": process.pid
                }
            else:
                stdout, stderr = process.communicate()
                return {
                    "success": False,
                    "error": f"调度器启动失败: {stderr.decode('utf-8', errors='ignore')[:200]}"
                }
                
        except Exception as e:
            return {
                "success": False,
                "error": f"启动调度器失败: {str(e)}"
            }
            
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }

