@app.get("/api/changelog")
async def get_changelog(from_version: str = None, to_version: str = None):
    """获取版本变更日志"""
    changes = []
    
    versions = list(API_VERSIONS.keys())
    start_idx = versions.index(from_version) if from_version in versions else 0
    end_idx = versions.index(to_version) + 1 if to_version in versions else len(versions)
    
    for v in versions[start_idx:end_idx]:
        info = API_VERSIONS[v]
        changes.append({
            "version": v,
            "release_date": info["release_date"],
            "features": info["features"],
            "deprecated": info["deprecated"],
            "breaking_changes": info["breaking_changes"]
        })
    
    return {
        "success": True,
        "changelog": changes
    }

