# ========== IP访问控制 ==========

IP_ACCESS_CONTROL = {
    "enabled": False,
    "mode": "whitelist",  # whitelist 或 blacklist
    "whitelist": ["127.0.0.1", "::1"],  # 白名单
    "blacklist": [],  # 黑名单
    "log_blocked": True
}

def check_ip_access(client_ip: str) -> bool:
    """检查IP访问权限"""
    if not IP_ACCESS_CONTROL["enabled"]:
        return True
    
    mode = IP_ACCESS_CONTROL["mode"]
    
    if mode == "whitelist":
        return client_ip in IP_ACCESS_CONTROL["whitelist"]
    else:  # blacklist
        return client_ip not in IP_ACCESS_CONTROL["blacklist"]

