# ========== 请求日志追踪增强 ==========

REQUEST_CHAINS = {}  # request_id -> chain of related requests

def link_request_chain(current_id: str, parent_id: str = None):
    """链接请求链"""
    if current_id not in REQUEST_CHAINS:
        REQUEST_CHAINS[current_id] = {
            "parent": parent_id,
            "children": [],
            "created": datetime.now().isoformat()
        }
    
    if parent_id and parent_id in REQUEST_CHAINS:
        REQUEST_CHAINS[parent_id]["children"].append(current_id)
    
    # 清理旧链
    if len(REQUEST_CHAINS) > 500:
        oldest = min(REQUEST_CHAINS.items(), key=lambda x: x[1]["created"])
        del REQUEST_CHAINS[oldest[0]]

@app.get("/api/logs/trace/{request_id}")
async def trace_request(request_id: str):
    """追踪单个请求的完整链路"""
    # 从审计日志查找
    audit_entry = None
    for entry in AUDIT_LOG:
        if entry.get("request_id") == request_id:
            audit_entry = entry
            break
    
    # 从请求追踪查找
    tracking_entry = REQUEST_TRACKING.get(request_id)
    
    # 从请求链查找
    chain = REQUEST_CHAINS.get(request_id)
    
    return {
        "success": True,
        "request_id": request_id,
        "audit": audit_entry,
        "tracking": tracking_entry,
        "chain": chain
    }

@app.get("/api/logs/search")
async def search_logs(query: str = "", method: str = "", path: str = "", limit: int = 50):
    """搜索审计日志"""
    results = []
    
    for entry in AUDIT_LOG:
        match = True
        
        if query and query.lower() not in json.dumps(entry).lower():
            match = False
        if method and entry.get("method", "").upper() != method.upper():
            match = False
        if path and path.lower() not in entry.get("path", "").lower():
            match = False
        
        if match:
            results.append(entry)
    
    return {
        "success": True,
        "total_matches": len(results),
        "limit": limit,
        "results": results[-limit:] if limit else results
    }

@app.get("/api/logs/timeline")
async def get_logs_timeline(hours: int = 24):
    """获取请求时间线"""
    now = datetime.now()
    start_time = (now - timedelta(hours=hours)).isoformat()
    
    timeline = {}
    
    for entry in AUDIT_LOG:
        if entry.get("timestamp", "") >= start_time:
            hour = entry["timestamp"][:13]  # YYYY-MM-DDTHH
            if hour not in timeline:
                timeline[hour] = {"total": 0, "by_method": {}, "by_status": {}}
            
            timeline[hour]["total"] += 1
            
            method = entry.get("method", "UNKNOWN")
            timeline[hour]["by_method"][method] = timeline[hour]["by_method"].get(method, 0) + 1
            
            status = str(entry.get("status_code", 0))
            timeline[hour]["by_status"][status] = timeline[hour]["by_status"].get(status, 0) + 1
    
    return {
        "success": True,
        "hours": hours,
        "timeline": timeline
    }

@app.get("/api/logs/errors")
async def get_error_logs(limit: int = 50):
    """获取错误请求日志"""
    errors = [e for e in AUDIT_LOG if e.get("status_code", 200) >= 400]
    
    return {
        "success": True,
        "total_errors": len(errors),
        "errors": errors[-limit:] if limit else errors
    }

@app.get("/api/logs/slow")
async def get_slow_requests(threshold_ms: float = 1000, limit: int = 50):
    """获取慢请求"""
    slow = [e for e in AUDIT_LOG if e.get("duration_ms", 0) >= threshold_ms]
    
    # 按耗时排序
    slow.sort(key=lambda x: x.get("duration_ms", 0), reverse=True)
    
    return {
        "success": True,
        "threshold_ms": threshold_ms,
        "total_slow": len(slow),
        "slow_requests": slow[:limit]
    }

# ========== API调用统计仪表盘 ==========

API_DASHBOARD = {
    "total_calls": 0,
    "by_endpoint": {},
    "by_method": {},
    "by_status": {},
    "by_hour": {},
    "errors_count": 0,
    "avg_response_time": 0,
    "total_response_time": 0
}

def update_dashboard_stats(entry: dict):
    """更新仪表盘统计"""
    API_DASHBOARD["total_calls"] += 1
    
    path = entry.get("path", "unknown")
    API_DASHBOARD["by_endpoint"][path] = API_DASHBOARD["by_endpoint"].get(path, 0) + 1
    
    method = entry.get("method", "UNKNOWN")
    API_DASHBOARD["by_method"][method] = API_DASHBOARD["by_method"].get(method, 0) + 1
    
    status = str(entry.get("status_code", 0))
    API_DASHBOARD["by_status"][status] = API_DASHBOARD["by_status"].get(status, 0) + 1
    
    hour = entry.get("timestamp", "")[:13]
    if hour:
        API_DASHBOARD["by_hour"][hour] = API_DASHBOARD["by_hour"].get(hour, 0) + 1
    
    if entry.get("status_code", 200) >= 400:
        API_DASHBOARD["errors_count"] += 1
    
    duration = entry.get("duration_ms", 0)
    API_DASHBOARD["total_response_time"] += duration
    API_DASHBOARD["avg_response_time"] = API_DASHBOARD["total_response_time"] / API_DASHBOARD["total_calls"]

