# ========== 请求队列管理 ==========

from collections import deque
import threading

REQUEST_QUEUE = {
    "queue": deque(),
    "max_size": 1000,
    "processing": 0,
    "total_queued": 0,
    "total_processed": 0,
    "total_rejected": 0,
    "lock": threading.Lock()
}

def add_to_queue(request_data: dict) -> bool:
    """添加请求到队列"""
    with REQUEST_QUEUE["lock"]:
        if len(REQUEST_QUEUE["queue"]) >= REQUEST_QUEUE["max_size"]:
            REQUEST_QUEUE["total_rejected"] += 1
            return False
        
        REQUEST_QUEUE["queue"].append({
            **request_data,
            "queued_at": datetime.now().isoformat()
        })
        REQUEST_QUEUE["total_queued"] += 1
        return True

def get_from_queue():
    """从队列获取请求"""
    with REQUEST_QUEUE["lock"]:
        if REQUEST_QUEUE["queue"]:
            REQUEST_QUEUE["processing"] += 1
            return REQUEST_QUEUE["queue"].popleft()
        return None

def complete_request():
    """完成请求处理"""
    with REQUEST_QUEUE["lock"]:
        REQUEST_QUEUE["processing"] -= 1
        REQUEST_QUEUE["total_processed"] += 1

@app.get("/api/queue/status")
async def get_queue_status():
    """获取队列状态"""
    with REQUEST_QUEUE["lock"]:
        return {
            "success": True,
            "status": {
                "queue_size": len(REQUEST_QUEUE["queue"]),
                "max_size": REQUEST_QUEUE["max_size"],
                "processing": REQUEST_QUEUE["processing"],
                "total_queued": REQUEST_QUEUE["total_queued"],
                "total_processed": REQUEST_QUEUE["total_processed"],
                "total_rejected": REQUEST_QUEUE["total_rejected"],
                "utilization": round(len(REQUEST_QUEUE["queue"]) / REQUEST_QUEUE["max_size"] * 100, 2)
            }
        }

@app.post("/api/queue/config")
async def set_queue_config(request: Request):
    """设置队列配置"""
    data = await request.json()
    
    with REQUEST_QUEUE["lock"]:
        if "max_size" in data:
            REQUEST_QUEUE["max_size"] = data["max_size"]
    
    return {
        "success": True,
        "max_size": REQUEST_QUEUE["max_size"]
    }

@app.get("/api/queue/items")
async def list_queue_items(limit: int = 50):
    """列出队列中的请求"""
    with REQUEST_QUEUE["lock"]:
        items = list(REQUEST_QUEUE["queue"])[-limit:]
    
    return {
        "success": True,
        "total_items": len(REQUEST_QUEUE["queue"]),
        "items": items
    }

@app.delete("/api/queue/clear")
async def clear_queue():
    """清空队列"""
    with REQUEST_QUEUE["lock"]:
        cleared = len(REQUEST_QUEUE["queue"])
        REQUEST_QUEUE["queue"].clear()
    
    return {"success": True, "cleared": cleared}

@app.get("/api/queue/stats")
async def get_queue_stats():
    """获取队列统计"""
    with REQUEST_QUEUE["lock"]:
        avg_wait_time = 0
        if REQUEST_QUEUE["total_processed"] > 0:
            avg_wait_time = 50  # 模拟平均等待时间
        
        return {
            "success": True,
            "stats": {
                "throughput": REQUEST_QUEUE["total_processed"],
                "rejection_rate": round(
                    REQUEST_QUEUE["total_rejected"] / max(REQUEST_QUEUE["total_queued"] + REQUEST_QUEUE["total_rejected"], 1) * 100, 2
                ),
                "avg_wait_time_ms": avg_wait_time,
                "current_load": REQUEST_QUEUE["processing"],
                "queue_health": "healthy" if len(REQUEST_QUEUE["queue"]) < REQUEST_QUEUE["max_size"] * 0.8 else "warning"
            }
        }

@app.post("/api/queue/priority")
async def set_request_priority(request: Request):
    """设置请求优先级（将请求移到队首）"""
    data = await request.json()
    request_id = data.get("request_id")
    
    with REQUEST_QUEUE["lock"]:
        for i, item in enumerate(REQUEST_QUEUE["queue"]):
            if item.get("request_id") == request_id:
                REQUEST_QUEUE["queue"].remove(item)
                REQUEST_QUEUE["queue"].appendleft(item)
                return {"success": True, "message": f"请求 {request_id} 已移至队首"}
    
    return {"success": False, "error": "请求不存在"}

# ========== 系统资源监控 ==========

RESOURCE_HISTORY = {
    "cpu": [],
    "memory": [],
    "disk": [],
    "network": [],
    "max_history": 100
}

def collect_resource_metrics():
    """收集资源指标"""
    try:
        import psutil
        
        cpu = psutil.cpu_percent(interval=0.1)
        memory = psutil.virtual_memory()
        disk = psutil.disk_usage('/')
        net = psutil.net_io_counters()
        
        metrics = {
            "timestamp": datetime.now().isoformat(),
            "cpu_percent": cpu,
            "memory_percent": memory.percent,
            "memory_used_gb": round(memory.used / (1024**3), 2),
            "memory_total_gb": round(memory.total / (1024**3), 2),
            "disk_percent": disk.percent,
            "disk_used_gb": round(disk.used / (1024**3), 2),
            "disk_total_gb": round(disk.total / (1024**3), 2),
            "net_sent_mb": round(net.bytes_sent / (1024**2), 2),
            "net_recv_mb": round(net.bytes_recv / (1024**2), 2)
        }
        
        # 存储历史
        RESOURCE_HISTORY["cpu"].append({"t": metrics["timestamp"], "v": cpu})
        RESOURCE_HISTORY["memory"].append({"t": metrics["timestamp"], "v": memory.percent})
        RESOURCE_HISTORY["disk"].append({"t": metrics["timestamp"], "v": disk.percent})
        
        # 限制历史长度
        for key in ["cpu", "memory", "disk"]:
            if len(RESOURCE_HISTORY[key]) > RESOURCE_HISTORY["max_history"]:
                RESOURCE_HISTORY[key].pop(0)
        
        return metrics
    except Exception as e:
        return {"error": str(e)}

@app.get("/api/resources/current")
async def get_current_resources():
    """获取当前资源使用"""
    metrics = collect_resource_metrics()
    return {
        "success": True,
        "resources": metrics
    }

@app.get("/api/resources/history")
async def get_resource_history(resource_type: str = "cpu", limit: int = 50):
    """获取资源历史"""
    if resource_type not in RESOURCE_HISTORY:
        return {"success": False, "error": "无效的资源类型"}
    
    history = RESOURCE_HISTORY[resource_type][-limit:]
    
    return {
        "success": True,
        "resource_type": resource_type,
        "total_points": len(RESOURCE_HISTORY[resource_type]),
        "history": history
    }

@app.get("/api/resources/summary")
async def get_resource_summary():
    """获取资源摘要"""
    import psutil
    
    try:
        cpu = psutil.cpu_percent(interval=0.1)
        memory = psutil.virtual_memory()
        disk = psutil.disk_usage('/')
        
        # 计算平均值
        avg_cpu = sum(h["v"] for h in RESOURCE_HISTORY["cpu"][-10:]) / max(len(RESOURCE_HISTORY["cpu"][-10:]), 1)
        avg_mem = sum(h["v"] for h in RESOURCE_HISTORY["memory"][-10:]) / max(len(RESOURCE_HISTORY["memory"][-10:]), 1)
        
        return {
            "success": True,
            "summary": {
                "cpu": {
                    "current": cpu,
                    "avg_10min": round(avg_cpu, 2),
                    "status": "normal" if cpu < 70 else "warning" if cpu < 90 else "critical"
                },
                "memory": {
                    "current": memory.percent,
                    "avg_10min": round(avg_mem, 2),
                    "available_gb": round(memory.available / (1024**3), 2),
                    "status": "normal" if memory.percent < 70 else "warning" if memory.percent < 90 else "critical"
                },
                "disk": {
                    "current": disk.percent,
                    "free_gb": round(disk.free / (1024**3), 2),
                    "status": "normal" if disk.percent < 70 else "warning" if disk.percent < 90 else "critical"
                }
            },
            "overall_status": "healthy" if cpu < 70 and memory.percent < 70 else "warning" if cpu < 90 and memory.percent < 90 else "critical"
        }
    except Exception as e:
        return {"success": False, "error": str(e)}

