# ========== API响应时间分析 ==========

RESPONSE_TIME_ANALYSIS = {
    "by_endpoint": {},  # endpoint -> {count, total_time, min, max, avg}
    "percentiles": {},
    "slowest_endpoints": []
}

def update_response_analysis(endpoint: str, duration_ms: float):
    """更新响应时间分析"""
    if endpoint not in RESPONSE_TIME_ANALYSIS["by_endpoint"]:
        RESPONSE_TIME_ANALYSIS["by_endpoint"][endpoint] = {
            "count": 0,
            "total_time": 0,
            "min": float('inf'),
            "max": 0,
            "avg": 0,
            "times": []
        }
    
    stats = RESPONSE_TIME_ANALYSIS["by_endpoint"][endpoint]
    stats["count"] += 1
    stats["total_time"] += duration_ms
    stats["min"] = min(stats["min"], duration_ms)
    stats["max"] = max(stats["max"], duration_ms)
    stats["avg"] = stats["total_time"] / stats["count"]
    stats["times"].append(duration_ms)
    
    # 保留最近100次
    if len(stats["times"]) > 100:
        stats["times"].pop(0)

@app.get("/api/response/endpoints")
async def get_endpoint_response_stats(sort_by: str = "avg", limit: int = 20):
    """获取端点响应时间统计"""
    endpoints = []
    for endpoint, stats in RESPONSE_TIME_ANALYSIS["by_endpoint"].items():
        endpoints.append({
            "endpoint": endpoint,
            "count": stats["count"],
            "avg_ms": round(stats["avg"], 2),
            "min_ms": round(stats["min"], 2),
            "max_ms": round(stats["max"], 2),
            "total_time_ms": round(stats["total_time"], 2)
        })
    
    # 排序
    endpoints.sort(key=lambda x: x.get(sort_by, 0), reverse=True)
    
    return {
        "success": True,
        "total_endpoints": len(endpoints),
        "sorted_by": sort_by,
        "endpoints": endpoints[:limit]
    }

@app.get("/api/response/percentiles")
async def get_response_percentiles(endpoint: str = None):
    """获取响应时间百分位数"""
    if endpoint and endpoint in RESPONSE_TIME_ANALYSIS["by_endpoint"]:
        times = sorted(RESPONSE_TIME_ANALYSIS["by_endpoint"][endpoint]["times"])
    else:
        # 所有端点
        times = []
        for stats in RESPONSE_TIME_ANALYSIS["by_endpoint"].values():
            times.extend(stats["times"])
        times = sorted(times)
    
    if not times:
        return {"success": True, "percentiles": {}}
    
    def percentile(data, p):
        k = (len(data) - 1) * p / 100
        f = int(k)
        c = f + 1 if f + 1 < len(data) else f
        return data[f] + (k - f) * (data[c] - data[f]) if c != f else data[f]
    
    return {
        "success": True,
        "endpoint": endpoint or "all",
        "total_requests": len(times),
        "percentiles": {
            "p50": round(percentile(times, 50), 2),
            "p75": round(percentile(times, 75), 2),
            "p90": round(percentile(times, 90), 2),
            "p95": round(percentile(times, 95), 2),
            "p99": round(percentile(times, 99), 2)
        }
    }

@app.get("/api/response/slowest")
async def get_slowest_requests(limit: int = 20):
    """获取最慢的请求"""
    slowest = []
    
    for endpoint, stats in RESPONSE_TIME_ANALYSIS["by_endpoint"].items():
        if stats["max"] > 0:
            slowest.append({
                "endpoint": endpoint,
                "max_ms": round(stats["max"], 2),
                "avg_ms": round(stats["avg"], 2),
                "count": stats["count"]
            })
    
    slowest.sort(key=lambda x: x["max_ms"], reverse=True)
    
    return {
        "success": True,
        "slowest": slowest[:limit]
    }

@app.get("/api/response/distribution")
async def get_response_distribution(endpoint: str = None, buckets: int = 10):
    """获取响应时间分布"""
    if endpoint and endpoint in RESPONSE_TIME_ANALYSIS["by_endpoint"]:
        times = RESPONSE_TIME_ANALYSIS["by_endpoint"][endpoint]["times"]
    else:
        times = []
        for stats in RESPONSE_TIME_ANALYSIS["by_endpoint"].values():
            times.extend(stats["times"])
    
    if not times:
        return {"success": True, "distribution": {}}
    
    min_time = min(times)
    max_time = max(times)
    bucket_size = (max_time - min_time) / buckets if max_time > min_time else 1
    
    distribution = {}
    for i in range(buckets):
        low = min_time + i * bucket_size
        high = min_time + (i + 1) * bucket_size
        key = f"{round(low, 0)}-{round(high, 0)}ms"
        distribution[key] = 0
    
    for t in times:
        bucket_idx = min(int((t - min_time) / bucket_size), buckets - 1)
        low = min_time + bucket_idx * bucket_size
        high = min_time + (bucket_idx + 1) * bucket_size
        key = f"{round(low, 0)}-{round(high, 0)}ms"
        distribution[key] += 1
    
    return {
        "success": True,
        "endpoint": endpoint or "all",
        "total_requests": len(times),
        "min_ms": round(min_time, 2),
        "max_ms": round(max_time, 2),
        "distribution": distribution
    }

@app.get("/api/response/summary")
async def get_response_summary():
    """获取响应时间摘要"""
    all_times = []
    for stats in RESPONSE_TIME_ANALYSIS["by_endpoint"].values():
        all_times.extend(stats["times"])
    
    if not all_times:
        return {
            "success": True,
            "summary": {
                "total_requests": 0,
                "total_endpoints": len(RESPONSE_TIME_ANALYSIS["by_endpoint"]),
                "avg_ms": 0,
                "min_ms": 0,
                "max_ms": 0
            }
        }
    
    return {
        "success": True,
        "summary": {
            "total_requests": len(all_times),
            "total_endpoints": len(RESPONSE_TIME_ANALYSIS["by_endpoint"]),
            "avg_ms": round(sum(all_times) / len(all_times), 2),
            "min_ms": round(min(all_times), 2),
            "max_ms": round(max(all_times), 2),
            "fast_requests": len([t for t in all_times if t < 100]),
            "medium_requests": len([t for t in all_times if 100 <= t < 500]),
            "slow_requests": len([t for t in all_times if t >= 500])
        }
    }

# ========== 会话超时管理 ==========

SESSION_TIMEOUT_CONFIG = {
    "enabled": True,
    "default_timeout_minutes": 30,
    "max_timeout_minutes": 1440,  # 24小时
    "cleanup_interval_seconds": 60,
    "last_cleanup": None
}

SESSION_ACTIVITY = {}  # session_id -> last_activity

# Wire session_persistence module to our globals
_sp_mod.init(SESSION_STORE_DIR, SESSION_ACTIVITY, SESSION_TIMEOUT_CONFIG)

def update_session_activity(session_id: str):
    """更新会话活动时间"""
    SESSION_ACTIVITY[session_id] = datetime.now()

def check_session_timeout(session_id: str) -> bool:
    """检查会话是否超时"""
    if not SESSION_TIMEOUT_CONFIG["enabled"]:
        return False
    
    if session_id not in SESSION_ACTIVITY:
        return True  # 不存在视为超时
    
    last_activity = SESSION_ACTIVITY[session_id]
    timeout = timedelta(minutes=SESSION_TIMEOUT_CONFIG["default_timeout_minutes"])
    
    return datetime.now() - last_activity > timeout

async def cleanup_expired_sessions():
    """清理过期会话"""
    expired = []
    for session_id, last_activity in list(SESSION_ACTIVITY.items()):
        if check_session_timeout(session_id):
            expired.append(session_id)
            del SESSION_ACTIVITY[session_id]
    
    SESSION_TIMEOUT_CONFIG["last_cleanup"] = datetime.now().isoformat()
    
    # 只标记会话文件过期，不删除历史数据，避免刷新后无法恢复会话内容
    for session_id in expired:
        try:
            payload = load_session_payload(session_id)
            if payload:
                payload["expired"] = True
                payload["expired_at"] = datetime.now().isoformat()
                _persist_session_payload(session_id, payload)
        except Exception as exc:
            logger.warning(f"标记过期会话失败: session={session_id}, error={exc}")
    
    return expired

@app.get("/api/session/timeout/config")
async def get_timeout_config():
    """获取超时配置"""
    return {
        "success": True,
        "config": SESSION_TIMEOUT_CONFIG
    }

@app.post("/api/session/timeout/config")
async def set_timeout_config(request: Request):
    """设置超时配置"""
    data = await request.json()
    
    if "enabled" in data:
        SESSION_TIMEOUT_CONFIG["enabled"] = data["enabled"]
    if "default_timeout_minutes" in data:
        SESSION_TIMEOUT_CONFIG["default_timeout_minutes"] = min(
            data["default_timeout_minutes"],
            SESSION_TIMEOUT_CONFIG["max_timeout_minutes"]
        )
    if "cleanup_interval_seconds" in data:
        SESSION_TIMEOUT_CONFIG["cleanup_interval_seconds"] = data["cleanup_interval_seconds"]
    
    return {
        "success": True,
        "config": SESSION_TIMEOUT_CONFIG
    }

@app.get("/api/session/active")
async def list_active_sessions():
    """列出活跃会话"""
    active = []
    now = datetime.now()
    
    for session_id, last_activity in SESSION_ACTIVITY.items():
        idle_minutes = (now - last_activity).total_seconds() / 60
        active.append({
            "session_id": session_id,
            "last_activity": last_activity.isoformat(),
            "idle_minutes": round(idle_minutes, 2),
            "status": "active" if idle_minutes < SESSION_TIMEOUT_CONFIG["default_timeout_minutes"] else "expired"
        })
    
    return {
        "success": True,
        "total_sessions": len(active),
        "active_sessions": [s for s in active if s["status"] == "active"],
        "expired_sessions": [s for s in active if s["status"] == "expired"]
    }

@app.post("/api/session/renew/{session_id}")
async def renew_session(session_id: str):
    """续期会话"""
    if session_id in SESSION_ACTIVITY:
        touch_session_activity(session_id, persist=True)
        return {"success": True, "message": f"会话 {session_id} 已续期"}
    return {"success": False, "error": "会话不存在"}

@app.delete("/api/session/expire/{session_id}")
async def expire_session(session_id: str):
    """手动使会话过期"""
    if session_id in SESSION_ACTIVITY:
        del SESSION_ACTIVITY[session_id]
        try:
            payload = load_session_payload(session_id)
            if payload:
                payload["expired"] = True
                payload["expired_at"] = datetime.now().isoformat()
                _persist_session_payload(session_id, payload)
        except Exception as exc:
            logger.warning(f"标记过期会话失败: session={session_id}, error={exc}")
        return {"success": True, "message": f"会话 {session_id} 已过期"}
    return {"success": False, "error": "会话不存在"}

