@app.get("/api/ratelimit/status/{ip}")
async def get_ip_rate_limit_status(ip: str):
    """获取IP限流状态"""
    now = time.time()
    
    # 令牌桶状态
    bucket = RATE_LIMIT_STATE["token_buckets"].get(ip, {})
    
    # 固定窗口状态
    window = RATE_LIMIT_STATE["fixed_windows"].get(ip, {})
    
    # 滑动窗口状态
    sliding = [t for t in RATE_LIMIT_STATE["sliding_windows"][ip] if now - t < 60]
    
    return {
        "success": True,
        "ip": ip,
        "status": {
            "token_bucket": {
                "tokens": bucket.get("tokens", RATE_LIMIT_STRATEGIES["burst_size"]),
                "last_refill": bucket.get("last_refill", now)
            },
            "fixed_window": {
                "count": window.get("count", 0),
                "window_start": window.get("window_start", 0)
            },
            "sliding_window": {
                "request_count": len(sliding),
                "oldest_request": min(sliding) if sliding else None
            }
        }
    }

@app.delete("/api/ratelimit/reset/{ip}")
async def reset_ip_rate_limit(ip: str):
    """重置IP限流状态"""
    if ip in RATE_LIMIT_STATE["token_buckets"]:
        del RATE_LIMIT_STATE["token_buckets"][ip]
    if ip in RATE_LIMIT_STATE["fixed_windows"]:
        del RATE_LIMIT_STATE["fixed_windows"][ip]
    if ip in RATE_LIMIT_STATE["sliding_windows"]:
        RATE_LIMIT_STATE["sliding_windows"][ip] = []
    
    return {"success": True, "message": f"IP {ip} 限流状态已重置"}

@app.get("/api/ratelimit/top")
async def get_top_rate_limited_ips(limit: int = 20):
    """获取被限流最多的IP"""
    ip_stats = []
    
    for ip, requests in RATE_LIMIT_STATE["sliding_windows"].items():
        now = time.time()
        recent = [t for t in requests if now - t < 60]
        ip_stats.append({
            "ip": ip,
            "requests_last_minute": len(recent),
            "limit": RATE_LIMIT_STRATEGIES["per_ip_limit"],
            "utilization": round(len(recent) / RATE_LIMIT_STRATEGIES["per_ip_limit"] * 100, 2)
        })
    
    ip_stats.sort(key=lambda x: x["requests_last_minute"], reverse=True)
    
    return {
        "success": True,
        "total_ips": len(ip_stats),
        "top_ips": ip_stats[:limit]
    }

# ========== API请求日志分析 ==========

REQUEST_LOG_ANALYSIS = {
    "enabled": True,
    "log_retention_hours": 24,
    "analysis_interval_seconds": 60,
    "max_logs_per_endpoint": 1000
}

REQUEST_LOGS = {
    "by_endpoint": defaultdict(list),
    "by_ip": defaultdict(list),
    "by_status": defaultdict(list),
    "errors": [],
    "total_requests": 0
}

def add_request_log(request_id: str, endpoint: str, method: str, ip: str, 
                    status_code: int, duration_ms: float, timestamp: float):
    """添加请求日志"""
    if not REQUEST_LOG_ANALYSIS["enabled"]:
        return
    
    log_entry = {
        "request_id": request_id,
        "endpoint": endpoint,
        "method": method,
        "ip": ip,
        "status_code": status_code,
        "duration_ms": duration_ms,
        "timestamp": timestamp
    }
    
    # 按端点存储
    REQUEST_LOGS["by_endpoint"][endpoint].append(log_entry)
    if len(REQUEST_LOGS["by_endpoint"][endpoint]) > REQUEST_LOG_ANALYSIS["max_logs_per_endpoint"]:
        REQUEST_LOGS["by_endpoint"][endpoint].pop(0)
    
    # 按IP存储
    REQUEST_LOGS["by_ip"][ip].append(log_entry)
    if len(REQUEST_LOGS["by_ip"][ip]) > 100:
        REQUEST_LOGS["by_ip"][ip].pop(0)
    
    # 按状态码存储
    status_key = f"{status_code // 100}xx"
    REQUEST_LOGS["by_status"][status_key].append(log_entry)
    if len(REQUEST_LOGS["by_status"][status_key]) > 500:
        REQUEST_LOGS["by_status"][status_key].pop(0)
    
    # 错误日志
    if status_code >= 400:
        REQUEST_LOGS["errors"].append(log_entry)
        if len(REQUEST_LOGS["errors"]) > 200:
            REQUEST_LOGS["errors"].pop(0)
    
    REQUEST_LOGS["total_requests"] += 1

