# ========== API请求去重机制 ==========

import hashlib

DEDUPLICATION_CONFIG = {
    "enabled": True,
    "window_seconds": 5,  # 去重时间窗口
    "max_pending_requests": 1000,
    "hash_algorithm": "md5",  # md5, sha256
    "include_headers": False,  # 是否包含headers在hash计算中
    "exclude_paths": ["/health", "/api/status", "/api/metrics"]  # 排除路径
}

DEDUPLICATION_STATS = {
    "total_requests": 0,
    "duplicate_requests": 0,
    "unique_requests": 0,
    "blocked_duplicates": 0,
    "by_endpoint": {}
}

PENDING_REQUESTS = {}  # request_hash -> {timestamp, request_id, endpoint}

def generate_request_hash(request: Request, body: bytes = None) -> str:
    """生成请求唯一标识"""
    components = [
        request.method,
        str(request.url.path),
        str(request.url.query)
    ]
    
    if body:
        components.append(body.decode('utf-8', errors='ignore')[:1000])
    
    if DEDUPLICATION_CONFIG["include_headers"]:
        # 只包含关键headers
        for key in ['content-type', 'authorization']:
            if key in request.headers:
                components.append(f"{key}:{request.headers[key]}")
    
    data = "|".join(components)
    
    if DEDUPLICATION_CONFIG["hash_algorithm"] == "sha256":
        return hashlib.sha256(data.encode()).hexdigest()[:16]
    else:
        return hashlib.md5(data.encode()).hexdigest()[:16]

def check_duplicate(request_hash: str) -> dict:
    """检查是否为重复请求"""
    if not DEDUPLICATION_CONFIG["enabled"]:
        return {"is_duplicate": False}
    
    now = time.time()
    window = DEDUPLICATION_CONFIG["window_seconds"]
    
    # 清理过期请求
    expired = [h for h, r in PENDING_REQUESTS.items() if now - r["timestamp"] > window]
    for h in expired:
        del PENDING_REQUESTS[h]
    
    # 检查是否存在
    if request_hash in PENDING_REQUESTS:
        existing = PENDING_REQUESTS[request_hash]
        return {
            "is_duplicate": True,
            "original_request_id": existing["request_id"],
            "original_timestamp": existing["timestamp"],
            "time_diff_seconds": round(now - existing["timestamp"], 3)
        }
    
    return {"is_duplicate": False}

def register_request(request_hash: str, request_id: str, endpoint: str):
    """注册请求"""
    PENDING_REQUESTS[request_hash] = {
        "timestamp": time.time(),
        "request_id": request_id,
        "endpoint": endpoint
    }
    
    # 限制大小
    if len(PENDING_REQUESTS) > DEDUPLICATION_CONFIG["max_pending_requests"]:
        # 移除最旧的
        oldest = min(PENDING_REQUESTS.items(), key=lambda x: x[1]["timestamp"])
        del PENDING_REQUESTS[oldest[0]]

