@app.post("/api/circuit/reset/{endpoint:path}")
async def reset_circuit_endpoint(endpoint: str):
    """重置端点熔断状态"""
    if endpoint in CIRCUIT_BREAKER_STATS["by_endpoint"]:
        state = CIRCUIT_BREAKER_STATS["by_endpoint"][endpoint]
        state["state"] = CIRCUIT_BREAKER_STATES["closed"]
        state["failures"] = 0
        state["successes"] = 0
        state["consecutive_failures"] = 0
        state["consecutive_successes"] = 0
        state["last_state_change"] = time.time()
        
        return {"success": True, "message": f"端点 {endpoint} 熔断状态已重置"}
    
    return {"success": False, "message": f"端点 {endpoint} 不存在"}

@app.post("/api/circuit/open/{endpoint:path}")
async def manually_open_circuit(endpoint: str):
    """手动打开熔断"""
    state = get_circuit_state(endpoint)
    state["state"] = CIRCUIT_BREAKER_STATES["open"]
    state["last_state_change"] = time.time()
    CIRCUIT_BREAKER_STATS["total_circuit_opens"] += 1
    
    return {"success": True, "message": f"端点 {endpoint} 熔断已手动打开"}

@app.post("/api/circuit/close/{endpoint:path}")
async def manually_close_circuit(endpoint: str):
    """手动关闭熔断"""
    state = get_circuit_state(endpoint)
    state["state"] = CIRCUIT_BREAKER_STATES["closed"]
    state["last_state_change"] = time.time()
    state["failures"] = 0
    state["consecutive_failures"] = 0
    
    return {"success": True, "message": f"端点 {endpoint} 熔断已手动关闭"}

