@app.post("/api/circuit/test")
async def test_circuit_breaker(request: Request):
    """测试熔断功能"""
    data = await request.json()
    endpoint = data.get("endpoint", "/test/circuit")
    action = data.get("action", "check")  # check, success, failure
    
    if action == "check":
        result = check_circuit(endpoint)
        return {"success": True, "check": result}
    elif action == "success":
        record_success(endpoint)
        state = get_circuit_state(endpoint)
        return {"success": True, "state": state["state"]}
    elif action == "failure":
        record_failure(endpoint)
        state = get_circuit_state(endpoint)
        return {"success": True, "state": state["state"]}
    
    return {"success": False, "message": "无效操作"}

# ========== API负载均衡机制 ==========

LOAD_BALANCER_CONFIG = {
    "enabled": True,
    "strategy": "round_robin",  # round_robin, weighted, least_connections, random
    "health_check_interval_seconds": 30,
    "health_check_timeout_seconds": 5,
    "unhealthy_threshold": 3,
    "healthy_threshold": 2,
    "retry_count": 2,
    "retry_delay_ms": 100
}

BACKEND_SERVERS = {
    # server_id -> {url, weight, connections, healthy, last_check, failures, successes}
}

LOAD_BALANCER_STATS = {
    "total_requests": 0,
    "total_rerouted": 0,
    "total_failures": 0,
    "by_server": {}
}

_current_server_index = 0

def get_next_server(strategy: str = None) -> dict:
    """获取下一个服务器"""
    global _current_server_index
    
    if not LOAD_BALANCER_CONFIG["enabled"]:
        return None
    
    strategy = strategy or LOAD_BALANCER_CONFIG["strategy"]
    healthy_servers = [s for s_id, s in BACKEND_SERVERS.items() if s.get("healthy", True)]
    
    if not healthy_servers:
        return None
    
    if strategy == "round_robin":
        server = healthy_servers[_current_server_index % len(healthy_servers)]
        _current_server_index += 1
        return server
    
    elif strategy == "weighted":
        # 加权随机选择
        import random
        total_weight = sum(s.get("weight", 1) for s in healthy_servers)
        r = random.uniform(0, total_weight)
        current = 0
        for server in healthy_servers:
            current += server.get("weight", 1)
            if current >= r:
                return server
        return healthy_servers[0]
    
    elif strategy == "least_connections":
        # 最少连接
        return min(healthy_servers, key=lambda s: s.get("connections", 0))
    
    elif strategy == "random":
        import random
        return random.choice(healthy_servers)
    
    return healthy_servers[0]

def update_server_connections(server_id: str, delta: int):
    """更新服务器连接数"""
    if server_id in BACKEND_SERVERS:
        BACKEND_SERVERS[server_id]["connections"] = max(0, BACKEND_SERVERS[server_id].get("connections", 0) + delta)

def record_server_result(server_id: str, success: bool):
    """记录服务器请求结果"""
    if server_id not in LOAD_BALANCER_STATS["by_server"]:
        LOAD_BALANCER_STATS["by_server"][server_id] = {
            "requests": 0, "successes": 0, "failures": 0
        }
    
    LOAD_BALANCER_STATS["by_server"][server_id]["requests"] += 1
    if success:
        LOAD_BALANCER_STATS["by_server"][server_id]["successes"] += 1
    else:
        LOAD_BALANCER_STATS["by_server"][server_id]["failures"] += 1

