@app.post("/api/lb/servers/{server_id}/health")
async def check_server_health(server_id: str):
    """检查服务器健康状态"""
    if server_id not in BACKEND_SERVERS:
        return {"success": False, "message": f"服务器 {server_id} 不存在"}
    
    server = BACKEND_SERVERS[server_id]
    
    # 模拟健康检查
    try:
        # 实际应使用连接池发送请求
        is_healthy = True  # 简化处理
        server["last_check"] = time.time()
        
        if is_healthy:
            server["successes"] = server.get("successes", 0) + 1
            server["failures"] = 0
            if server["successes"] >= LOAD_BALANCER_CONFIG["healthy_threshold"]:
                server["healthy"] = True
        else:
            server["failures"] = server.get("failures", 0) + 1
            server["successes"] = 0
            if server["failures"] >= LOAD_BALANCER_CONFIG["unhealthy_threshold"]:
                server["healthy"] = False
        
        return {
            "success": True,
            "server_id": server_id,
            "healthy": server["healthy"],
            "last_check": server["last_check"]
        }
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }

