# ========== API服务发现机制 ==========

SERVICE_DISCOVERY_CONFIG = {
    "enabled": True,
    "registry_type": "memory",  # memory, file, consul, etcd
    "heartbeat_interval_seconds": 10,
    "heartbeat_timeout_seconds": 30,
    "refresh_interval_seconds": 5,
    "namespace": "default"
}

SERVICE_REGISTRY = {
    # service_name -> [{instance_id, host, port, metadata, healthy, last_heartbeat}]
}

SERVICE_DISCOVERY_STATS = {
    "total_services": 0,
    "total_instances": 0,
    "healthy_instances": 0,
    "total_lookups": 0,
    "total_registrations": 0,
    "total_deregistrations": 0
}

def register_service_instance(service_name: str, host: str, port: int, 
                              metadata: dict = None) -> str:
    """注册服务实例"""
    instance_id = f"{service_name}-{host}:{port}"
    
    if service_name not in SERVICE_REGISTRY:
        SERVICE_REGISTRY[service_name] = []
    
    # 检查是否已存在
    for instance in SERVICE_REGISTRY[service_name]:
        if instance["instance_id"] == instance_id:
            instance["last_heartbeat"] = time.time()
            instance["healthy"] = True
            return instance_id
    
    # 新实例
    instance = {
        "instance_id": instance_id,
        "host": host,
        "port": port,
        "metadata": metadata or {},
        "healthy": True,
        "last_heartbeat": time.time(),
        "registered_at": time.time()
    }
    
    SERVICE_REGISTRY[service_name].append(instance)
    SERVICE_DISCOVERY_STATS["total_registrations"] += 1
    
    return instance_id

def deregister_service_instance(service_name: str, instance_id: str) -> bool:
    """注销服务实例"""
    if service_name not in SERVICE_REGISTRY:
        return False
    
    for i, instance in enumerate(SERVICE_REGISTRY[service_name]):
        if instance["instance_id"] == instance_id:
            SERVICE_REGISTRY[service_name].pop(i)
            SERVICE_DISCOVERY_STATS["total_deregistrations"] += 1
            return True
    
    return False

def discover_service(service_name: str, healthy_only: bool = True) -> list:
    """发现服务实例"""
    SERVICE_DISCOVERY_STATS["total_lookups"] += 1
    
    if service_name not in SERVICE_REGISTRY:
        return []
    
    instances = SERVICE_REGISTRY[service_name]
    
    if healthy_only:
        return [i for i in instances if i["healthy"]]
    
    return instances

def send_heartbeat(service_name: str, instance_id: str) -> bool:
    """发送心跳"""
    if service_name not in SERVICE_REGISTRY:
        return False
    
    for instance in SERVICE_REGISTRY[service_name]:
        if instance["instance_id"] == instance_id:
            instance["last_heartbeat"] = time.time()
            instance["healthy"] = True
            return True
    
    return False

def check_instance_health():
    """检查实例健康状态"""
    now = time.time()
    timeout = SERVICE_DISCOVERY_CONFIG["heartbeat_timeout_seconds"]
    
    for service_name, instances in SERVICE_REGISTRY.items():
        for instance in instances:
            if now - instance["last_heartbeat"] > timeout:
                instance["healthy"] = False

def get_service_stats() -> dict:
    """获取服务统计"""
    total_services = len(SERVICE_REGISTRY)
    total_instances = sum(len(instances) for instances in SERVICE_REGISTRY.values())
    healthy_instances = sum(
        len([i for i in instances if i["healthy"]])
        for instances in SERVICE_REGISTRY.values()
    )
    
    return {
        "total_services": total_services,
        "total_instances": total_instances,
        "healthy_instances": healthy_instances,
        "unhealthy_instances": total_instances - healthy_instances
    }

