@app.post("/api/discovery/heartbeat")
async def heartbeat(request: Request):
    """发送心跳"""
    data = await request.json()
    
    service_name = data.get("service_name")
    instance_id = data.get("instance_id")
    
    if not service_name or not instance_id:
        return {"success": False, "message": "service_name and instance_id are required"}
    
    success = send_heartbeat(service_name, instance_id)
    
    if success:
        return {"success": True, "message": "心跳已更新"}
    return {"success": False, "message": "实例不存在"}

