# ========== API分布式追踪机制 ==========

DISTRIBUTED_TRACING_CONFIG = {
    "enabled": True,
    "sample_rate": 1.0,  # 采样率 0-1
    "max_spans_per_trace": 100,
    "trace_retention_seconds": 3600,  # 追踪保留时间
    "propagation_format": "w3c",  # w3c, b3, jaeger
    "collect_headers": True
}

TRACES = {
    # trace_id -> {spans, start_time, duration, status}
}

TRACING_STATS = {
    "total_traces": 0,
    "total_spans": 0,
    "active_traces": 0,
    "sampled_traces": 0,
    "dropped_traces": 0,
    "by_service": {}
}

def generate_trace_id() -> str:
    """生成追踪ID"""
    import secrets
    return secrets.token_hex(16)

def generate_span_id() -> str:
    """生成Span ID"""
    import secrets
    return secrets.token_hex(8)

def start_span(trace_id: str, span_id: str, parent_span_id: str,
               service_name: str, operation: str, start_time: float) -> dict:
    """开始Span"""
    return {
        "trace_id": trace_id,
        "span_id": span_id,
        "parent_span_id": parent_span_id,
        "service_name": service_name,
        "operation": operation,
        "start_time": start_time,
        "end_time": None,
        "duration_ms": None,
        "status": "ok",
        "tags": {},
        "logs": []
    }

def end_span(span: dict, end_time: float = None, status: str = "ok"):
    """结束Span"""
    span["end_time"] = end_time or time.time()
    span["duration_ms"] = round((span["end_time"] - span["start_time"]) * 1000, 2)
    span["status"] = status

def should_sample() -> bool:
    """决定是否采样"""
    import random
    return random.random() <= DISTRIBUTED_TRACING_CONFIG["sample_rate"]

def record_trace(trace_id: str, span: dict):
    """记录追踪"""
    if trace_id not in TRACES:
        TRACES[trace_id] = {
            "spans": [],
            "start_time": span["start_time"],
            "end_time": None,
            "duration_ms": None,
            "status": "ok",
            "service_count": {}
        }
        TRACING_STATS["total_traces"] += 1
        TRACING_STATS["active_traces"] += 1
    
    TRACES[trace_id]["spans"].append(span)
    
    # 更新服务计数
    service = span["service_name"]
    if service not in TRACES[trace_id]["service_count"]:
        TRACES[trace_id]["service_count"][service] = 0
    TRACES[trace_id]["service_count"][service] += 1
    
    # 更新统计
    TRACING_STATS["total_spans"] += 1
    
    if service not in TRACING_STATS["by_service"]:
        TRACING_STATS["by_service"][service] = {"traces": 0, "spans": 0}
    TRACING_STATS["by_service"][service]["spans"] += 1

def finish_trace(trace_id: str, status: str = "ok"):
    """完成追踪"""
    if trace_id in TRACES:
        trace = TRACES[trace_id]
        trace["end_time"] = time.time()
        trace["duration_ms"] = round((trace["end_time"] - trace["start_time"]) * 1000, 2)
        trace["status"] = status
        TRACING_STATS["active_traces"] -= 1

def cleanup_old_traces():
    """清理过期追踪"""
    now = time.time()
    retention = DISTRIBUTED_TRACING_CONFIG["trace_retention_seconds"]
    
    expired = [tid for tid, t in TRACES.items() 
               if t.get("end_time") and now - t["end_time"] > retention]
    
    for tid in expired:
        del TRACES[tid]

@app.get("/api/tracing/config")
async def get_tracing_config():
    """获取分布式追踪配置"""
    return {
        "success": True,
        "config": DISTRIBUTED_TRACING_CONFIG
    }

@app.post("/api/tracing/config")
async def set_tracing_config(request: Request):
    """设置分布式追踪配置"""
    data = await request.json()
    
    if "enabled" in data:
        DISTRIBUTED_TRACING_CONFIG["enabled"] = data["enabled"]
    if "sample_rate" in data:
        DISTRIBUTED_TRACING_CONFIG["sample_rate"] = min(1.0, max(0.0, data["sample_rate"]))
    if "max_spans_per_trace" in data:
        DISTRIBUTED_TRACING_CONFIG["max_spans_per_trace"] = data["max_spans_per_trace"]
    if "trace_retention_seconds" in data:
        DISTRIBUTED_TRACING_CONFIG["trace_retention_seconds"] = data["trace_retention_seconds"]
    if "propagation_format" in data:
        DISTRIBUTED_TRACING_CONFIG["propagation_format"] = data["propagation_format"]
    if "collect_headers" in data:
        DISTRIBUTED_TRACING_CONFIG["collect_headers"] = data["collect_headers"]
    
    return {
        "success": True,
        "config": DISTRIBUTED_TRACING_CONFIG
    }

@app.post("/api/tracing/start")
async def start_trace_endpoint(request: Request):
    """开始追踪"""
    data = await request.json()
    
    if not should_sample():
        TRACING_STATS["dropped_traces"] += 1
        return {"success": True, "sampled": False}
    
    trace_id = data.get("trace_id") or generate_trace_id()
    span_id = generate_span_id()
    parent_span_id = data.get("parent_span_id")
    service_name = data.get("service_name", "unknown")
    operation = data.get("operation", "unknown")
    
    span = start_span(trace_id, span_id, parent_span_id, service_name, operation, time.time())
    record_trace(trace_id, span)
    TRACING_STATS["sampled_traces"] += 1
    
    if service_name not in TRACING_STATS["by_service"]:
        TRACING_STATS["by_service"][service_name] = {"traces": 0, "spans": 0}
    TRACING_STATS["by_service"][service_name]["traces"] += 1
    
    return {
        "success": True,
        "sampled": True,
        "trace_id": trace_id,
        "span_id": span_id
    }

@app.post("/api/tracing/span")
async def add_span_endpoint(request: Request):
    """添加Span"""
    data = await request.json()
    
    trace_id = data.get("trace_id")
    if not trace_id or trace_id not in TRACES:
        return {"success": False, "message": "trace_id is required and must exist"}
    
    trace = TRACES[trace_id]
    if len(trace["spans"]) >= DISTRIBUTED_TRACING_CONFIG["max_spans_per_trace"]:
        return {"success": False, "message": "max spans per trace exceeded"}
    
    span_id = generate_span_id()
    parent_span_id = data.get("parent_span_id")
    service_name = data.get("service_name", "unknown")
    operation = data.get("operation", "unknown")
    
    span = start_span(trace_id, span_id, parent_span_id, service_name, operation, time.time())
    record_trace(trace_id, span)
    
    return {
        "success": True,
        "span_id": span_id
    }

@app.post("/api/tracing/end")
async def end_trace_endpoint(request: Request):
    """结束追踪"""
    data = await request.json()
    
    trace_id = data.get("trace_id")
    span_id = data.get("span_id")
    status = data.get("status", "ok")
    
    if trace_id and trace_id in TRACES:
        # 结束特定span
        if span_id:
            for span in TRACES[trace_id]["spans"]:
                if span["span_id"] == span_id:
                    end_span(span, status=status)
                    break
        
        # 如果没有span_id，结束整个trace
        if not span_id:
            finish_trace(trace_id, status)
        
        return {"success": True}
    
    return {"success": False, "message": "trace not found"}

@app.get("/api/tracing/traces")
async def list_traces(limit: int = 50, status: str = None):
    """列出追踪"""
    traces = []
    
    for trace_id, trace in list(TRACES.items())[:limit]:
        if status and trace.get("status") != status:
            continue
        
        traces.append({
            "trace_id": trace_id,
            "span_count": len(trace["spans"]),
            "duration_ms": trace.get("duration_ms"),
            "status": trace.get("status"),
            "services": list(trace.get("service_count", {}).keys()),
            "start_time": trace["start_time"]
        })
    
    return {
        "success": True,
        "total_traces": len(TRACES),
        "traces": traces
    }

