# ========== API混沌工程-故障注入 ==========

CHAOS_CONFIG = {
    "enabled": False,  # 默认关闭，需要手动开启
    "default_duration_seconds": 60,
    "max_duration_seconds": 300,
    "probability": 0.1,  # 故障注入概率
    "allowed_endpoints": ["*"],  # 允许注入的端点
    "blocked_endpoints": ["/api/health", "/api/status"]  # 禁止注入的端点
}

CHAOS_EXPERIMENTS = {
    # experiment_id -> {type, config, status, start_time, end_time}
}

CHAOS_STATS = {
    "total_experiments": 0,
    "active_experiments": 0,
    "total_faults_injected": 0,
    "by_type": {},
    "by_endpoint": {}
}

FAULT_TYPES = {
    "latency": {
        "description": "延迟注入",
        "config": {"min_ms": 100, "max_ms": 5000}
    },
    "error_500": {
        "description": "500错误注入",
        "config": {"error_rate": 0.5}
    },
    "error_503": {
        "description": "503服务不可用",
        "config": {"error_rate": 0.5}
    },
    "error_429": {
        "description": "429限流错误",
        "config": {"error_rate": 0.3}
    },
    "timeout": {
        "description": "超时注入",
        "config": {"timeout_seconds": 30}
    },
    "connection_reset": {
        "description": "连接重置",
        "config": {"probability": 0.1}
    },
    "memory_pressure": {
        "description": "内存压力",
        "config": {"mb": 100}
    },
    "cpu_stress": {
        "description": "CPU压力",
        "config": {"percent": 50, "duration_seconds": 10}
    }
}

def should_inject_fault(endpoint: str) -> bool:
    """判断是否应该注入故障"""
    if not CHAOS_CONFIG["enabled"]:
        return False
    
    # 检查是否在禁止列表
    if endpoint in CHAOS_CONFIG["blocked_endpoints"]:
        return False
    
    # 检查是否在允许列表
    if "*" not in CHAOS_CONFIG["allowed_endpoints"]:
        if endpoint not in CHAOS_CONFIG["allowed_endpoints"]:
            return False
    
    import random
    return random.random() < CHAOS_CONFIG["probability"]

def inject_latency(min_ms: int, max_ms: int):
    """注入延迟"""
    import random
    import asyncio
    delay = random.randint(min_ms, max_ms) / 1000
    return delay

def get_error_response(fault_type: str):
    """获取错误响应"""
    from fastapi.responses import JSONResponse
    
    if fault_type == "error_500":
        return JSONResponse(
            status_code=500,
            content={"error": "Internal Server Error (Chaos Injected)"}
        )
    elif fault_type == "error_503":
        return JSONResponse(
            status_code=503,
            content={"error": "Service Unavailable (Chaos Injected)"}
        )
    elif fault_type == "error_429":
        return JSONResponse(
            status_code=429,
            content={"error": "Too Many Requests (Chaos Injected)"}
        )
    
    return None

def create_experiment(experiment_type: str, config: dict, 
                      endpoints: list, duration: int) -> str:
    """创建混沌实验"""
    import secrets
    experiment_id = f"exp_{secrets.token_hex(4)}"
    
    CHAOS_EXPERIMENTS[experiment_id] = {
        "id": experiment_id,
        "type": experiment_type,
        "config": config,
        "endpoints": endpoints,
        "duration_seconds": duration,
        "status": "created",
        "start_time": None,
        "end_time": None,
        "faults_injected": 0
    }
    
    CHAOS_STATS["total_experiments"] += 1
    
    if experiment_type not in CHAOS_STATS["by_type"]:
        CHAOS_STATS["by_type"][experiment_type] = 0
    
    return experiment_id

def start_experiment(experiment_id: str) -> bool:
    """启动实验"""
    if experiment_id not in CHAOS_EXPERIMENTS:
        return False
    
    experiment = CHAOS_EXPERIMENTS[experiment_id]
    experiment["status"] = "running"
    experiment["start_time"] = time.time()
    experiment["end_time"] = experiment["start_time"] + experiment["duration_seconds"]
    
    CHAOS_STATS["active_experiments"] += 1
    
    return True

def stop_experiment(experiment_id: str) -> bool:
    """停止实验"""
    if experiment_id not in CHAOS_EXPERIMENTS:
        return False
    
    experiment = CHAOS_EXPERIMENTS[experiment_id]
    if experiment["status"] == "running":
        experiment["status"] = "stopped"
        experiment["end_time"] = time.time()
        CHAOS_STATS["active_experiments"] -= 1
    
    return True

def record_fault_injection(experiment_id: str, endpoint: str):
    """记录故障注入"""
    if experiment_id in CHAOS_EXPERIMENTS:
        CHAOS_EXPERIMENTS[experiment_id]["faults_injected"] += 1
    
    CHAOS_STATS["total_faults_injected"] += 1
    
    if endpoint not in CHAOS_STATS["by_endpoint"]:
        CHAOS_STATS["by_endpoint"][endpoint] = 0
    CHAOS_STATS["by_endpoint"][endpoint] += 1

