    endpoint = data.get("endpoint", "/test")
    duration_ms = data.get("duration_ms", 1000)
    
    if fault_type not in FAULT_TYPES:
        return {"success": False, "message": f"invalid fault_type: {fault_type}"}
    
    CHAOS_STATS["total_faults_injected"] += 1
    
    if fault_type not in CHAOS_STATS["by_type"]:
        CHAOS_STATS["by_type"][fault_type] = 0
    CHAOS_STATS["by_type"][fault_type] += 1
    
    if fault_type == "latency":
        import asyncio
        await asyncio.sleep(duration_ms / 1000)
        return {"success": True, "message": f"延迟注入 {duration_ms}ms"}
    
    elif fault_type in ["error_500", "error_503", "error_429"]:
        return get_error_response(fault_type)
    
    return {"success": True, "message": f"故障 {fault_type} 已注入"}

