# ========== API金丝雀发布机制 ==========

CANARY_CONFIG = {
    "enabled": True,
    "default_traffic_percentage": 10,  # 默认金丝雀流量比例
    "max_traffic_percentage": 50,  # 最大金丝雀流量比例
    "auto_promote": False,  # 自动提升
    "auto_rollback": True,  # 自动回滚
    "error_rate_threshold": 0.05,  # 错误率阈值
    "latency_threshold_ms": 1000,  # 延迟阈值
    "evaluation_period_seconds": 300,  # 评估周期
    "promotion_steps": [10, 25, 50, 100]  # 提升步骤
}

CANARY_DEPLOYMENTS = {
    # deployment_id -> {version, status, traffic_percent, metrics, start_time}
}

CANARY_STATS = {
    "total_deployments": 0,
    "active_deployments": 0,
    "successful_promotions": 0,
    "rollbacks": 0,
    "total_requests_routed": 0,
    "by_version": {}
}

def create_canary_deployment(version: str, target_version: str, 
                             traffic_percent: int, config: dict = None) -> str:
    """创建金丝雀部署"""
    import secrets
    deployment_id = f"canary_{secrets.token_hex(4)}"
    
    CANARY_DEPLOYMENTS[deployment_id] = {
        "id": deployment_id,
        "version": version,
        "target_version": target_version,
        "traffic_percent": min(traffic_percent, CANARY_CONFIG["max_traffic_percentage"]),
        "config": config or {},
        "status": "created",
        "start_time": None,
        "end_time": None,
        "metrics": {
            "total_requests": 0,
            "errors": 0,
            "total_latency_ms": 0,
            "error_rate": 0,
            "avg_latency_ms": 0
        },
        "promotion_history": []
    }
    
    CANARY_STATS["total_deployments"] += 1
    
    if version not in CANARY_STATS["by_version"]:
        CANARY_STATS["by_version"][version] = {"deployments": 0, "requests": 0}
    CANARY_STATS["by_version"][version]["deployments"] += 1
    
    return deployment_id

def start_canary_deployment(deployment_id: str) -> bool:
    """启动金丝雀部署"""
    if deployment_id not in CANARY_DEPLOYMENTS:
        return False
    
    deployment = CANARY_DEPLOYMENTS[deployment_id]
    deployment["status"] = "running"
    deployment["start_time"] = time.time()
    
    CANARY_STATS["active_deployments"] += 1
    
    return True

def route_to_canary(deployment_id: str) -> bool:
    """决定是否路由到金丝雀版本"""
    if deployment_id not in CANARY_DEPLOYMENTS:
        return False
    
    deployment = CANARY_DEPLOYMENTS[deployment_id]
    if deployment["status"] != "running":
        return False
    
    import random
    return random.random() * 100 < deployment["traffic_percent"]

def record_canary_request(deployment_id: str, is_error: bool = False, 
                          latency_ms: float = 0):
    """记录金丝雀请求"""
    if deployment_id not in CANARY_DEPLOYMENTS:
        return
    
    deployment = CANARY_DEPLOYMENTS[deployment_id]
    metrics = deployment["metrics"]
    
    metrics["total_requests"] += 1
    CANARY_STATS["total_requests_routed"] += 1
    
    if is_error:
        metrics["errors"] += 1
    
    metrics["total_latency_ms"] += latency_ms
    
    # 更新计算指标
    metrics["error_rate"] = metrics["errors"] / metrics["total_requests"]
    metrics["avg_latency_ms"] = metrics["total_latency_ms"] / metrics["total_requests"]

def evaluate_canary_health(deployment_id: str) -> dict:
    """评估金丝雀健康状态"""
    if deployment_id not in CANARY_DEPLOYMENTS:
        return {"healthy": False, "reason": "deployment not found"}
    
    deployment = CANARY_DEPLOYMENTS[deployment_id]
    metrics = deployment["metrics"]
    
    issues = []
    
    # 检查错误率
    if metrics["error_rate"] > CANARY_CONFIG["error_rate_threshold"]:
        issues.append(f"error_rate {metrics['error_rate']:.2%} exceeds threshold")
    
    # 检查延迟
    if metrics["avg_latency_ms"] > CANARY_CONFIG["latency_threshold_ms"]:
        issues.append(f"latency {metrics['avg_latency_ms']:.0f}ms exceeds threshold")
    
    return {
        "healthy": len(issues) == 0,
        "issues": issues,
        "metrics": metrics
    }

def promote_canary(deployment_id: str, new_traffic: int = None) -> bool:
    """提升金丝雀流量"""
    if deployment_id not in CANARY_DEPLOYMENTS:
        return False
    
    deployment = CANARY_DEPLOYMENTS[deployment_id]
    
    if new_traffic is None:
        # 自动提升到下一阶段
        current = deployment["traffic_percent"]
        steps = CANARY_CONFIG["promotion_steps"]
        for step in steps:
            if step > current:
                new_traffic = step
                break
        if new_traffic is None:
            new_traffic = 100
    
    deployment["traffic_percent"] = min(new_traffic, CANARY_CONFIG["max_traffic_percentage"])
    deployment["promotion_history"].append({
        "time": time.time(),
        "traffic_percent": deployment["traffic_percent"]
    })
    
    if deployment["traffic_percent"] >= 100:
        deployment["status"] = "promoted"
        deployment["end_time"] = time.time()
        CANARY_STATS["active_deployments"] -= 1
        CANARY_STATS["successful_promotions"] += 1
    
    return True

def rollback_canary(deployment_id: str) -> bool:
    """回滚金丝雀部署"""
    if deployment_id not in CANARY_DEPLOYMENTS:
        return False
    
    deployment = CANARY_DEPLOYMENTS[deployment_id]
    deployment["status"] = "rolled_back"
    deployment["end_time"] = time.time()
    deployment["traffic_percent"] = 0
    
    if deployment["status"] == "running":
        CANARY_STATS["active_deployments"] -= 1
    
    CANARY_STATS["rollbacks"] += 1
    
    return True

def auto_evaluate_and_act(deployment_id: str):
    """自动评估并采取行动"""
    if not CANARY_CONFIG["auto_rollback"]:
        return
    
    result = evaluate_canary_health(deployment_id)
    
    if not result["healthy"]:
        rollback_canary(deployment_id)

