@app.post("/api/canary/deployments")
async def create_canary_deployment_endpoint(request: Request):
    """创建金丝雀部署"""
    data = await request.json()
    
    version = data.get("version")
    target_version = data.get("target_version")
    traffic_percent = data.get("traffic_percent", CANARY_CONFIG["default_traffic_percentage"])
    config = data.get("config")
    
    if not version or not target_version:
        return {"success": False, "message": "version and target_version are required"}
    
