def get_active_color() -> str:
    """获取当前活跃颜色"""
    return BLUE_GREEN_CONFIG["active_color"]

def get_inactive_color() -> str:
    """获取非活跃颜色"""
    return "green" if BLUE_GREEN_CONFIG["active_color"] == "blue" else "blue"

def create_blue_green_deployment(version: str, target_color: str = None) -> str:
    """创建蓝绿部署"""
    import secrets
    deployment_id = f"bg_{secrets.token_hex(4)}"
    
    if target_color is None:
        target_color = get_inactive_color()
    
    BLUE_GREEN_DEPLOYMENTS[deployment_id] = {
        "id": deployment_id,
        "version": version,
        "target_color": target_color,
        "status": "created",
        "created_time": time.time(),
        "deploy_time": None,
        "switch_time": None,
        "rollback_time": None
    }
    
    BLUE_GREEN_STATS["total_deployments"] += 1
    
    return deployment_id

def deploy_to_environment(deployment_id: str) -> bool:
    """部署到目标环境"""
    if deployment_id not in BLUE_GREEN_DEPLOYMENTS:
        return False
    
    deployment = BLUE_GREEN_DEPLOYMENTS[deployment_id]
    target_color = deployment["target_color"]
    
    # 更新环境状态
    DEPLOYMENT_ENVIRONMENTS[target_color]["version"] = deployment["version"]
    DEPLOYMENT_ENVIRONMENTS[target_color]["status"] = "deploying"
    DEPLOYMENT_ENVIRONMENTS[target_color]["last_deploy_time"] = time.time()
    
    deployment["status"] = "deployed"
    deployment["deploy_time"] = time.time()
    
    return True

def check_environment_health(color: str) -> dict:
    """检查环境健康状态"""
    env = DEPLOYMENT_ENVIRONMENTS[color]
    
    # 简化健康检查逻辑
    if env["status"] == "deploying":
        env["health_status"] = "checking"
    elif env["version"] is None:
        env["health_status"] = "no_version"
    else:
        env["health_status"] = "healthy"
    
    return {
        "color": color,
        "status": env["status"],
        "health_status": env["health_status"],
        "version": env["version"]
    }

def switch_traffic(deployment_id: str) -> bool:
    """切换流量"""
    if deployment_id not in BLUE_GREEN_DEPLOYMENTS:
        return False
    
    deployment = BLUE_GREEN_DEPLOYMENTS[deployment_id]
    target_color = deployment["target_color"]
    
    # 检查目标环境健康
    if BLUE_GREEN_CONFIG["require_health_check"]:
        health = check_environment_health(target_color)
        if health["health_status"] != "healthy":
            deployment["status"] = "switch_failed"
            BLUE_GREEN_STATS["failed_switches"] += 1
            return False
    
    # 执行切换
    old_color = BLUE_GREEN_CONFIG["active_color"]
    BLUE_GREEN_CONFIG["active_color"] = target_color
    
    # 更新环境状态
    DEPLOYMENT_ENVIRONMENTS[old_color]["status"] = "inactive"
    DEPLOYMENT_ENVIRONMENTS[target_color]["status"] = "active"
    
    deployment["status"] = "switched"
    deployment["switch_time"] = time.time()
    
    BLUE_GREEN_STATS["total_switches"] += 1
    BLUE_GREEN_STATS["successful_switches"] += 1
    BLUE_GREEN_STATS["by_color"][target_color] += 1
    
    return True

def rollback_deployment(deployment_id: str) -> bool:
    """回滚部署"""
    if deployment_id not in BLUE_GREEN_DEPLOYMENTS:
        return False
    
    deployment = BLUE_GREEN_DEPLOYMENTS[deployment_id]
    
    # 切换回原来的颜色
    current_color = BLUE_GREEN_CONFIG["active_color"]
    rollback_color = get_inactive_color()
    
    BLUE_GREEN_CONFIG["active_color"] = rollback_color
    
    DEPLOYMENT_ENVIRONMENTS[current_color]["status"] = "inactive"
    DEPLOYMENT_ENVIRONMENTS[rollback_color]["status"] = "active"
    
    deployment["status"] = "rolled_back"
    deployment["rollback_time"] = time.time()
    
    BLUE_GREEN_STATS["rollbacks"] += 1
    
    return True

def complete_deployment(deployment_id: str) -> bool:
    """完成部署"""
    if deployment_id not in BLUE_GREEN_DEPLOYMENTS:
        return False
    
    deployment = BLUE_GREEN_DEPLOYMENTS[deployment_id]
    deployment["status"] = "completed"
    
    # 清理非活跃环境
    inactive_color = get_inactive_color()
    DEPLOYMENT_ENVIRONMENTS[inactive_color]["status"] = "idle"
    
    return True

