@app.post("/api/bluegreen/deployments")
async def create_bluegreen_deployment_endpoint(request: Request):
    """创建蓝绿部署"""
    data = await request.json()
    
    version = data.get("version")
    target_color = data.get("target_color")
    
    if not version:
        return {"success": False, "message": "version is required"}
    
    if target_color and target_color not in ["blue", "green"]:
        return {"success": False, "message": "target_color must be blue or green"}
    
    deployment_id = create_blue_green_deployment(version, target_color)
    
    return {
        "success": True,
        "deployment_id": deployment_id,
        "deployment": BLUE_GREEN_DEPLOYMENTS[deployment_id]
    }

