@app.post("/api/bluegreen/switch")
async def manual_switch_endpoint(request: Request):
    """手动切换"""
    data = await request.json()
    target_color = data.get("target_color")
    
    if target_color not in ["blue", "green"]:
        return {"success": False, "message": "target_color must be blue or green"}
    
    if target_color == BLUE_GREEN_CONFIG["active_color"]:
        return {"success": True, "message": "already active", "active_color": target_color}
    
    old_color = BLUE_GREEN_CONFIG["active_color"]
    BLUE_GREEN_CONFIG["active_color"] = target_color
    
    DEPLOYMENT_ENVIRONMENTS[old_color]["status"] = "inactive"
    DEPLOYMENT_ENVIRONMENTS[target_color]["status"] = "active"
    
    BLUE_GREEN_STATS["total_switches"] += 1
    BLUE_GREEN_STATS["by_color"][target_color] += 1
    
    return {
        "success": True,
        "active_color": target_color,
        "previous_color": old_color
    }

