# ========== API A/B测试机制 ==========

AB_TEST_CONFIG = {
    "enabled": True,
    "default_traffic_split": 50,  # 默认流量分配 50/50
    "min_sample_size": 100,  # 最小样本量
    "confidence_level": 0.95,  # 置信水平
    "auto_winner": False,  # 自动选择胜者
    "test_duration_hours": 24  # 测试持续时间
}

AB_TESTS = {
    # test_id -> {name, variants, status, metrics, ...}
}

AB_STATS = {
    "total_tests": 0,
    "active_tests": 0,
    "completed_tests": 0,
    "total_participants": 0,
    "winners_selected": 0
}

def create_ab_test(name: str, variants: list, config: dict = None) -> str:
    """创建A/B测试"""
    import secrets
    test_id = f"ab_{secrets.token_hex(4)}"
    
    # 验证变体配置
    total_traffic = sum(v.get("traffic_percent", 0) for v in variants)
    if total_traffic != 100:
        # 自动调整流量分配
        base_percent = 100 // len(variants)
        for i, v in enumerate(variants):
            v["traffic_percent"] = base_percent if i < len(variants) - 1 else 100 - base_percent * (len(variants) - 1)
    
    AB_TESTS[test_id] = {
        "id": test_id,
        "name": name,
        "variants": variants,
        "config": config or {},
        "status": "created",
        "created_time": time.time(),
        "start_time": None,
        "end_time": None,
        "winner": None,
        "metrics": {
            "total_participants": 0,
            "conversions": 0,
            "by_variant": {}
        }
    }
    
    # 初始化变体指标
    for v in variants:
        variant_id = v.get("id", v.get("name", "default"))
        AB_TESTS[test_id]["metrics"]["by_variant"][variant_id] = {
            "participants": 0,
            "conversions": 0,
            "conversion_rate": 0,
            "total_value": 0
        }
    
    AB_STATS["total_tests"] += 1
    
    return test_id

def start_ab_test(test_id: str) -> bool:
    """启动A/B测试"""
    if test_id not in AB_TESTS:
        return False
    
    test = AB_TESTS[test_id]
    test["status"] = "running"
    test["start_time"] = time.time()
    test["end_time"] = test["start_time"] + AB_TEST_CONFIG["test_duration_hours"] * 3600
    
    AB_STATS["active_tests"] += 1
    
    return True

def assign_variant(test_id: str, user_id: str = None) -> str:
    """分配变体给用户"""
    if test_id not in AB_TESTS:
        return None
    
    test = AB_TESTS[test_id]
    if test["status"] != "running":
        return None
    
    import random
    import hashlib
    
    # 使用用户ID或随机分配
    if user_id:
        # 确保同一用户始终分配到同一变体
        hash_val = int(hashlib.md5(f"{test_id}{user_id}".encode()).hexdigest(), 16)
        rand_val = (hash_val % 100) / 100
    else:
        rand_val = random.random()
    
    # 根据流量分配选择变体
    cumulative = 0
    for variant in test["variants"]:
        cumulative += variant.get("traffic_percent", 0) / 100
        if rand_val <= cumulative:
            return variant.get("id", variant.get("name"))
    
    return test["variants"][-1].get("id", test["variants"][-1].get("name"))

def record_ab_event(test_id: str, variant_id: str, event_type: str = "participation", value: float = 0):
    """记录A/B测试事件"""
    if test_id not in AB_TESTS:
        return
    
    test = AB_TESTS[test_id]
    
    if event_type == "participation":
        test["metrics"]["total_participants"] += 1
        AB_STATS["total_participants"] += 1
        
        if variant_id in test["metrics"]["by_variant"]:
            test["metrics"]["by_variant"][variant_id]["participants"] += 1
    
    elif event_type == "conversion":
        test["metrics"]["conversions"] += 1
        
        if variant_id in test["metrics"]["by_variant"]:
            test["metrics"]["by_variant"][variant_id]["conversions"] += 1
            test["metrics"]["by_variant"][variant_id]["total_value"] += value
    
    # 更新转化率
    for vid, vm in test["metrics"]["by_variant"].items():
        if vm["participants"] > 0:
            vm["conversion_rate"] = vm["conversions"] / vm["participants"]

def calculate_ab_results(test_id: str) -> dict:
    """计算A/B测试结果"""
    if test_id not in AB_TESTS:
        return {"success": False, "message": "test not found"}
    
    test = AB_TESTS[test_id]
    results = []
    
    for variant in test["variants"]:
        variant_id = variant.get("id", variant.get("name"))
        vm = test["metrics"]["by_variant"].get(variant_id, {})
        
        results.append({
            "variant_id": variant_id,
            "name": variant.get("name", variant_id),
            "participants": vm.get("participants", 0),
            "conversions": vm.get("conversions", 0),
            "conversion_rate": vm.get("conversion_rate", 0),
            "total_value": vm.get("total_value", 0)
        })
    
    # 找出最佳变体
    if results:
        best = max(results, key=lambda x: x["conversion_rate"])
        results.sort(key=lambda x: x["conversion_rate"], reverse=True)
    else:
        best = None
    
    return {
        "test_id": test_id,
        "status": test["status"],
        "total_participants": test["metrics"]["total_participants"],
        "best_variant": best,
        "all_variants": results
    }

def select_winner(test_id: str, variant_id: str = None) -> bool:
    """选择胜者"""
    if test_id not in AB_TESTS:
        return False
    
    test = AB_TESTS[test_id]
    
    if variant_id is None:
        # 自动选择最佳变体
        results = calculate_ab_results(test_id)
        if results.get("best_variant"):
            variant_id = results["best_variant"]["variant_id"]
        else:
            return False
    
    test["winner"] = variant_id
    test["status"] = "completed"
    test["end_time"] = time.time()
    
    AB_STATS["active_tests"] -= 1
    AB_STATS["completed_tests"] += 1
    AB_STATS["winners_selected"] += 1
    
    return True

@app.get("/api/abtest/config")
async def get_abtest_config():
    """获取A/B测试配置"""
    return {
        "success": True,
        "config": AB_TEST_CONFIG
    }

@app.post("/api/abtest/config")
async def set_abtest_config(request: Request):
    """设置A/B测试配置"""
    data = await request.json()
    
    if "enabled" in data:
        AB_TEST_CONFIG["enabled"] = data["enabled"]
    if "default_traffic_split" in data:
        AB_TEST_CONFIG["default_traffic_split"] = data["default_traffic_split"]
    if "min_sample_size" in data:
        AB_TEST_CONFIG["min_sample_size"] = data["min_sample_size"]
    if "confidence_level" in data:
        AB_TEST_CONFIG["confidence_level"] = data["confidence_level"]
    if "auto_winner" in data:
        AB_TEST_CONFIG["auto_winner"] = data["auto_winner"]
    if "test_duration_hours" in data:
        AB_TEST_CONFIG["test_duration_hours"] = data["test_duration_hours"]
    
    return {
        "success": True,
        "config": AB_TEST_CONFIG
    }

@app.post("/api/abtest/tests")
async def create_abtest_endpoint(request: Request):
    """创建A/B测试"""
    data = await request.json()
    
    name = data.get("name")
    variants = data.get("variants", [])
    config = data.get("config")
    
    if not name:
        return {"success": False, "message": "name is required"}
    
    if not variants or len(variants) < 2:
        return {"success": False, "message": "at least 2 variants are required"}
    
    test_id = create_ab_test(name, variants, config)
    
    return {
        "success": True,
        "test_id": test_id,
        "test": AB_TESTS[test_id]
    }

@app.get("/api/abtest/tests")
async def list_ab_tests(status: str = None):
    """列出A/B测试"""
    tests = []
    
    for tid, test in AB_TESTS.items():
        if status and test["status"] != status:
            continue
        tests.append(test)
    
    return {
        "success": True,
        "total_tests": len(tests),
        "tests": tests
    }

@app.get("/api/abtest/tests/{test_id}")
async def get_ab_test(test_id: str):
    """获取A/B测试详情"""
    if test_id not in AB_TESTS:
        return {"success": False, "message": "test not found"}
    
    return {
        "success": True,
        "test": AB_TESTS[test_id]
    }

@app.post("/api/abtest/tests/{test_id}/start")
async def start_abtest_endpoint(test_id: str):
    """启动A/B测试"""
    success = start_ab_test(test_id)
    
    if success:
        return {
            "success": True,
            "test": AB_TESTS[test_id]
        }
    
    return {"success": False, "message": "test not found"}

@app.post("/api/abtest/tests/{test_id}/assign")
async def assign_variant_endpoint(test_id: str, request: Request):
    """分配变体"""
    data = await request.json() if request else {}
    user_id = data.get("user_id")
    
    variant_id = assign_variant(test_id, user_id)
    
    if variant_id:
        # 记录参与
        record_ab_event(test_id, variant_id, "participation")
        
        return {
            "success": True,
            "test_id": test_id,
            "variant_id": variant_id
        }
    
    return {"success": False, "message": "test not running or not found"}

@app.post("/api/abtest/tests/{test_id}/convert")
async def record_conversion_endpoint(test_id: str, request: Request):
    """记录转化"""
    data = await request.json()
    
    variant_id = data.get("variant_id")
    value = data.get("value", 0)
    
    if not variant_id:
        return {"success": False, "message": "variant_id is required"}
    
    record_ab_event(test_id, variant_id, "conversion", value)
    
    return {
        "success": True,
        "metrics": AB_TESTS[test_id]["metrics"]["by_variant"].get(variant_id)
    }

@app.get("/api/abtest/tests/{test_id}/results")
async def get_abtest_results(test_id: str):
    """获取A/B测试结果"""
    result = calculate_ab_results(test_id)
    
    return {
        "success": True,
        **result
    }

@app.post("/api/abtest/tests/{test_id}/winner")
async def select_winner_endpoint(test_id: str, request: Request):
    """选择胜者"""
    data = await request.json() if request else {}
    variant_id = data.get("variant_id")
    
    success = select_winner(test_id, variant_id)
    
    if success:
        return {
            "success": True,
            "test": AB_TESTS[test_id]
        }
    
    return {"success": False, "message": "test not found"}

@app.post("/api/abtest/tests/{test_id}/stop")
async def stop_abtest_endpoint(test_id: str):
    """停止A/B测试"""
    if test_id not in AB_TESTS:
        return {"success": False, "message": "test not found"}
    
    test = AB_TESTS[test_id]
    if test["status"] == "running":
        test["status"] = "stopped"
        test["end_time"] = time.time()
        AB_STATS["active_tests"] -= 1
    
    return {
        "success": True,
        "test": test
    }

@app.delete("/api/abtest/tests/{test_id}")
async def delete_ab_test(test_id: str):
    """删除A/B测试"""
    if test_id not in AB_TESTS:
        return {"success": False, "message": "test not found"}
    
    test = AB_TESTS[test_id]
    if test["status"] == "running":
        AB_STATS["active_tests"] -= 1
    
    del AB_TESTS[test_id]
    
    return {"success": True, "message": f"test {test_id} deleted"}

