# ========== API功能开关管理 ==========

FEATURE_FLAGS = {
    # flag_name -> {enabled, description, conditions, created_time, modified_time}
}

FEATURE_FLAG_CONFIG = {
    "enabled": True,
    "cache_ttl_seconds": 60,  # 功能开关缓存TTL
    "allow_override": True,  # 允许请求级别覆盖
    "default_enabled": False  # 默认状态
}

FEATURE_FLAG_STATS = {
    "total_flags": 0,
    "enabled_flags": 0,
    "disabled_flags": 0,
    "total_evaluations": 0,
    "by_flag": {}
}

def create_feature_flag(name: str, enabled: bool = False, description: str = "", 
                        conditions: dict = None) -> bool:
    """创建功能开关"""
    if name in FEATURE_FLAGS:
        return False
    
    FEATURE_FLAGS[name] = {
        "name": name,
        "enabled": enabled,
        "description": description,
        "conditions": conditions or {},
        "created_time": time.time(),
        "modified_time": time.time(),
        "evaluation_count": 0
    }
    
    FEATURE_FLAG_STATS["total_flags"] += 1
    if enabled:
        FEATURE_FLAG_STATS["enabled_flags"] += 1
    else:
        FEATURE_FLAG_STATS["disabled_flags"] += 1
    
    FEATURE_FLAG_STATS["by_flag"][name] = {
        "evaluations": 0,
        "enabled_count": 0,
        "disabled_count": 0
    }
    
    return True

def evaluate_feature_flag(name: str, context: dict = None) -> bool:
    """评估功能开关"""
    if name not in FEATURE_FLAGS:
        return FEATURE_FLAG_CONFIG["default_enabled"]
    
    flag = FEATURE_FLAGS[name]
    flag["evaluation_count"] += 1
    
    FEATURE_FLAG_STATS["total_evaluations"] += 1
    FEATURE_FLAG_STATS["by_flag"][name]["evaluations"] += 1
    
    # 如果开关被禁用，直接返回False
    if not flag["enabled"]:
        FEATURE_FLAG_STATS["by_flag"][name]["disabled_count"] += 1
        return False
    
    # 检查条件
    conditions = flag.get("conditions", {})
    
    if not conditions:
        FEATURE_FLAG_STATS["by_flag"][name]["enabled_count"] += 1
        return True
    
    context = context or {}
    
    # 检查用户ID条件
    if "user_ids" in conditions:
        user_id = context.get("user_id")
        if user_id and user_id in conditions["user_ids"]:
            FEATURE_FLAG_STATS["by_flag"][name]["enabled_count"] += 1
            return True
    
    # 检查百分比条件
    if "percentage" in conditions:
        import random
        if random.random() * 100 < conditions["percentage"]:
            FEATURE_FLAG_STATS["by_flag"][name]["enabled_count"] += 1
            return True
    
    # 检查时间范围条件
    if "start_time" in conditions:
        if time.time() < conditions["start_time"]:
            FEATURE_FLAG_STATS["by_flag"][name]["disabled_count"] += 1
            return False
    
    if "end_time" in conditions:
        if time.time() > conditions["end_time"]:
            FEATURE_FLAG_STATS["by_flag"][name]["disabled_count"] += 1
            return False
    
    # 检查环境条件
    if "environments" in conditions:
        env = context.get("environment")
        if env and env in conditions["environments"]:
            FEATURE_FLAG_STATS["by_flag"][name]["enabled_count"] += 1
            return True
    
    FEATURE_FLAG_STATS["by_flag"][name]["enabled_count"] += 1
    return flag["enabled"]

def update_feature_flag(name: str, **kwargs) -> bool:
    """更新功能开关"""
    if name not in FEATURE_FLAGS:
        return False
    
    flag = FEATURE_FLAGS[name]
    old_enabled = flag["enabled"]
    
    if "enabled" in kwargs:
        flag["enabled"] = kwargs["enabled"]
    if "description" in kwargs:
        flag["description"] = kwargs["description"]
    if "conditions" in kwargs:
        flag["conditions"] = kwargs["conditions"]
    
    flag["modified_time"] = time.time()
    
    # 更新统计
    if old_enabled != flag["enabled"]:
        if flag["enabled"]:
            FEATURE_FLAG_STATS["enabled_flags"] += 1
            FEATURE_FLAG_STATS["disabled_flags"] -= 1
        else:
            FEATURE_FLAG_STATS["enabled_flags"] -= 1
            FEATURE_FLAG_STATS["disabled_flags"] += 1
    
    return True

def delete_feature_flag(name: str) -> bool:
    """删除功能开关"""
    if name not in FEATURE_FLAGS:
        return False
    
    flag = FEATURE_FLAGS[name]
    
    if flag["enabled"]:
        FEATURE_FLAG_STATS["enabled_flags"] -= 1
    else:
        FEATURE_FLAG_STATS["disabled_flags"] -= 1
    
    FEATURE_FLAG_STATS["total_flags"] -= 1
    del FEATURE_FLAG_STATS["by_flag"][name]
    del FEATURE_FLAGS[name]
    
    return True

