# ========== API多租户支持机制 ==========

TENANT_CONFIG = {
    "enabled": True,
    "default_tenant": "default",
    "isolation_level": "logical",  # logical, physical
    "max_tenants": 100,
    "tenant_id_header": "X-Tenant-ID",
    "auto_create": False  # 自动创建租户
}

TENANTS = {
    # tenant_id -> {name, status, config, quotas, created_time}
}

TENANT_STATS = {
    "total_tenants": 0,
    "active_tenants": 0,
    "total_requests": 0,
    "by_tenant": {}
}

def create_tenant(tenant_id: str, name: str, config: dict = None, 
                  quotas: dict = None) -> bool:
    """创建租户"""
    if tenant_id in TENANTS:
        return False
    
    if len(TENANTS) >= TENANT_CONFIG["max_tenants"]:
        return False
    
    TENANTS[tenant_id] = {
        "id": tenant_id,
        "name": name,
        "status": "active",
        "config": config or {},
        "quotas": quotas or {
            "max_requests_per_minute": 100,
            "max_requests_per_day": 10000,
            "max_storage_mb": 100,
            "max_sessions": 50
        },
        "usage": {
            "requests_this_minute": 0,
            "requests_today": 0,
            "storage_mb": 0,
            "sessions": 0
        },
        "created_time": time.time(),
        "modified_time": time.time()
    }
    
    TENANT_STATS["total_tenants"] += 1
    TENANT_STATS["active_tenants"] += 1
    
    TENANT_STATS["by_tenant"][tenant_id] = {
        "total_requests": 0,
        "errors": 0,
        "last_request_time": None
    }
    
    return True

def get_tenant(tenant_id: str) -> dict:
    """获取租户信息"""
    return TENANTS.get(tenant_id)

def update_tenant(tenant_id: str, **kwargs) -> bool:
    """更新租户"""
    if tenant_id not in TENANTS:
        return False
    
    tenant = TENANTS[tenant_id]
    
    if "name" in kwargs:
        tenant["name"] = kwargs["name"]
    if "status" in kwargs:
        old_status = tenant["status"]
        tenant["status"] = kwargs["status"]
        if old_status == "active" and kwargs["status"] != "active":
            TENANT_STATS["active_tenants"] -= 1
        elif old_status != "active" and kwargs["status"] == "active":
            TENANT_STATS["active_tenants"] += 1
    if "config" in kwargs:
        tenant["config"].update(kwargs["config"])
    if "quotas" in kwargs:
        tenant["quotas"].update(kwargs["quotas"])
    
    tenant["modified_time"] = time.time()
    
    return True

def delete_tenant(tenant_id: str) -> bool:
    """删除租户"""
    if tenant_id not in TENANTS:
        return False
    
    tenant = TENANTS[tenant_id]
    
    if tenant["status"] == "active":
        TENANT_STATS["active_tenants"] -= 1
    
    TENANT_STATS["total_tenants"] -= 1
    del TENANT_STATS["by_tenant"][tenant_id]
    del TENANTS[tenant_id]
    
    return True

def check_tenant_quota(tenant_id: str, resource: str) -> dict:
    """检查租户配额"""
    if tenant_id not in TENANTS:
        return {"allowed": False, "reason": "tenant not found"}
    
    tenant = TENANTS[tenant_id]
    
    if tenant["status"] != "active":
        return {"allowed": False, "reason": "tenant inactive"}
    
    quota = tenant["quotas"].get(resource, float("inf"))
    usage = tenant["usage"].get(resource, 0)
    
    return {
        "allowed": usage < quota,
        "quota": quota,
        "usage": usage,
        "remaining": max(0, quota - usage)
    }

def record_tenant_usage(tenant_id: str, resource: str, amount: int = 1) -> bool:
    """记录租户使用量"""
    if tenant_id not in TENANTS:
        return False
    
    tenant = TENANTS[tenant_id]
    
    if resource in tenant["usage"]:
        tenant["usage"][resource] += amount
    
    # 更新统计
    if resource == "requests_this_minute":
        TENANT_STATS["total_requests"] += amount
        TENANT_STATS["by_tenant"][tenant_id]["total_requests"] += amount
        TENANT_STATS["by_tenant"][tenant_id]["last_request_time"] = time.time()
    
    return True

def reset_tenant_usage(tenant_id: str, resource: str = None) -> bool:
    """重置租户使用量"""
    if tenant_id not in TENANTS:
        return False
    
    tenant = TENANTS[tenant_id]
    
    if resource:
        tenant["usage"][resource] = 0
    else:
        for r in tenant["usage"]:
            tenant["usage"][r] = 0
    
    return True

def get_tenant_context(request: Request) -> str:
    """从请求获取租户上下文"""
    tenant_id = request.headers.get(TENANT_CONFIG["tenant_id_header"])
    
    if not tenant_id:
        tenant_id = TENANT_CONFIG["default_tenant"]
    
    # 自动创建租户
    if tenant_id not in TENANTS and TENANT_CONFIG["auto_create"]:
        create_tenant(tenant_id, f"Tenant {tenant_id}")
    
    return tenant_id

