    if "isolation_level" in data:
        TENANT_CONFIG["isolation_level"] = data["isolation_level"]
    if "max_tenants" in data:
        TENANT_CONFIG["max_tenants"] = data["max_tenants"]
    if "tenant_id_header" in data:
        TENANT_CONFIG["tenant_id_header"] = data["tenant_id_header"]
    if "auto_create" in data:
        TENANT_CONFIG["auto_create"] = data["auto_create"]
    
    return {
        "success": True,
        "config": TENANT_CONFIG
    }

