async def create_tenant_endpoint(request: Request):
    """创建租户"""
    data = await request.json()
    
    tenant_id = data.get("id") or data.get("tenant_id")
    name = data.get("name")
    config = data.get("config")
    quotas = data.get("quotas")
    
    if not tenant_id:
        return {"success": False, "message": "tenant id is required"}
    
    if not name:
        name = f"Tenant {tenant_id}"
    
    success = create_tenant(tenant_id, name, config, quotas)
    
    if success:
        return {
            "success": True,
            "tenant": TENANTS[tenant_id]
        }
    
    return {"success": False, "message": "tenant already exists or max tenants reached"}

