@app.get("/api/tenants/{tenant_id}/quota")
async def get_tenant_quota_endpoint(tenant_id: str, resource: str = None):
    """获取租户配额"""
    if tenant_id not in TENANTS:
        return {"success": False, "message": "tenant not found"}
    
    tenant = TENANTS[tenant_id]
    
    if resource:
        result = check_tenant_quota(tenant_id, resource)
        return {
            "success": True,
            "resource": resource,
            **result
        }
    
    # 返回所有配额
    quotas = {}
    for r in tenant["quotas"]:
        quotas[r] = check_tenant_quota(tenant_id, r)
    
    return {
        "success": True,
        "quotas": quotas
    }

