# ========== API请求优先级队列 ==========

PRIORITY_QUEUE_CONFIG = {
    "enabled": True,
    "max_queue_size": 1000,
    "priority_levels": {
        "critical": 1,    # 最高优先级
        "high": 2,
        "normal": 3,
        "low": 4,
        "background": 5   # 最低优先级
    },
    "default_priority": "normal",
    "priority_header": "X-Request-Priority",
    "processing_interval_ms": 100,
    "max_concurrent": 10
}

PRIORITY_QUEUES = {
    # priority_level -> [requests]
    "critical": [],
    "high": [],
    "normal": [],
    "low": [],
    "background": []
}

PRIORITY_QUEUE_STATS = {
    "total_enqueued": 0,
    "total_processed": 0,
    "total_dropped": 0,
    "by_priority": {
        "critical": {"enqueued": 0, "processed": 0, "dropped": 0},
        "high": {"enqueued": 0, "processed": 0, "dropped": 0},
        "normal": {"enqueued": 0, "processed": 0, "dropped": 0},
        "low": {"enqueued": 0, "processed": 0, "dropped": 0},
        "background": {"enqueued": 0, "processed": 0, "dropped": 0}
    },
    "current_queue_sizes": {},
    "avg_wait_time_ms": 0
}

PROCESSING_REQUESTS = {
    # request_id -> {priority, start_time, ...}
}

def enqueue_request(request_id: str, priority: str, request_data: dict = None) -> bool:
    """将请求加入优先级队列"""
    if priority not in PRIORITY_QUEUES:
        priority = PRIORITY_QUEUE_CONFIG["default_priority"]
    
    queue = PRIORITY_QUEUES[priority]
    
    if len(queue) >= PRIORITY_QUEUE_CONFIG["max_queue_size"]:
        PRIORITY_QUEUE_STATS["total_dropped"] += 1
        PRIORITY_QUEUE_STATS["by_priority"][priority]["dropped"] += 1
        return False
    
    queue.append({
        "id": request_id,
        "priority": priority,
        "data": request_data or {},
        "enqueued_time": time.time()
    })
    
    PRIORITY_QUEUE_STATS["total_enqueued"] += 1
    PRIORITY_QUEUE_STATS["by_priority"][priority]["enqueued"] += 1
    PRIORITY_QUEUE_STATS["current_queue_sizes"][priority] = len(queue)
    
    return True

def dequeue_request() -> dict:
    """从优先级队列取出请求(按优先级顺序)"""
    for priority in ["critical", "high", "normal", "low", "background"]:
        queue = PRIORITY_QUEUES[priority]
        if queue:
            request = queue.pop(0)
            
            PRIORITY_QUEUE_STATS["total_processed"] += 1
            PRIORITY_QUEUE_STATS["by_priority"][priority]["processed"] += 1
            PRIORITY_QUEUE_STATS["current_queue_sizes"][priority] = len(queue)
            
            # 计算等待时间
            wait_time = (time.time() - request["enqueued_time"]) * 1000
            request["wait_time_ms"] = wait_time
            
            return request
    
    return None

def get_queue_position(request_id: str) -> dict:
    """获取请求在队列中的位置"""
    for priority, queue in PRIORITY_QUEUES.items():
        for i, req in enumerate(queue):
            if req["id"] == request_id:
                # 计算在所有队列中的综合位置
                position = i + 1
                for p in ["critical", "high", "normal", "low", "background"]:
                    if p == priority:
                        break
                    position += len(PRIORITY_QUEUES[p])
                
                return {
                    "found": True,
                    "priority": priority,
                    "position_in_queue": i + 1,
                    "global_position": position,
                    "enqueued_time": req["enqueued_time"],
                    "wait_time_ms": (time.time() - req["enqueued_time"]) * 1000
                }
    
    return {"found": False}

def remove_from_queue(request_id: str) -> bool:
    """从队列中移除请求"""
    for priority, queue in PRIORITY_QUEUES.items():
        for i, req in enumerate(queue):
            if req["id"] == request_id:
                queue.pop(i)
                PRIORITY_QUEUE_STATS["current_queue_sizes"][priority] = len(queue)
                return True
    return False

def get_queue_status() -> dict:
    """获取队列状态"""
    status = {
        "total_queued": 0,
        "queues": {},
        "processing_count": len(PROCESSING_REQUESTS)
    }
    
    for priority, queue in PRIORITY_QUEUES.items():
        count = len(queue)
        status["total_queued"] += count
        status["queues"][priority] = {
            "count": count,
            "oldest_wait_ms": 0,
            "newest_wait_ms": 0
        }
        
        if queue:
            oldest = queue[0]
            newest = queue[-1]
            status["queues"][priority]["oldest_wait_ms"] = (time.time() - oldest["enqueued_time"]) * 1000
            status["queues"][priority]["newest_wait_ms"] = (time.time() - newest["enqueued_time"]) * 1000
    
    return status

def clear_queue(priority: str = None) -> int:
    """清空队列"""
    cleared = 0
    
    if priority:
        if priority in PRIORITY_QUEUES:
            cleared = len(PRIORITY_QUEUES[priority])
            PRIORITY_QUEUES[priority] = []
            PRIORITY_QUEUE_STATS["current_queue_sizes"][priority] = 0
    else:
        for p in PRIORITY_QUEUES:
            cleared += len(PRIORITY_QUEUES[p])
            PRIORITY_QUEUES[p] = []
            PRIORITY_QUEUE_STATS["current_queue_sizes"][p] = 0
    
    return cleared

def start_processing(request_id: str, priority: str) -> bool:
    """开始处理请求"""
    PROCESSING_REQUESTS[request_id] = {
        "priority": priority,
        "start_time": time.time()
    }
    return True

def finish_processing(request_id: str) -> dict:
    """完成处理请求"""
    if request_id in PROCESSING_REQUESTS:
        req = PROCESSING_REQUESTS.pop(request_id)
        processing_time = (time.time() - req["start_time"]) * 1000
        return {
            "success": True,
            "processing_time_ms": processing_time,
            "priority": req["priority"]
        }
    return {"success": False}

