async def enqueue_request_endpoint(request: Request):
    """将请求加入队列"""
    data = await request.json()
    
    import secrets
    request_id = data.get("id") or f"req_{secrets.token_hex(4)}"
    priority = data.get("priority", PRIORITY_QUEUE_CONFIG["default_priority"])
