# ========== API请求限流滑动窗口 ==========

SLIDING_WINDOW_CONFIG = {
    "enabled": True,
    "default_window_seconds": 60,
    "default_max_requests": 100,
    "cleanup_interval_seconds": 300,
    "max_windows_per_key": 1000
}

SLIDING_WINDOWS = {
    # key -> {timestamps: [timestamp1, timestamp2, ...], last_cleanup: time}
}

SLIDING_WINDOW_RULES = {
    # key_pattern -> {window_seconds, max_requests, action}
}

SLIDING_WINDOW_STATS = {
    "total_requests": 0,
    "allowed_requests": 0,
    "blocked_requests": 0,
    "by_key": {},
    "window_sizes": {}
}

def sliding_window_check(key: str, window_seconds: int = None, 
                         max_requests: int = None) -> dict:
    """滑动窗口限流检查"""
    window_seconds = window_seconds or SLIDING_WINDOW_CONFIG["default_window_seconds"]
    max_requests = max_requests or SLIDING_WINDOW_CONFIG["default_max_requests"]
    
    current_time = time.time()
    window_start = current_time - window_seconds
    
    # 获取或创建窗口
    if key not in SLIDING_WINDOWS:
        SLIDING_WINDOWS[key] = {
            "timestamps": [],
            "last_cleanup": current_time
        }
    
    window = SLIDING_WINDOWS[key]
    
    # 清理过期时间戳
    if current_time - window["last_cleanup"] > SLIDING_WINDOW_CONFIG["cleanup_interval_seconds"]:
        window["timestamps"] = [ts for ts in window["timestamps"] if ts > window_start]
        window["last_cleanup"] = current_time
    
    # 过滤窗口内的时间戳
    valid_timestamps = [ts for ts in window["timestamps"] if ts > window_start]
    
    # 检查是否超过限制
    current_count = len(valid_timestamps)
    
    SLIDING_WINDOW_STATS["total_requests"] += 1
    
    if key not in SLIDING_WINDOW_STATS["by_key"]:
        SLIDING_WINDOW_STATS["by_key"][key] = {
            "total": 0,
            "allowed": 0,
            "blocked": 0
        }
    
    SLIDING_WINDOW_STATS["by_key"][key]["total"] += 1
    
    if current_count >= max_requests:
        SLIDING_WINDOW_STATS["blocked_requests"] += 1
        SLIDING_WINDOW_STATS["by_key"][key]["blocked"] += 1
        
        # 计算需要等待的时间
        oldest_in_window = min(valid_timestamps) if valid_timestamps else current_time
        wait_seconds = oldest_in_window + window_seconds - current_time
        
        return {
            "allowed": False,
            "current_count": current_count,
            "max_requests": max_requests,
            "window_seconds": window_seconds,
            "wait_seconds": max(0, wait_seconds),
            "retry_after": int(wait_seconds) + 1
        }
    
    # 添加当前请求时间戳
    window["timestamps"].append(current_time)
    
    SLIDING_WINDOW_STATS["allowed_requests"] += 1
    SLIDING_WINDOW_STATS["by_key"][key]["allowed"] += 1
    
    return {
        "allowed": True,
        "current_count": current_count + 1,
        "max_requests": max_requests,
        "window_seconds": window_seconds,
        "remaining": max_requests - current_count - 1
    }

def get_sliding_window_status(key: str, window_seconds: int = None) -> dict:
    """获取滑动窗口状态"""
    window_seconds = window_seconds or SLIDING_WINDOW_CONFIG["default_window_seconds"]
    current_time = time.time()
    window_start = current_time - window_seconds
    
    if key not in SLIDING_WINDOWS:
        return {
            "key": key,
            "current_count": 0,
            "timestamps": [],
            "window_start": window_start,
            "window_end": current_time
        }
    
    window = SLIDING_WINDOWS[key]
    valid_timestamps = [ts for ts in window["timestamps"] if ts > window_start]
    
    return {
        "key": key,
        "current_count": len(valid_timestamps),
        "timestamps": valid_timestamps[-10:],  # 最近10个
        "window_start": window_start,
        "window_end": current_time
    }

def reset_sliding_window(key: str = None) -> int:
    """重置滑动窗口"""
    if key:
        if key in SLIDING_WINDOWS:
            SLIDING_WINDOWS[key]["timestamps"] = []
            return 1
        return 0
    
    count = len(SLIDING_WINDOWS)
    SLIDING_WINDOWS.clear()
    return count

def add_sliding_window_rule(pattern: str, window_seconds: int, 
                            max_requests: int, action: str = "block") -> bool:
    """添加滑动窗口规则"""
    SLIDING_WINDOW_RULES[pattern] = {
        "pattern": pattern,
        "window_seconds": window_seconds,
        "max_requests": max_requests,
        "action": action,
        "created_time": time.time()
    }
    
    SLIDING_WINDOW_STATS["window_sizes"][pattern] = {
        "window_seconds": window_seconds,
        "max_requests": max_requests
    }
    
    return True

def remove_sliding_window_rule(pattern: str) -> bool:
    """移除滑动窗口规则"""
    if pattern in SLIDING_WINDOW_RULES:
        del SLIDING_WINDOW_RULES[pattern]
        if pattern in SLIDING_WINDOW_STATS["window_sizes"]:
            del SLIDING_WINDOW_STATS["window_sizes"][pattern]
        return True
    return False

