# ========== API请求令牌桶限流 ==========

TOKEN_BUCKET_CONFIG = {
    "enabled": True,
    "default_capacity": 100,
    "default_refill_rate": 10,  # 每秒补充令牌数
    "cleanup_interval_seconds": 300,
    "max_buckets": 10000
}

TOKEN_BUCKETS = {
    # key -> {tokens, capacity, refill_rate, last_refill_time}
}

TOKEN_BUCKET_STATS = {
    "total_requests": 0,
    "allowed_requests": 0,
    "blocked_requests": 0,
    "total_tokens_consumed": 0,
    "total_tokens_refilled": 0,
    "by_key": {}
}

def refill_bucket(key: str) -> float:
    """补充令牌桶"""
    if key not in TOKEN_BUCKETS:
        return 0
    
    bucket = TOKEN_BUCKETS[key]
    current_time = time.time()
    
    # 计算应该补充的令牌数
    time_elapsed = current_time - bucket["last_refill_time"]
    tokens_to_add = time_elapsed * bucket["refill_rate"]
    
    # 补充令牌，不超过容量
    old_tokens = bucket["tokens"]
    bucket["tokens"] = min(bucket["capacity"], bucket["tokens"] + tokens_to_add)
    bucket["last_refill_time"] = current_time
    
    tokens_added = bucket["tokens"] - old_tokens
    TOKEN_BUCKET_STATS["total_tokens_refilled"] += tokens_added
    
    return tokens_added

def token_bucket_check(key: str, tokens_needed: int = 1, 
                       capacity: int = None, refill_rate: float = None) -> dict:
    """令牌桶限流检查"""
    capacity = capacity or TOKEN_BUCKET_CONFIG["default_capacity"]
    refill_rate = refill_rate or TOKEN_BUCKET_CONFIG["default_refill_rate"]
    
    # 创建或获取桶
    if key not in TOKEN_BUCKETS:
        TOKEN_BUCKETS[key] = {
            "tokens": capacity,  # 初始满桶
            "capacity": capacity,
            "refill_rate": refill_rate,
            "last_refill_time": time.time()
        }
        TOKEN_BUCKET_STATS["by_key"][key] = {
            "total": 0,
            "allowed": 0,
            "blocked": 0,
            "tokens_consumed": 0
        }
    
    # 补充令牌
    refill_bucket(key)
    
    bucket = TOKEN_BUCKETS[key]
    
    TOKEN_BUCKET_STATS["total_requests"] += 1
    TOKEN_BUCKET_STATS["by_key"][key]["total"] += 1
    
    # 检查是否有足够令牌
    if bucket["tokens"] >= tokens_needed:
        bucket["tokens"] -= tokens_needed
        
        TOKEN_BUCKET_STATS["allowed_requests"] += 1
        TOKEN_BUCKET_STATS["total_tokens_consumed"] += tokens_needed
        TOKEN_BUCKET_STATS["by_key"][key]["allowed"] += 1
        TOKEN_BUCKET_STATS["by_key"][key]["tokens_consumed"] += tokens_needed
        
        return {
            "allowed": True,
            "tokens_remaining": bucket["tokens"],
            "tokens_consumed": tokens_needed,
            "capacity": bucket["capacity"],
            "refill_rate": bucket["refill_rate"]
        }
    
    TOKEN_BUCKET_STATS["blocked_requests"] += 1
    TOKEN_BUCKET_STATS["by_key"][key]["blocked"] += 1
    
    # 计算等待时间
    tokens_deficit = tokens_needed - bucket["tokens"]
    wait_seconds = tokens_deficit / bucket["refill_rate"]
    
    return {
        "allowed": False,
        "tokens_remaining": bucket["tokens"],
        "tokens_needed": tokens_needed,
        "tokens_deficit": tokens_deficit,
        "wait_seconds": wait_seconds,
        "capacity": bucket["capacity"],
        "refill_rate": bucket["refill_rate"]
    }

def get_bucket_status(key: str) -> dict:
    """获取令牌桶状态"""
    if key not in TOKEN_BUCKETS:
        return {
            "key": key,
            "tokens": 0,
            "capacity": TOKEN_BUCKET_CONFIG["default_capacity"],
            "refill_rate": TOKEN_BUCKET_CONFIG["default_refill_rate"],
            "exists": False
        }
    
    refill_bucket(key)
    bucket = TOKEN_BUCKETS[key]
    
    return {
        "key": key,
        "tokens": bucket["tokens"],
        "capacity": bucket["capacity"],
        "refill_rate": bucket["refill_rate"],
        "fill_percentage": (bucket["tokens"] / bucket["capacity"]) * 100,
        "last_refill_time": bucket["last_refill_time"],
        "exists": True
    }

def reset_bucket(key: str = None) -> int:
    """重置令牌桶"""
    if key:
        if key in TOKEN_BUCKETS:
            TOKEN_BUCKETS[key]["tokens"] = TOKEN_BUCKETS[key]["capacity"]
            TOKEN_BUCKETS[key]["last_refill_time"] = time.time()
            return 1
        return 0
    
    count = len(TOKEN_BUCKETS)
    for k in TOKEN_BUCKETS:
        TOKEN_BUCKETS[k]["tokens"] = TOKEN_BUCKETS[k]["capacity"]
        TOKEN_BUCKETS[k]["last_refill_time"] = time.time()
    return count

def delete_bucket(key: str) -> bool:
    """删除令牌桶"""
    if key in TOKEN_BUCKETS:
        del TOKEN_BUCKETS[key]
        if key in TOKEN_BUCKET_STATS["by_key"]:
            del TOKEN_BUCKET_STATS["by_key"][key]
        return True
    return False

