# ========== API请求漏桶限流 ==========

LEAKY_BUCKET_CONFIG = {
    "enabled": True,
    "default_capacity": 100,
    "default_leak_rate": 10,  # 每秒漏出请求数
    "cleanup_interval_seconds": 300,
    "max_buckets": 10000
}

LEAKY_BUCKETS = {
    # key -> {water_level, capacity, leak_rate, last_leak_time}
}

LEAKY_BUCKET_STATS = {
    "total_requests": 0,
    "allowed_requests": 0,
    "blocked_requests": 0,
    "total_water_added": 0,
    "total_water_leaked": 0,
    "by_key": {}
}

def leak_bucket(key: str) -> float:
    """漏桶漏水"""
    if key not in LEAKY_BUCKETS:
        return 0
    
    bucket = LEAKY_BUCKETS[key]
    current_time = time.time()
    
    # 计算应该漏出的水量
    time_elapsed = current_time - bucket["last_leak_time"]
    water_to_leak = time_elapsed * bucket["leak_rate"]
    
    # 漏水，不低于0
    old_water = bucket["water_level"]
    bucket["water_level"] = max(0, bucket["water_level"] - water_to_leak)
    bucket["last_leak_time"] = current_time
    
    water_leaked = old_water - bucket["water_level"]
    LEAKY_BUCKET_STATS["total_water_leaked"] += water_leaked
    
    return water_leaked

def leaky_bucket_check(key: str, water_amount: int = 1, 
                       capacity: int = None, leak_rate: float = None) -> dict:
    """漏桶限流检查"""
    capacity = capacity or LEAKY_BUCKET_CONFIG["default_capacity"]
    leak_rate = leak_rate or LEAKY_BUCKET_CONFIG["default_leak_rate"]
    
    # 创建或获取桶
    if key not in LEAKY_BUCKETS:
        LEAKY_BUCKETS[key] = {
            "water_level": 0,
            "capacity": capacity,
            "leak_rate": leak_rate,
            "last_leak_time": time.time()
        }
        LEAKY_BUCKET_STATS["by_key"][key] = {
            "total": 0,
            "allowed": 0,
            "blocked": 0,
            "water_added": 0
        }
    
    # 先漏水
    leak_bucket(key)
    
    bucket = LEAKY_BUCKETS[key]
    
    LEAKY_BUCKET_STATS["total_requests"] += 1
    LEAKY_BUCKET_STATS["by_key"][key]["total"] += 1
    
    # 检查是否能加入水
    if bucket["water_level"] + water_amount <= bucket["capacity"]:
        bucket["water_level"] += water_amount
        
        LEAKY_BUCKET_STATS["allowed_requests"] += 1
        LEAKY_BUCKET_STATS["total_water_added"] += water_amount
        LEAKY_BUCKET_STATS["by_key"][key]["allowed"] += 1
        LEAKY_BUCKET_STATS["by_key"][key]["water_added"] += water_amount
        
        return {
            "allowed": True,
            "water_level": bucket["water_level"],
            "water_added": water_amount,
            "capacity": bucket["capacity"],
            "leak_rate": bucket["leak_rate"],
            "remaining_capacity": bucket["capacity"] - bucket["water_level"]
        }
    
    LEAKY_BUCKET_STATS["blocked_requests"] += 1
    LEAKY_BUCKET_STATS["by_key"][key]["blocked"] += 1
    
    # 计算等待时间
    water_overflow = bucket["water_level"] + water_amount - bucket["capacity"]
    wait_seconds = water_overflow / bucket["leak_rate"]
    
    return {
        "allowed": False,
        "water_level": bucket["water_level"],
        "water_amount": water_amount,
        "capacity": bucket["capacity"],
        "leak_rate": bucket["leak_rate"],
        "wait_seconds": wait_seconds
    }

def get_leaky_bucket_status(key: str) -> dict:
    """获取漏桶状态"""
    if key not in LEAKY_BUCKETS:
        return {
            "key": key,
            "water_level": 0,
            "capacity": LEAKY_BUCKET_CONFIG["default_capacity"],
            "leak_rate": LEAKY_BUCKET_CONFIG["default_leak_rate"],
            "exists": False
        }
    
    leak_bucket(key)
    bucket = LEAKY_BUCKETS[key]
    
    return {
        "key": key,
        "water_level": bucket["water_level"],
        "capacity": bucket["capacity"],
        "leak_rate": bucket["leak_rate"],
        "fill_percentage": (bucket["water_level"] / bucket["capacity"]) * 100 if bucket["capacity"] > 0 else 0,
        "last_leak_time": bucket["last_leak_time"],
        "exists": True
    }

def reset_leaky_bucket(key: str = None) -> int:
    """重置漏桶"""
    if key:
        if key in LEAKY_BUCKETS:
            LEAKY_BUCKETS[key]["water_level"] = 0
            LEAKY_BUCKETS[key]["last_leak_time"] = time.time()
            return 1
        return 0
    
    count = len(LEAKY_BUCKETS)
    for k in LEAKY_BUCKETS:
        LEAKY_BUCKETS[k]["water_level"] = 0
        LEAKY_BUCKETS[k]["last_leak_time"] = time.time()
    return count

def delete_leaky_bucket(key: str) -> bool:
    """删除漏桶"""
    if key in LEAKY_BUCKETS:
        del LEAKY_BUCKETS[key]
        if key in LEAKY_BUCKET_STATS["by_key"]:
            del LEAKY_BUCKET_STATS["by_key"][key]
        return True
    return False

