# ========== API请求自适应限流 ==========

ADAPTIVE_RATE_LIMIT_CONFIG = {
    "enabled": True,
    "min_rate": 10,
    "max_rate": 1000,
    "initial_rate": 100,
    "target_latency_ms": 200,
    "tolerance": 0.1,
    "increase_factor": 1.1,
    "decrease_factor": 0.9,
    "sample_window_seconds": 10,
    "min_samples": 10
}

ADAPTIVE_LIMITERS = {
    # key -> {current_rate, latency_samples, last_adjustment_time, stats}
}

ADAPTIVE_STATS = {
    "total_requests": 0,
    "total_allowed": 0,
    "total_blocked": 0,
    "total_adjustments": 0,
    "by_key": {}
}

def record_latency(key: str, latency_ms: float):
    """记录延迟样本"""
    if key not in ADAPTIVE_LIMITERS:
        ADAPTIVE_LIMITERS[key] = {
            "current_rate": ADAPTIVE_RATE_LIMIT_CONFIG["initial_rate"],
            "latency_samples": [],
            "last_adjustment_time": time.time(),
            "stats": {"adjustments": 0, "rate_history": []}
        }
        ADAPTIVE_STATS["by_key"][key] = {
            "total": 0,
            "allowed": 0,
            "blocked": 0
        }
    
    limiter = ADAPTIVE_LIMITERS[key]
    limiter["latency_samples"].append({
        "latency": latency_ms,
        "timestamp": time.time()
    })
    
    # 清理过期样本
    window_start = time.time() - ADAPTIVE_RATE_LIMIT_CONFIG["sample_window_seconds"]
    limiter["latency_samples"] = [
        s for s in limiter["latency_samples"] 
        if s["timestamp"] > window_start
    ]

def calculate_avg_latency(key: str) -> float:
    """计算平均延迟"""
    if key not in ADAPTIVE_LIMITERS:
        return 0
    
    samples = ADAPTIVE_LIMITERS[key]["latency_samples"]
    if not samples:
        return 0
    
    return sum(s["latency"] for s in samples) / len(samples)

def adjust_rate(key: str) -> dict:
    """自适应调整速率"""
    if key not in ADAPTIVE_LIMITERS:
        return {"adjusted": False, "reason": "limiter not found"}
    
    limiter = ADAPTIVE_LIMITERS[key]
    samples = limiter["latency_samples"]
    
    # 检查样本数量
    if len(samples) < ADAPTIVE_RATE_LIMIT_CONFIG["min_samples"]:
        return {"adjusted": False, "reason": "insufficient samples"}
    
    # 检查调整间隔
    time_since_adjustment = time.time() - limiter["last_adjustment_time"]
    if time_since_adjustment < ADAPTIVE_RATE_LIMIT_CONFIG["sample_window_seconds"]:
        return {"adjusted": False, "reason": "too soon"}
    
    avg_latency = calculate_avg_latency(key)
    target_latency = ADAPTIVE_RATE_LIMIT_CONFIG["target_latency_ms"]
    tolerance = ADAPTIVE_RATE_LIMIT_CONFIG["tolerance"]
    
    old_rate = limiter["current_rate"]
    new_rate = old_rate
    
    # 延迟过高，降低速率
    if avg_latency > target_latency * (1 + tolerance):
        new_rate = max(
            ADAPTIVE_RATE_LIMIT_CONFIG["min_rate"],
            int(old_rate * ADAPTIVE_RATE_LIMIT_CONFIG["decrease_factor"])
        )
    # 延迟正常，提高速率
    elif avg_latency < target_latency * (1 - tolerance):
        new_rate = min(
            ADAPTIVE_RATE_LIMIT_CONFIG["max_rate"],
            int(old_rate * ADAPTIVE_RATE_LIMIT_CONFIG["increase_factor"])
        )
    
    if new_rate != old_rate:
        limiter["current_rate"] = new_rate
        limiter["last_adjustment_time"] = time.time()
        limiter["stats"]["adjustments"] += 1
        limiter["stats"]["rate_history"].append({
            "old_rate": old_rate,
            "new_rate": new_rate,
            "avg_latency": avg_latency,
            "timestamp": time.time()
        })
        
        ADAPTIVE_STATS["total_adjustments"] += 1
        
        return {
            "adjusted": True,
            "old_rate": old_rate,
            "new_rate": new_rate,
            "avg_latency": avg_latency,
            "direction": "increase" if new_rate > old_rate else "decrease"
        }
    
    return {"adjusted": False, "reason": "rate unchanged"}

def adaptive_rate_check(key: str) -> dict:
    """自适应限流检查"""
    # 确保limiter存在
    if key not in ADAPTIVE_LIMITERS:
        ADAPTIVE_LIMITERS[key] = {
            "current_rate": ADAPTIVE_RATE_LIMIT_CONFIG["initial_rate"],
            "latency_samples": [],
            "last_adjustment_time": time.time(),
            "stats": {"adjustments": 0, "rate_history": []}
        }
        ADAPTIVE_STATS["by_key"][key] = {
            "total": 0,
            "allowed": 0,
            "blocked": 0
        }
    
    limiter = ADAPTIVE_LIMITERS[key]
    current_rate = limiter["current_rate"]
    
    ADAPTIVE_STATS["total_requests"] += 1
    ADAPTIVE_STATS["by_key"][key]["total"] += 1
    
    # 使用当前速率进行限流检查
    # 这里简单实现，实际可结合滑动窗口等
    current_time = time.time()
    window_start = current_time - 1  # 1秒窗口
    
    # 统计最近1秒的请求数
    recent_samples = [
        s for s in limiter["latency_samples"] 
        if s["timestamp"] > window_start
    ]
    current_count = len(recent_samples)
    
    if current_count < current_rate:
        ADAPTIVE_STATS["total_allowed"] += 1
        ADAPTIVE_STATS["by_key"][key]["allowed"] += 1
        
        return {
            "allowed": True,
            "current_rate": current_rate,
            "current_count": current_count,
            "remaining": current_rate - current_count - 1
        }
    
    ADAPTIVE_STATS["total_blocked"] += 1
    ADAPTIVE_STATS["by_key"][key]["blocked"] += 1
    
    return {
        "allowed": False,
        "current_rate": current_rate,
        "current_count": current_count,
        "retry_after": 1
    }

def get_adaptive_limiter_status(key: str) -> dict:
    """获取自适应限流器状态"""
    if key not in ADAPTIVE_LIMITERS:
        return {
            "key": key,
            "exists": False,
            "current_rate": ADAPTIVE_RATE_LIMIT_CONFIG["initial_rate"],
            "avg_latency": 0,
            "sample_count": 0
        }
    
    limiter = ADAPTIVE_LIMITERS[key]
    avg_latency = calculate_avg_latency(key)
    
    return {
        "key": key,
        "exists": True,
        "current_rate": limiter["current_rate"],
        "avg_latency": avg_latency,
        "sample_count": len(limiter["latency_samples"]),
        "adjustments": limiter["stats"]["adjustments"],
        "last_adjustment_time": limiter["last_adjustment_time"],
        "rate_history": limiter["stats"]["rate_history"][-5:]  # 最近5次调整
    }

def reset_adaptive_limiter(key: str = None) -> int:
    """重置自适应限流器"""
    if key:
        if key in ADAPTIVE_LIMITERS:
            ADAPTIVE_LIMITERS[key]["current_rate"] = ADAPTIVE_RATE_LIMIT_CONFIG["initial_rate"]
            ADAPTIVE_LIMITERS[key]["latency_samples"] = []
            ADAPTIVE_LIMITERS[key]["last_adjustment_time"] = time.time()
            return 1
        return 0
    
    count = len(ADAPTIVE_LIMITERS)
    for k in ADAPTIVE_LIMITERS:
        ADAPTIVE_LIMITERS[k]["current_rate"] = ADAPTIVE_RATE_LIMIT_CONFIG["initial_rate"]
        ADAPTIVE_LIMITERS[k]["latency_samples"] = []
        ADAPTIVE_LIMITERS[k]["last_adjustment_time"] = time.time()
    return count

