# ========== API请求并发限流 ==========

CONCURRENT_LIMIT_CONFIG = {
    "enabled": True,
    "default_max_concurrent": 100,
    "cleanup_interval_seconds": 60,
    "timeout_seconds": 30
}

CONCURRENT_LIMITERS = {
    # key -> {current_count, max_concurrent, active_requests, last_activity}
}

CONCURRENT_STATS = {
    "total_requests": 0,
    "total_acquired": 0,
    "total_rejected": 0,
    "total_released": 0,
    "total_timeouts": 0,
    "by_key": {}
}

def acquire_concurrent(key: str, request_id: str = None, 
                       max_concurrent: int = None) -> dict:
    """获取并发槽位"""
    max_concurrent = max_concurrent or CONCURRENT_LIMIT_CONFIG["default_max_concurrent"]
    request_id = request_id or str(uuid.uuid4())[:8]
    
    # 创建或获取limiter
    if key not in CONCURRENT_LIMITERS:
        CONCURRENT_LIMITERS[key] = {
            "current_count": 0,
            "max_concurrent": max_concurrent,
            "active_requests": {},
            "last_activity": time.time()
        }
        CONCURRENT_STATS["by_key"][key] = {
            "total": 0,
            "acquired": 0,
            "rejected": 0,
            "released": 0,
            "timeouts": 0
        }
    
    limiter = CONCURRENT_LIMITERS[key]
    CONCURRENT_STATS["total_requests"] += 1
    CONCURRENT_STATS["by_key"][key]["total"] += 1
    
    # 检查是否有可用槽位
    if limiter["current_count"] < limiter["max_concurrent"]:
        limiter["current_count"] += 1
        limiter["active_requests"][request_id] = {
            "acquired_at": time.time(),
            "status": "active"
        }
        limiter["last_activity"] = time.time()
        
        CONCURRENT_STATS["total_acquired"] += 1
        CONCURRENT_STATS["by_key"][key]["acquired"] += 1
        
        return {
            "acquired": True,
            "request_id": request_id,
            "current_count": limiter["current_count"],
            "max_concurrent": limiter["max_concurrent"],
            "remaining": limiter["max_concurrent"] - limiter["current_count"]
        }
    
    CONCURRENT_STATS["total_rejected"] += 1
    CONCURRENT_STATS["by_key"][key]["rejected"] += 1
    
    return {
        "acquired": False,
        "request_id": request_id,
        "current_count": limiter["current_count"],
        "max_concurrent": limiter["max_concurrent"],
        "message": "concurrent limit reached"
    }

def release_concurrent(key: str, request_id: str) -> dict:
    """释放并发槽位"""
    if key not in CONCURRENT_LIMITERS:
        return {"released": False, "message": "limiter not found"}
    
    limiter = CONCURRENT_LIMITERS[key]
    
    if request_id not in limiter["active_requests"]:
        return {"released": False, "message": "request not found"}
    
    del limiter["active_requests"][request_id]
    limiter["current_count"] = max(0, limiter["current_count"] - 1)
    limiter["last_activity"] = time.time()
    
    CONCURRENT_STATS["total_released"] += 1
    CONCURRENT_STATS["by_key"][key]["released"] += 1
    
    return {
        "released": True,
        "request_id": request_id,
        "current_count": limiter["current_count"],
        "remaining": limiter["max_concurrent"] - limiter["current_count"]
    }

def cleanup_stale_requests(key: str = None) -> int:
    """清理过期请求"""
    timeout = CONCURRENT_LIMIT_CONFIG["timeout_seconds"]
    current_time = time.time()
    cleaned = 0
    
    keys_to_check = [key] if key else list(CONCURRENT_LIMITERS.keys())
    
    for k in keys_to_check:
        if k not in CONCURRENT_LIMITERS:
            continue
        
        limiter = CONCURRENT_LIMITERS[k]
        stale_requests = []
        
        for req_id, req_info in limiter["active_requests"].items():
            if current_time - req_info["acquired_at"] > timeout:
                stale_requests.append(req_id)
        
        for req_id in stale_requests:
            del limiter["active_requests"][req_id]
            limiter["current_count"] = max(0, limiter["current_count"] - 1)
            cleaned += 1
            
            CONCURRENT_STATS["total_timeouts"] += 1
            if k in CONCURRENT_STATS["by_key"]:
                CONCURRENT_STATS["by_key"][k]["timeouts"] += 1
    
    return cleaned

def get_concurrent_status(key: str) -> dict:
    """获取并发限流器状态"""
    if key not in CONCURRENT_LIMITERS:
        return {
            "key": key,
            "exists": False,
            "current_count": 0,
            "max_concurrent": CONCURRENT_LIMIT_CONFIG["default_max_concurrent"]
        }
    
    limiter = CONCURRENT_LIMITERS[key]
    
    return {
        "key": key,
        "exists": True,
        "current_count": limiter["current_count"],
        "max_concurrent": limiter["max_concurrent"],
        "remaining": limiter["max_concurrent"] - limiter["current_count"],
        "active_requests": len(limiter["active_requests"]),
        "last_activity": limiter["last_activity"]
    }

def reset_concurrent_limiter(key: str = None) -> int:
    """重置并发限流器"""
    if key:
        if key in CONCURRENT_LIMITERS:
            CONCURRENT_LIMITERS[key]["current_count"] = 0
            CONCURRENT_LIMITERS[key]["active_requests"].clear()
            return 1
        return 0
    
    count = len(CONCURRENT_LIMITERS)
    for k in CONCURRENT_LIMITERS:
        CONCURRENT_LIMITERS[k]["current_count"] = 0
        CONCURRENT_LIMITERS[k]["active_requests"].clear()
    return count

