# ========== API请求分布式限流 ==========

DISTRIBUTED_LIMIT_CONFIG = {
    "enabled": True,
    "default_limit": 1000,
    "default_window_seconds": 60,
    "sync_interval_seconds": 5,
    "node_id": "node-1",
    "cluster_nodes": ["node-1", "node-2", "node-3"],
    "replication_factor": 2
}

DISTRIBUTED_LIMITERS = {
    # key -> {local_count, remote_counts, last_sync, window_start}
}

DISTRIBUTED_STATS = {
    "total_requests": 0,
    "total_allowed": 0,
    "total_blocked": 0,
    "total_syncs": 0,
    "sync_errors": 0,
    "by_key": {}
}

def get_cluster_count(key: str) -> int:
    """获取集群总计数"""
    if key not in DISTRIBUTED_LIMITERS:
        return 0
    
    limiter = DISTRIBUTED_LIMITERS[key]
    total = limiter.get("local_count", 0)
    
    for node, count in limiter.get("remote_counts", {}).items():
        total += count
    
    return total

def sync_with_cluster(key: str) -> dict:
    """同步集群计数（模拟）"""
    if key not in DISTRIBUTED_LIMITERS:
        return {"synced": False, "reason": "limiter not found"}
    
    limiter = DISTRIBUTED_LIMITERS[key]
    
    # 模拟从其他节点获取计数
    # 实际实现中会使用Redis/etcd等
    for node in DISTRIBUTED_LIMIT_CONFIG["cluster_nodes"]:
        if node != DISTRIBUTED_LIMIT_CONFIG["node_id"]:
            # 模拟网络延迟
            if node not in limiter["remote_counts"]:
                limiter["remote_counts"][node] = 0
    
    limiter["last_sync"] = time.time()
    DISTRIBUTED_STATS["total_syncs"] += 1
    
    return {
        "synced": True,
        "cluster_count": get_cluster_count(key),
        "nodes_synced": len(limiter["remote_counts"])
    }

def distributed_limit_check(key: str, increment: int = 1,
                            limit: int = None, 
                            window_seconds: int = None) -> dict:
    """分布式限流检查"""
    limit = limit or DISTRIBUTED_LIMIT_CONFIG["default_limit"]
    window_seconds = window_seconds or DISTRIBUTED_LIMIT_CONFIG["default_window_seconds"]
    
    # 创建或获取limiter
    if key not in DISTRIBUTED_LIMITERS:
        DISTRIBUTED_LIMITERS[key] = {
            "local_count": 0,
            "remote_counts": {},
            "last_sync": time.time(),
            "window_start": time.time(),
            "limit": limit,
            "window_seconds": window_seconds
        }
        DISTRIBUTED_STATS["by_key"][key] = {
            "total": 0,
            "allowed": 0,
            "blocked": 0
        }
    
    limiter = DISTRIBUTED_LIMITERS[key]
    
    # 检查窗口是否过期
    if time.time() - limiter["window_start"] > window_seconds:
        limiter["local_count"] = 0
        limiter["remote_counts"].clear()
        limiter["window_start"] = time.time()
    
    # 定期同步
    if time.time() - limiter["last_sync"] > DISTRIBUTED_LIMIT_CONFIG["sync_interval_seconds"]:
        sync_with_cluster(key)
    
    DISTRIBUTED_STATS["total_requests"] += 1
    DISTRIBUTED_STATS["by_key"][key]["total"] += 1
    
    # 获取集群总计数
    cluster_count = get_cluster_count(key)
    
    # 检查是否超过限制
    if cluster_count + increment <= limit:
        limiter["local_count"] += increment
        
        DISTRIBUTED_STATS["total_allowed"] += 1
        DISTRIBUTED_STATS["by_key"][key]["allowed"] += 1
        
        return {
            "allowed": True,
            "local_count": limiter["local_count"],
            "cluster_count": cluster_count + increment,
            "limit": limit,
            "remaining": limit - cluster_count - increment
        }
    
    DISTRIBUTED_STATS["total_blocked"] += 1
    DISTRIBUTED_STATS["by_key"][key]["blocked"] += 1
    
    return {
        "allowed": False,
        "local_count": limiter["local_count"],
        "cluster_count": cluster_count,
        "limit": limit,
        "remaining": 0
    }

def update_remote_count(key: str, node: str, count: int) -> dict:
    """更新远程节点计数"""
    if key not in DISTRIBUTED_LIMITERS:
        DISTRIBUTED_LIMITERS[key] = {
            "local_count": 0,
            "remote_counts": {},
            "last_sync": time.time(),
            "window_start": time.time(),
            "limit": DISTRIBUTED_LIMIT_CONFIG["default_limit"],
            "window_seconds": DISTRIBUTED_LIMIT_CONFIG["default_window_seconds"]
        }
    
    DISTRIBUTED_LIMITERS[key]["remote_counts"][node] = count
    
    return {
        "updated": True,
        "node": node,
        "count": count,
        "cluster_count": get_cluster_count(key)
    }

def get_distributed_status(key: str) -> dict:
    """获取分布式限流器状态"""
    if key not in DISTRIBUTED_LIMITERS:
        return {
            "key": key,
            "exists": False,
            "local_count": 0,
            "cluster_count": 0
        }
    
    limiter = DISTRIBUTED_LIMITERS[key]
    
    return {
        "key": key,
        "exists": True,
        "node_id": DISTRIBUTED_LIMIT_CONFIG["node_id"],
        "local_count": limiter["local_count"],
        "remote_counts": limiter["remote_counts"],
        "cluster_count": get_cluster_count(key),
        "limit": limiter["limit"],
        "window_seconds": limiter["window_seconds"],
        "last_sync": limiter["last_sync"],
        "window_start": limiter["window_start"]
    }

def reset_distributed_limiter(key: str = None) -> int:
    """重置分布式限流器"""
    if key:
        if key in DISTRIBUTED_LIMITERS:
            DISTRIBUTED_LIMITERS[key]["local_count"] = 0
            DISTRIBUTED_LIMITERS[key]["remote_counts"].clear()
            DISTRIBUTED_LIMITERS[key]["window_start"] = time.time()
            return 1
        return 0
    
    count = len(DISTRIBUTED_LIMITERS)
    for k in DISTRIBUTED_LIMITERS:
        DISTRIBUTED_LIMITERS[k]["local_count"] = 0
        DISTRIBUTED_LIMITERS[k]["remote_counts"].clear()
        DISTRIBUTED_LIMITERS[k]["window_start"] = time.time()
    return count

