# ========== API请求限流黑白名单 ==========

RATE_LIMIT_WHITELIST_CONFIG = {
    "enabled": True,
    "whitelist": [],  # IP或Key白名单
    "blacklist": [],  # IP或Key黑名单
    "whitelist_limit_multiplier": 10,  # 白名单限流倍数
    "blacklist_block_duration_seconds": 3600,  # 黑名单封禁时长
    "auto_blacklist_threshold": 100,  # 自动加入黑名单阈值
    "auto_blacklist_window_seconds": 60
}

RATE_LIMIT_LIST_STATS = {
    "total_requests": 0,
    "whitelist_allowed": 0,
    "blacklist_blocked": 0,
    "auto_blacklisted": 0,
    "by_key": {}
}

RATE_LIMIT_VIOLATIONS = {
    # key -> {count, window_start, auto_blacklisted}
}

def check_whitelist(key: str) -> bool:
    """检查是否在白名单"""
    return key in RATE_LIMIT_WHITELIST_CONFIG["whitelist"]

def check_blacklist(key: str) -> bool:
    """检查是否在黑名单"""
    return key in RATE_LIMIT_WHITELIST_CONFIG["blacklist"]

def add_to_whitelist(key: str) -> dict:
    """添加到白名单"""
    if key not in RATE_LIMIT_WHITELIST_CONFIG["whitelist"]:
        RATE_LIMIT_WHITELIST_CONFIG["whitelist"].append(key)
        return {"added": True, "key": key}
    return {"added": False, "reason": "already in whitelist"}

def remove_from_whitelist(key: str) -> dict:
    """从白名单移除"""
    if key in RATE_LIMIT_WHITELIST_CONFIG["whitelist"]:
        RATE_LIMIT_WHITELIST_CONFIG["whitelist"].remove(key)
        return {"removed": True, "key": key}
    return {"removed": False, "reason": "not in whitelist"}

def add_to_blacklist(key: str, duration: int = None) -> dict:
    """添加到黑名单"""
    duration = duration or RATE_LIMIT_WHITELIST_CONFIG["blacklist_block_duration_seconds"]
    
    if key not in RATE_LIMIT_WHITELIST_CONFIG["blacklist"]:
        RATE_LIMIT_WHITELIST_CONFIG["blacklist"].append(key)
        RATE_LIMIT_LIST_STATS["auto_blacklisted"] += 1
    
    # 记录黑名单信息
    if key not in RATE_LIMIT_LIST_STATS["by_key"]:
        RATE_LIMIT_LIST_STATS["by_key"][key] = {
            "whitelist_hits": 0,
            "blacklist_hits": 0,
            "violations": 0
        }
    
    RATE_LIMIT_LIST_STATS["by_key"][key]["blacklisted_at"] = time.time()
    RATE_LIMIT_LIST_STATS["by_key"][key]["duration"] = duration
    
    return {
        "added": True,
        "key": key,
        "duration": duration,
        "expires_at": time.time() + duration
    }

def remove_from_blacklist(key: str) -> dict:
    """从黑名单移除"""
    if key in RATE_LIMIT_WHITELIST_CONFIG["blacklist"]:
        RATE_LIMIT_WHITELIST_CONFIG["blacklist"].remove(key)
        
        if key in RATE_LIMIT_LIST_STATS["by_key"]:
            del RATE_LIMIT_LIST_STATS["by_key"][key]["blacklisted_at"]
            del RATE_LIMIT_LIST_STATS["by_key"][key]["duration"]
        
        return {"removed": True, "key": key}
    return {"removed": False, "reason": "not in blacklist"}

def record_violation(key: str) -> dict:
    """记录违规（用于自动黑名单）"""
    if key not in RATE_LIMIT_VIOLATIONS:
        RATE_LIMIT_VIOLATIONS[key] = {
            "count": 0,
            "window_start": time.time(),
            "auto_blacklisted": False
        }
    
    violation = RATE_LIMIT_VIOLATIONS[key]
    
    # 检查窗口是否过期
    if time.time() - violation["window_start"] > RATE_LIMIT_WHITELIST_CONFIG["auto_blacklist_window_seconds"]:
        violation["count"] = 0
        violation["window_start"] = time.time()
    
    violation["count"] += 1
    
    # 检查是否达到自动黑名单阈值
    if violation["count"] >= RATE_LIMIT_WHITELIST_CONFIG["auto_blacklist_threshold"]:
        if not violation["auto_blacklisted"]:
            add_to_blacklist(key)
            violation["auto_blacklisted"] = True
            return {
                "violation_count": violation["count"],
                "auto_blacklisted": True
            }
    
    return {
        "violation_count": violation["count"],
        "auto_blacklisted": violation["auto_blacklisted"]
    }

def check_rate_limit_list(key: str) -> dict:
    """检查限流黑白名单"""
    RATE_LIMIT_LIST_STATS["total_requests"] += 1
    
    if key not in RATE_LIMIT_LIST_STATS["by_key"]:
        RATE_LIMIT_LIST_STATS["by_key"][key] = {
            "whitelist_hits": 0,
            "blacklist_hits": 0,
            "violations": 0
        }
    
    # 检查黑名单
    if check_blacklist(key):
        RATE_LIMIT_LIST_STATS["blacklist_blocked"] += 1
        RATE_LIMIT_LIST_STATS["by_key"][key]["blacklist_hits"] += 1
        
        return {
            "allowed": False,
            "reason": "blacklisted",
            "key": key
        }
    
    # 检查白名单
    if check_whitelist(key):
        RATE_LIMIT_LIST_STATS["whitelist_allowed"] += 1
        RATE_LIMIT_LIST_STATS["by_key"][key]["whitelist_hits"] += 1
        
        return {
            "allowed": True,
            "reason": "whitelisted",
            "key": key,
            "limit_multiplier": RATE_LIMIT_WHITELIST_CONFIG["whitelist_limit_multiplier"]
        }
    
    return {
        "allowed": True,
        "reason": "normal",
        "key": key
    }

def get_list_status(key: str = None) -> dict:
    """获取黑白名单状态"""
    if key:
        return {
            "key": key,
            "in_whitelist": check_whitelist(key),
            "in_blacklist": check_blacklist(key),
            "stats": RATE_LIMIT_LIST_STATS["by_key"].get(key, {})
        }
    
    return {
        "whitelist_count": len(RATE_LIMIT_WHITELIST_CONFIG["whitelist"]),
        "blacklist_count": len(RATE_LIMIT_WHITELIST_CONFIG["blacklist"]),
        "whitelist": RATE_LIMIT_WHITELIST_CONFIG["whitelist"],
        "blacklist": RATE_LIMIT_WHITELIST_CONFIG["blacklist"]
    }

def clear_lists(whitelist: bool = False, blacklist: bool = False) -> dict:
    """清空黑白名单"""
    cleared = {"whitelist": 0, "blacklist": 0}
    
    if whitelist:
        cleared["whitelist"] = len(RATE_LIMIT_WHITELIST_CONFIG["whitelist"])
        RATE_LIMIT_WHITELIST_CONFIG["whitelist"].clear()
    
    if blacklist:
        cleared["blacklist"] = len(RATE_LIMIT_WHITELIST_CONFIG["blacklist"])
        RATE_LIMIT_WHITELIST_CONFIG["blacklist"].clear()
    
    return cleared

