# ========== API请求限流规则引擎 ==========

RATE_LIMIT_RULES_CONFIG = {
    "enabled": True,
    "default_action": "allow",  # allow/deny
    "rule_priority": "order",  # order/specificity
    "max_rules": 1000
}

RATE_LIMIT_RULES = []
# 规则格式: {
#   id: str,
#   name: str,
#   priority: int,
#   conditions: [{field, operator, value}],
#   action: "allow"/"deny"/"throttle",
#   throttle_config: {rate, window},
#   enabled: bool,
#   created_at: timestamp,
#   hits: int
# }

RATE_LIMIT_RULES_STATS = {
    "total_requests": 0,
    "total_rule_matches": 0,
    "total_allowed": 0,
    "total_denied": 0,
    "total_throttled": 0,
    "by_rule": {}
}

RULE_ID_COUNTER = 0

def create_rule_id() -> str:
    """创建规则ID"""
    global RULE_ID_COUNTER
    RULE_ID_COUNTER += 1
    return f"rule-{RULE_ID_COUNTER}"

def evaluate_condition(value, operator: str, condition_value) -> bool:
    """评估单个条件"""
    if operator == "eq":
        return value == condition_value
    elif operator == "ne":
        return value != condition_value
    elif operator == "gt":
        return value > condition_value
    elif operator == "lt":
        return value < condition_value
    elif operator == "gte":
        return value >= condition_value
    elif operator == "lte":
        return value <= condition_value
    elif operator == "contains":
        return condition_value in str(value)
    elif operator == "startswith":
        return str(value).startswith(condition_value)
    elif operator == "endswith":
        return str(value).endswith(condition_value)
    elif operator == "regex":
        import re
        return bool(re.match(condition_value, str(value)))
    elif operator == "in":
        return value in condition_value
    elif operator == "notin":
        return value not in condition_value
    return False

def evaluate_rule(request_data: dict, rule: dict) -> bool:
    """评估规则是否匹配"""
    if not rule.get("enabled", True):
        return False
    
    conditions = rule.get("conditions", [])
    if not conditions:
        return False
    
    # 所有条件都必须满足
    for condition in conditions:
        field = condition.get("field")
        operator = condition.get("operator")
        condition_value = condition.get("value")
        
        # 获取请求中的字段值
        value = request_data.get(field)
        if value is None:
            return False
        
        if not evaluate_condition(value, operator, condition_value):
            return False
    
    return True

def apply_rules(request_data: dict) -> dict:
    """应用规则引擎"""
    RATE_LIMIT_RULES_STATS["total_requests"] += 1
    
    # 按优先级排序规则
    sorted_rules = sorted(
        [r for r in RATE_LIMIT_RULES if r.get("enabled", True)],
        key=lambda r: r.get("priority", 100)
    )
    
    for rule in sorted_rules:
        if evaluate_rule(request_data, rule):
            RATE_LIMIT_RULES_STATS["total_rule_matches"] += 1
            
            rule_id = rule["id"]
            if rule_id not in RATE_LIMIT_RULES_STATS["by_rule"]:
                RATE_LIMIT_RULES_STATS["by_rule"][rule_id] = {
                    "name": rule["name"],
                    "hits": 0,
                    "allowed": 0,
                    "denied": 0,
                    "throttled": 0
                }
            
            RATE_LIMIT_RULES_STATS["by_rule"][rule_id]["hits"] += 1
            rule["hits"] = (rule.get("hits", 0) + 1)
            
            action = rule.get("action", "allow")
            
            if action == "allow":
                RATE_LIMIT_RULES_STATS["total_allowed"] += 1
                RATE_LIMIT_RULES_STATS["by_rule"][rule_id]["allowed"] += 1
                return {
                    "matched": True,
                    "rule_id": rule_id,
                    "rule_name": rule["name"],
                    "action": "allowed"
                }
            elif action == "deny":
                RATE_LIMIT_RULES_STATS["total_denied"] += 1
                RATE_LIMIT_RULES_STATS["by_rule"][rule_id]["denied"] += 1
                return {
                    "matched": True,
                    "rule_id": rule_id,
                    "rule_name": rule["name"],
                    "action": "denied"
                }
            elif action == "throttle":
                RATE_LIMIT_RULES_STATS["total_throttled"] += 1
                RATE_LIMIT_RULES_STATS["by_rule"][rule_id]["throttled"] += 1
                throttle_config = rule.get("throttle_config", {})
                return {
                    "matched": True,
                    "rule_id": rule_id,
                    "rule_name": rule["name"],
                    "action": "throttled",
                    "throttle_config": throttle_config
                }
    
    # 没有匹配的规则，使用默认动作
    default_action = RATE_LIMIT_RULES_CONFIG["default_action"]
    if default_action == "allow":
        RATE_LIMIT_RULES_STATS["total_allowed"] += 1
    else:
        RATE_LIMIT_RULES_STATS["total_denied"] += 1
    
    return {
        "matched": False,
        "action": default_action,
        "reason": "no matching rule"
    }

def add_rule(name: str, conditions: list, action: str,
             priority: int = 100, throttle_config: dict = None,
             enabled: bool = True) -> dict:
    """添加规则"""
    if len(RATE_LIMIT_RULES) >= RATE_LIMIT_RULES_CONFIG["max_rules"]:
        return {"added": False, "reason": "max rules reached"}
    
    rule_id = create_rule_id()
    
    rule = {
        "id": rule_id,
        "name": name,
        "priority": priority,
        "conditions": conditions,
        "action": action,
        "throttle_config": throttle_config or {},
        "enabled": enabled,
        "created_at": time.time(),
        "hits": 0
    }
    
    RATE_LIMIT_RULES.append(rule)
    
    return {
        "added": True,
        "rule": rule
    }

def update_rule(rule_id: str, updates: dict) -> dict:
    """更新规则"""
    for rule in RATE_LIMIT_RULES:
        if rule["id"] == rule_id:
            for key in ["name", "priority", "conditions", "action", 
                        "throttle_config", "enabled"]:
                if key in updates:
                    rule[key] = updates[key]
            return {"updated": True, "rule": rule}
    return {"updated": False, "reason": "rule not found"}

def delete_rule(rule_id: str) -> dict:
    """删除规则"""
    for i, rule in enumerate(RATE_LIMIT_RULES):
        if rule["id"] == rule_id:
            deleted = RATE_LIMIT_RULES.pop(i)
            return {"deleted": True, "rule": deleted}
    return {"deleted": False, "reason": "rule not found"}

def get_rule(rule_id: str) -> dict:
    """获取规则"""
    for rule in RATE_LIMIT_RULES:
        if rule["id"] == rule_id:
            return {"found": True, "rule": rule}
    return {"found": False}

def clear_rules() -> int:
    """清空所有规则"""
    count = len(RATE_LIMIT_RULES)
    RATE_LIMIT_RULES.clear()
    return count

