async def get_rate_limit_rules_config():
    """获取规则引擎配置"""
    return {
        "success": True,
        "config": RATE_LIMIT_RULES_CONFIG
    }

@app.post("/api/rate-limit-rules/config")
async def set_rate_limit_rules_config(request: Request):
    """设置规则引擎配置"""
    data = await request.json()
    
    for key in ["enabled", "default_action", "rule_priority", "max_rules"]:
        if key in data:
            RATE_LIMIT_RULES_CONFIG[key] = data[key]
    
    return {
        "success": True,
        "config": RATE_LIMIT_RULES_CONFIG
    }

@app.post("/api/rate-limit-rules/evaluate")
async def evaluate_rules_endpoint(request: Request):
    """评估规则"""
    data = await request.json()
    
    result = apply_rules(data)
    
    return {
        "success": True,
        **result
    }

@app.post("/api/rate-limit-rules/add")
async def add_rule_endpoint(request: Request):
    """添加规则"""
    data = await request.json()
    
    name = data.get("name")
    conditions = data.get("conditions", [])
    action = data.get("action", "allow")
    priority = data.get("priority", 100)
    throttle_config = data.get("throttle_config")
    enabled = data.get("enabled", True)
    
    if not name:
        return {"success": False, "message": "name is required"}
    
    result = add_rule(name, conditions, action, priority, throttle_config, enabled)
    
    return {
        "success": True,
        **result
    }

@app.put("/api/rate-limit-rules/{rule_id}")
async def update_rule_endpoint(rule_id: str, request: Request):
    """更新规则"""
    data = await request.json()
    
    result = update_rule(rule_id, data)
    
    return {
        "success": True,
        **result
    }

@app.delete("/api/rate-limit-rules/{rule_id}")
async def delete_rule_endpoint(rule_id: str):
    """删除规则"""
    result = delete_rule(rule_id)
    
    return {
        "success": True,
        **result
    }

@app.get("/api/rate-limit-rules/{rule_id}")
async def get_rule_endpoint(rule_id: str):
    """获取规则"""
    result = get_rule(rule_id)
    
    return {
        "success": True,
        **result
    }

@app.get("/api/rate-limit-rules")
async def list_rules_endpoint():
    """列出所有规则"""
    sorted_rules = sorted(RATE_LIMIT_RULES, key=lambda r: r.get("priority", 100))
    
    return {
        "success": True,
        "total_rules": len(RATE_LIMIT_RULES),
        "rules": sorted_rules
    }

@app.delete("/api/rate-limit-rules")
async def clear_rules_endpoint():
    """清空所有规则"""
    count = clear_rules()
    
    return {
        "success": True,
        "cleared": count,
        "message": f"cleared {count} rules"
    }

@app.get("/api/rate-limit-rules/stats")
async def get_rules_stats():
    """获取规则统计"""
    return {
        "success": True,
        "stats": RATE_LIMIT_RULES_STATS
    }

@app.delete("/api/rate-limit-rules/stats")
async def clear_rules_stats():
    """清除规则统计"""
    RATE_LIMIT_RULES_STATS["total_requests"] = 0
    RATE_LIMIT_RULES_STATS["total_rule_matches"] = 0
    RATE_LIMIT_RULES_STATS["total_allowed"] = 0
    RATE_LIMIT_RULES_STATS["total_denied"] = 0
    RATE_LIMIT_RULES_STATS["total_throttled"] = 0
    RATE_LIMIT_RULES_STATS["by_rule"].clear()
    
    # 重置规则命中计数
    for rule in RATE_LIMIT_RULES:
        rule["hits"] = 0
    
    return {"success": True, "message": "规则统计已清除"}

# ========== API请求限流动态配置 ==========

DYNAMIC_RATE_LIMIT_CONFIG = {
    "enabled": True,
    "config_version": 1,
    "last_updated": time.time(),
    "update_history": [],
    "profiles": {
        "default": {
            "rate": 100,
            "window": 60,
            "burst": 200
        },
        "strict": {
            "rate": 10,
            "window": 60,
            "burst": 20
        },
        "relaxed": {
            "rate": 1000,
            "window": 60,
            "burst": 2000
        }
    },
    "active_profile": "default",
    "overrides": {
        # key -> {rate, window, burst, expires_at}
    },
    "schedule": {
        # time_range -> profile_name
    }
}

DYNAMIC_CONFIG_STATS = {
    "total_updates": 0,
    "total_profile_switches": 0,
    "total_overrides": 0,
    "total_scheduled_changes": 0,
    "by_profile": {}
}

def get_active_config() -> dict:
    """获取当前活动配置"""
    profile_name = DYNAMIC_RATE_LIMIT_CONFIG["active_profile"]
    profile = DYNAMIC_RATE_LIMIT_CONFIG["profiles"].get(profile_name, {})
    
    return {
        "profile": profile_name,
        "config": profile,
        "version": DYNAMIC_RATE_LIMIT_CONFIG["config_version"],
        "last_updated": DYNAMIC_RATE_LIMIT_CONFIG["last_updated"]
    }

def switch_profile(profile_name: str) -> dict:
    """切换配置档案"""
    if profile_name not in DYNAMIC_RATE_LIMIT_CONFIG["profiles"]:
        return {"switched": False, "reason": "profile not found"}
    
    old_profile = DYNAMIC_RATE_LIMIT_CONFIG["active_profile"]
    DYNAMIC_RATE_LIMIT_CONFIG["active_profile"] = profile_name
    DYNAMIC_RATE_LIMIT_CONFIG["config_version"] += 1
    DYNAMIC_RATE_LIMIT_CONFIG["last_updated"] = time.time()
    
    # 记录更新历史
    DYNAMIC_RATE_LIMIT_CONFIG["update_history"].append({
        "type": "profile_switch",
        "from": old_profile,
        "to": profile_name,
        "timestamp": time.time()
    })
    
    DYNAMIC_CONFIG_STATS["total_profile_switches"] += 1
    
    if profile_name not in DYNAMIC_CONFIG_STATS["by_profile"]:
        DYNAMIC_CONFIG_STATS["by_profile"][profile_name] = {"switches": 0, "usage_time": 0}
    DYNAMIC_CONFIG_STATS["by_profile"][profile_name]["switches"] += 1
    
    return {
        "switched": True,
        "from_profile": old_profile,
        "to_profile": profile_name,
        "version": DYNAMIC_RATE_LIMIT_CONFIG["config_version"]
    }

def create_profile(name: str, config: dict) -> dict:
    """创建配置档案"""
    if name in DYNAMIC_RATE_LIMIT_CONFIG["profiles"]:
        return {"created": False, "reason": "profile already exists"}
    
    DYNAMIC_RATE_LIMIT_CONFIG["profiles"][name] = {
        "rate": config.get("rate", 100),
        "window": config.get("window", 60),
        "burst": config.get("burst", 200)
    }
    
    DYNAMIC_RATE_LIMIT_CONFIG["config_version"] += 1
    DYNAMIC_RATE_LIMIT_CONFIG["last_updated"] = time.time()
    
    return {"created": True, "profile": name, "config": config}

def update_profile(name: str, config: dict) -> dict:
    """更新配置档案"""
    if name not in DYNAMIC_RATE_LIMIT_CONFIG["profiles"]:
        return {"updated": False, "reason": "profile not found"}
    
    for key in ["rate", "window", "burst"]:
        if key in config:
            DYNAMIC_RATE_LIMIT_CONFIG["profiles"][name][key] = config[key]
    
    DYNAMIC_RATE_LIMIT_CONFIG["config_version"] += 1
    DYNAMIC_RATE_LIMIT_CONFIG["last_updated"] = time.time()
    
    return {"updated": True, "profile": name, "config": DYNAMIC_RATE_LIMIT_CONFIG["profiles"][name]}

def delete_profile(name: str) -> dict:
    """删除配置档案"""
    if name not in DYNAMIC_RATE_LIMIT_CONFIG["profiles"]:
        return {"deleted": False, "reason": "profile not found"}
    
    if name == DYNAMIC_RATE_LIMIT_CONFIG["active_profile"]:
        return {"deleted": False, "reason": "cannot delete active profile"}
    
    del DYNAMIC_RATE_LIMIT_CONFIG["profiles"][name]
    DYNAMIC_RATE_LIMIT_CONFIG["config_version"] += 1
    
    return {"deleted": True, "profile": name}

def set_override(key: str, config: dict, duration: int = None) -> dict:
    """设置覆盖配置"""
    override = {
        "rate": config.get("rate"),
        "window": config.get("window"),
        "burst": config.get("burst"),
        "created_at": time.time()
    }
    
    if duration:
        override["expires_at"] = time.time() + duration
    
    DYNAMIC_RATE_LIMIT_CONFIG["overrides"][key] = override
    DYNAMIC_CONFIG_STATS["total_overrides"] += 1
    
    return {"set": True, "key": key, "override": override}

def remove_override(key: str) -> dict:
    """移除覆盖配置"""
    if key in DYNAMIC_RATE_LIMIT_CONFIG["overrides"]:
        del DYNAMIC_RATE_LIMIT_CONFIG["overrides"][key]
        return {"removed": True, "key": key}
    return {"removed": False, "reason": "override not found"}

def get_override(key: str) -> dict:
    """获取覆盖配置"""
    override = DYNAMIC_RATE_LIMIT_CONFIG["overrides"].get(key)
    
    if not override:
        return {"exists": False}
    
    # 检查是否过期
    if "expires_at" in override and time.time() > override["expires_at"]:
        del DYNAMIC_RATE_LIMIT_CONFIG["overrides"][key]
        return {"exists": False, "reason": "expired"}
    
    return {"exists": True, "override": override}

def add_schedule(time_range: str, profile_name: str) -> dict:
    """添加定时配置"""
    if profile_name not in DYNAMIC_RATE_LIMIT_CONFIG["profiles"]:
        return {"added": False, "reason": "profile not found"}
    
    DYNAMIC_RATE_LIMIT_CONFIG["schedule"][time_range] = profile_name
    DYNAMIC_CONFIG_STATS["total_scheduled_changes"] += 1
    
    return {"added": True, "time_range": time_range, "profile": profile_name}

def remove_schedule(time_range: str) -> dict:
    """移除定时配置"""
    if time_range in DYNAMIC_RATE_LIMIT_CONFIG["schedule"]:
        del DYNAMIC_RATE_LIMIT_CONFIG["schedule"][time_range]
        return {"removed": True, "time_range": time_range}
    return {"removed": False, "reason": "schedule not found"}

def check_schedule() -> dict:
    """检查并应用定时配置"""
    current_hour = time.localtime().tm_hour
    current_minute = time.localtime().tm_minute
    current_time = f"{current_hour:02d}:{current_minute:02d}"
    
    for time_range, profile_name in DYNAMIC_RATE_LIMIT_CONFIG["schedule"].items():
        # 简单时间范围检查 (格式: "HH:MM-HH:MM")
        try:
            start, end = time_range.split("-")
            if start <= current_time <= end:
                if DYNAMIC_RATE_LIMIT_CONFIG["active_profile"] != profile_name:
                    return switch_profile(profile_name)
        except:
            continue
    
    return {"checked": True, "no_change": True}

