# ========== API请求限流监控仪表盘 ==========

RATE_LIMIT_DASHBOARD_CONFIG = {
    "enabled": True,
    "refresh_interval_seconds": 5,
    "history_retention_minutes": 60,
    "alert_thresholds": {
        "high_block_rate": 0.5,  # 50%封禁率告警
        "high_latency_ms": 1000,
        "low_success_rate": 0.9
    }
}

RATE_LIMIT_DASHBOARD_DATA = {
    "realtime": {
        "total_requests": 0,
        "allowed_requests": 0,
        "blocked_requests": 0,
        "throttled_requests": 0,
        "avg_latency_ms": 0,
        "peak_latency_ms": 0,
        "active_limiters": 0,
        "last_updated": 0
    },
    "history": [],  # [{timestamp, requests, allowed, blocked, latency}]
    "top_blocked_keys": [],  # [{key, blocked_count}]
    "top_requesters": [],  # [{key, request_count}]
    "alerts": []
}

RATE_LIMIT_DASHBOARD_STATS = {
    "uptime_seconds": 0,
    "start_time": time.time(),
    "total_data_points": 0,
    "total_alerts": 0
}

def update_dashboard_data(request_data: dict) -> None:
    """更新仪表盘数据"""
    realtime = RATE_LIMIT_DASHBOARD_DATA["realtime"]
    
    # 更新实时数据
    realtime["total_requests"] += 1
    
    action = request_data.get("action", "allowed")
    if action == "allowed":
        realtime["allowed_requests"] += 1
    elif action == "blocked":
        realtime["blocked_requests"] += 1
    elif action == "throttled":
        realtime["throttled_requests"] += 1
    
    latency = request_data.get("latency_ms", 0)
    if latency > realtime["peak_latency_ms"]:
        realtime["peak_latency_ms"] = latency
    
    # 计算平均延迟
    total = realtime["total_requests"]
    current_avg = realtime["avg_latency_ms"]
    realtime["avg_latency_ms"] = (current_avg * (total - 1) + latency) / total
    
    realtime["last_updated"] = time.time()
    
    # 更新历史数据
    RATE_LIMIT_DASHBOARD_DATA["history"].append({
        "timestamp": time.time(),
        "requests": realtime["total_requests"],
        "allowed": realtime["allowed_requests"],
        "blocked": realtime["blocked_requests"],
        "latency": latency
    })
    
    # 清理过期历史数据
    retention = RATE_LIMIT_DASHBOARD_CONFIG["history_retention_minutes"] * 60
    cutoff = time.time() - retention
    RATE_LIMIT_DASHBOARD_DATA["history"] = [
        h for h in RATE_LIMIT_DASHBOARD_DATA["history"]
        if h["timestamp"] > cutoff
    ]
    
    # 更新Top被封禁Keys
    key = request_data.get("key")
    if key and action == "blocked":
        top_blocked = RATE_LIMIT_DASHBOARD_DATA["top_blocked_keys"]
        found = False
        for item in top_blocked:
            if item["key"] == key:
                item["blocked_count"] += 1
                found = True
                break
        if not found:
            top_blocked.append({"key": key, "blocked_count": 1})
        # 排序并保留前10
        top_blocked.sort(key=lambda x: x["blocked_count"], reverse=True)
        RATE_LIMIT_DASHBOARD_DATA["top_blocked_keys"] = top_blocked[:10]
    
    # 更新Top请求者
    if key:
        top_requesters = RATE_LIMIT_DASHBOARD_DATA["top_requesters"]
        found = False
        for item in top_requesters:
            if item["key"] == key:
                item["request_count"] += 1
                found = True
                break
        if not found:
            top_requesters.append({"key": key, "request_count": 1})
        top_requesters.sort(key=lambda x: x["request_count"], reverse=True)
        RATE_LIMIT_DASHBOARD_DATA["top_requesters"] = top_requesters[:10]
    
    # 检查告警
    check_alerts(realtime)

def check_alerts(realtime: dict) -> None:
    """检查告警条件"""
    thresholds = RATE_LIMIT_DASHBOARD_CONFIG["alert_thresholds"]
    alerts = RATE_LIMIT_DASHBOARD_DATA["alerts"]
    
    # 高封禁率告警
    total = realtime["total_requests"]
    if total > 10:  # 至少10个请求才检查
        block_rate = realtime["blocked_requests"] / total
        if block_rate > thresholds["high_block_rate"]:
            alert = {
                "type": "high_block_rate",
                "severity": "warning",
                "message": f"封禁率过高: {block_rate:.2%}",
                "value": block_rate,
                "threshold": thresholds["high_block_rate"],
                "timestamp": time.time()
            }
            alerts.append(alert)
            RATE_LIMIT_DASHBOARD_STATS["total_alerts"] += 1
    
    # 高延迟告警
    if realtime["avg_latency_ms"] > thresholds["high_latency_ms"]:
        alert = {
            "type": "high_latency",
            "severity": "warning",
            "message": f"平均延迟过高: {realtime['avg_latency_ms']:.0f}ms",
            "value": realtime["avg_latency_ms"],
            "threshold": thresholds["high_latency_ms"],
            "timestamp": time.time()
        }
        alerts.append(alert)
        RATE_LIMIT_DASHBOARD_STATS["total_alerts"] += 1
    
    # 低成功率告警
    if total > 10:
        success_rate = realtime["allowed_requests"] / total
        if success_rate < thresholds["low_success_rate"]:
            alert = {
                "type": "low_success_rate",
                "severity": "critical",
                "message": f"成功率过低: {success_rate:.2%}",
                "value": success_rate,
                "threshold": thresholds["low_success_rate"],
                "timestamp": time.time()
            }
            alerts.append(alert)
            RATE_LIMIT_DASHBOARD_STATS["total_alerts"] += 1
    
    # 保留最近50条告警
    RATE_LIMIT_DASHBOARD_DATA["alerts"] = alerts[-50:]

def get_dashboard_summary() -> dict:
    """获取仪表盘摘要"""
    realtime = RATE_LIMIT_DASHBOARD_DATA["realtime"]
    stats = RATE_LIMIT_DASHBOARD_STATS
    
    total = realtime["total_requests"]
    block_rate = realtime["blocked_requests"] / total if total > 0 else 0
    success_rate = realtime["allowed_requests"] / total if total > 0 else 0
    
    return {
        "uptime_seconds": time.time() - stats["start_time"],
        "total_requests": total,
        "allowed_requests": realtime["allowed_requests"],
        "blocked_requests": realtime["blocked_requests"],
        "throttled_requests": realtime["throttled_requests"],
        "block_rate": f"{block_rate:.2%}",
        "success_rate": f"{success_rate:.2%}",
        "avg_latency_ms": f"{realtime['avg_latency_ms']:.2f}",
        "peak_latency_ms": realtime["peak_latency_ms"],
        "active_limiters": realtime["active_limiters"],
        "total_alerts": stats["total_alerts"],
        "last_updated": realtime["last_updated"]
    }

def get_dashboard_charts() -> dict:
    """获取图表数据"""
    history = RATE_LIMIT_DASHBOARD_DATA["history"]
    
    # 时间序列数据
    timeline = []
    for h in history[-100:]:  # 最近100个数据点
        timeline.append({
            "time": h["timestamp"],
            "requests": h["requests"],
            "allowed": h["allowed"],
            "blocked": h["blocked"],
            "latency": h["latency"]
        })
    
    return {
        "timeline": timeline,
        "top_blocked_keys": RATE_LIMIT_DASHBOARD_DATA["top_blocked_keys"],
        "top_requesters": RATE_LIMIT_DASHBOARD_DATA["top_requesters"]
    }

def reset_dashboard() -> dict:
    """重置仪表盘"""
    RATE_LIMIT_DASHBOARD_DATA["realtime"] = {
        "total_requests": 0,
        "allowed_requests": 0,
        "blocked_requests": 0,
        "throttled_requests": 0,
        "avg_latency_ms": 0,
        "peak_latency_ms": 0,
        "active_limiters": 0,
        "last_updated": 0
    }
    RATE_LIMIT_DASHBOARD_DATA["history"].clear()
    RATE_LIMIT_DASHBOARD_DATA["top_blocked_keys"].clear()
    RATE_LIMIT_DASHBOARD_DATA["top_requesters"].clear()
    RATE_LIMIT_DASHBOARD_DATA["alerts"].clear()
    RATE_LIMIT_DASHBOARD_STATS["total_data_points"] = 0
    RATE_LIMIT_DASHBOARD_STATS["total_alerts"] = 0
    RATE_LIMIT_DASHBOARD_STATS["start_time"] = time.time()
    
    return {"reset": True}

