@app.get("/api/rate-limit-dashboard/health")
async def get_dashboard_health():
    """获取仪表盘健康状态"""
    realtime = RATE_LIMIT_DASHBOARD_DATA["realtime"]
    thresholds = RATE_LIMIT_DASHBOARD_CONFIG["alert_thresholds"]
    
    total = realtime["total_requests"]
    issues = []
    
    # 检查各项指标
    if total > 10:
        block_rate = realtime["blocked_requests"] / total
        if block_rate > thresholds["high_block_rate"]:
            issues.append({
                "metric": "block_rate",
                "status": "warning",
                "value": f"{block_rate:.2%}",
                "threshold": f"{thresholds['high_block_rate']:.2%}"
            })
    
    if realtime["avg_latency_ms"] > thresholds["high_latency_ms"]:
        issues.append({
            "metric": "latency",
            "status": "warning",
            "value": f"{realtime['avg_latency_ms']:.0f}ms",
            "threshold": f"{thresholds['high_latency_ms']}ms"
        })
    
    if total > 10:
        success_rate = realtime["allowed_requests"] / total
        if success_rate < thresholds["low_success_rate"]:
            issues.append({
                "metric": "success_rate",
                "status": "critical",
                "value": f"{success_rate:.2%}",
                "threshold": f"{thresholds['low_success_rate']:.2%}"
            })
    
    health_status = "healthy" if not issues else "degraded"
    if any(i["status"] == "critical" for i in issues):
        health_status = "critical"
    
    return {
        "success": True,
        "status": health_status,
        "issues": issues,
        "total_requests": total,
        "uptime_seconds": time.time() - RATE_LIMIT_DASHBOARD_STATS["start_time"]
    }

# ========== API请求限流多策略组合 ==========

MULTI_STRATEGY_CONFIG = {
    "enabled": True,
    "combination_mode": "strict",  # strict/loose/priority
    "failure_action": "deny",  # deny/allow/fallback
    "fallback_strategy": "sliding_window"
}

MULTI_STRATEGY_CHAINS = {}
# 链格式: {
#   name: str,
#   strategies: [{type, config, priority}],
#   enabled: bool,
#   stats: {total, passed, failed, by_strategy}
# }

MULTI_STRATEGY_STATS = {
    "total_requests": 0,
    "total_passed": 0,
    "total_failed": 0,
    "total_chains": 0,
    "by_chain": {}
}

CHAIN_ID_COUNTER = 0

def create_chain_id() -> str:
    """创建链ID"""
    global CHAIN_ID_COUNTER
    CHAIN_ID_COUNTER += 1
    return f"chain-{CHAIN_ID_COUNTER}"

def evaluate_strategy(strategy: dict, request_data: dict) -> dict:
    """评估单个策略"""
    strategy_type = strategy.get("type")
    config = strategy.get("config", {})
    
    # 根据策略类型调用相应的限流检查
    if strategy_type == "sliding_window":
        key = request_data.get("key", "default")
        limit = config.get("limit", 100)
        window = config.get("window", 60)
        current_count = request_data.get("count", 0)
        passed = current_count < limit
        remaining = max(0, limit - current_count)
        return {
            "passed": passed,
            "strategy": strategy_type,
            "remaining": remaining,
            "limit": limit,
            "reset_at": time.time() + window
        }
    
    elif strategy_type == "token_bucket":
        key = request_data.get("key", "default")
        rate = config.get("rate", 10)
        burst = config.get("burst", 100)
        tokens = request_data.get("tokens", burst)
        passed = tokens > 0
        remaining = max(0, tokens - 1)
        return {
            "passed": passed,
            "strategy": strategy_type,
            "remaining": remaining,
            "burst": burst,
            "rate": rate
        }
    
    elif strategy_type == "leaky_bucket":
        key = request_data.get("key", "default")
        rate = config.get("rate", 10)
        capacity = config.get("capacity", 100)
        queue_size = request_data.get("queue_size", 0)
        passed = queue_size < capacity
        remaining = max(0, capacity - queue_size)
        return {
            "passed": passed,
            "strategy": strategy_type,
            "remaining": remaining,
            "capacity": capacity,
            "rate": rate
        }
    
    elif strategy_type == "concurrent":
        key = request_data.get("key", "default")
        max_concurrent = config.get("max_concurrent", 100)
        current_concurrent = request_data.get("concurrent", 0)
        passed = current_concurrent < max_concurrent
        remaining = max(0, max_concurrent - current_concurrent)
        return {
            "passed": passed,
            "strategy": strategy_type,
            "remaining": remaining,
            "max_concurrent": max_concurrent
        }
    
    elif strategy_type == "whitelist":
        key = request_data.get("key", "")
        whitelist = config.get("whitelist", [])
        passed = key in whitelist
        return {
            "passed": passed,
            "strategy": strategy_type,
            "in_whitelist": passed
        }
    
    elif strategy_type == "blacklist":
        key = request_data.get("key", "")
        blacklist = config.get("blacklist", [])
        passed = key not in blacklist
        return {
            "passed": passed,
            "strategy": strategy_type,
            "in_blacklist": not passed
        }
    
    elif strategy_type == "rule":
        rules = config.get("rules", [])
        for rule in rules:
            if rule.get("action") == "deny":
                passed = False
                return {
                    "passed": passed,
                    "strategy": strategy_type,
                    "matched_rule": rule.get("name")
                }
        return {
            "passed": True,
            "strategy": strategy_type,
            "matched_rule": None
        }
    
    return {
        "passed": True,
        "strategy": strategy_type,
        "reason": "unknown strategy, default pass"
    }

def evaluate_chain(chain_name: str, request_data: dict) -> dict:
    """评估策略链"""
    if chain_name not in MULTI_STRATEGY_CHAINS:
        return {"passed": False, "reason": "chain not found"}
    
    chain = MULTI_STRATEGY_CHAINS[chain_name]
    
    if not chain.get("enabled", True):
        return {"passed": False, "reason": "chain disabled"}
    
    strategies = chain.get("strategies", [])
    mode = MULTI_STRATEGY_CONFIG["combination_mode"]
    
    results = []
    sorted_strategies = sorted(strategies, key=lambda s: s.get("priority", 100))
    
    for strategy in sorted_strategies:
        result = evaluate_strategy(strategy, request_data)
        results.append(result)
        
        if mode == "strict":
            if not result["passed"]:
                chain["stats"]["total"] += 1
                chain["stats"]["failed"] += 1
                return {
                    "passed": False,
                    "chain": chain_name,
                    "mode": mode,
                    "failed_strategy": result.get("strategy"),
                    "results": results
                }
        
        elif mode == "loose":
            if result["passed"]:
                chain["stats"]["total"] += 1
                chain["stats"]["passed"] += 1
                return {
                    "passed": True,
                    "chain": chain_name,
                    "mode": mode,
                    "passed_strategy": result.get("strategy"),
                    "results": results
                }
        
        elif mode == "priority":
            chain["stats"]["total"] += 1
            if result["passed"]:
                chain["stats"]["passed"] += 1
            else:
                chain["stats"]["failed"] += 1
            return {
                "passed": result["passed"],
                "chain": chain_name,
                "mode": mode,
                "deciding_strategy": result.get("strategy"),
                "results": results
            }
    
    chain["stats"]["total"] += 1
    
    if mode == "strict":
        chain["stats"]["passed"] += 1
        return {"passed": True, "chain": chain_name, "mode": mode, "all_passed": True, "results": results}
    elif mode == "loose":
        chain["stats"]["failed"] += 1
        return {"passed": False, "chain": chain_name, "mode": mode, "all_failed": True, "results": results}
    
    return {"passed": True, "chain": chain_name, "mode": mode, "results": results}

def create_chain(name: str, strategies: list, enabled: bool = True) -> dict:
    """创建策略链"""
    if name in MULTI_STRATEGY_CHAINS:
        return {"created": False, "reason": "chain already exists"}
    
    chain_id = create_chain_id()
    
    chain = {
        "id": chain_id,
        "name": name,
        "strategies": strategies,
        "enabled": enabled,
        "created_at": time.time(),
        "stats": {"total": 0, "passed": 0, "failed": 0, "by_strategy": {}}
    }
    
    MULTI_STRATEGY_CHAINS[name] = chain
    MULTI_STRATEGY_STATS["total_chains"] += 1
    
    return {"created": True, "chain": chain}

def update_chain(name: str, updates: dict) -> dict:
    """更新策略链"""
    if name not in MULTI_STRATEGY_CHAINS:
        return {"updated": False, "reason": "chain not found"}
    
    chain = MULTI_STRATEGY_CHAINS[name]
    
    for key in ["strategies", "enabled"]:
        if key in updates:
            chain[key] = updates[key]
    
    return {"updated": True, "chain": chain}

def delete_chain(name: str) -> dict:
    """删除策略链"""
    if name not in MULTI_STRATEGY_CHAINS:
        return {"deleted": False, "reason": "chain not found"}
    
    del MULTI_STRATEGY_CHAINS[name]
    MULTI_STRATEGY_STATS["total_chains"] -= 1
    
    return {"deleted": True, "name": name}

