# ========== API请求限流智能预测 ==========

PREDICTION_CONFIG = {
    "enabled": True,
    "prediction_window_seconds": 60,
    "min_samples": 10,
    "confidence_threshold": 0.7,
    "auto_adjust": False,
    "adjustment_factor": 0.1
}

PREDICTION_DATA = {
    "request_history": [],  # [{timestamp, key, count}]
    "predictions": {},  # {key: {predicted_load, confidence}}
    "models": {},  # {key: {avg, variance, trend}}
    "alerts": []
}

PREDICTION_STATS = {
    "total_predictions": 0,
    "accurate_predictions": 0,
    "accuracy_rate": 0.0,
    "auto_adjustments": 0,
    "alerts_triggered": 0
}

def add_request_sample(key: str, count: int = 1) -> None:
    """添加请求样本"""
    PREDICTION_DATA["request_history"].append({
        "timestamp": time.time(),
        "key": key,
        "count": count
    })
    
    # 清理过期数据
    window = PREDICTION_CONFIG["prediction_window_seconds"]
    cutoff = time.time() - window * 2
    PREDICTION_DATA["request_history"] = [
        h for h in PREDICTION_DATA["request_history"]
        if h["timestamp"] > cutoff
    ]

def build_model(key: str) -> dict:
    """构建预测模型"""
    window = PREDICTION_CONFIG["prediction_window_seconds"]
    cutoff = time.time() - window
    
    samples = [
        h for h in PREDICTION_DATA["request_history"]
        if h["key"] == key and h["timestamp"] > cutoff
    ]
    
    if len(samples) < PREDICTION_CONFIG["min_samples"]:
        return {"avg": 0, "variance": 0, "trend": 0, "samples": len(samples)}
    
    counts = [s["count"] for s in samples]
    avg = sum(counts) / len(counts)
    
    if len(counts) > 1:
        variance = sum((c - avg) ** 2 for c in counts) / len(counts)
    else:
        variance = 0
    
    # 计算趋势（简单线性）
    if len(samples) >= 3:
        recent = samples[-3:]
        trend = (recent[-1]["count"] - recent[0]["count"]) / 3
    else:
        trend = 0
    
    return {
        "avg": avg,
        "variance": variance,
        "trend": trend,
        "samples": len(samples)
    }

def predict_load(key: str) -> dict:
    """预测负载"""
    if key not in PREDICTION_DATA["models"]:
        PREDICTION_DATA["models"][key] = build_model(key)
    
    model = PREDICTION_DATA["models"][key]
    
    if model["samples"] < PREDICTION_CONFIG["min_samples"]:
        return {
            "predicted_load": 0,
            "confidence": 0,
            "reason": "insufficient_samples"
        }
    
    # 基于平均值和趋势预测
    predicted = model["avg"] + model["trend"]
    predicted = max(0, predicted)
    
    # 计算置信度（基于方差）
    if model["avg"] > 0:
        cv = (model["variance"] ** 0.5) / model["avg"]  # 变异系数
        confidence = max(0, 1 - cv)
    else:
        confidence = 0
    
    PREDICTION_DATA["predictions"][key] = {
        "predicted_load": predicted,
        "confidence": confidence,
        "timestamp": time.time()
    }
    
    PREDICTION_STATS["total_predictions"] += 1
    
    return {
        "predicted_load": predicted,
        "confidence": confidence,
        "trend": model["trend"],
        "samples": model["samples"]
    }

def check_prediction_alert(key: str, predicted_load: float, confidence: float) -> dict:
    """检查预测告警"""
    alerts = []
    
    # 高负载预测
    if predicted_load > 80 and confidence > PREDICTION_CONFIG["confidence_threshold"]:
        alert = {
            "type": "high_load_predicted",
            "key": key,
            "predicted_load": predicted_load,
            "confidence": confidence,
            "timestamp": time.time()
        }
        alerts.append(alert)
        PREDICTION_DATA["alerts"].append(alert)
        PREDICTION_STATS["alerts_triggered"] += 1
    
    # 低置信度警告
    if confidence < 0.3 and predicted_load > 50:
        alert = {
            "type": "low_confidence_high_load",
            "key": key,
            "predicted_load": predicted_load,
            "confidence": confidence,
            "timestamp": time.time()
        }
        alerts.append(alert)
        PREDICTION_DATA["alerts"].append(alert)
        PREDICTION_STATS["alerts_triggered"] += 1
    
    # 保留最近50条告警
    PREDICTION_DATA["alerts"] = PREDICTION_DATA["alerts"][-50:]
    
    return {"alerts": alerts}

def auto_adjust_limits(key: str, predicted_load: float) -> dict:
    """自动调整限制"""
    if not PREDICTION_CONFIG["auto_adjust"]:
        return {"adjusted": False, "reason": "auto_adjust disabled"}
    
    factor = PREDICTION_CONFIG["adjustment_factor"]
    
    # 简化的自动调整逻辑
    if predicted_load > 80:
        # 高负载时增加限制
        adjustment = 1 + factor
        PREDICTION_STATS["auto_adjustments"] += 1
        return {
            "adjusted": True,
            "direction": "increase",
            "factor": adjustment,
            "reason": "high_load_predicted"
        }
    elif predicted_load < 20:
        # 低负载时减少限制
        adjustment = 1 - factor
        PREDICTION_STATS["auto_adjustments"] += 1
        return {
            "adjusted": True,
            "direction": "decrease",
            "factor": adjustment,
            "reason": "low_load_predicted"
        }
    
    return {"adjusted": False, "reason": "load_within_normal"}

def get_prediction_summary() -> dict:
    """获取预测摘要"""
    predictions = PREDICTION_DATA["predictions"]
    
    total_keys = len(predictions)
    high_load_keys = sum(1 for p in predictions.values() if p["predicted_load"] > 80)
    avg_confidence = sum(p["confidence"] for p in predictions.values()) / total_keys if total_keys > 0 else 0
    
    return {
        "total_keys_tracked": total_keys,
        "high_load_keys": high_load_keys,
        "average_confidence": f"{avg_confidence:.2%}",
        "total_alerts": len(PREDICTION_DATA["alerts"]),
        "accuracy_rate": f"{PREDICTION_STATS['accuracy_rate']:.2%}"
    }

