    for key in ["enabled", "detection_window_seconds", "z_score_threshold",
                "min_samples", "spike_threshold", "drop_threshold",
                "auto_block", "auto_block_duration"]:
        if key in data:
            ANOMALY_CONFIG[key] = data[key]
    
    return {"success": True, "config": ANOMALY_CONFIG}

