# ========== API请求限流流量整形 ==========

TRAFFIC_SHAPER_CONFIG = {
    "enabled": True,
    "default_rate": 100,  # 默认速率（请求/秒）
    "default_burst": 200,  # 默认突发容量
    "default_peak": 500,  # 默认峰值
    "shaping_mode": "token_bucket",  # token_bucket, leaky_bucket, smoothed
    "queue_enabled": True,
    "max_queue_size": 1000,
    "queue_timeout_seconds": 30
}

TRAFFIC_SHAPER_DATA = {
    "shapers": {},  # {key: {rate, burst, peak, tokens, last_update}}
    "queues": {},  # {key: [{request_id, timestamp, priority}]}
    "stats": {}  # {key: {shaped_requests, queued_requests, dropped_requests, avg_delay}}
}

TRAFFIC_SHAPER_STATS = {
    "total_shaped": 0,
    "total_queued": 0,
    "total_dropped": 0,
    "total_released": 0,
    "avg_queue_time": 0.0
}

def create_shaper(key: str, rate: int = None, burst: int = None, peak: int = None) -> dict:
    """创建流量整形器"""
    shaper = {
        "rate": rate or TRAFFIC_SHAPER_CONFIG["default_rate"],
        "burst": burst or TRAFFIC_SHAPER_CONFIG["default_burst"],
        "peak": peak or TRAFFIC_SHAPER_CONFIG["default_peak"],
        "tokens": burst or TRAFFIC_SHAPER_CONFIG["default_burst"],
        "last_update": time.time(),
        "created_at": time.time()
    }
    
    TRAFFIC_SHAPER_DATA["shapers"][key] = shaper
    TRAFFIC_SHAPER_DATA["stats"][key] = {
        "shaped_requests": 0,
        "queued_requests": 0,
        "dropped_requests": 0,
        "released_requests": 0,
        "avg_delay": 0.0
    }
    
    return shaper

def update_tokens(key: str) -> float:
    """更新令牌数"""
    if key not in TRAFFIC_SHAPER_DATA["shapers"]:
        create_shaper(key)
    
    shaper = TRAFFIC_SHAPER_DATA["shapers"][key]
    
    now = time.time()
    elapsed = now - shaper["last_update"]
    
    # 按速率补充令牌
    new_tokens = elapsed * shaper["rate"]
    shaper["tokens"] = min(shaper["burst"], shaper["tokens"] + new_tokens)
    shaper["last_update"] = now
    
    return shaper["tokens"]

def shape_request(key: str, tokens_needed: int = 1) -> dict:
    """整形请求"""
    if not TRAFFIC_SHAPER_CONFIG["enabled"]:
        return {"allowed": True, "shaped": False}
    
    if key not in TRAFFIC_SHAPER_DATA["shapers"]:
        create_shaper(key)
    
    current_tokens = update_tokens(key)
    shaper = TRAFFIC_SHAPER_DATA["shapers"][key]
    stats = TRAFFIC_SHAPER_DATA["stats"][key]
    
    if current_tokens >= tokens_needed:
        # 有足够令牌，直接通过
        shaper["tokens"] -= tokens_needed
        stats["shaped_requests"] += 1
        TRAFFIC_SHAPER_STATS["total_shaped"] += 1
        return {
            "allowed": True,
            "shaped": True,
            "tokens_remaining": shaper["tokens"],
            "delay": 0
        }
    
    # 令牌不足，检查是否可以排队
    if TRAFFIC_SHAPER_CONFIG["queue_enabled"]:
        queue = TRAFFIC_SHAPER_DATA["queues"].get(key, [])
        
        if len(queue) < TRAFFIC_SHAPER_CONFIG["max_queue_size"]:
            # 加入队列
            request_id = str(uuid.uuid4())[:8]
            queue.append({
                "request_id": request_id,
                "tokens_needed": tokens_needed,
                "timestamp": time.time(),
                "priority": 0
            })
            TRAFFIC_SHAPER_DATA["queues"][key] = queue
            
            stats["queued_requests"] += 1
            TRAFFIC_SHAPER_STATS["total_queued"] += 1
            
            # 计算预估等待时间
            wait_time = (tokens_needed - current_tokens) / shaper["rate"]
            
            return {
                "allowed": False,
                "shaped": True,
                "queued": True,
                "request_id": request_id,
                "estimated_wait": wait_time,
                "queue_position": len(queue)
            }
    
    # 无法排队，丢弃
    stats["dropped_requests"] += 1
    TRAFFIC_SHAPER_STATS["total_dropped"] += 1
    
    return {
        "allowed": False,
        "shaped": True,
        "dropped": True,
        "reason": "tokens_unavailable"
    }

def process_queue(key: str) -> list:
    """处理队列"""
    if key not in TRAFFIC_SHAPER_DATA["queues"]:
        return []
    
    queue = TRAFFIC_SHAPER_DATA["queues"][key]
    released = []
    
    current_tokens = update_tokens(key)
    shaper = TRAFFIC_SHAPER_DATA["shapers"][key]
    stats = TRAFFIC_SHAPER_DATA["stats"][key]
    
    # 检查队列中的请求
    remaining_queue = []
    
    for item in queue:
        # 检查是否超时
        elapsed = time.time() - item["timestamp"]
        if elapsed > TRAFFIC_SHAPER_CONFIG["queue_timeout_seconds"]:
            stats["dropped_requests"] += 1
            TRAFFIC_SHAPER_STATS["total_dropped"] += 1
            continue
        
        if current_tokens >= item["tokens_needed"]:
            # 可以释放
            current_tokens -= item["tokens_needed"]
            shaper["tokens"] = current_tokens
            
            delay = time.time() - item["timestamp"]
            released.append({
                "request_id": item["request_id"],
                "delay": delay
            })
            
            stats["released_requests"] += 1
            TRAFFIC_SHAPER_STATS["total_released"] += 1
            
            # 更新平均延迟
            if stats["avg_delay"] == 0:
                stats["avg_delay"] = delay
            else:
                stats["avg_delay"] = (stats["avg_delay"] + delay) / 2
        else:
            remaining_queue.append(item)
    
    TRAFFIC_SHAPER_DATA["queues"][key] = remaining_queue
    
    return released

def get_queue_status(key: str) -> dict:
    """获取队列状态"""
    queue = TRAFFIC_SHAPER_DATA["queues"].get(key, [])
    
    return {
        "queue_size": len(queue),
        "max_size": TRAFFIC_SHAPER_CONFIG["max_queue_size"],
        "oldest_age": time.time() - queue[0]["timestamp"] if queue else 0,
        "total_waiting": sum(item["tokens_needed"] for item in queue)
    }

def smooth_traffic(key: str, window_seconds: int = 10) -> dict:
    """平滑流量"""
    if key not in TRAFFIC_SHAPER_DATA["shapers"]:
        return {"smoothed": False, "reason": "shaper_not_found"}
    
    shaper = TRAFFIC_SHAPER_DATA["shapers"][key]
    
    # 计算平滑后的速率
    # 使用指数移动平均
    current_rate = shaper["rate"]
    target_rate = shaper["rate"] * 0.8  # 目标降低20%
    
    smoothed_rate = current_rate * 0.7 + target_rate * 0.3
    shaper["rate"] = smoothed_rate
    
    return {
        "smoothed": True,
        "original_rate": current_rate,
        "smoothed_rate": smoothed_rate,
        "reduction": f"{((current_rate - smoothed_rate) / current_rate * 100):.1f}%"
    }

def apply_burst_limit(key: str, burst_requests: int) -> dict:
    """应用突发限制"""
    if key not in TRAFFIC_SHAPER_DATA["shapers"]:
        create_shaper(key)
    
    shaper = TRAFFIC_SHAPER_DATA["shapers"][key]
    
    if burst_requests > shaper["peak"]:
        # 超过峰值，需要限制
        excess = burst_requests - shaper["peak"]
        delay = excess / shaper["rate"]
        
        return {
            "limited": True,
            "excess": excess,
            "recommended_delay": delay,
            "peak": shaper["peak"]
        }
    
    return {
        "limited": False,
        "burst_requests": burst_requests,
        "peak": shaper["peak"]
    }

