# ========== API请求限流分布式协调 ==========

DISTRIBUTED_COORD_CONFIG = {
    "enabled": True,
    "node_id": "node_1",
    "cluster_size": 3,
    "heartbeat_interval_seconds": 5,
    "election_timeout_seconds": 15,
    "sync_interval_seconds": 10,
    "quorum_size": 2
}

DISTRIBUTED_COORD_DATA = {
    "nodes": {},  # {node_id: {status, last_heartbeat, role, priority}}
    "leader": None,
    "term": 0,
    "votes": {},  # {term: {voter: vote}}
    "logs": [],  # [{term, command, timestamp}]
    "commit_index": 0,
    "last_applied": 0
}

DISTRIBUTED_COORD_STATS = {
    "total_elections": 0,
    "total_heartbeats": 0,
    "total_syncs": 0,
    "leader_changes": 0,
    "sync_failures": 0
}

def register_node(node_id: str, priority: int = 0) -> dict:
    """注册节点"""
    node = {
        "node_id": node_id,
        "status": "active",
        "role": "follower",
        "priority": priority,
        "last_heartbeat": time.time(),
        "registered_at": time.time()
    }
    
    DISTRIBUTED_COORD_DATA["nodes"][node_id] = node
    
    return node

def send_heartbeat(node_id: str) -> dict:
    """发送心跳"""
    if node_id not in DISTRIBUTED_COORD_DATA["nodes"]:
        return {"success": False, "reason": "node_not_registered"}
    
    node = DISTRIBUTED_COORD_DATA["nodes"][node_id]
    node["last_heartbeat"] = time.time()
    node["status"] = "active"
    
    DISTRIBUTED_COORD_STATS["total_heartbeats"] += 1
    
    return {
        "success": True,
        "node_id": node_id,
        "leader": DISTRIBUTED_COORD_DATA["leader"],
        "term": DISTRIBUTED_COORD_DATA["term"]
    }

def check_node_health() -> dict:
    """检查节点健康"""
    now = time.time()
    timeout = DISTRIBUTED_COORD_CONFIG["heartbeat_interval_seconds"] * 3
    
    unhealthy = []
    
    for node_id, node in DISTRIBUTED_COORD_DATA["nodes"].items():
        if now - node["last_heartbeat"] > timeout:
            node["status"] = "inactive"
            unhealthy.append(node_id)
    
    return {
        "total_nodes": len(DISTRIBUTED_COORD_DATA["nodes"]),
        "active_nodes": len([n for n in DISTRIBUTED_COORD_DATA["nodes"].values() if n["status"] == "active"]),
        "unhealthy_nodes": unhealthy
    }

def start_election(candidate_id: str) -> dict:
    """开始选举"""
    if candidate_id not in DISTRIBUTED_COORD_DATA["nodes"]:
        return {"success": False, "reason": "node_not_registered"}
    
    DISTRIBUTED_COORD_DATA["term"] += 1
    term = DISTRIBUTED_COORD_DATA["term"]
    
    # 投票给自己
    DISTRIBUTED_COORD_DATA["votes"][term] = {candidate_id: True}
    
    DISTRIBUTED_COORD_STATS["total_elections"] += 1
    
    return {
        "success": True,
        "term": term,
        "candidate": candidate_id,
        "votes_needed": DISTRIBUTED_COORD_CONFIG["quorum_size"]
    }

def vote(node_id: str, term: int, vote_granted: bool) -> dict:
    """投票"""
    if term not in DISTRIBUTED_COORD_DATA["votes"]:
        DISTRIBUTED_COORD_DATA["votes"][term] = {}
    
    DISTRIBUTED_COORD_DATA["votes"][term][node_id] = vote_granted
    
    # 检查是否获得多数票
    votes = sum(1 for v in DISTRIBUTED_COORD_DATA["votes"][term].values() if v)
    
    if votes >= DISTRIBUTED_COORD_CONFIG["quorum_size"]:
        # 成为leader
        leader_id = None
        for vid, v in DISTRIBUTED_COORD_DATA["votes"][term].items():
            if v:
                leader_id = vid
                break
        
        if leader_id:
            DISTRIBUTED_COORD_DATA["leader"] = leader_id
            DISTRIBUTED_COORD_DATA["nodes"][leader_id]["role"] = "leader"
            DISTRIBUTED_COORD_STATS["leader_changes"] += 1
            
            return {
                "success": True,
                "elected": True,
                "leader": leader_id,
                "term": term
            }
    
    return {
        "success": True,
        "elected": False,
        "current_votes": votes,
        "votes_needed": DISTRIBUTED_COORD_CONFIG["quorum_size"]
    }

def sync_state(leader_id: str, state: dict) -> dict:
    """同步状态"""
    if DISTRIBUTED_COORD_DATA["leader"] != leader_id:
        return {"success": False, "reason": "not_leader"}
    
    DISTRIBUTED_COORD_STATS["total_syncs"] += 1
    
    # 记录同步日志
    log_entry = {
        "term": DISTRIBUTED_COORD_DATA["term"],
        "command": "sync",
        "state": state,
        "timestamp": time.time()
    }
    DISTRIBUTED_COORD_DATA["logs"].append(log_entry)
    
    # 保留最近100条日志
    DISTRIBUTED_COORD_DATA["logs"] = DISTRIBUTED_COORD_DATA["logs"][-100:]
    
    return {
        "success": True,
        "log_index": len(DISTRIBUTED_COORD_DATA["logs"]) - 1
    }

def append_log(leader_id: str, command: str, data: dict = None) -> dict:
    """追加日志"""
    if DISTRIBUTED_COORD_DATA["leader"] != leader_id:
        return {"success": False, "reason": "not_leader"}
    
    entry = {
        "term": DISTRIBUTED_COORD_DATA["term"],
        "command": command,
        "data": data or {},
        "timestamp": time.time()
    }
    
    DISTRIBUTED_COORD_DATA["logs"].append(entry)
    
    return {
        "success": True,
        "index": len(DISTRIBUTED_COORD_DATA["logs"]) - 1
    }

def commit_log(leader_id: str, index: int) -> dict:
    """提交日志"""
    if DISTRIBUTED_COORD_DATA["leader"] != leader_id:
        return {"success": False, "reason": "not_leader"}
    
    if index >= len(DISTRIBUTED_COORD_DATA["logs"]):
        return {"success": False, "reason": "invalid_index"}
    
    DISTRIBUTED_COORD_DATA["commit_index"] = index
    
    return {
        "success": True,
        "commit_index": index
    }

def get_cluster_state() -> dict:
    """获取集群状态"""
    health = check_node_health()
    
    return {
        "leader": DISTRIBUTED_COORD_DATA["leader"],
        "term": DISTRIBUTED_COORD_DATA["term"],
        "commit_index": DISTRIBUTED_COORD_DATA["commit_index"],
        "log_count": len(DISTRIBUTED_COORD_DATA["logs"]),
        **health
    }

def distribute_rate_limit(key: str, limit: int, leader_id: str) -> dict:
    """分发限流配置"""
    if DISTRIBUTED_COORD_DATA["leader"] != leader_id:
        return {"success": False, "reason": "not_leader"}
    
    # 计算每个节点的配额
    active_nodes = [n for n in DISTRIBUTED_COORD_DATA["nodes"].values() if n["status"] == "active"]
    node_count = len(active_nodes)
    
    if node_count == 0:
        return {"success": False, "reason": "no_active_nodes"}
    
    per_node_limit = limit // node_count
    remainder = limit % node_count
    
    distribution = {}
    for i, node in enumerate(active_nodes):
        distribution[node["node_id"]] = per_node_limit + (1 if i < remainder else 0)
    
    # 记录分发日志
    append_log(leader_id, "distribute_rate_limit", {
        "key": key,
        "total_limit": limit,
        "distribution": distribution
    })
    
    return {
        "success": True,
        "key": key,
        "total_limit": limit,
        "distribution": distribution,
        "node_count": node_count
    }

