# ========== API请求限流自适应调节器 ==========

ADAPTIVE_REGULATOR_CONFIG = {
    "enabled": True,
    "min_limit": 10,
    "max_limit": 10000,
    "initial_limit": 100,
    "adjustment_interval_seconds": 60,
    "target_utilization": 0.7,
    "increase_factor": 1.2,
    "decrease_factor": 0.8,
    "smoothing_factor": 0.3,
    "learning_rate": 0.1
}

ADAPTIVE_REGULATOR_DATA = {
    "regulators": {},  # {key: {current_limit, history, adjustments}}
    "metrics": {},  # {key: {utilization, latency, errors, throughput}}
    "adjustments_log": []  # [{key, old_limit, new_limit, reason, timestamp}]
}

ADAPTIVE_REGULATOR_STATS = {
    "total_adjustments": 0,
    "increases": 0,
    "decreases": 0,
    "avg_adjustment_ratio": 1.0,
    "stable_periods": 0
}

def create_regulator(key: str, initial_limit: int = None) -> dict:
    """创建调节器"""
    regulator = {
        "key": key,
        "current_limit": initial_limit or ADAPTIVE_REGULATOR_CONFIG["initial_limit"],
        "min_limit": ADAPTIVE_REGULATOR_CONFIG["min_limit"],
        "max_limit": ADAPTIVE_REGULATOR_CONFIG["max_limit"],
        "history": [],
        "created_at": time.time(),
        "last_adjustment": time.time()
    }
    
    ADAPTIVE_REGULATOR_DATA["regulators"][key] = regulator
    ADAPTIVE_REGULATOR_DATA["metrics"][key] = {
        "utilization": 0.0,
        "latency": 0.0,
        "errors": 0,
        "throughput": 0.0
    }
    
    return regulator

def update_metrics(key: str, utilization: float, latency: float, errors: int, throughput: float) -> None:
    """更新指标"""
    if key not in ADAPTIVE_REGULATOR_DATA["metrics"]:
        ADAPTIVE_REGULATOR_DATA["metrics"][key] = {
            "utilization": 0.0,
            "latency": 0.0,
            "errors": 0,
            "throughput": 0.0
        }
    
    metrics = ADAPTIVE_REGULATOR_DATA["metrics"][key]
    
    # 使用指数移动平均平滑指标
    alpha = ADAPTIVE_REGULATOR_CONFIG["smoothing_factor"]
    
    metrics["utilization"] = alpha * utilization + (1 - alpha) * metrics["utilization"]
    metrics["latency"] = alpha * latency + (1 - alpha) * metrics["latency"]
    metrics["errors"] = errors
    metrics["throughput"] = alpha * throughput + (1 - alpha) * metrics["throughput"]

def calculate_adjustment(key: str) -> dict:
    """计算调整"""
    if key not in ADAPTIVE_REGULATOR_DATA["regulators"]:
        return {"adjust": False, "reason": "regulator_not_found"}
    
    regulator = ADAPTIVE_REGULATOR_DATA["regulators"][key]
    metrics = ADAPTIVE_REGULATOR_DATA["metrics"].get(key, {})
    
    current_limit = regulator["current_limit"]
    target_util = ADAPTIVE_REGULATOR_CONFIG["target_utilization"]
    current_util = metrics.get("utilization", 0.5)
    
    # 计算利用率偏差
    util_deviation = current_util - target_util
    
    # 基于利用率的调整
    if current_util > 0.9:
        # 过载，需要降低
        factor = ADAPTIVE_REGULATOR_CONFIG["decrease_factor"]
        reason = "overload"
    elif current_util < 0.5:
        # 利用不足，可以增加
        factor = ADAPTIVE_REGULATOR_CONFIG["increase_factor"]
        reason = "under_utilized"
    elif abs(util_deviation) < 0.1:
        # 接近目标，微调
        factor = 1.0 + (util_deviation * ADAPTIVE_REGULATOR_CONFIG["learning_rate"])
        reason = "fine_tune"
    else:
        # 中等偏差
        if util_deviation > 0:
            factor = 1.0 - (util_deviation * ADAPTIVE_REGULATOR_CONFIG["learning_rate"] * 2)
            reason = "reduce_pressure"
        else:
            factor = 1.0 - (util_deviation * ADAPTIVE_REGULATOR_CONFIG["learning_rate"] * 2)
            reason = "increase_capacity"
    
    new_limit = int(current_limit * factor)
    
    # 应用边界
    new_limit = max(regulator["min_limit"], min(regulator["max_limit"], new_limit))
    
    # 检查是否需要调整
    if new_limit == current_limit:
        return {
            "adjust": False,
            "reason": "no_change_needed",
            "current_limit": current_limit
        }
    
    return {
        "adjust": True,
        "old_limit": current_limit,
        "new_limit": new_limit,
        "factor": factor,
        "reason": reason,
        "utilization": current_util
    }

def apply_adjustment(key: str, adjustment: dict) -> dict:
    """应用调整"""
    if not adjustment.get("adjust"):
        return {"applied": False, "reason": adjustment.get("reason")}
    
    regulator = ADAPTIVE_REGULATOR_DATA["regulators"][key]
    
    old_limit = regulator["current_limit"]
    new_limit = adjustment["new_limit"]
    
    regulator["current_limit"] = new_limit
    regulator["last_adjustment"] = time.time()
    
    # 记录历史
    regulator["history"].append({
        "old_limit": old_limit,
        "new_limit": new_limit,
        "reason": adjustment["reason"],
        "timestamp": time.time()
    })
    
    # 保留最近50条历史
    regulator["history"] = regulator["history"][-50:]
    
    # 记录调整日志
    ADAPTIVE_REGULATOR_DATA["adjustments_log"].append({
        "key": key,
        "old_limit": old_limit,
        "new_limit": new_limit,
        "reason": adjustment["reason"],
        "timestamp": time.time()
    })
    
    # 保留最近100条日志
    ADAPTIVE_REGULATOR_DATA["adjustments_log"] = ADAPTIVE_REGULATOR_DATA["adjustments_log"][-100:]
    
    # 更新统计
    ADAPTIVE_REGULATOR_STATS["total_adjustments"] += 1
    if new_limit > old_limit:
        ADAPTIVE_REGULATOR_STATS["increases"] += 1
    else:
        ADAPTIVE_REGULATOR_STATS["decreases"] += 1
    
    ratio = new_limit / old_limit if old_limit > 0 else 1.0
    ADAPTIVE_REGULATOR_STATS["avg_adjustment_ratio"] = (
        ADAPTIVE_REGULATOR_STATS["avg_adjustment_ratio"] * 0.9 + ratio * 0.1
    )
    
    return {
        "applied": True,
        "key": key,
        "old_limit": old_limit,
        "new_limit": new_limit,
        "reason": adjustment["reason"]
    }

def auto_adjust(key: str) -> dict:
    """自动调整"""
    adjustment = calculate_adjustment(key)
    
    if adjustment.get("adjust"):
        return apply_adjustment(key, adjustment)
    
    ADAPTIVE_REGULATOR_STATS["stable_periods"] += 1
    
    return {
        "applied": False,
        "key": key,
        "current_limit": ADAPTIVE_REGULATOR_DATA["regulators"][key]["current_limit"],
        "reason": adjustment.get("reason")
    }

def get_regulator_status(key: str) -> dict:
    """获取调节器状态"""
    if key not in ADAPTIVE_REGULATOR_DATA["regulators"]:
        return {"found": False}
    
    regulator = ADAPTIVE_REGULATOR_DATA["regulators"][key]
    metrics = ADAPTIVE_REGULATOR_DATA["metrics"].get(key, {})
    
    return {
        "found": True,
        "current_limit": regulator["current_limit"],
        "min_limit": regulator["min_limit"],
        "max_limit": regulator["max_limit"],
        "metrics": metrics,
        "history_count": len(regulator["history"]),
        "last_adjustment": regulator["last_adjustment"],
        "age_seconds": time.time() - regulator["created_at"]
    }

def predict_optimal_limit(key: str) -> dict:
    """预测最优限制"""
    if key not in ADAPTIVE_REGULATOR_DATA["regulators"]:
        return {"predicted": False, "reason": "regulator_not_found"}
    
    regulator = ADAPTIVE_REGULATOR_DATA["regulators"][key]
    metrics = ADAPTIVE_REGULATOR_DATA["metrics"].get(key, {})
    
    current_util = metrics.get("utilization", 0.5)
    current_limit = regulator["current_limit"]
    target_util = ADAPTIVE_REGULATOR_CONFIG["target_utilization"]
    
    if current_util > 0:
        # 基于当前利用率预测
        predicted_limit = int(current_limit * target_util / current_util)
    else:
        predicted_limit = current_limit
    
    # 应用边界
    predicted_limit = max(regulator["min_limit"], min(regulator["max_limit"], predicted_limit))
    
    return {
        "predicted": True,
        "current_limit": current_limit,
        "predicted_limit": predicted_limit,
        "current_utilization": current_util,
        "target_utilization": target_util,
        "adjustment_needed": predicted_limit != current_limit
    }

