# ========== API请求限流智能调度器 ==========

SMART_SCHEDULER_CONFIG = {
    "enabled": True,
    "default_priority": 5,
    "max_priority": 10,
    "min_priority": 1,
    "scheduling_interval_seconds": 1,
    "max_concurrent": 100,
    "fair_share_enabled": True,
    "preemption_enabled": True,
    "aging_enabled": True,
    "aging_interval_seconds": 60
}

SMART_SCHEDULER_DATA = {
    "queues": {},  # {priority: [{request_id, key, timestamp, tokens, status}]}
    "requests": {},  # {request_id: {key, priority, tokens, status, created_at, started_at, completed_at}}
    "running": {},  # {key: {request_id, tokens, started_at}}
    "stats": {}  # {key: {total_requests, completed, preempted, avg_wait_time}}
}

SMART_SCHEDULER_STATS = {
    "total_scheduled": 0,
    "total_completed": 0,
    "total_preempted": 0,
    "total_rejected": 0,
    "avg_wait_time": 0.0,
    "avg_execution_time": 0.0,
    "current_queue_size": 0,
    "current_running": 0
}

def create_scheduler_queue(priority: int) -> list:
    """创建调度队列"""
    if priority not in SMART_SCHEDULER_DATA["queues"]:
        SMART_SCHEDULER_DATA["queues"][priority] = []
    return SMART_SCHEDULER_DATA["queues"][priority]

def submit_request(key: str, tokens: int = 1, priority: int = None) -> dict:
    """提交请求"""
    if not SMART_SCHEDULER_CONFIG["enabled"]:
        return {"scheduled": False, "reason": "scheduler_disabled"}
    
    priority = priority or SMART_SCHEDULER_CONFIG["default_priority"]
    priority = max(SMART_SCHEDULER_CONFIG["min_priority"], 
                   min(SMART_SCHEDULER_CONFIG["max_priority"], priority))
    
    request_id = str(uuid.uuid4())[:8]
    
    request = {
        "request_id": request_id,
        "key": key,
        "tokens": tokens,
        "priority": priority,
        "status": "queued",
        "created_at": time.time(),
        "started_at": None,
        "completed_at": None,
        "wait_time": 0
    }
    
    # 检查是否可以直接运行
    current_running = len(SMART_SCHEDULER_DATA["running"])
    
    if current_running < SMART_SCHEDULER_CONFIG["max_concurrent"]:
        # 直接运行
        request["status"] = "running"
        request["started_at"] = time.time()
        
        SMART_SCHEDULER_DATA["running"][request_id] = {
            "key": key,
            "tokens": tokens,
            "started_at": request["started_at"]
        }
        
        SMART_SCHEDULER_DATA["requests"][request_id] = request
        SMART_SCHEDULER_STATS["total_scheduled"] += 1
        SMART_SCHEDULER_STATS["current_running"] = current_running + 1
        
        return {
            "scheduled": True,
            "immediate": True,
            "request_id": request_id,
            "status": "running"
        }
    
    # 加入队列
    create_scheduler_queue(priority)
    SMART_SCHEDULER_DATA["queues"][priority].append(request)
    SMART_SCHEDULER_DATA["requests"][request_id] = request
    
    # 更新统计
    SMART_SCHEDULER_STATS["total_scheduled"] += 1
    SMART_SCHEDULER_STATS["current_queue_size"] = sum(len(q) for q in SMART_SCHEDULER_DATA["queues"].values())
    
    return {
        "scheduled": True,
        "immediate": False,
        "request_id": request_id,
        "priority": priority,
        "queue_position": len(SMART_SCHEDULER_DATA["queues"][priority])
    }

def get_next_request() -> dict:
    """获取下一个请求"""
    if not SMART_SCHEDULER_CONFIG["enabled"]:
        return {"found": False, "reason": "scheduler_disabled"}
    
    # 检查运行容量
    current_running = len(SMART_SCHEDULER_DATA["running"])
    if current_running >= SMART_SCHEDULER_CONFIG["max_concurrent"]:
        return {"found": False, "reason": "max_concurrent_reached"}
    
    # 按优先级查找
    for priority in range(SMART_SCHEDULER_CONFIG["max_priority"], 
                          SMART_SCHEDULER_CONFIG["min_priority"] - 1, -1):
        queue = SMART_SCHEDULER_DATA["queues"].get(priority, [])
        
        if queue:
            request = queue.pop(0)
            request["status"] = "running"
            request["started_at"] = time.time()
            request["wait_time"] = request["started_at"] - request["created_at"]
            
            SMART_SCHEDULER_DATA["running"][request["request_id"]] = {
                "key": request["key"],
                "tokens": request["tokens"],
                "started_at": request["started_at"]
            }
            
            SMART_SCHEDULER_STATS["current_running"] = len(SMART_SCHEDULER_DATA["running"])
            SMART_SCHEDULER_STATS["current_queue_size"] = sum(len(q) for q in SMART_SCHEDULER_DATA["queues"].values())
            
            # 更新平均等待时间
            SMART_SCHEDULER_STATS["avg_wait_time"] = (
                SMART_SCHEDULER_STATS["avg_wait_time"] * 0.9 + request["wait_time"] * 0.1
            )
            
            return {"found": True, "request": request}
    
    return {"found": False, "reason": "queue_empty"}

def complete_request(request_id: str) -> dict:
    """完成请求"""
    if request_id not in SMART_SCHEDULER_DATA["requests"]:
        return {"completed": False, "reason": "request_not_found"}
    
    request = SMART_SCHEDULER_DATA["requests"][request_id]
    
    if request["status"] != "running":
        return {"completed": False, "reason": "request_not_running"}
    
    request["status"] = "completed"
    request["completed_at"] = time.time()
    
    execution_time = request["completed_at"] - request["started_at"]
    
    # 从运行中移除
    if request_id in SMART_SCHEDULER_DATA["running"]:
        del SMART_SCHEDULER_DATA["running"][request_id]
    
    # 更新统计
    SMART_SCHEDULER_STATS["total_completed"] += 1
    SMART_SCHEDULER_STATS["current_running"] = len(SMART_SCHEDULER_DATA["running"])
    SMART_SCHEDULER_STATS["avg_execution_time"] = (
        SMART_SCHEDULER_STATS["avg_execution_time"] * 0.9 + execution_time * 0.1
    )
    
    # 更新key统计
    key = request["key"]
    if key not in SMART_SCHEDULER_DATA["stats"]:
        SMART_SCHEDULER_DATA["stats"][key] = {
            "total_requests": 0,
            "completed": 0,
            "preempted": 0,
            "avg_wait_time": 0.0
        }
    
    SMART_SCHEDULER_DATA["stats"][key]["completed"] += 1
    SMART_SCHEDULER_DATA["stats"][key]["avg_wait_time"] = (
        SMART_SCHEDULER_DATA["stats"][key]["avg_wait_time"] * 0.9 + request["wait_time"] * 0.1
    )
    
    return {
        "completed": True,
        "request_id": request_id,
        "execution_time": execution_time,
        "wait_time": request["wait_time"]
    }

def preempt_request(request_id: str, reason: str = "higher_priority") -> dict:
    """抢占请求"""
    if request_id not in SMART_SCHEDULER_DATA["requests"]:
        return {"preempted": False, "reason": "request_not_found"}
    
    request = SMART_SCHEDULER_DATA["requests"][request_id]
    
    if request["status"] != "running":
        return {"preempted": False, "reason": "request_not_running"}
    
    # 标记为被抢占
    request["status"] = "preempted"
    request["completed_at"] = time.time()
    
    # 从运行中移除
    if request_id in SMART_SCHEDULER_DATA["running"]:
        del SMART_SCHEDULER_DATA["running"][request_id]
    
    # 重新加入队列（降低优先级）
    new_priority = max(SMART_SCHEDULER_CONFIG["min_priority"], request["priority"] - 1)
    request["priority"] = new_priority
    request["status"] = "queued"
    request["started_at"] = None
    
    create_scheduler_queue(new_priority)
    SMART_SCHEDULER_DATA["queues"][new_priority].append(request)
    
    # 更新统计
    SMART_SCHEDULER_STATS["total_preempted"] += 1
    SMART_SCHEDULER_STATS["current_running"] = len(SMART_SCHEDULER_DATA["running"])
    
    key = request["key"]
    if key in SMART_SCHEDULER_DATA["stats"]:
        SMART_SCHEDULER_DATA["stats"][key]["preempted"] += 1
    
    return {
        "preempted": True,
        "request_id": request_id,
        "new_priority": new_priority,
        "reason": reason
    }

def apply_aging() -> dict:
    """应用老化机制"""
    if not SMART_SCHEDULER_CONFIG["aging_enabled"]:
        return {"applied": False, "reason": "aging_disabled"}
    
    aged_count = 0
    now = time.time()
    aging_interval = SMART_SCHEDULER_CONFIG["aging_interval_seconds"]
    
    for priority, queue in SMART_SCHEDULER_DATA["queues"].items():
        for request in queue:
            wait_time = now - request["created_at"]
            
            # 每等待一个aging_interval，提升一级优先级
            priority_boost = int(wait_time / aging_interval)
            
            if priority_boost > 0:
                new_priority = min(SMART_SCHEDULER_CONFIG["max_priority"], 
                                   request["priority"] + priority_boost)
                
                if new_priority > request["priority"]:
                    request["priority"] = new_priority
                    aged_count += 1
    
    return {
        "applied": True,
        "aged_requests": aged_count
    }

def get_queue_status() -> dict:
    """获取队列状态"""
    queues = {}
    total_queued = 0
    
    for priority, queue in SMART_SCHEDULER_DATA["queues"].items():
        queues[priority] = {
            "count": len(queue),
            "oldest_age": time.time() - queue[0]["created_at"] if queue else 0
        }
        total_queued += len(queue)
    
    return {
        "total_queued": total_queued,
        "total_running": len(SMART_SCHEDULER_DATA["running"]),
        "queues": queues
    }

def get_fair_share() -> dict:
    """获取公平份额"""
    if not SMART_SCHEDULER_CONFIG["fair_share_enabled"]:
        return {"enabled": False}
    
    # 计算每个key的份额
    key_shares = {}
    total_requests = sum(
        stats["total_requests"] for stats in SMART_SCHEDULER_DATA["stats"].values()
    )
    
    for key, stats in SMART_SCHEDULER_DATA["stats"].items():
        if total_requests > 0:
            share = stats["completed"] / total_requests
        else:
            share = 0
        
        key_shares[key] = {
            "completed": stats["completed"],
            "share": f"{share:.2%}"
        }
    
    return {
        "enabled": True,
        "total_requests": total_requests,
        "shares": key_shares
    }

