@app.delete("/api/smart-scheduler/request/{request_id}")
async def cancel_request(request_id: str):
    """取消请求"""
    if request_id not in SMART_SCHEDULER_DATA["requests"]:
        return {"success": True, "cancelled": False, "reason": "not_found"}
    
    request = SMART_SCHEDULER_DATA["requests"][request_id]
    
    if request["status"] == "queued":
        # 从队列移除
        priority = request["priority"]
        if priority in SMART_SCHEDULER_DATA["queues"]:
            SMART_SCHEDULER_DATA["queues"][priority] = [
                r for r in SMART_SCHEDULER_DATA["queues"][priority] 
                if r["request_id"] != request_id
            ]
    
    request["status"] = "cancelled"
    SMART_SCHEDULER_STATS["total_rejected"] += 1
    
    return {"success": True, "cancelled": True, "request_id": request_id}

