# ========== API请求限流资源配额管理 ==========

RESOURCE_QUOTA_CONFIG = {
    "enabled": True,
    "default_quota": 1000,
    "max_quota": 100000,
    "min_quota": 10,
    "quota_period_seconds": 3600,
    "overage_allowed": 0.1,
    "borrowing_enabled": True,
    "max_borrow": 100
}

RESOURCE_QUOTA_DATA = {
    "quotas": {},  # {key: {total, used, borrowed, lent, period_start}}
    "history": {},  # {key: [{period_start, period_end, used, borrowed}]}
    "reservations": {}  # {reservation_id: {key, amount, status, created_at}}
}

RESOURCE_QUOTA_STATS = {
    "total_allocated": 0,
    "total_used": 0,
    "total_borrowed": 0,
    "total_lent": 0,
    "overage_events": 0,
    "quota_exceeded": 0
}

def create_quota(key: str, total: int = None) -> dict:
    """创建配额"""
    total = total or RESOURCE_QUOTA_CONFIG["default_quota"]
    total = max(RESOURCE_QUOTA_CONFIG["min_quota"], 
                min(RESOURCE_QUOTA_CONFIG["max_quota"], total))
    
    quota = {
        "key": key,
        "total": total,
        "used": 0,
        "borrowed": 0,
        "lent": 0,
        "available": total,
        "period_start": time.time(),
        "period_end": time.time() + RESOURCE_QUOTA_CONFIG["quota_period_seconds"],
        "created_at": time.time()
    }
    
    RESOURCE_QUOTA_DATA["quotas"][key] = quota
    RESOURCE_QUOTA_DATA["history"][key] = []
    
    RESOURCE_QUOTA_STATS["total_allocated"] += total
    
    return quota

def check_quota(key: str, amount: int = 1) -> dict:
    """检查配额"""
    if key not in RESOURCE_QUOTA_DATA["quotas"]:
        return {"allowed": False, "reason": "quota_not_found"}
    
    quota = RESOURCE_QUOTA_DATA["quotas"][key]
    
    # 检查是否需要重置周期
    if time.time() >= quota["period_end"]:
        reset_quota_period(key)
    
    available = quota["available"]
    overage_allowed = int(quota["total"] * RESOURCE_QUOTA_CONFIG["overage_allowed"])
    max_available = quota["total"] + overage_allowed
    
    if quota["used"] + amount <= max_available:
        return {
            "allowed": True,
            "available": available,
            "used": quota["used"],
            "total": quota["total"],
            "remaining": max(0, max_available - quota["used"] - amount)
        }
    
    RESOURCE_QUOTA_STATS["quota_exceeded"] += 1
    
    return {
        "allowed": False,
        "reason": "quota_exceeded",
        "available": available,
        "used": quota["used"],
        "total": quota["total"]
    }

def consume_quota(key: str, amount: int = 1) -> dict:
    """消耗配额"""
    check = check_quota(key, amount)
    
    if not check["allowed"]:
        return {"consumed": False, **check}
    
    quota = RESOURCE_QUOTA_DATA["quotas"][key]
    quota["used"] += amount
    quota["available"] = quota["total"] + quota["borrowed"] - quota["lent"] - quota["used"]
    
    # 检查是否超限
    if quota["used"] > quota["total"]:
        overage = quota["used"] - quota["total"]
        if overage <= int(quota["total"] * RESOURCE_QUOTA_CONFIG["overage_allowed"]):
            RESOURCE_QUOTA_STATS["overage_events"] += 1
    
    RESOURCE_QUOTA_STATS["total_used"] += amount
    
    return {
        "consumed": True,
        "amount": amount,
        "used": quota["used"],
        "available": quota["available"],
        "total": quota["total"]
    }

def release_quota(key: str, amount: int = 1) -> dict:
    """释放配额"""
    if key not in RESOURCE_QUOTA_DATA["quotas"]:
        return {"released": False, "reason": "quota_not_found"}
    
    quota = RESOURCE_QUOTA_DATA["quotas"][key]
    
    actual_release = min(amount, quota["used"])
    quota["used"] -= actual_release
    quota["available"] = quota["total"] + quota["borrowed"] - quota["lent"] - quota["used"]
    
    return {
        "released": True,
        "amount": actual_release,
        "used": quota["used"],
        "available": quota["available"]
    }

def reset_quota_period(key: str) -> dict:
    """重置配额周期"""
    if key not in RESOURCE_QUOTA_DATA["quotas"]:
        return {"reset": False, "reason": "quota_not_found"}
    
    quota = RESOURCE_QUOTA_DATA["quotas"][key]
    
    # 记录历史
    RESOURCE_QUOTA_DATA["history"][key].append({
        "period_start": quota["period_start"],
        "period_end": quota["period_end"],
        "used": quota["used"],
        "borrowed": quota["borrowed"],
        "lent": quota["lent"]
    })
    
    # 保留最近24个周期
    RESOURCE_QUOTA_DATA["history"][key] = RESOURCE_QUOTA_DATA["history"][key][-24:]
    
    # 重置
    quota["used"] = 0
    quota["borrowed"] = 0
    quota["lent"] = 0
    quota["available"] = quota["total"]
    quota["period_start"] = time.time()
    quota["period_end"] = time.time() + RESOURCE_QUOTA_CONFIG["quota_period_seconds"]
    
    return {
        "reset": True,
        "key": key,
        "total": quota["total"],
        "new_period_start": quota["period_start"]
    }

def borrow_quota(from_key: str, to_key: str, amount: int) -> dict:
    """借用配额"""
    if not RESOURCE_QUOTA_CONFIG["borrowing_enabled"]:
        return {"borrowed": False, "reason": "borrowing_disabled"}
    
    if from_key not in RESOURCE_QUOTA_DATA["quotas"]:
        return {"borrowed": False, "reason": "source_quota_not_found"}
    
    if to_key not in RESOURCE_QUOTA_DATA["quotas"]:
        return {"borrowed": False, "reason": "target_quota_not_found"}
    
    from_quota = RESOURCE_QUOTA_DATA["quotas"][from_key]
    to_quota = RESOURCE_QUOTA_DATA["quotas"][to_key]
    
    # 检查借出限制
    max_borrow = min(
        RESOURCE_QUOTA_CONFIG["max_borrow"],
        from_quota["available"]
    )
    
    if amount > max_borrow:
        return {"borrowed": False, "reason": "amount_exceeds_limit", "max_borrowable": max_borrow}
    
    # 执行借用
    from_quota["lent"] += amount
    from_quota["available"] -= amount
    
    to_quota["borrowed"] += amount
    to_quota["available"] += amount
    
    RESOURCE_QUOTA_STATS["total_borrowed"] += amount
    RESOURCE_QUOTA_STATS["total_lent"] += amount
    
    return {
        "borrowed": True,
        "from_key": from_key,
        "to_key": to_key,
        "amount": amount,
        "from_available": from_quota["available"],
        "to_available": to_quota["available"]
    }

def reserve_quota(key: str, amount: int, duration_seconds: int = 300) -> dict:
    """预留配额"""
    check = check_quota(key, amount)
    
    if not check["allowed"]:
        return {"reserved": False, **check}
    
    reservation_id = str(uuid.uuid4())[:8]
    
    # 消耗配额
    consume_quota(key, amount)
    
    reservation = {
        "reservation_id": reservation_id,
        "key": key,
        "amount": amount,
        "status": "active",
        "expires_at": time.time() + duration_seconds,
        "created_at": time.time()
    }
    
    RESOURCE_QUOTA_DATA["reservations"][reservation_id] = reservation
    
    return {
        "reserved": True,
        "reservation_id": reservation_id,
        "key": key,
        "amount": amount,
        "expires_at": reservation["expires_at"]
    }

def cancel_reservation(reservation_id: str) -> dict:
    """取消预留"""
    if reservation_id not in RESOURCE_QUOTA_DATA["reservations"]:
        return {"cancelled": False, "reason": "reservation_not_found"}
    
    reservation = RESOURCE_QUOTA_DATA["reservations"][reservation_id]
    
    if reservation["status"] != "active":
        return {"cancelled": False, "reason": "reservation_not_active"}
    
    # 释放配额
    release_quota(reservation["key"], reservation["amount"])
    
    reservation["status"] = "cancelled"
    
    return {
        "cancelled": True,
        "reservation_id": reservation_id,
        "released_amount": reservation["amount"]
    }

def get_quota_status(key: str) -> dict:
    """获取配额状态"""
    if key not in RESOURCE_QUOTA_DATA["quotas"]:
        return {"found": False}
    
    quota = RESOURCE_QUOTA_DATA["quotas"][key]
    
    # 检查周期
    if time.time() >= quota["period_end"]:
        reset_quota_period(key)
        quota = RESOURCE_QUOTA_DATA["quotas"][key]
    
    usage_percent = (quota["used"] / quota["total"] * 100) if quota["total"] > 0 else 0
    
    return {
        "found": True,
        "key": key,
        "total": quota["total"],
        "used": quota["used"],
        "available": quota["available"],
        "borrowed": quota["borrowed"],
        "lent": quota["lent"],
        "usage_percent": f"{usage_percent:.1f}%",
        "period_remaining": max(0, quota["period_end"] - time.time())
    }

def get_quota_usage_history(key: str) -> dict:
    """获取配额使用历史"""
    if key not in RESOURCE_QUOTA_DATA["history"]:
        return {"found": False}
    
    return {
        "found": True,
        "key": key,
        "history_count": len(RESOURCE_QUOTA_DATA["history"][key]),
        "history": RESOURCE_QUOTA_DATA["history"][key]
    }

