@app.put("/api/resource-quota/quota/{key}")
async def update_quota(key: str, request: Request):
    """更新配额"""
    if key not in RESOURCE_QUOTA_DATA["quotas"]:
        return {"success": False, "reason": "quota_not_found"}
    
    data = await request.json()
    quota = RESOURCE_QUOTA_DATA["quotas"][key]
    
    if "total" in data:
        new_total = max(RESOURCE_QUOTA_CONFIG["min_quota"],
                        min(RESOURCE_QUOTA_CONFIG["max_quota"], data["total"]))
        RESOURCE_QUOTA_STATS["total_allocated"] += (new_total - quota["total"])
        quota["total"] = new_total
        quota["available"] = quota["total"] + quota["borrowed"] - quota["lent"] - quota["used"]
    
    return {"success": True, "quota": quota}

@app.delete("/api/resource-quota/quota/{key}")
async def delete_quota(key: str):
    """删除配额"""
    if key in RESOURCE_QUOTA_DATA["quotas"]:
        quota = RESOURCE_QUOTA_DATA["quotas"][key]
        RESOURCE_QUOTA_STATS["total_allocated"] -= quota["total"]
        del RESOURCE_QUOTA_DATA["quotas"][key]
        return {"success": True, "deleted": True}
    return {"success": True, "deleted": False}

