# ==================== 回答质量统计API ====================

# 质量统计数据存储
QUALITY_STATS_DATA = {
    "total_evaluations": 0,
    "total_score_sum": 0.0,
    "structure_score_sum": 0.0,
    "relevance_score_sum": 0.0,
    "length_score_sum": 0.0,
    "retry_count": 0,
    "recent_scores": [],
    "issue_counts": {},
    "trend": "no_data",
    "session_start": None
}

@app.get("/api/quality/stats")
async def get_quality_stats():
    """获取回答质量统计"""
    if QUALITY_STATS_DATA["total_evaluations"] == 0:
        return {
            "success": True,
            "stats": {
                "avg_total_score": 0.0,
                "avg_structure_score": 0.0,
                "avg_relevance_score": 0.0,
                "avg_length_score": 0.0,
                "retry_rate": 0.0,
                "trend": "no_data",
                "top_issues": [],
                "recent_scores": [],
                "total_evaluations": 0
            }
        }
    
    n = QUALITY_STATS_DATA["total_evaluations"]
    
    # 获取最常见问题
    sorted_issues = sorted(
        QUALITY_STATS_DATA["issue_counts"].items(),
        key=lambda x: x[1],
        reverse=True
    )[:5]
    
    return {
        "success": True,
        "stats": {
            "avg_total_score": QUALITY_STATS_DATA["total_score_sum"] / n,
            "avg_structure_score": QUALITY_STATS_DATA["structure_score_sum"] / n,
            "avg_relevance_score": QUALITY_STATS_DATA["relevance_score_sum"] / n,
            "avg_length_score": QUALITY_STATS_DATA["length_score_sum"] / n,
            "retry_rate": QUALITY_STATS_DATA["retry_count"] / n,
            "trend": QUALITY_STATS_DATA["trend"],
            "top_issues": sorted_issues,
            "recent_scores": QUALITY_STATS_DATA["recent_scores"][-10:],
            "total_evaluations": n,
            "retry_count": QUALITY_STATS_DATA["retry_count"]
        }
    }

@app.post("/api/quality/update")
async def update_quality_stats(
    total_score: float = 0.0,
    structure_score: float = 0.0,
    relevance_score: float = 0.0,
    length_score: float = 0.0,
    retry: int = 0,
    issues: list = []
):
    """更新质量统计（由处理器调用）"""
    import time
    
    QUALITY_STATS_DATA["total_evaluations"] += 1
    QUALITY_STATS_DATA["total_score_sum"] += total_score
    QUALITY_STATS_DATA["structure_score_sum"] += structure_score
    QUALITY_STATS_DATA["relevance_score_sum"] += relevance_score
    QUALITY_STATS_DATA["length_score_sum"] += length_score
    QUALITY_STATS_DATA["retry_count"] += retry
    
    # 记录最近评分
    QUALITY_STATS_DATA["recent_scores"].append(total_score)
    if len(QUALITY_STATS_DATA["recent_scores"]) > 20:
        QUALITY_STATS_DATA["recent_scores"] = QUALITY_STATS_DATA["recent_scores"][-20:]
    
    # 统计问题类型
    for issue in issues:
        issue_key = issue.split('：')[0] if '：' in issue else issue[:10]
        QUALITY_STATS_DATA["issue_counts"][issue_key] = \
            QUALITY_STATS_DATA["issue_counts"].get(issue_key, 0) + 1
    
    # 计算趋势
    if len(QUALITY_STATS_DATA["recent_scores"]) >= 10:
        recent = QUALITY_STATS_DATA["recent_scores"][-5:]
        earlier = QUALITY_STATS_DATA["recent_scores"][-10:-5]
        recent_avg = sum(recent) / len(recent)
        earlier_avg = sum(earlier) / len(earlier)
        
        if recent_avg > earlier_avg + 5:
            QUALITY_STATS_DATA["trend"] = "improving"
        elif recent_avg < earlier_avg - 5:
            QUALITY_STATS_DATA["trend"] = "declining"
        else:
            QUALITY_STATS_DATA["trend"] = "stable"
    
    return {"success": True, "message": "质量统计已更新"}

@app.delete("/api/quality/stats")
async def reset_quality_stats():
    """重置质量统计"""
    import time
    
    QUALITY_STATS_DATA["total_evaluations"] = 0
    QUALITY_STATS_DATA["total_score_sum"] = 0.0
    QUALITY_STATS_DATA["structure_score_sum"] = 0.0
    QUALITY_STATS_DATA["relevance_score_sum"] = 0.0
    QUALITY_STATS_DATA["length_score_sum"] = 0.0
    QUALITY_STATS_DATA["retry_count"] = 0
    QUALITY_STATS_DATA["recent_scores"] = []
    QUALITY_STATS_DATA["issue_counts"] = {}
    QUALITY_STATS_DATA["trend"] = "no_data"
    QUALITY_STATS_DATA["session_start"] = time.time()
    
    return {"success": True, "message": "质量统计已重置"}

@app.get("/api/quality/summary")
async def get_quality_summary():
    """获取质量摘要"""
    if QUALITY_STATS_DATA["total_evaluations"] == 0:
        return {
            "success": True,
            "summary": {
                "status": "暂无数据",
                "message": "等待更多对话以生成质量报告"
            }
        }
    
    n = QUALITY_STATS_DATA["total_evaluations"]
    avg_score = QUALITY_STATS_DATA["total_score_sum"] / n
    
    # 质量等级
    if avg_score >= 80:
        level = "优秀"
        emoji = "🌟"
    elif avg_score >= 70:
        level = "良好"
        emoji = "✅"
    elif avg_score >= 60:
        level = "合格"
        emoji = "📋"
    else:
        level = "需改进"
        emoji = "⚠️"
    
    return {
        "success": True,
        "summary": {
            "level": f"{emoji} {level}",
            "avg_score": f"{avg_score:.1f}分",
            "total_evaluations": n,
            "trend": QUALITY_STATS_DATA["trend"],
            "retry_rate": f"{QUALITY_STATS_DATA['retry_count'] / n * 100:.1f}%",
            "top_issue": list(QUALITY_STATS_DATA["issue_counts"].keys())[0] if QUALITY_STATS_DATA["issue_counts"] else "无"
        }
    }

@app.get("/api/quality/alert")
async def get_quality_alert():
    """获取质量趋势预警"""
    if QUALITY_STATS_DATA["total_evaluations"] < 5:
        return {
            "success": True,
            "alert": {
                "level": "normal",
                "message": "数据不足，等待更多评估",
                "recommendations": [],
                "auto_actions": []
            }
        }
    
    avg_score = QUALITY_STATS_DATA["total_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
    trend = QUALITY_STATS_DATA["trend"]
    retry_rate = QUALITY_STATS_DATA["retry_count"] / QUALITY_STATS_DATA["total_evaluations"]
    
    alert = {
        "level": "normal",
        "message": "",
        "recommendations": [],
        "auto_actions": []
    }
    
    # 临界状态
    if avg_score < 50 or (trend == "declining" and avg_score < 60):
        alert["level"] = "critical"
        alert["message"] = f"⚠️ 质量严重下降！平均分: {avg_score:.1f}，趋势: {trend}"
        alert["recommendations"] = ["检查LLM模型状态", "调整质量阈值", "优化prompt模板"]
        alert["auto_actions"] = ["lower_threshold", "increase_retry"]
    
    # 警告状态
    elif trend == "declining" or avg_score < 65 or retry_rate > 0.3:
        alert["level"] = "warning"
        alert["message"] = f"📉 质量下降趋势，平均分: {avg_score:.1f}，重试率: {retry_rate*100:.1f}%"
        alert["recommendations"] = ["关注常见问题类型", "检查最近回答质量"]
        alert["auto_actions"] = ["monitor_closely"]
    
    # 正常稳定
    elif trend == "stable" and avg_score >= 70:
        alert["level"] = "normal"
        alert["message"] = f"✅ 质量稳定，平均分: {avg_score:.1f}"
    
    # 改善中
    elif trend == "improving":
        alert["level"] = "normal"
        alert["message"] = f"📈 质量提升中，平均分: {avg_score:.1f}"
        alert["auto_actions"] = ["raise_threshold"]
    
    return {
        "success": True,
        "alert": alert,
        "stats": {
            "avg_score": avg_score,
            "trend": trend,
            "retry_rate": retry_rate,
            "total_evaluations": QUALITY_STATS_DATA["total_evaluations"]
        }
    }

@app.post("/api/quality/alert/execute")
async def execute_quality_alert_actions(request: Request):
    """自动执行质量预警动作"""
    data = await request.json()
    actions = data.get("actions", [])
    
    results = {
        "executed": [],
        "failed": [],
        "changes": {}
    }
    
    for action in actions:
        try:
            if action == "lower_threshold":
                results["changes"]["threshold"] = 50.0
                results["executed"].append(action)
                
            elif action == "raise_threshold":
                results["changes"]["threshold"] = 75.0
                results["executed"].append(action)
                
            elif action == "increase_retry":
                results["changes"]["max_retries"] = 3
                results["executed"].append(action)
                
            elif action == "monitor_closely":
                results["changes"]["monitor_mode"] = "enhanced"
                results["executed"].append(action)
                
        except Exception as e:
            results["failed"].append({"action": action, "error": str(e)})
    
    return {
        "success": True,
        "results": results
    }

@app.post("/api/quality/suggestions")
async def generate_quality_suggestions(request: Request):
    """生成质量改进建议"""
    data = await request.json()
    quality = data.get("quality", {})
    
    suggestions = {
        "priority": "low",
        "actions": [],
        "prompt_hints": [],
        "focus_areas": []
    }
    
    total_score = quality.get("total_score", 0)
    issues = quality.get("issues", [])
    question_type = quality.get("question_type", "query")
    
    # 根据总分确定优先级
    if total_score < 50:
        suggestions["priority"] = "high"
    elif total_score < 70:
        suggestions["priority"] = "medium"
    else:
        suggestions["priority"] = "low"
    
    # 根据问题生成具体建议
    for issue in issues:
        if "Markdown" in issue or "标题" in issue:
            suggestions["actions"].append("添加##标题分层")
            suggestions["prompt_hints"].append("使用Markdown标题(##)组织内容")
            suggestions["focus_areas"].append("structure")
            
        elif "列表" in issue:
            suggestions["actions"].append("使用-或*列表格式")
            suggestions["prompt_hints"].append("用列表呈现要点")
            suggestions["focus_areas"].append("structure")
            
        elif "emoji" in issue.lower():
            suggestions["actions"].append("添加状态标识emoji")
            suggestions["prompt_hints"].append("使用✅⚠️🔧等emoji标注")
            suggestions["focus_areas"].append("structure")
            
        elif "过长" in issue:
            suggestions["actions"].append("精简回答内容")
            suggestions["prompt_hints"].append("控制在100-200字")
            suggestions["focus_areas"].append("length")
            
        elif "过短" in issue:
            suggestions["actions"].append("补充必要细节")
            suggestions["prompt_hints"].append("添加简要说明")
            suggestions["focus_areas"].append("length")
            
        elif "相关性" in issue:
            suggestions["actions"].append("聚焦核心问题")
            suggestions["prompt_hints"].append("先回答核心问题再展开")
            suggestions["focus_areas"].append("relevance")
    
    # 根据问题类型添加特定建议
    type_suggestions = {
        "query": ["明确回答问题", "提供关键信息"],
        "test": ["说明测试步骤", "预期结果"],
        "operation": ["分步骤指导", "注意事项"],
        "analysis": ["数据支撑", "结论明确"],
        "config": ["配置示例", "参数说明"]
    }
    
    if question_type in type_suggestions:
        suggestions["prompt_hints"].extend(type_suggestions[question_type])
    
    # 去重
    suggestions["actions"] = list(set(suggestions["actions"]))
    suggestions["prompt_hints"] = list(set(suggestions["prompt_hints"]))
    suggestions["focus_areas"] = list(set(suggestions["focus_areas"]))
    
    return {
        "success": True,
        "suggestions": suggestions
    }

@app.post("/api/quality/history/save")
async def save_quality_history():
    """保存质量历史到文件"""
    import json
    import os
    
    filepath = os.path.join(os.path.dirname(__file__), '.quality_history.json')
    
    try:
        with open(filepath, 'w', encoding='utf-8') as f:
            json.dump(QUALITY_STATS_DATA, f, ensure_ascii=False, indent=2)
        
        return {
            "success": True,
            "filepath": filepath,
            "total_evaluations": QUALITY_STATS_DATA["total_evaluations"]
        }
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }

@app.get("/api/quality/history/load")
async def load_quality_history():
    """从文件加载质量历史"""
    import json
    import os
    
    filepath = os.path.join(os.path.dirname(__file__), '.quality_history.json')
    
    global QUALITY_STATS_DATA
    
    try:
        if not os.path.exists(filepath):
            return {
                "success": False,
                "error": "File not found"
            }
        
        with open(filepath, 'r', encoding='utf-8') as f:
            loaded = json.load(f)
        
        # 更新全局数据
        QUALITY_STATS_DATA.update(loaded)
        
        return {
            "success": True,
            "filepath": filepath,
            "total_evaluations": QUALITY_STATS_DATA["total_evaluations"]
        }
    except Exception as e:
        return {
            "success": False,
            "error": str(e)
        }

@app.get("/api/quality/history/export")
async def export_quality_history():
    """导出质量历史为JSON文件下载"""
    import json
    from fastapi.responses import Response
    
    content = json.dumps(QUALITY_STATS_DATA, ensure_ascii=False, indent=2)
    
    return Response(
        content=content,
        media_type="application/json",
        headers={
            "Content-Disposition": "attachment; filename=quality_history.json"
        }
    )

