# 用户反馈数据存储
USER_FEEDBACK_DATA = {
    "total_feedbacks": 0,
    "positive_count": 0,
    "negative_count": 0,
    "neutral_count": 0,
    "feedback_history": [],
    "average_user_rating": 0.0,
    "rating_sum": 0
}

@app.post("/api/quality/feedback")
async def submit_quality_feedback(request: Request):
    """提交用户对回答质量的反馈"""
    data = await request.json()
    
    session_id = data.get("session_id", "")
    rating = data.get("rating", 3)  # 1-5分
    feedback_type = data.get("feedback_type", "neutral")  # positive/negative/neutral
    comment = data.get("comment", "")
    quality_score = data.get("quality_score", 0)
    
    # 更新反馈统计
    USER_FEEDBACK_DATA["total_feedbacks"] += 1
    USER_FEEDBACK_DATA["rating_sum"] += rating
    USER_FEEDBACK_DATA["average_user_rating"] = USER_FEEDBACK_DATA["rating_sum"] / USER_FEEDBACK_DATA["total_feedbacks"]
    
    if feedback_type == "positive":
        USER_FEEDBACK_DATA["positive_count"] += 1
    elif feedback_type == "negative":
        USER_FEEDBACK_DATA["negative_count"] += 1
    else:
        USER_FEEDBACK_DATA["neutral_count"] += 1
    
    # 记录反馈历史
    from datetime import datetime
    feedback_record = {
        "session_id": session_id,
        "rating": rating,
        "feedback_type": feedback_type,
        "comment": comment,
        "quality_score": quality_score,
        "timestamp": datetime.now().isoformat()
    }
    USER_FEEDBACK_DATA["feedback_history"].append(feedback_record)
    
    # 保留最近100条反馈
    if len(USER_FEEDBACK_DATA["feedback_history"]) > 100:
        USER_FEEDBACK_DATA["feedback_history"] = USER_FEEDBACK_DATA["feedback_history"][-100:]
    
    # 根据反馈调整质量阈值（如果用户评分低，降低阈值使重试更容易触发）
    if rating <= 2 and quality_score >= 60:
        adjustment = {
            "action": "lower_threshold",
            "reason": "用户评分较低但系统评分较高，可能需要调整评估标准",
            "suggested_threshold": max(50, quality_score - 10)
        }
    elif rating >= 4 and quality_score < 60:
        adjustment = {
            "action": "raise_threshold",
            "reason": "用户评分较高但系统评分较低，可能评估过于严格",
            "suggested_threshold": min(75, quality_score + 5)
        }
    else:
        adjustment = None
    
    return {
        "success": True,
        "message": "反馈已记录",
        "feedback_id": len(USER_FEEDBACK_DATA["feedback_history"]),
        "adjustment": adjustment
    }

@app.get("/api/quality/feedback/stats")
async def get_feedback_stats():
    """获取用户反馈统计"""
    return {
        "success": True,
        "stats": {
            "total_feedbacks": USER_FEEDBACK_DATA["total_feedbacks"],
            "positive_count": USER_FEEDBACK_DATA["positive_count"],
            "negative_count": USER_FEEDBACK_DATA["negative_count"],
            "neutral_count": USER_FEEDBACK_DATA["neutral_count"],
            "average_user_rating": round(USER_FEEDBACK_DATA["average_user_rating"], 2),
            "satisfaction_rate": round(
                USER_FEEDBACK_DATA["positive_count"] / max(1, USER_FEEDBACK_DATA["total_feedbacks"]) * 100, 1
            )
        },
        "recent_feedbacks": USER_FEEDBACK_DATA["feedback_history"][-10:]
    }

# 反馈学习模型配置
FEEDBACK_LEARNING_MODEL = {
    "learning_enabled": True,
    "weight_adjustments": {
        "structure_weight": 0.4,
        "relevance_weight": 0.35,
        "length_weight": 0.25
    },
    "threshold_adjustments": {
        "base_threshold": 60,
        "adjustment_factor": 0.0
    },
    "learning_rate": 0.1,
    "min_samples_for_learning": 10,
    "last_learning_time": None,
    "learning_history": []
}

@app.post("/api/quality/feedback/learn")
async def learn_from_feedback():
    """基于用户反馈学习并调整质量评估参数"""
    from datetime import datetime
    
    if not FEEDBACK_LEARNING_MODEL["learning_enabled"]:
        return {
            "success": False,
            "message": "反馈学习功能已禁用"
        }
    
    # 检查是否有足够的反馈数据
    if USER_FEEDBACK_DATA["total_feedbacks"] < FEEDBACK_LEARNING_MODEL["min_samples_for_learning"]:
        return {
            "success": False,
            "message": f"反馈数据不足，需要至少{FEEDBACK_LEARNING_MODEL['min_samples_for_learning']}条反馈",
            "current_feedbacks": USER_FEEDBACK_DATA["total_feedbacks"]
        }
    
    # 分析反馈数据
    feedback_history = USER_FEEDBACK_DATA["feedback_history"]
    
    # 计算用户评分与系统评分的相关性
    correlations = []
    for fb in feedback_history:
        if fb.get("quality_score", 0) > 0:
            # 用户评分(1-5)转换为0-100分
            user_score_normalized = fb["rating"] * 20
            system_score = fb["quality_score"]
            gap = user_score_normalized - system_score
            correlations.append({
                "user_normalized": user_score_normalized,
                "system_score": system_score,
                "gap": gap
            })
    
    if not correlations:
        return {
            "success": False,
            "message": "没有足够的评分数据进行学习"
        }
    
    # 计算平均差距
    avg_gap = sum(c["gap"] for c in correlations) / len(correlations)
    
    # 根据差距调整阈值
    learning_rate = FEEDBACK_LEARNING_MODEL["learning_rate"]
    current_threshold = FEEDBACK_LEARNING_MODEL["threshold_adjustments"]["base_threshold"]
    
    # 如果用户评分普遍高于系统评分，说明系统过于严格，应降低阈值
    # 如果用户评分普遍低于系统评分，说明系统过于宽松，应提高阈值
    threshold_adjustment = -avg_gap * learning_rate * 0.5  # 阈值调整方向与差距相反
    new_threshold = max(50, min(75, current_threshold + threshold_adjustment))
    
    FEEDBACK_LEARNING_MODEL["threshold_adjustments"]["base_threshold"] = new_threshold
    FEEDBACK_LEARNING_MODEL["threshold_adjustments"]["adjustment_factor"] = threshold_adjustment
    FEEDBACK_LEARNING_MODEL["last_learning_time"] = datetime.now().isoformat()
    
    # 分析不同反馈类型的模式
    positive_feedbacks = [fb for fb in feedback_history if fb["feedback_type"] == "positive"]
    negative_feedbacks = [fb for fb in feedback_history if fb["feedback_type"] == "negative"]
    
    # 根据反馈类型调整权重
    weight_adjustments = {}
    if len(negative_feedbacks) > len(positive_feedbacks):
        # 负面反馈多，增加各维度权重敏感度
        weight_adjustments = {
            "structure_weight": 0.45,
            "relevance_weight": 0.35,
            "length_weight": 0.20
        }
    else:
        # 正面反馈多，保持默认权重
        weight_adjustments = {
            "structure_weight": 0.40,
            "relevance_weight": 0.35,
            "length_weight": 0.25
        }
    
    FEEDBACK_LEARNING_MODEL["weight_adjustments"] = weight_adjustments
    
    # 记录学习历史
    learning_record = {
        "timestamp": FEEDBACK_LEARNING_MODEL["last_learning_time"],
        "samples_used": len(correlations),
        "avg_gap": round(avg_gap, 2),
        "threshold_before": round(current_threshold, 1),
        "threshold_after": round(new_threshold, 1),
        "weight_adjustments": weight_adjustments
    }
    FEEDBACK_LEARNING_MODEL["learning_history"].append(learning_record)
    
    # 保留最近20次学习记录
    if len(FEEDBACK_LEARNING_MODEL["learning_history"]) > 20:
        FEEDBACK_LEARNING_MODEL["learning_history"] = FEEDBACK_LEARNING_MODEL["learning_history"][-20:]
    
    return {
        "success": True,
        "message": "学习完成，参数已调整",
        "learning_result": {
            "samples_analyzed": len(correlations),
            "average_gap": round(avg_gap, 2),
            "threshold_adjustment": {
                "before": round(current_threshold, 1),
                "after": round(new_threshold, 1),
                "change": round(threshold_adjustment, 2)
            },
            "weight_adjustments": weight_adjustments,
            "insight": "用户评分普遍高于系统评分，系统评估可能过于严格" if avg_gap > 5 else
                      "用户评分普遍低于系统评分，系统评估可能过于宽松" if avg_gap < -5 else
                      "用户评分与系统评分基本一致，评估标准合理"
        }
    }

