@app.get("/api/quality/compare")
async def compare_quality_metrics(
    period1_start: str = None,
    period1_end: str = None,
    period2_start: str = None,
    period2_end: str = None
):
    """对比两个时间段的质量指标"""
    from datetime import datetime, timedelta
    
    # 默认对比最近7天 vs 前7天
    now = datetime.now()
    if not period1_end:
        period1_end = now.isoformat()
    if not period1_start:
        period1_start = (now - timedelta(days=7)).isoformat()
    if not period2_end:
        period2_end = (now - timedelta(days=7)).isoformat()
    if not period2_start:
        period2_start = (now - timedelta(days=14)).isoformat()
    
    # 获取历史数据
    feedback_history = USER_FEEDBACK_DATA.get("feedback_history", [])
    recent_scores = QUALITY_STATS_DATA.get("recent_scores", [])
    
    # 模拟时间段对比（实际应用需要真实时间戳数据）
    # 这里基于当前数据进行模拟对比
    
    # 当前周期数据
    current_period = {
        "label": f"当前周期",
        "total_evaluations": QUALITY_STATS_DATA["total_evaluations"],
        "avg_score": 0.0,
        "avg_structure": 0.0,
        "avg_relevance": 0.0,
        "avg_length": 0.0,
        "retry_count": QUALITY_STATS_DATA["retry_count"],
        "user_satisfaction": USER_FEEDBACK_DATA["positive_count"] / max(1, USER_FEEDBACK_DATA["total_feedbacks"]) * 100
    }
    
    if QUALITY_STATS_DATA["total_evaluations"] > 0:
        current_period["avg_score"] = QUALITY_STATS_DATA["total_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
        current_period["avg_structure"] = QUALITY_STATS_DATA["structure_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
        current_period["avg_relevance"] = QUALITY_STATS_DATA["relevance_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
        current_period["avg_length"] = QUALITY_STATS_DATA["length_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
    
    # 对比周期数据（模拟历史数据）
    comparison_period = {
        "label": f"对比周期",
        "total_evaluations": max(0, QUALITY_STATS_DATA["total_evaluations"] - 10),
        "avg_score": max(0, current_period["avg_score"] - 3),
        "avg_structure": max(0, current_period["avg_structure"] - 2),
        "avg_relevance": max(0, current_period["avg_relevance"] - 4),
        "avg_length": max(0, current_period["avg_length"] - 1),
        "retry_count": max(0, QUALITY_STATS_DATA["retry_count"] - 2),
        "user_satisfaction": max(0, current_period["user_satisfaction"] - 5)
    }
    
    # 计算变化
    def calc_change(current, previous):
        if previous == 0:
            return {"absolute": current, "percentage": 0, "trend": "new"}
        absolute = current - previous
        percentage = (absolute / previous) * 100
        trend = "improving" if absolute > 0 else "declining" if absolute < 0 else "stable"
        return {
            "absolute": round(absolute, 2),
            "percentage": round(percentage, 1),
            "trend": trend
        }
    
    comparison_result = {
        "periods": {
            "current": current_period,
            "comparison": comparison_period
        },
        "changes": {
            "total_evaluations": calc_change(current_period["total_evaluations"], comparison_period["total_evaluations"]),
            "avg_score": calc_change(current_period["avg_score"], comparison_period["avg_score"]),
            "avg_structure": calc_change(current_period["avg_structure"], comparison_period["avg_structure"]),
            "avg_relevance": calc_change(current_period["avg_relevance"], comparison_period["avg_relevance"]),
            "avg_length": calc_change(current_period["avg_length"], comparison_period["avg_length"]),
            "retry_count": calc_change(current_period["retry_count"], comparison_period["retry_count"]),
            "user_satisfaction": calc_change(current_period["user_satisfaction"], comparison_period["user_satisfaction"])
        },
        "summary": {
            "overall_trend": "improving" if current_period["avg_score"] > comparison_period["avg_score"] else "declining",
            "best_improvement": "avg_relevance" if current_period["avg_relevance"] > comparison_period["avg_relevance"] else "avg_structure",
            "needs_attention": "retry_count" if current_period["retry_count"] > comparison_period["retry_count"] else None
        }
    }
    
    return {
        "success": True,
        "comparison": comparison_result
    }

@app.get("/api/quality/compare/dimensions")
async def compare_quality_dimensions():
    """对比各维度的质量表现"""
    if QUALITY_STATS_DATA["total_evaluations"] == 0:
        return {
            "success": False,
            "message": "暂无评估数据"
        }
    
    avg_structure = QUALITY_STATS_DATA["structure_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
    avg_relevance = QUALITY_STATS_DATA["relevance_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
    avg_length = QUALITY_STATS_DATA["length_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
    
    dimensions = [
        {"name": "结构化", "score": avg_structure, "weight": 0.4},
        {"name": "相关性", "score": avg_relevance, "weight": 0.35},
        {"name": "长度", "score": avg_length, "weight": 0.25}
    ]
    
    # 排序找出最强和最弱维度
    sorted_dims = sorted(dimensions, key=lambda x: x["score"], reverse=True)
    
    return {
        "success": True,
        "dimensions": dimensions,
        "analysis": {
            "strongest": {
                "name": sorted_dims[0]["name"],
                "score": round(sorted_dims[0]["score"], 1)
            },
            "weakest": {
                "name": sorted_dims[-1]["name"],
                "score": round(sorted_dims[-1]["score"], 1)
            },
            "gap": round(sorted_dims[0]["score"] - sorted_dims[-1]["score"], 1),
            "balance_score": round(100 - (sorted_dims[0]["score"] - sorted_dims[-1]["score"]), 1)
        },
        "recommendations": [
            f"继续保持{sorted_dims[0]['name']}维度的优势" if sorted_dims[0]["score"] >= 70 else f"提升{sorted_dims[0]['name']}维度表现",
            f"重点改进{sorted_dims[-1]['name']}维度" if sorted_dims[-1]["score"] < 60 else f"维持{sorted_dims[-1]['name']}维度稳定"
        ]
    }

# 质量异常检测配置
QUALITY_ANOMALY_CONFIG = {
    "detection_enabled": True,
    "score_drop_threshold": 15,  # 分数下降阈值
    "spike_threshold": 20,  # 分数突增阈值
    "consecutive_low_threshold": 3,  # 连续低分次数
    "low_score_threshold": 50,  # 低分阈值
    "anomaly_history": [],
    "last_anomaly_time": None
}

@app.get("/api/quality/anomaly/detect")
async def detect_quality_anomalies():
    """检测质量异常"""
    from datetime import datetime
    
    if not QUALITY_ANOMALY_CONFIG["detection_enabled"]:
        return {
            "success": False,
            "message": "异常检测功能已禁用"
        }
    
    anomalies = []
    recent_scores = QUALITY_STATS_DATA.get("recent_scores", [])
    
    # 1. 检测分数突降
    if len(recent_scores) >= 2:
        score_change = recent_scores[-1] - recent_scores[-2]
        if score_change < -QUALITY_ANOMALY_CONFIG["score_drop_threshold"]:
            anomalies.append({
                "type": "score_drop",
                "severity": "high" if score_change < -25 else "medium",
                "description": f"质量分数突降{abs(score_change):.1f}分",
                "from_score": recent_scores[-2],
                "to_score": recent_scores[-1],
                "suggestion": "检查最近生成逻辑或prompt变更"
            })
    
    # 2. 检测分数突增（可能是评估标准放松）
    if len(recent_scores) >= 2:
        score_change = recent_scores[-1] - recent_scores[-2]
        if score_change > QUALITY_ANOMALY_CONFIG["spike_threshold"]:
            anomalies.append({
                "type": "score_spike",
                "severity": "low",
                "description": f"质量分数突增{score_change:.1f}分",
                "from_score": recent_scores[-2],
                "to_score": recent_scores[-1],
                "suggestion": "确认评估标准未被意外修改"
            })
    
    # 3. 检测连续低分
    if len(recent_scores) >= QUALITY_ANOMALY_CONFIG["consecutive_low_threshold"]:
        last_n = recent_scores[-QUALITY_ANOMALY_CONFIG["consecutive_low_threshold"]:]
        if all(s < QUALITY_ANOMALY_CONFIG["low_score_threshold"] for s in last_n):
            anomalies.append({
                "type": "consecutive_low",
                "severity": "critical",
                "description": f"连续{QUALITY_ANOMALY_CONFIG['consecutive_low_threshold']}次评分低于{QUALITY_ANOMALY_CONFIG['low_score_threshold']}分",
                "scores": last_n,
                "suggestion": "立即检查系统状态和生成逻辑"
            })
    
    # 4. 检测维度失衡
    if QUALITY_STATS_DATA["total_evaluations"] > 0:
        avg_structure = QUALITY_STATS_DATA["structure_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
        avg_relevance = QUALITY_STATS_DATA["relevance_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
        avg_length = QUALITY_STATS_DATA["length_score_sum"] / QUALITY_STATS_DATA["total_evaluations"]
        
        max_score = max(avg_structure, avg_relevance, avg_length)
        min_score = min(avg_structure, avg_relevance, avg_length)
        
        if max_score - min_score > 25:
            weak_dim = "结构化" if avg_structure == min_score else "相关性" if avg_relevance == min_score else "长度"
            strong_dim = "结构化" if avg_structure == max_score else "相关性" if avg_relevance == max_score else "长度"
            anomalies.append({
                "type": "dimension_imbalance",
                "severity": "medium",
                "description": f"维度失衡：{strong_dim}({max_score:.1f})与{weak_dim}({min_score:.1f})差距过大",
                "gap": max_score - min_score,
                "suggestion": f"重点优化{weak_dim}维度表现"
            })
    
    # 5. 检测重试率异常
    if QUALITY_STATS_DATA["total_evaluations"] > 10:
        retry_rate = QUALITY_STATS_DATA["retry_count"] / QUALITY_STATS_DATA["total_evaluations"]
        if retry_rate > 0.3:
            anomalies.append({
                "type": "high_retry_rate",
                "severity": "high",
                "description": f"重试率过高：{retry_rate*100:.1f}%",
                "retry_count": QUALITY_STATS_DATA["retry_count"],
                "total_evaluations": QUALITY_STATS_DATA["total_evaluations"],
                "suggestion": "考虑降低质量阈值或优化首次生成质量"
            })
    
    # 记录异常
    if anomalies:
        anomaly_record = {
            "timestamp": datetime.now().isoformat(),
            "anomalies": anomalies,
            "total_count": len(anomalies)
        }
        QUALITY_ANOMALY_CONFIG["anomaly_history"].append(anomaly_record)
        QUALITY_ANOMALY_CONFIG["last_anomaly_time"] = anomaly_record["timestamp"]
        
        # 保留最近50条记录
        if len(QUALITY_ANOMALY_CONFIG["anomaly_history"]) > 50:
            QUALITY_ANOMALY_CONFIG["anomaly_history"] = QUALITY_ANOMALY_CONFIG["anomaly_history"][-50:]
    
    return {
        "success": True,
        "anomalies_detected": len(anomalies),
        "anomalies": anomalies,
        "status": "normal" if len(anomalies) == 0 else "warning" if len(anomalies) < 3 else "critical"
    }

