        {"id": 4, "type": "analytical", "question": "比较REST和GraphQL的优缺点", "expected_keywords": ["REST", "GraphQL", "优点", "缺点"]},
        {"id": 5, "type": "creative", "question": "设计一个用户认证系统", "expected_keywords": ["认证", "安全", "用户", "密码"]}
