@app.get("/api/quality/benchmark/compare")
async def compare_benchmark_results():
    """比较最近两次基准测试结果"""
    history = QUALITY_BENCHMARK["benchmark_history"]
    
    if len(history) < 2:
        return {
            "success": False,
            "message": "需要至少2次基准测试记录"
        }
    
    current = history[-1]
    previous = history[-2]
    
    score_change = current["avg_score"] - previous["avg_score"]
    pass_rate_change = current["pass_rate"] - previous["pass_rate"]
    
    return {
        "success": True,
        "comparison": {
            "current": current,
            "previous": previous,
            "changes": {
                "avg_score": {
                    "absolute": round(score_change, 1),
                    "trend": "improving" if score_change > 0 else "declining" if score_change < 0 else "stable"
                },
                "pass_rate": {
                    "absolute": round(pass_rate_change, 1),
                    "trend": "improving" if pass_rate_change > 0 else "declining" if pass_rate_change < 0 else "stable"
                }
            },
            "overall_trend": "improving" if score_change > 2 else "declining" if score_change < -2 else "stable"
        }
    }

# 质量目标配置
QUALITY_GOALS = {
    "enabled": True,
    "goals": [],
    "active_goal": None,
    "goal_history": []
}

@app.post("/api/quality/goal")
async def set_quality_goal(request: Request):
    """设定质量目标"""
    from datetime import datetime, timedelta
    
    data = await request.json()
    
    if not QUALITY_GOALS["enabled"]:
        return {
            "success": False,
            "message": "目标设定功能已禁用"
        }
    
    # 验证必要字段
    required_fields = ["target_score", "deadline"]
    if not all(f in data for f in required_fields):
        return {
            "success": False,
            "message": "缺少必要字段：target_score, deadline"
        }
    
    # 创建目标
    goal = {
        "id": len(QUALITY_GOALS["goals"]) + 1,
        "target_score": data["target_score"],
        "deadline": data["deadline"],
        "dimensions": data.get("dimensions", {
            "structure": 70,
            "relevance": 70,
            "length": 70
        }),
        "created_at": datetime.now().isoformat(),
        "status": "active",
        "progress": 0,
        "current_score": QUALITY_STATS_DATA.get("recent_scores", [0])[-1] if QUALITY_STATS_DATA.get("recent_scores") else 0,
        "milestones": []
    }
    
    # 添加里程碑
    if "milestones" in data:
        goal["milestones"] = data["milestones"]
    else:
        # 自动生成里程碑
        current = goal["current_score"]
        target = goal["target_score"]
        steps = 4
        step_size = (target - current) / steps
        for i in range(1, steps):
            milestone_score = current + step_size * i
            goal["milestones"].append({
                "score": round(milestone_score, 1),
                "status": "pending",
                "reached_at": None
            })
    
    QUALITY_GOALS["goals"].append(goal)
    QUALITY_GOALS["active_goal"] = goal
    
    return {
        "success": True,
        "message": "质量目标已设定",
        "goal": goal
    }

@app.get("/api/quality/goal")
async def get_quality_goal():
    """获取当前质量目标"""
    if not QUALITY_GOALS["active_goal"]:
        return {
            "success": False,
            "message": "未设定质量目标"
        }
    
    goal = QUALITY_GOALS["active_goal"]
    current_score = QUALITY_STATS_DATA.get("recent_scores", [0])[-1] if QUALITY_STATS_DATA.get("recent_scores") else 0
    
    # 更新进度
    target = goal["target_score"]
    start = goal["current_score"]
    if target != start:
        progress = min(100, max(0, (current_score - start) / (target - start) * 100))
    else:
        progress = 100 if current_score >= target else 0
    
    goal["progress"] = round(progress, 1)
    goal["current_score"] = current_score
    
    # 检查里程碑
    for milestone in goal["milestones"]:
        if milestone["status"] == "pending" and current_score >= milestone["score"]:
            milestone["status"] = "reached"
            milestone["reached_at"] = datetime.now().isoformat()
    
    # 检查目标是否达成
    from datetime import datetime
    if current_score >= target and goal["status"] == "active":
        goal["status"] = "achieved"
        goal["achieved_at"] = datetime.now().isoformat()
        QUALITY_GOALS["goal_history"].append({
            "goal_id": goal["id"],
            "target": target,
            "achieved_score": current_score,
            "achieved_at": goal["achieved_at"]
        })
    
    # 检查是否过期
    deadline = datetime.fromisoformat(goal["deadline"])
    if datetime.now() > deadline and goal["status"] == "active":
        goal["status"] = "expired"
    
    # 计算剩余时间
    remaining_days = (deadline - datetime.now()).days if goal["status"] == "active" else 0
    
    # 计算所需改进速度
    if goal["status"] == "active" and remaining_days > 0:
        daily_improvement_needed = (target - current_score) / remaining_days
    else:
        daily_improvement_needed = 0
    
    return {
        "success": True,
        "goal": goal,
        "tracking": {
            "progress": goal["progress"],
            "gap_to_target": round(target - current_score, 1),
            "remaining_days": max(0, remaining_days),
            "daily_improvement_needed": round(daily_improvement_needed, 2),
            "on_track": current_score >= start + (target - start) * (1 - remaining_days / max(1, (deadline - datetime.fromisoformat(goal["created_at"])).days)) if goal["status"] == "active" else False,
            "milestones_completed": sum(1 for m in goal["milestones"] if m["status"] == "reached"),
            "milestones_total": len(goal["milestones"])
        }
    }

