@app.post("/api/quality/strategy/recommend")
async def recommend_optimization_strategy():
    """根据当前质量状况推荐优化策略"""
    from datetime import datetime
    
    if not QUALITY_OPTIMIZATION_STRATEGIES["enabled"]:
        return {
            "success": False,
            "message": "优化策略功能已禁用"
        }
    
    recent_scores = QUALITY_STATS_DATA.get("recent_scores", [])
    dimension_scores = QUALITY_STATS_DATA.get("dimension_history", [])
    
    if len(recent_scores) < 3:
        return {
            "success": False,
            "message": "数据不足，需要至少3次评估记录"
        }
    
    # 分析当前质量状况
    avg_score = sum(recent_scores) / len(recent_scores)
    
    # 分析各维度表现
    dimension_avg = {"structure": 70, "relevance": 70, "length": 70}
    if dimension_scores:
        for dim in ["structure", "relevance", "length"]:
            dim_scores = [d.get(dim, 70) for d in dimension_scores[-10:]]
            if dim_scores:
                dimension_avg[dim] = sum(dim_scores) / len(dim_scores)
    
    # 找出最弱维度
    weakest_dimension = min(dimension_avg, key=dimension_avg.get)
    weakest_score = dimension_avg[weakest_dimension]
    
    # 推荐策略
    recommendations = []
    
    # 基于最弱维度推荐
    for strategy in QUALITY_OPTIMIZATION_STRATEGIES["strategies"]:
        if strategy["target_dimension"] == weakest_dimension or strategy["target_dimension"] == "all":
            priority = "high" if strategy["target_dimension"] == weakest_dimension else "medium"
            recommendations.append({
                "strategy": strategy,
                "priority": priority,
                "reason": f"当前{weakest_dimension}维度得分{weakest_score:.1f}，需要重点优化",
                "expected_gain": strategy["expected_improvement"]
            })
    
    # 如果整体分数低，推荐综合策略
    if avg_score < 65:
        for strategy in QUALITY_OPTIMIZATION_STRATEGIES["strategies"]:
            if strategy["target_dimension"] == "all":
                recommendations.append({
                    "strategy": strategy,
                    "priority": "high",
                    "reason": f"整体质量分数{avg_score:.1f}偏低，建议综合优化",
                    "expected_gain": strategy["expected_improvement"]
                })
    
    # 按优先级排序
    recommendations.sort(key=lambda x: (x["priority"] == "high", x["expected_gain"]), reverse=True)
    
    # 生成行动计划
    action_plan = []
    for i, rec in enumerate(recommendations[:3]):
        for action in rec["strategy"]["actions"]:
            action_plan.append({
                "step": len(action_plan) + 1,
                "action": action,
                "strategy": rec["strategy"]["name"],
                "priority": rec["priority"]
            })
    
    return {
        "success": True,
        "analysis": {
            "overall_avg": round(avg_score, 1),
            "dimension_scores": {k: round(v, 1) for k, v in dimension_avg.items()},
            "weakest_dimension": weakest_dimension,
            "improvement_potential": round(100 - avg_score, 1)
        },
        "recommendations": recommendations[:5],
        "action_plan": action_plan[:10],
        "quick_wins": [
            {"action": "添加分段标题", "expected_gain": 3},
            {"action": "精简冗余内容", "expected_gain": 2},
            {"action": "聚焦核心问题", "expected_gain": 4}
        ]
    }

@app.post("/api/quality/strategy/apply")
async def apply_optimization_strategy(request: Request):
    """应用优化策略"""
    from datetime import datetime
    
    data = await request.json()
    strategy_id = data.get("strategy_id")
    
    if not strategy_id:
        return {
            "success": False,
            "message": "缺少策略ID"
        }
    
    # 查找策略
    strategy = None
    for s in QUALITY_OPTIMIZATION_STRATEGIES["strategies"]:
        if s["id"] == strategy_id:
            strategy = s
            break
    
    if not strategy:
        return {
            "success": False,
            "message": "策略不存在"
        }
    
    # 记录应用
    application = {
        "strategy_id": strategy_id,
        "strategy_name": strategy["name"],
        "applied_at": datetime.now().isoformat(),
        "target_dimension": strategy["target_dimension"],
        "expected_improvement": strategy["expected_improvement"],
        "status": "applied"
    }
    
    QUALITY_OPTIMIZATION_STRATEGIES["applied_strategies"].append(application)
    
    # 保留最近50条记录
    if len(QUALITY_OPTIMIZATION_STRATEGIES["applied_strategies"]) > 50:
        QUALITY_OPTIMIZATION_STRATEGIES["applied_strategies"] = QUALITY_OPTIMIZATION_STRATEGIES["applied_strategies"][-50:]
    
    return {
        "success": True,
        "message": f"策略 '{strategy['name']}' 已应用",
        "application": application,
        "actions_to_take": strategy["actions"]
    }

