@app.post("/api/quality/calibration/adjust")
async def adjust_calibration(request: Request):
    """调整校准参数"""
    from datetime import datetime
    
    data = await request.json()
    
    if not QUALITY_CALIBRATION["enabled"]:
        return {
            "success": False,
            "message": "校准功能已禁用"
        }
    
    # 更新校准因子
    if "factors" in data:
        for dim, factor in data["factors"].items():
            if dim in QUALITY_CALIBRATION["calibration_factors"]:
                # 限制因子范围在0.5-1.5之间
                QUALITY_CALIBRATION["calibration_factors"][dim] = max(0.5, min(1.5, factor))
    
    # 更新偏移调整
    if "offsets" in data:
        for dim, offset in data["offsets"].items():
            if dim in QUALITY_CALIBRATION["offset_adjustments"]:
                # 限制偏移范围在-20到+20之间
                QUALITY_CALIBRATION["offset_adjustments"][dim] = max(-20, min(20, offset))
    
    # 记录调整历史
    adjustment_record = {
        "timestamp": datetime.now().isoformat(),
        "factors": QUALITY_CALIBRATION["calibration_factors"].copy(),
        "offsets": QUALITY_CALIBRATION["offset_adjustments"].copy(),
        "reason": data.get("reason", "手动调整")
    }
    
    QUALITY_CALIBRATION["calibration_history"].append(adjustment_record)
    
    # 保留最近50条记录
    if len(QUALITY_CALIBRATION["calibration_history"]) > 50:
        QUALITY_CALIBRATION["calibration_history"] = QUALITY_CALIBRATION["calibration_history"][-50:]
    
    return {
        "success": True,
        "message": "校准参数已调整",
        "current_calibration": {
            "factors": QUALITY_CALIBRATION["calibration_factors"],
            "offsets": QUALITY_CALIBRATION["offset_adjustments"]
        }
    }

