@app.post("/api/quality/calibration/compute")
async def compute_calibration():
    """基于样本计算校准参数"""
    from datetime import datetime
    
    samples = QUALITY_CALIBRATION["calibration_samples"]
    
    if len(samples) < 10:
        return {
            "success": False,
            "message": f"样本数量不足，当前{len(samples)}个，需要至少10个"
        }
    
    # 计算系统分数与人工分数的相关性
    system_scores = [s["system_score"] for s in samples]
    human_scores = [s["human_score"] for s in samples]
    
    # 计算平均偏差
    avg_system = sum(system_scores) / len(system_scores)
    avg_human = sum(human_scores) / len(human_scores)
    
    # 计算偏差
    deviations = [s["system_score"] - s["human_score"] for s in samples]
    avg_deviation = sum(deviations) / len(deviations)
    
    # 计算校准因子（简单线性回归）
    # 计算协方差和方差
    covariance = sum((system_scores[i] - avg_system) * (human_scores[i] - avg_human) for i in range(len(samples)))
    variance = sum((s - avg_system) ** 2 for s in system_scores)
    
    if variance > 0:
        slope = covariance / variance
        intercept = avg_human - slope * avg_system
    else:
        slope = 1.0
        intercept = 0
    
    # 更新校准参数
    # 因子用于缩放，偏移用于平移
    new_factor = max(0.5, min(1.5, slope))
    new_offset = max(-20, min(20, intercept))
    
    # 应用到所有维度
    for dim in QUALITY_CALIBRATION["calibration_factors"]:
        QUALITY_CALIBRATION["calibration_factors"][dim] = new_factor
        QUALITY_CALIBRATION["calibration_factors"][dim] = round(new_factor, 3)
    
    for dim in QUALITY_CALIBRATION["offset_adjustments"]:
        QUALITY_CALIBRATION["offset_adjustments"][dim] = round(new_offset, 1)
    
    # 计算校准后的预期改进
    calibrated_deviations = []
    for s in samples:
        calibrated_score = s["system_score"] * new_factor + new_offset
        calibrated_score = max(0, min(100, calibrated_score))
        calibrated_deviations.append(abs(calibrated_score - s["human_score"]))
    
    avg_calibrated_deviation = sum(calibrated_deviations) / len(calibrated_deviations)
    improvement = avg_deviation - avg_calibrated_deviation
    
    # 记录校准计算
    computation_record = {
        "timestamp": datetime.now().isoformat(),
        "samples_used": len(samples),
        "avg_system_score": round(avg_system, 1),
        "avg_human_score": round(avg_human, 1),
        "avg_deviation_before": round(avg_deviation, 2),
        "avg_deviation_after": round(avg_calibrated_deviation, 2),
        "improvement": round(improvement, 2),
        "computed_factor": round(new_factor, 3),
        "computed_offset": round(new_offset, 1)
    }
    
    QUALITY_CALIBRATION["calibration_history"].append(computation_record)
    
    return {
        "success": True,
        "message": "校准参数已计算并应用",
        "computation": computation_record,
        "new_calibration": {
            "factors": QUALITY_CALIBRATION["calibration_factors"],
            "offsets": QUALITY_CALIBRATION["offset_adjustments"]
        }
    }

@app.get("/api/quality/calibration/validate")
async def validate_calibration():
    """验证当前校准效果"""
    samples = QUALITY_CALIBRATION["calibration_samples"]
    
    if len(samples) < 5:
        return {
            "success": False,
            "message": f"样本数量不足，当前{len(samples)}个，需要至少5个"
        }
    
    # 计算校准前后的偏差
    before_deviations = []
    after_deviations = []
    
    for s in samples:
        # 校准前偏差
        before_deviations.append(abs(s["system_score"] - s["human_score"]))
        
        # 校准后偏差
        calibrated = s["system_score"] * QUALITY_CALIBRATION["calibration_factors"]["structure"] + QUALITY_CALIBRATION["offset_adjustments"]["structure"]
        calibrated = max(0, min(100, calibrated))
        after_deviations.append(abs(calibrated - s["human_score"]))
    
    avg_before = sum(before_deviations) / len(before_deviations)
    avg_after = sum(after_deviations) / len(after_deviations)
    
    # 计算改进百分比
    improvement_pct = (avg_before - avg_after) / avg_before * 100 if avg_before > 0 else 0
    
    # 评估校准质量
    if avg_after < 5:
        quality = "excellent"
    elif avg_after < 10:
        quality = "good"
    elif avg_after < 15:
        quality = "acceptable"
    else:
        quality = "poor"
    
    return {
        "success": True,
        "validation": {
            "samples_count": len(samples),
            "avg_deviation_before": round(avg_before, 2),
            "avg_deviation_after": round(avg_after, 2),
            "improvement_pct": round(improvement_pct, 1),
            "calibration_quality": quality,
            "recommendation": "校准效果良好，建议保持当前设置" if quality in ["excellent", "good"] else "建议添加更多样本并重新计算校准参数"
        }
    }

