@app.post("/api/quality/explain")
async def explain_quality_score(request: Request):
    """解释质量评分"""
    from datetime import datetime
    
    data = await request.json()
    
    if not QUALITY_EXPLAINABILITY["enabled"]:
        return {
            "success": False,
            "message": "可解释性功能已禁用"
        }
    
    # 获取评分数据
    total_score = data.get("total_score", 0)
    dimensions = data.get("dimensions", {
        "structure": 70,
        "relevance": 70,
        "length": 70
    })
    question_type = data.get("question_type", "general")
    question = data.get("question", "")
    answer = data.get("answer", "")
    
    # 计算各维度贡献
    contributions = {}
    weights = {"structure": 0.4, "relevance": 0.35, "length": 0.25}
    
    for dim, score in dimensions.items():
        weight = weights.get(dim, 0.33)
        contribution = score * weight
        contributions[dim] = {
            "score": score,
            "weight": weight,
            "contribution": round(contribution, 2),
            "percentage": round(contribution / max(1, total_score) * 100, 1)
        }
    
    # 确定各维度等级
    dim_levels = {}
    for dim, score in dimensions.items():
        if score >= 80:
            dim_levels[dim] = "high"
        elif score >= 60:
            dim_levels[dim] = "medium"
        else:
            dim_levels[dim] = "low"
    
    # 生成解释
    explanations = {}
    for dim, level in dim_levels.items():
        template = QUALITY_EXPLAINABILITY["explanation_templates"].get(dim, {}).get(level, "")
        explanations[dim] = {
            "level": level,
            "description": template,
            "score": dimensions[dim],
            "contribution": contributions[dim]["contribution"]
        }
    
    # 生成改进建议
    improvements = {}
    for dim, level in dim_levels.items():
        actions = QUALITY_EXPLAINABILITY["improvement_actions"].get(dim, {}).get(level, [])
        improvements[dim] = {
            "priority": "high" if level == "low" else "medium" if level == "medium" else "low",
            "actions": actions
        }
    
    # 计算总体评级
    if total_score >= 85:
        overall_level = "优秀"
        overall_color = "green"
    elif total_score >= 70:
        overall_level = "良好"
        overall_color = "blue"
    elif total_score >= 55:
        overall_level = "一般"
        overall_color = "yellow"
    else:
        overall_level = "待改进"
        overall_color = "red"
    
    # 识别最强和最弱维度
    strongest_dim = max(dimensions, key=dimensions.get)
    weakest_dim = min(dimensions, key=dimensions.get)
    
    # 生成总结
    summary = f"总分{total_score}分（{overall_level}），"
    summary += f"最强维度是{strongest_dim}（{dimensions[strongest_dim]}分），"
    summary += f"最需改进的是{weakest_dim}（{dimensions[weakest_dim]}分）。"
    
    # 生成详细解释
    detailed_explanation = []
    detailed_explanation.append(f"## 评分总览")
    detailed_explanation.append(f"- 总分：{total_score}/100")
    detailed_explanation.append(f"- 评级：{overall_level}")
    detailed_explanation.append(f"- 问题类型：{question_type}")
    detailed_explanation.append(f"")
    detailed_explanation.append(f"## 维度分析")
    
    for dim, info in explanations.items():
        dim_name = {"structure": "结构", "relevance": "相关性", "length": "长度"}.get(dim, dim)
        detailed_explanation.append(f"### {dim_name}（{info['score']}分）")
        detailed_explanation.append(f"- 等级：{info['level']}")
        detailed_explanation.append(f"- 贡献：{info['contribution']}分（{contributions[dim]['percentage']}%）")
        detailed_explanation.append(f"- 说明：{info['description']}")
    
    detailed_explanation.append(f"")
    detailed_explanation.append(f"## 改进建议")
    
    # 按优先级排序改进建议
    sorted_improvements = sorted(improvements.items(), key=lambda x: x[1]["priority"])
    for dim, info in sorted_improvements:
        if info["priority"] != "low":
            dim_name = {"structure": "结构", "relevance": "相关性", "length": "长度"}.get(dim, dim)
            detailed_explanation.append(f"### {dim_name}改进（优先级：{info['priority']}）")
            for action in info["actions"]:
                detailed_explanation.append(f"- {action}")
    
    # 记录解释历史
    explanation_record = {
        "timestamp": datetime.now().isoformat(),
        "total_score": total_score,
        "dimensions": dimensions,
        "question_type": question_type,
        "overall_level": overall_level
    }
    QUALITY_EXPLAINABILITY["explanation_history"].append(explanation_record)
    
    # 保留最近50条记录
    if len(QUALITY_EXPLAINABILITY["explanation_history"]) > 50:
        QUALITY_EXPLAINABILITY["explanation_history"] = QUALITY_EXPLAINABILITY["explanation_history"][-50:]
    
    return {
        "success": True,
        "explanation": {
            "summary": summary,
            "overall": {
                "score": total_score,
                "level": overall_level,
                "color": overall_color
            },
            "dimensions": explanations,
            "contributions": contributions,
            "strongest_dimension": {
                "name": strongest_dim,
                "score": dimensions[strongest_dim]
            },
            "weakest_dimension": {
                "name": weakest_dim,
                "score": dimensions[weakest_dim]
            },
            "improvements": improvements,
            "detailed_explanation": "\n".join(detailed_explanation)
        }
    }

