@app.post("/api/quality/explain/compare")
async def compare_quality_explanations(request: Request):
    """比较两次评分的解释"""
    from datetime import datetime
    
    data = await request.json()
    
    score1 = data.get("score1", {})
    score2 = data.get("score2", {})
    
    if not score1 or not score2:
        return {
            "success": False,
            "message": "需要提供两次评分数据进行比较"
        }
    
    # 提取数据
    total1 = score1.get("total_score", 0)
    total2 = score2.get("total_score", 0)
    dims1 = score1.get("dimensions", {})
    dims2 = score2.get("dimensions", {})
    
    # 计算变化
    total_change = total2 - total1
    
    dim_changes = {}
    for dim in ["structure", "relevance", "length"]:
        d1 = dims1.get(dim, 70)
        d2 = dims2.get(dim, 70)
        change = d2 - d1
        dim_changes[dim] = {
            "before": d1,
            "after": d2,
            "change": change,
            "trend": "up" if change > 0 else "down" if change < 0 else "stable"
        }
    
    # 识别改进和退步维度
    improved_dims = [dim for dim, info in dim_changes.items() if info["change"] > 0]
    declined_dims = [dim for dim, info in dim_changes.items() if info["change"] < 0]
    
    # 生成比较总结
    if total_change > 5:
        comparison_summary = f"质量显著提升{total_change}分，"
    elif total_change > 0:
        comparison_summary = f"质量略有提升{total_change}分，"
    elif total_change < -5:
        comparison_summary = f"质量明显下降{abs(total_change)}分，"
    elif total_change < 0:
        comparison_summary = f"质量略有下降{abs(total_change)}分，"
    else:
        comparison_summary = "质量保持稳定，"
    
    if improved_dims:
        dim_names = [{"structure": "结构", "relevance": "相关性", "length": "长度"}.get(d, d) for d in improved_dims]
        comparison_summary += f"改进维度：{', '.join(dim_names)}。"
    
    if declined_dims:
        dim_names = [{"structure": "结构", "relevance": "相关性", "length": "长度"}.get(d, d) for d in declined_dims]
        comparison_summary += f"退步维度：{', '.join(dim_names)}。"
    
    return {
        "success": True,
        "comparison": {
            "total_change": total_change,
            "trend": "improved" if total_change > 0 else "declined" if total_change < 0 else "stable",
            "dimension_changes": dim_changes,
            "improved_dimensions": improved_dims,
            "declined_dimensions": declined_dims,
            "summary": comparison_summary,
            "recommendations": [
                f"继续保持{improved_dims[0]}的改进趋势" if improved_dims else "保持当前水平",
                f"重点关注{declined_dims[0]}的提升" if declined_dims else "继续优化各维度"
            ]
        }
    }

