@app.get("/api/quality/visualize/trend")
async def visualize_trend_chart(days: int = 7):
    """生成趋势图数据"""
    from datetime import datetime, timedelta
    
    # 模拟历史数据
    history = QUALITY_STATS_DATA.get("recent_scores", [70] * days)
    
    # 生成日期标签
    today = datetime.now()
    labels = [(today - timedelta(days=i)).strftime("%m-%d") for i in range(days-1, -1, -1)]
    
    # 确保数据长度匹配
    if len(history) < days:
        history = [70] * (days - len(history)) + history
    elif len(history) > days:
        history = history[-days:]
    
    # 生成趋势图数据
    trend_data = {
        "type": "line",
        "data": {
            "labels": labels,
            "datasets": [{
                "label": "质量总分",
                "data": history,
                "fill": True,
                "backgroundColor": "rgba(33, 150, 243, 0.1)",
                "borderColor": "#2196F3",
                "borderWidth": 2,
                "tension": 0.4,
                "pointRadius": 4,
                "pointHoverRadius": 6
            }]
        },
        "options": {
            "responsive": True,
            "scales": {
                "y": {
                    "beginAtZero": False,
                    "min": 50,
                    "max": 100,
                    "ticks": {
                        "stepSize": 10
                    }
                }
            },
            "plugins": {
                "legend": {
                    "position": "top"
                },
                "title": {
                    "display": True,
                    "text": f"近{days}天质量趋势"
                }
            }
        }
    }
    
    # 计算趋势统计
    avg_score = sum(history) / len(history) if history else 0
    trend = "up" if len(history) > 1 and history[-1] > history[0] else "down" if len(history) > 1 and history[-1] < history[0] else "stable"
    change = history[-1] - history[0] if len(history) > 1 else 0
    
    return {
        "success": True,
        "chart_type": "line",
        "chart_data": trend_data,
        "statistics": {
            "avg_score": round(avg_score, 1),
            "min_score": min(history) if history else 0,
            "max_score": max(history) if history else 0,
            "trend": trend,
            "change": round(change, 1),
            "days": days
        }
    }

