@app.get("/api/quality/history/query")
async def query_quality_history(
    start_date: str = None,
    end_date: str = None,
    limit: int = 100,
    min_score: float = 0,
    max_score: float = 100,
    question_type: str = None
):
    """查询质量历史数据"""
    from datetime import datetime, timedelta
    
    # 获取历史数据
    history = QUALITY_STATS_DATA.get("quality_history", [])
    
    # 过滤数据
    filtered = []
    for record in history:
        # 日期过滤
        if start_date:
            try:
                record_date = datetime.fromisoformat(record.get("timestamp", ""))
                if record_date < datetime.fromisoformat(start_date):
                    continue
            except:
                pass
        
        if end_date:
            try:
                record_date = datetime.fromisoformat(record.get("timestamp", ""))
                if record_date > datetime.fromisoformat(end_date):
                    continue
            except:
                pass
        
        # 分数过滤
        score = record.get("total_score", 0)
        if score < min_score or score > max_score:
            continue
        
        # 问题类型过滤
        if question_type and record.get("question_type") != question_type:
            continue
        
        filtered.append(record)
    
    # 限制数量
    filtered = filtered[-limit:]
    
    return {
        "success": True,
        "total_records": len(history),
        "filtered_records": len(filtered),
        "query_params": {
            "start_date": start_date,
            "end_date": end_date,
            "limit": limit,
            "min_score": min_score,
            "max_score": max_score,
            "question_type": question_type
        },
        "records": filtered
    }

@app.get("/api/quality/history/trend")
async def analyze_history_trend(period: str = "daily"):
    """分析历史趋势"""
    from datetime import datetime, timedelta
    from collections import defaultdict
    
    history = QUALITY_STATS_DATA.get("quality_history", [])
    
    if not history:
        return {
            "success": True,
            "message": "暂无历史数据",
            "trend": []
        }
    
    # 按时间段分组
    grouped_data = defaultdict(list)
    
    for record in history:
        try:
            timestamp = record.get("timestamp", "")
            dt = datetime.fromisoformat(timestamp)
            
            if period == "daily":
                key = dt.strftime("%Y-%m-%d")
            elif period == "weekly":
                # 获取周数
                week_start = dt - timedelta(days=dt.weekday())
                key = week_start.strftime("%Y-%m-%d") + " (周)"
            elif period == "monthly":
                key = dt.strftime("%Y-%m")
            else:
                key = dt.strftime("%Y-%m-%d")
            
            grouped_data[key].append(record.get("total_score", 70))
        except:
            continue
    
    # 计算每个时间段的统计
    trend_data = []
    for key in sorted(grouped_data.keys()):
        scores = grouped_data[key]
        trend_data.append({
            "period": key,
            "avg_score": round(sum(scores) / len(scores), 1) if scores else 0,
            "min_score": min(scores) if scores else 0,
            "max_score": max(scores) if scores else 0,
            "count": len(scores),
            "std_dev": round((sum((s - sum(scores)/len(scores))**2 for s in scores) / len(scores))**0.5, 2) if len(scores) > 1 else 0
        })
    
    # 计算整体趋势
    if len(trend_data) >= 2:
        first_avg = trend_data[0]["avg_score"]
        last_avg = trend_data[-1]["avg_score"]
        overall_trend = "up" if last_avg > first_avg else "down" if last_avg < first_avg else "stable"
        change_rate = round((last_avg - first_avg) / max(1, first_avg) * 100, 1)
    else:
        overall_trend = "insufficient_data"
        change_rate = 0
    
    return {
        "success": True,
        "period": period,
        "overall_trend": overall_trend,
        "change_rate": change_rate,
        "trend_data": trend_data,
        "summary": {
            "total_periods": len(trend_data),
            "avg_score_all": round(sum(t["avg_score"] for t in trend_data) / len(trend_data), 1) if trend_data else 0,
            "best_period": max(trend_data, key=lambda x: x["avg_score"])["period"] if trend_data else None,
            "worst_period": min(trend_data, key=lambda x: x["avg_score"])["period"] if trend_data else None
        }
    }

@app.get("/api/quality/history/compare")
async def compare_history_periods(period1: str = None, period2: str = None):
    """对比两个时间段的质量"""
    from datetime import datetime, timedelta
    from collections import defaultdict
    
    history = QUALITY_STATS_DATA.get("quality_history", [])
    
    if not period1 or not period2:
        return {
            "success": False,
            "message": "需要提供两个时间段进行对比"
        }
    
    # 分组数据
    period1_scores = []
    period2_scores = []
    period1_dims = {"structure": [], "relevance": [], "length": []}
    period2_dims = {"structure": [], "relevance": [], "length": []}
    
    for record in history:
        try:
            timestamp = record.get("timestamp", "")
            dt = datetime.fromisoformat(timestamp)
            date_str = dt.strftime("%Y-%m-%d")
            month_str = dt.strftime("%Y-%m")
            
            score = record.get("total_score", 70)
            dims = record.get("dimensions", {})
            
            # 匹配时间段
            if date_str == period1 or month_str == period1:
                period1_scores.append(score)
                for dim in ["structure", "relevance", "length"]:
                    period1_dims[dim].append(dims.get(dim, 70))
            elif date_str == period2 or month_str == period2:
                period2_scores.append(score)
                for dim in ["structure", "relevance", "length"]:
                    period2_dims[dim].append(dims.get(dim, 70))
        except:
            continue
    
    # 计算统计
    def calc_stats(scores):
        if not scores:
            return {"avg": 0, "min": 0, "max": 0, "count": 0}
        return {
            "avg": round(sum(scores) / len(scores), 1),
            "min": min(scores),
            "max": max(scores),
            "count": len(scores)
        }
    
    period1_stats = calc_stats(period1_scores)
    period2_stats = calc_stats(period2_scores)
    
    # 维度对比
    dim_comparison = {}
    for dim in ["structure", "relevance", "length"]:
        p1_avg = sum(period1_dims[dim]) / len(period1_dims[dim]) if period1_dims[dim] else 0
        p2_avg = sum(period2_dims[dim]) / len(period2_dims[dim]) if period2_dims[dim] else 0
        dim_comparison[dim] = {
            "period1_avg": round(p1_avg, 1),
            "period2_avg": round(p2_avg, 1),
            "change": round(p2_avg - p1_avg, 1),
            "trend": "up" if p2_avg > p1_avg else "down" if p2_avg < p1_avg else "stable"
        }
    
    # 生成对比总结
    total_change = period2_stats["avg"] - period1_stats["avg"]
    if total_change > 5:
        summary = f"{period2}相比{period1}质量显著提升{total_change}分"
    elif total_change > 0:
        summary = f"{period2}相比{period1}质量略有提升{total_change}分"
    elif total_change < -5:
        summary = f"{period2}相比{period1}质量明显下降{abs(total_change)}分"
    elif total_change < 0:
        summary = f"{period2}相比{period1}质量略有下降{abs(total_change)}分"
    else:
        summary = f"{period2}与{period1}质量基本持平"
    
    return {
        "success": True,
        "comparison": {
            "period1": {
                "name": period1,
                "stats": period1_stats
            },
            "period2": {
                "name": period2,
                "stats": period2_stats
            },
            "dimension_comparison": dim_comparison,
            "total_change": round(total_change, 1),
            "trend": "improved" if total_change > 0 else "declined" if total_change < 0 else "stable"
        },
        "summary": summary
    }

@app.get("/api/quality/history/statistics")
async def get_history_statistics():
    """获取历史统计汇总"""
    from datetime import datetime, timedelta
    
    history = QUALITY_STATS_DATA.get("quality_history", [])
    
    if not history:
        return {
            "success": True,
            "message": "暂无历史数据",
            "statistics": {}
        }
    
    # 基本统计
    all_scores = [r.get("total_score", 70) for r in history]
    
    # 问题类型分布
    type_distribution = {}
    for record in history:
        qtype = record.get("question_type", "general")
        type_distribution[qtype] = type_distribution.get(qtype, 0) + 1
    
    # 维度统计
    dim_stats = {"structure": [], "relevance": [], "length": []}
    for record in history:
        dims = record.get("dimensions", {})
        for dim in dim_stats:
            dim_stats[dim].append(dims.get(dim, 70))
    
    # 时间范围
    timestamps = []
    for record in history:
        try:
            ts = record.get("timestamp", "")
            timestamps.append(datetime.fromisoformat(ts))
        except:
            pass
    
    # 质量等级分布
    level_distribution = {"excellent": 0, "good": 0, "average": 0, "poor": 0}
    for score in all_scores:
        if score >= 85:
            level_distribution["excellent"] += 1
        elif score >= 70:
            level_distribution["good"] += 1
        elif score >= 55:
            level_distribution["average"] += 1
        else:
            level_distribution["poor"] += 1
    
    return {
        "success": True,
        "statistics": {
            "total_evaluations": len(history),
            "time_range": {
                "earliest": min(timestamps).isoformat() if timestamps else None,
                "latest": max(timestamps).isoformat() if timestamps else None,
                "span_days": (max(timestamps) - min(timestamps)).days if len(timestamps) >= 2 else 0
            },
            "score_statistics": {
                "avg": round(sum(all_scores) / len(all_scores), 1),
                "min": min(all_scores),
                "max": max(all_scores),
                "std_dev": round((sum((s - sum(all_scores)/len(all_scores))**2 for s in all_scores) / len(all_scores))**0.5, 2)
            },
            "dimension_statistics": {
                dim: {
                    "avg": round(sum(scores) / len(scores), 1) if scores else 0,
                    "min": min(scores) if scores else 0,
                    "max": max(scores) if scores else 0
                } for dim, scores in dim_stats.items()
            },
            "level_distribution": level_distribution,
            "type_distribution": type_distribution
        }
    }

@app.get("/api/quality/history/export")
async def export_history_data(format: str = "json"):
    """导出历史数据"""
    from datetime import datetime
    
    history = QUALITY_STATS_DATA.get("quality_history", [])
    stats = await get_history_statistics()
    trend = await analyze_history_trend("daily")
    
    export_data = {
        "export_time": datetime.now().isoformat(),
        "format": format,
        "data": {
            "history": history,
            "statistics": stats.get("statistics", {}),
            "trend_analysis": trend.get("trend_data", [])
        }
    }
    
    return {
        "success": True,
        "export_data": export_data,
        "record_count": len(history),
        "download_url": f"/api/quality/history/download?format={format}"
    }

@app.get("/api/quality/history/clear")
async def clear_history_data(before_date: str = None):
    """清除历史数据"""
    from datetime import datetime
    
    if before_date:
        history = QUALITY_STATS_DATA.get("quality_history", [])
        cutoff = datetime.fromisoformat(before_date)
        
        # 过滤保留指定日期之后的数据
        filtered = []
        for record in history:
            try:
                ts = datetime.fromisoformat(record.get("timestamp", ""))
                if ts >= cutoff:
                    filtered.append(record)
            except:
                filtered.append(record)
        
        QUALITY_STATS_DATA["quality_history"] = filtered
        removed_count = len(history) - len(filtered)
        
        return {
            "success": True,
            "message": f"已清除{removed_count}条历史记录",
            "remaining_records": len(filtered)
        }
    else:
        # 清除所有历史
        QUALITY_STATS_DATA["quality_history"] = []
        return {
            "success": True,
            "message": "已清除所有历史记录",
            "remaining_records": 0
        }

