@app.get("/api/quality/i18n/translate")
async def translate_quality_text(
    score: float = 70,
    dimensions: str = "70,70,70",
    language: str = "en"
):
    """翻译质量评分文本"""
    if language not in QUALITY_I18N["supported_languages"]:
        language = QUALITY_I18N["default_language"]
    
    trans = QUALITY_I18N["translations"].get(language, QUALITY_I18N["translations"]["zh"])
    
    # 解析维度分数
    try:
        dim_scores = [float(s) for s in dimensions.split(",")]
        if len(dim_scores) != 3:
            dim_scores = [70, 70, 70]
    except:
        dim_scores = [70, 70, 70]
    
    dim_names = ["structure", "relevance", "length"]
    dim_map = dict(zip(dim_names, dim_scores))
    
    # 确定等级
    if score >= 85:
        level_key = "excellent"
    elif score >= 70:
        level_key = "good"
    elif score >= 55:
        level_key = "average"
    else:
        level_key = "poor"
    
    # 找出最强和最弱维度
    strongest = max(dim_map, key=dim_map.get)
    weakest = min(dim_map, key=dim_map.get)
    
    # 生成翻译文本
    summary = trans["messages"]["score_summary"].format(
        score=score,
        level=trans["levels"][level_key],
        strongest=trans["dimensions"][strongest],
        strongest_score=dim_map[strongest],
        weakest=trans["dimensions"][weakest],
        weakest_score=dim_map[weakest]
    )
    
    improvement = trans["messages"]["improvement_hint"].format(
        dimension=trans["dimensions"][weakest]
    )
    
    return {
        "success": True,
        "language": language,
        "translation": {
            "summary": summary,
            "improvement_hint": improvement,
            "dimensions": {
                dim: {
                    "name": trans["dimensions"][dim],
                    "score": dim_map[dim]
                } for dim in dim_names
            },
            "level": {
                "key": level_key,
                "name": trans["levels"][level_key]
            }
        }
    }

