    # 更新全局数据
    QUALITY_STATS_DATA["last_broadcast"] = {
        "timestamp": datetime.now().isoformat(),
        "quality_score": score,
        "dimensions": dimensions
    }
    
    # 返回广播状态
    active_count = len(QUALITY_STREAMING["active_streams"])
    
    return {
        "success": True,
        "broadcast": {
            "timestamp": datetime.now().isoformat(),
            "quality_score": score,
            "dimensions": dimensions
        },
        "delivered_to": active_count,
        "message": f"已广播到{active_count}个活跃连接"
    }

