@app.get("/api/quality/audit/log")
async def get_audit_log(
    start_date: str = None,
    end_date: str = None,
    action_type: str = None,
    user_id: str = None,
    limit: int = 100
):
    """获取审计日志"""
    from datetime import datetime
    
    audit_log = QUALITY_AUDIT["audit_log"]
    
    # 过滤日期
    if start_date:
        try:
            start_dt = datetime.fromisoformat(start_date)
            audit_log = [e for e in audit_log if datetime.fromisoformat(e["timestamp"]) >= start_dt]
        except:
            pass
    
    if end_date:
        try:
            end_dt = datetime.fromisoformat(end_date)
            audit_log = [e for e in audit_log if datetime.fromisoformat(e["timestamp"]) <= end_dt]
        except:
            pass
    
    # 过滤操作类型
    if action_type:
        audit_log = [e for e in audit_log if e.get("action_type") == action_type]
    
    # 过滤用户
    if user_id:
        audit_log = [e for e in audit_log if e.get("user_id") == user_id]
    
    # 限制数量
    audit_log = audit_log[-limit:]
    
    return {
        "success": True,
        "total_entries": len(QUALITY_AUDIT["audit_log"]),
        "filtered_entries": len(audit_log),
        "audit_log": audit_log,
        "query_params": {
            "start_date": start_date,
            "end_date": end_date,
            "action_type": action_type,
            "user_id": user_id,
            "limit": limit
        }
    }

