@app.get("/api/quality/audit/summary")
async def get_audit_summary(days: int = 7):
    """获取审计摘要"""
    from datetime import datetime, timedelta
    
    cutoff = datetime.now() - timedelta(days=days)
    
    # 过滤最近N天的日志
    recent_logs = [
        e for e in QUALITY_AUDIT["audit_log"]
        if datetime.fromisoformat(e["timestamp"]) >= cutoff
    ]
    
    # 统计操作类型
    action_counts = {}
    for entry in recent_logs:
        action = entry.get("action_type", "unknown")
        action_counts[action] = action_counts.get(action, 0) + 1
    
    # 统计用户活动
    user_activity = {}
    for entry in recent_logs:
        user = entry.get("user_id", "system")
        user_activity[user] = user_activity.get(user, 0) + 1
    
    # 统计每日活动
    daily_activity = {}
    for entry in recent_logs:
        date = entry["timestamp"][:10]
        daily_activity[date] = daily_activity.get(date, 0) + 1
    
    return {
        "success": True,
        "period_days": days,
        "summary": {
            "total_entries": len(recent_logs),
            "unique_users": len(user_activity),
            "action_breakdown": action_counts,
            "top_users": sorted(user_activity.items(), key=lambda x: x[1], reverse=True)[:5],
            "daily_activity": daily_activity
        },
        "audit_config": {
            "enabled": QUALITY_AUDIT["enabled"],
            "retention_days": QUALITY_AUDIT["retention_days"],
            "max_log_size": QUALITY_AUDIT["max_log_size"]
        }
    }

@app.get("/api/quality/audit/trace/{resource_id}")
async def trace_resource_history(resource_id: str):
    """追踪资源历史"""
    from datetime import datetime
    
    # 查找所有相关条目
    history = [
        entry for entry in QUALITY_AUDIT["audit_log"]
        if entry.get("resource_id") == resource_id
    ]
    
    # 按时间排序
    history.sort(key=lambda x: x["timestamp"])
    
    # 构建变更时间线
    timeline = []
    for i, entry in enumerate(history):
        change = {
            "sequence": i + 1,
            "timestamp": entry["timestamp"],
            "action": entry["action_type"],
            "user": entry["user_id"],
            "changes": {
                "from": entry.get("old_value"),
                "to": entry.get("new_value")
            },
            "details": entry.get("details", {})
        }
        timeline.append(change)
    
    return {
        "success": True,
        "resource_id": resource_id,
        "total_changes": len(history),
        "first_seen": history[0]["timestamp"] if history else None,
        "last_seen": history[-1]["timestamp"] if history else None,
        "timeline": timeline
    }

@app.post("/api/quality/audit/export")
async def export_audit_log(request: Request):
    """导出审计日志"""
    from datetime import datetime
    
    data = await request.json()
    
    format_type = data.get("format", "json")
    start_date = data.get("start_date")
    end_date = data.get("end_date")
    
    audit_log = QUALITY_AUDIT["audit_log"]
    
    # 过滤日期
    if start_date:
        try:
            start_dt = datetime.fromisoformat(start_date)
            audit_log = [e for e in audit_log if datetime.fromisoformat(e["timestamp"]) >= start_dt]
        except:
            pass
    
    if end_date:
        try:
            end_dt = datetime.fromisoformat(end_date)
            audit_log = [e for e in audit_log if datetime.fromisoformat(e["timestamp"]) <= end_dt]
        except:
            pass
    
    if format_type == "csv":
        # 生成CSV格式
        csv_lines = ["audit_id,timestamp,action_type,user_id,resource,resource_id,old_value,new_value"]
        for entry in audit_log:
            csv_lines.append(
                f"{entry['audit_id']},{entry['timestamp']},{entry['action_type']},{entry['user_id']},{entry['resource']},{entry['resource_id']},{entry.get('old_value', '')},{entry.get('new_value', '')}"
            )
        return {
            "success": True,
            "format": "csv",
            "count": len(audit_log),
            "data": "\n".join(csv_lines)
        }
    else:
        return {
            "success": True,
            "format": "json",
            "count": len(audit_log),
            "data": audit_log,
            "exported_at": datetime.now().isoformat()
        }

@app.post("/api/quality/audit/clear")
async def clear_audit_log(before_date: str = None):
    """清除审计日志"""
    from datetime import datetime
    
    if before_date:
        try:
            cutoff = datetime.fromisoformat(before_date)
            original_count = len(QUALITY_AUDIT["audit_log"])
            QUALITY_AUDIT["audit_log"] = [
                e for e in QUALITY_AUDIT["audit_log"]
                if datetime.fromisoformat(e["timestamp"]) >= cutoff
            ]
            removed = original_count - len(QUALITY_AUDIT["audit_log"])
            return {
                "success": True,
                "message": f"已清除{removed}条审计记录",
                "removed_count": removed,
                "remaining_count": len(QUALITY_AUDIT["audit_log"])
            }
        except:
            return {
                "success": False,
                "message": "日期格式无效"
            }
    else:
        count = len(QUALITY_AUDIT["audit_log"])
        QUALITY_AUDIT["audit_log"] = []
        return {
            "success": True,
            "message": f"已清除所有{count}条审计记录",
            "removed_count": count,
            "remaining_count": 0
        }

