@app.post("/api/quality/archive/create")
async def create_quality_archive(request: Request):
    """创建质量数据归档"""
    from datetime import datetime
    import json
    import os
    
    data = await request.json()
    
    # 获取要归档的数据范围
    start_date = data.get("start_date")
    end_date = data.get("end_date")
    include_history = data.get("include_history", True)
    include_feedback = data.get("include_feedback", True)
    include_audit = data.get("include_audit", True)
    
    # 创建归档ID
    archive_id = f"archive_{datetime.now().strftime('%Y%m%d_%H%M%S')}"
    
    # 收集归档数据
    archive_data = {
        "archive_id": archive_id,
        "created_at": datetime.now().isoformat(),
        "date_range": {
            "start": start_date,
            "end": end_date
        },
        "metadata": {
            "include_history": include_history,
            "include_feedback": include_feedback,
            "include_audit": include_audit
        }
    }
    
    # 添加历史数据
    if include_history:
        history = QUALITY_STATS_DATA.get("quality_history", [])
        if start_date:
            try:
                start_dt = datetime.fromisoformat(start_date)
                history = [h for h in history if datetime.fromisoformat(h.get("timestamp", "")) >= start_dt]
            except:
                pass
        if end_date:
            try:
                end_dt = datetime.fromisoformat(end_date)
                history = [h for h in history if datetime.fromisoformat(h.get("timestamp", "")) <= end_dt]
            except:
                pass
        archive_data["quality_history"] = history
        archive_data["history_count"] = len(history)
    
    # 添加反馈数据
    if include_feedback:
        feedback = QUALITY_STATS_DATA.get("feedback_records", [])
        archive_data["feedback_records"] = feedback
        archive_data["feedback_count"] = len(feedback)
    
    # 添加审计数据
    if include_audit:
        audit = QUALITY_AUDIT.get("audit_log", [])
        archive_data["audit_log"] = audit
        archive_data["audit_count"] = len(audit)
    
    # 确保归档目录存在
    archive_dir = QUALITY_ARCHIVE["archive_path"]
    os.makedirs(archive_dir, exist_ok=True)
    
    # 保存归档文件
    archive_file = os.path.join(archive_dir, f"{archive_id}.json")
    with open(archive_file, "w", encoding="utf-8") as f:
        json.dump(archive_data, f, ensure_ascii=False, indent=2)
    
    # 记录归档信息
    archive_info = {
        "archive_id": archive_id,
        "created_at": datetime.now().isoformat(),
        "file_path": archive_file,
        "file_size_kb": os.path.getsize(archive_file) // 1024,
        "records_count": archive_data.get("history_count", 0) + archive_data.get("feedback_count", 0) + archive_data.get("audit_count", 0)
    }
    
    QUALITY_ARCHIVE["archives"].append(archive_info)
    
    return {
        "success": True,
        "archive_id": archive_id,
        "archive_info": archive_info,
        "message": f"归档创建成功，包含{archive_info['records_count']}条记录"
    }

