@app.post("/api/quality/archive/cleanup")
async def cleanup_old_archives():
    """清理过期归档"""
    import os
    from datetime import datetime, timedelta
    
    retention_days = QUALITY_ARCHIVE["retention_days"]
    cutoff = datetime.now() - timedelta(days=retention_days)
    
    removed_archives = []
    kept_archives = []
    
    for archive in QUALITY_ARCHIVE["archives"]:
        created_at = archive.get("created_at", "")
        try:
            archive_date = datetime.fromisoformat(created_at)
            if archive_date < cutoff:
                # 删除过期归档
                archive_file = archive.get("file_path", "")
                if os.path.exists(archive_file):
                    os.remove(archive_file)
                removed_archives.append(archive["archive_id"])
            else:
                kept_archives.append(archive)
        except:
            kept_archives.append(archive)
    
    QUALITY_ARCHIVE["archives"] = kept_archives
    
    return {
        "success": True,
        "removed_count": len(removed_archives),
        "removed_archives": removed_archives,
        "kept_count": len(kept_archives),
        "retention_days": retention_days,
        "message": f"已清理{len(removed_archives)}个过期归档"
    }

