@app.post("/api/quality/validate/score")
async def validate_quality_score(request: Request):
    """验证质量评分数据"""
    from datetime import datetime
    
    data = await request.json()
    
    errors = []
    warnings = []
    
    # 验证评分范围
    score = data.get("quality_score")
    if score is not None:
        min_score = QUALITY_VALIDATION["validation_rules"]["score_range"]["min"]
        max_score = QUALITY_VALIDATION["validation_rules"]["score_range"]["max"]
        if not isinstance(score, (int, float)):
            errors.append({"field": "quality_score", "message": "评分必须是数字"})
        elif score < min_score or score > max_score:
            errors.append({"field": "quality_score", "message": f"评分必须在{min_score}-{max_score}之间"})
    
    # 验证维度
    dimensions = data.get("dimensions", {})
    required_dims = QUALITY_VALIDATION["validation_rules"]["dimensions_required"]
    for dim in required_dims:
        if dim not in dimensions:
            errors.append({"field": f"dimensions.{dim}", "message": f"缺少必需维度: {dim}"})
        elif not isinstance(dimensions[dim], (int, float)):
            errors.append({"field": f"dimensions.{dim}", "message": "维度值必须是数字"})
        elif dimensions[dim] < 0 or dimensions[dim] > 100:
            warnings.append({"field": f"dimensions.{dim}", "message": f"维度值建议在0-100之间"})
    
    # 验证答案长度
    answer = data.get("answer", "")
    min_len = QUALITY_VALIDATION["validation_rules"]["min_answer_length"]
    max_len = QUALITY_VALIDATION["validation_rules"]["max_answer_length"]
    
    if len(answer) < min_len:
        warnings.append({"field": "answer", "message": f"答案长度过短（{len(answer)}<{min_len}）"})
    if len(answer) > max_len:
        warnings.append({"field": "answer", "message": f"答案长度过长（{len(answer)}>{max_len}）"})
    
    # 验证时间戳
    timestamp = data.get("timestamp")
    if timestamp:
        try:
            datetime.fromisoformat(timestamp)
        except:
            errors.append({"field": "timestamp", "message": "时间戳格式无效"})
    
    is_valid = len(errors) == 0
    
    return {
        "success": True,
        "is_valid": is_valid,
        "errors": errors,
        "warnings": warnings,
        "validated_at": datetime.now().isoformat(),
        "strict_mode": QUALITY_VALIDATION["strict_mode"]
    }

@app.post("/api/quality/validate/batch")
async def validate_quality_batch(request: Request):
    """批量验证质量评分数据"""
    from datetime import datetime
    
    data = await request.json()
    scores = data.get("scores", [])
    
    results = []
    total_errors = 0
    total_warnings = 0
    valid_count = 0
    
    for i, score_data in enumerate(scores):
        # 验证每条数据
        errors = []
        warnings = []
        
        score = score_data.get("quality_score")
        if score is not None:
            if not isinstance(score, (int, float)):
                errors.append({"field": "quality_score", "message": "评分必须是数字"})
            elif score < 0 or score > 100:
                errors.append({"field": "quality_score", "message": "评分必须在0-100之间"})
        
        dimensions = score_data.get("dimensions", {})
        for dim in ["structure", "relevance", "length"]:
            if dim not in dimensions:
                errors.append({"field": f"dimensions.{dim}", "message": f"缺少维度: {dim}"})
        
        results.append({
            "index": i,
            "is_valid": len(errors) == 0,
            "errors": errors,
            "warnings": warnings
        })
        
        total_errors += len(errors)
        total_warnings += len(warnings)
        if len(errors) == 0:
            valid_count += 1
    
    return {
        "success": True,
        "total_count": len(scores),
        "valid_count": valid_count,
        "invalid_count": len(scores) - valid_count,
        "total_errors": total_errors,
        "total_warnings": total_warnings,
        "results": results,
        "validated_at": datetime.now().isoformat()
    }

