@app.post("/api/quality/validate/schema")
async def validate_against_schema(request: Request):
    """根据Schema验证数据"""
    from datetime import datetime
    
    data = await request.json()
    
    # 定义Schema
    schema = {
        "quality_score": {"type": "number", "required": True, "min": 0, "max": 100},
        "dimensions": {
            "type": "object",
            "required": True,
            "properties": {
                "structure": {"type": "number", "min": 0, "max": 100},
                "relevance": {"type": "number", "min": 0, "max": 100},
                "length": {"type": "number", "min": 0, "max": 100}
            }
        },
        "level": {"type": "string", "enum": ["excellent", "good", "average", "poor"]},
        "timestamp": {"type": "string", "format": "iso8601"},
        "question_type": {"type": "string"},
        "answer": {"type": "string", "min_length": 10}
    }
    
    validation_results = []
    
    for field, rules in schema.items():
        field_result = {"field": field, "valid": True, "errors": []}
        
        value = data.get(field)
        
        # 检查必需字段
        if rules.get("required") and value is None:
            field_result["valid"] = False
            field_result["errors"].append("字段为必填项")
            validation_results.append(field_result)
            continue
        
        if value is None:
            validation_results.append(field_result)
            continue
        
        # 类型检查
        expected_type = rules.get("type")
        if expected_type == "number" and not isinstance(value, (int, float)):
            field_result["valid"] = False
            field_result["errors"].append(f"类型应为{expected_type}")
        elif expected_type == "string" and not isinstance(value, str):
            field_result["valid"] = False
            field_result["errors"].append(f"类型应为{expected_type}")
        elif expected_type == "object" and not isinstance(value, dict):
            field_result["valid"] = False
            field_result["errors"].append(f"类型应为{expected_type}")
        
        # 范围检查
        if expected_type == "number" and isinstance(value, (int, float)):
            if "min" in rules and value < rules["min"]:
                field_result["valid"] = False
                field_result["errors"].append(f"值不能小于{rules['min']}")
            if "max" in rules and value > rules["max"]:
                field_result["valid"] = False
                field_result["errors"].append(f"值不能大于{rules['max']}")
        
        # 枚举检查
        if "enum" in rules and value not in rules["enum"]:
            field_result["valid"] = False
            field_result["errors"].append(f"值必须是以下之一: {rules['enum']}")
        
        # 字符串长度检查
        if expected_type == "string" and isinstance(value, str):
            if "min_length" in rules and len(value) < rules["min_length"]:
                field_result["valid"] = False
                field_result["errors"].append(f"长度不能小于{rules['min_length']}")
        
        validation_results.append(field_result)
    
    all_valid = all(r["valid"] for r in validation_results)
    
    return {
        "success": True,
        "is_valid": all_valid,
        "validation_results": validation_results,
        "validated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/validate/integrity")
async def validate_data_integrity():
    """验证数据完整性"""
    from datetime import datetime
    
    issues = []
    
    # 检查历史数据完整性
    history = QUALITY_STATS_DATA.get("quality_history", [])
    for i, record in enumerate(history):
        if not record.get("id"):
            issues.append({"type": "missing_id", "index": i, "message": "记录缺少ID"})
        if not record.get("timestamp"):
            issues.append({"type": "missing_timestamp", "index": i, "message": "记录缺少时间戳"})
        if record.get("quality_score") is None:
            issues.append({"type": "missing_score", "index": i, "message": "记录缺少评分"})
    
    # 检查维度数据
    for i, record in enumerate(history):
        dims = record.get("dimensions", {})
        for dim in ["structure", "relevance", "length"]:
            if dim not in dims:
                issues.append({"type": "missing_dimension", "index": i, "dimension": dim})
    
    # 检查重复记录
    ids = [r.get("id") for r in history if r.get("id")]
    duplicates = [id for id in set(ids) if ids.count(id) > 1]
    if duplicates:
        issues.append({"type": "duplicate_ids", "count": len(duplicates), "ids": duplicates[:5]})
    
    return {
        "success": True,
        "total_records": len(history),
        "issues_found": len(issues),
        "issues": issues[:50],
        "checked_at": datetime.now().isoformat()
    }

@app.post("/api/quality/validate/repair")
async def repair_validation_issues(request: Request):
    """修复验证问题"""
    from datetime import datetime
    import uuid
    
    data = await request.json()
    repair_types = data.get("repair_types", ["missing_id", "missing_timestamp"])
    
    repaired = []
    
    history = QUALITY_STATS_DATA.get("quality_history", [])
    
    for i, record in enumerate(history):
        repairs_made = []
        
        # 修复缺失ID
        if "missing_id" in repair_types and not record.get("id"):
            record["id"] = str(uuid.uuid4())[:8]
            repairs_made.append("added_id")
        
        # 修复缺失时间戳
        if "missing_timestamp" in repair_types and not record.get("timestamp"):
            record["timestamp"] = datetime.now().isoformat()
            repairs_made.append("added_timestamp")
        
        # 修复缺失维度
        if "missing_dimension" in repair_types:
            dims = record.setdefault("dimensions", {})
            for dim in ["structure", "relevance", "length"]:
                if dim not in dims:
                    dims[dim] = record.get("quality_score", 70)
                    repairs_made.append(f"added_dimension_{dim}")
        
        if repairs_made:
            repaired.append({"index": i, "repairs": repairs_made})
    
    return {
        "success": True,
        "repaired_count": len(repaired),
        "repaired_records": repaired,
        "repaired_at": datetime.now().isoformat()
    }

