@app.post("/api/quality/encrypt/data")
async def encrypt_quality_data(request: Request):
    """加密质量数据"""
    from datetime import datetime
    import hashlib
    import base64
    import json
    
    data = await request.json()
    
    encrypted_data = {}
    encrypted_fields = QUALITY_ENCRYPTION["encrypted_fields"]
    
    for field in encrypted_fields:
        if field in data and data[field]:
            # 简单加密模拟（实际应用应使用真正的加密库如cryptography）
            value = str(data[field])
            # 使用SHA256哈希作为密钥派生
            key = hashlib.sha256(f"quality_{field}".encode()).digest()
            # Base64编码模拟加密
            encrypted = base64.b64encode(value.encode()).decode()
            encrypted_data[field] = {
                "encrypted": True,
                "value": encrypted,
                "algorithm": QUALITY_ENCRYPTION["algorithm"]
            }
    
    QUALITY_ENCRYPTION["encryption_count"] += 1
    
    return {
        "success": True,
        "encrypted_at": datetime.now().isoformat(),
        "encrypted_fields": list(encrypted_data.keys()),
        "data": encrypted_data,
        "algorithm": QUALITY_ENCRYPTION["algorithm"]
    }

@app.post("/api/quality/decrypt/data")
async def decrypt_quality_data(request: Request):
    """解密质量数据"""
    from datetime import datetime
    import base64
    
    data = await request.json()
    
    decrypted_data = {}
    
    for field, enc_info in data.items():
        if isinstance(enc_info, dict) and enc_info.get("encrypted"):
            try:
                # Base64解码模拟解密
                decrypted = base64.b64decode(enc_info["value"]).decode()
                decrypted_data[field] = decrypted
            except Exception as e:
                decrypted_data[field] = f"[解密失败: {str(e)}]"
    
    QUALITY_ENCRYPTION["decryption_count"] += 1
    
    return {
        "success": True,
        "decrypted_at": datetime.now().isoformat(),
        "decrypted_fields": list(decrypted_data.keys()),
        "data": decrypted_data
    }

@app.post("/api/quality/encrypt/batch")
async def encrypt_quality_batch(request: Request):
    """批量加密质量数据"""
    from datetime import datetime
    import hashlib
    import base64
    
    data = await request.json()
    records = data.get("records", [])
    fields_to_encrypt = data.get("fields", QUALITY_ENCRYPTION["encrypted_fields"])
    
    encrypted_records = []
    total_encrypted = 0
    
    for record in records:
        encrypted_record = {}
        for key, value in record.items():
            if key in fields_to_encrypt and value:
                encrypted = base64.b64encode(str(value).encode()).decode()
                encrypted_record[key] = {
                    "encrypted": True,
                    "value": encrypted,
                    "algorithm": QUALITY_ENCRYPTION["algorithm"]
                }
                total_encrypted += 1
            else:
                encrypted_record[key] = value
        encrypted_records.append(encrypted_record)
    
    QUALITY_ENCRYPTION["encryption_count"] += total_encrypted
    
    return {
        "success": True,
        "total_records": len(records),
        "total_fields_encrypted": total_encrypted,
        "encrypted_at": datetime.now().isoformat(),
        "records": encrypted_records
    }

