@app.post("/api/quality/mask/data")
async def mask_quality_data(request: Request):
    """脱敏质量数据"""
    from datetime import datetime
    import hashlib
    import re
    
    data = await request.json()
    
    masked_data = {}
    masking_rules = QUALITY_MASKING["masking_rules"]
    
    for field, value in data.items():
        if field in masking_rules and value:
            rule = masking_rules[field]
            method = rule.get("method", "partial")
            
            if method == "partial":
                # 部分可见
                visible = rule.get("visible_chars", 4)
                str_val = str(value)
                if len(str_val) > visible:
                    masked_data[field] = str_val[:visible] + "*" * (len(str_val) - visible)
                else:
                    masked_data[field] = str_val
                    
            elif method == "hash":
                # 哈希脱敏
                algo = rule.get("algorithm", "sha256")
                if algo == "sha256":
                    masked_data[field] = hashlib.sha256(str(value).encode()).hexdigest()[:16]
                else:
                    masked_data[field] = hashlib.md5(str(value).encode()).hexdigest()[:16]
                    
            elif method == "truncate":
                # 截断脱敏
                max_len = rule.get("max_length", 50)
                str_val = str(value)
                if len(str_val) > max_len:
                    masked_data[field] = str_val[:max_len] + "..."
                else:
                    masked_data[field] = str_val
                    
            elif method == "full":
                # 完全脱敏
                masked_data[field] = "***MASKED***"
                
            else:
                masked_data[field] = value
        else:
            masked_data[field] = value
    
    QUALITY_MASKING["masking_count"] += 1
    
    return {
        "success": True,
        "masked_at": datetime.now().isoformat(),
        "masked_fields": list(masking_rules.keys()),
        "data": masked_data
    }

@app.post("/api/quality/mask/batch")
async def mask_quality_batch(request: Request):
    """批量脱敏质量数据"""
    from datetime import datetime
    import hashlib
    
    data = await request.json()
    records = data.get("records", [])
    fields_to_mask = data.get("fields", list(QUALITY_MASKING["masking_rules"].keys()))
    
    masked_records = []
    total_masked = 0
    
    for record in records:
        masked_record = {}
        for key, value in record.items():
            if key in fields_to_mask and value:
                # 默认使用部分脱敏
                str_val = str(value)
                if len(str_val) > 4:
                    masked_record[key] = str_val[:4] + "*" * (len(str_val) - 4)
                else:
                    masked_record[key] = str_val
                total_masked += 1
            else:
                masked_record[key] = value
        masked_records.append(masked_record)
    
    QUALITY_MASKING["masking_count"] += total_masked
    
    return {
        "success": True,
        "total_records": len(records),
        "total_fields_masked": total_masked,
        "masked_at": datetime.now().isoformat(),
        "records": masked_records[:100]  # 限制返回数量
    }

@app.post("/api/quality/mask/field")
async def mask_single_field(request: Request):
    """脱敏单个字段"""
    from datetime import datetime
    import hashlib
    
    data = await request.json()
    field_name = data.get("field")
    value = data.get("value")
    method = data.get("method", "partial")
    
    if not field_name or value is None:
        return {
            "success": False,
            "message": "缺少字段名或值"
        }
    
    str_val = str(value)
    
    if method == "partial":
        visible = data.get("visible_chars", 4)
        if len(str_val) > visible:
            masked_value = str_val[:visible] + "*" * (len(str_val) - visible)
        else:
            masked_value = str_val
    elif method == "hash":
        masked_value = hashlib.sha256(str_val.encode()).hexdigest()[:16]
    elif method == "truncate":
        max_len = data.get("max_length", 50)
        if len(str_val) > max_len:
            masked_value = str_val[:max_len] + "..."
        else:
            masked_value = str_val
    elif method == "full":
        masked_value = "***MASKED***"
    else:
        masked_value = str_val
    
    QUALITY_MASKING["masking_count"] += 1
    
    return {
        "success": True,
        "field": field_name,
        "original_value": str_val,
        "masked_value": masked_value,
        "method": method,
        "masked_at": datetime.now().isoformat()
    }

@app.post("/api/quality/mask/email")
async def mask_email(request: Request):
    """脱敏邮箱"""
    from datetime import datetime
    
    data = await request.json()
    email = data.get("email")
    
    if not email:
        return {"success": False, "message": "缺少邮箱"}
    
    # 邮箱脱敏：保留前2字符和@后域名
    if "@" in email:
        parts = email.split("@")
        local = parts[0]
        domain = parts[1]
        
        if len(local) > 2:
            masked_local = local[:2] + "*" * (len(local) - 2)
        else:
            masked_local = "*" * len(local)
        
        masked_email = f"{masked_local}@{domain}"
    else:
        masked_email = email[:2] + "*" * (len(email) - 2)
    
    QUALITY_MASKING["masking_count"] += 1
    
    return {
        "success": True,
        "original_email": email,
        "masked_email": masked_email,
        "masked_at": datetime.now().isoformat()
    }

@app.post("/api/quality/mask/phone")
async def mask_phone(request: Request):
    """脱敏手机号"""
    from datetime import datetime
    
    data = await request.json()
    phone = data.get("phone")
    
    if not phone:
        return {"success": False, "message": "缺少手机号"}
    
    # 手机号脱敏：保留前3后4
    str_phone = str(phone)
    if len(str_phone) >= 7:
        masked_phone = str_phone[:3] + "****" + str_phone[-4:]
    else:
        masked_phone = "*" * len(str_phone)
    
    QUALITY_MASKING["masking_count"] += 1
    
    return {
        "success": True,
        "original_phone": phone,
        "masked_phone": masked_phone,
        "masked_at": datetime.now().isoformat()
    }

@app.post("/api/quality/mask/ip")
async def mask_ip_address(request: Request):
    """脱敏IP地址"""
    from datetime import datetime
    
    data = await request.json()
    ip = data.get("ip_address")
    visible_octets = data.get("visible_octets", 2)
    
    if not ip:
        return {"success": False, "message": "缺少IP地址"}
    
    # IP地址脱敏
    parts = ip.split(".")
    if len(parts) == 4:
        masked_parts = parts[:visible_octets] + ["***"] * (4 - visible_octets)
        masked_ip = ".".join(masked_parts)
    else:
        masked_ip = "***.***.***.***"
    
    QUALITY_MASKING["masking_count"] += 1
    
    return {
        "success": True,
        "original_ip": ip,
        "masked_ip": masked_ip,
        "visible_octets": visible_octets,
        "masked_at": datetime.now().isoformat()
    }

