@app.post("/api/quality/mask/validate")
async def validate_masking(request: Request):
    """验证脱敏效果"""
    from datetime import datetime
    
    data = await request.json()
    original = data.get("original_data", {})
    masked = data.get("masked_data", {})
    
    validation_results = []
    all_valid = True
    
    for field in original:
        if field in masked:
            # 检查是否已脱敏
            orig_val = str(original[field])
            masked_val = str(masked[field])
            
            is_masked = orig_val != masked_val
            
            # 检查是否泄露原始数据
            contains_original = orig_val in masked_val and len(orig_val) > 4
            
            validation_results.append({
                "field": field,
                "is_masked": is_masked,
                "contains_original": contains_original,
                "valid": is_masked and not contains_original
            })
            
            if not is_masked or contains_original:
                all_valid = False
    
    return {
        "success": True,
        "all_valid": all_valid,
        "validated_at": datetime.now().isoformat(),
        "results": validation_results
    }

