    if role not in QUALITY_ACCESS_CONTROL["roles"]:
        return {"success": False, "message": f"无效角色: {role}"}
    
    # 授予角色
    old_role = QUALITY_ACCESS_CONTROL["user_roles"].get(user_id)
    QUALITY_ACCESS_CONTROL["user_roles"][user_id] = role
    
    return {
        "success": True,
        "message": "权限已授予",
        "user_id": user_id,
        "old_role": old_role,
        "new_role": role,
        "permissions": QUALITY_ACCESS_CONTROL["roles"][role]["permissions"],
        "granted_at": datetime.now().isoformat()
    }

