# 质量评分数据完整性校验配置
QUALITY_INTEGRITY = {
    "enabled": True,
    "check_rules": {
        "required_fields": ["score", "timestamp", "question_type"],
        "score_range": {"min": 0, "max": 100},
        "timestamp_format": "ISO8601",
        "max_answer_length": 10000,
        "min_answer_length": 1
    },
    "integrity_log": [],
    "check_count": 0,
    "failed_count": 0,
    "checksum_algorithm": "sha256"
}

@app.post("/api/quality/integrity/check")
async def check_data_integrity(request: Request):
    """检查数据完整性"""
    from datetime import datetime
    import hashlib
    
    data = await request.json()
    check_results = []
    all_valid = True
    
    rules = QUALITY_INTEGRITY["check_rules"]
    
    # 检查必填字段
    for field in rules["required_fields"]:
        if field not in data or data[field] is None:
            check_results.append({
                "check": "required_field",
                "field": field,
                "valid": False,
                "message": f"必填字段缺失: {field}"
            })
            all_valid = False
        else:
            check_results.append({
                "check": "required_field",
                "field": field,
                "valid": True,
                "message": "字段存在"
            })
    
    # 检查分数范围
    if "score" in data and data["score"] is not None:
        score = data["score"]
        if not isinstance(score, (int, float)):
            check_results.append({
                "check": "score_type",
                "valid": False,
                "message": "分数必须是数字"
            })
            all_valid = False
        elif not (rules["score_range"]["min"] <= score <= rules["score_range"]["max"]):
            check_results.append({
                "check": "score_range",
                "valid": False,
                "message": f"分数超出范围: {score}"
            })
            all_valid = False
        else:
            check_results.append({
                "check": "score_range",
                "valid": True,
                "message": f"分数在有效范围内: {score}"
            })
    
    # 检查时间戳格式
    if "timestamp" in data and data["timestamp"]:
        try:
            datetime.fromisoformat(data["timestamp"].replace("Z", "+00:00"))
            check_results.append({
                "check": "timestamp_format",
                "valid": True,
                "message": "时间戳格式正确"
            })
        except:
            check_results.append({
                "check": "timestamp_format",
                "valid": False,
                "message": "时间戳格式错误"
            })
            all_valid = False
    
    # 检查答案长度
    if "answer" in data and data["answer"]:
        answer_len = len(str(data["answer"]))
        if answer_len < rules["min_answer_length"]:
            check_results.append({
                "check": "answer_length",
                "valid": False,
                "message": f"答案过短: {answer_len}"
            })
            all_valid = False
        elif answer_len > rules["max_answer_length"]:
            check_results.append({
                "check": "answer_length",
                "valid": False,
                "message": f"答案过长: {answer_len}"
            })
            all_valid = False
        else:
            check_results.append({
                "check": "answer_length",
                "valid": True,
                "message": f"答案长度有效: {answer_len}"
            })
    
    QUALITY_INTEGRITY["check_count"] += 1
    if not all_valid:
        QUALITY_INTEGRITY["failed_count"] += 1
    
    QUALITY_INTEGRITY["integrity_log"].append({
        "timestamp": datetime.now().isoformat(),
        "all_valid": all_valid,
        "checks_count": len(check_results),
        "failed_checks": len([c for c in check_results if not c["valid"]])
    })
    
    return {
        "success": True,
        "all_valid": all_valid,
        "checked_at": datetime.now().isoformat(),
        "results": check_results,
        "summary": {
            "total_checks": len(check_results),
            "passed": len([c for c in check_results if c["valid"]]),
            "failed": len([c for c in check_results if not c["valid"]])
        }
    }

@app.post("/api/quality/integrity/batch")
async def check_batch_integrity(request: Request):
    """批量检查数据完整性"""
    from datetime import datetime
    
    data = await request.json()
    records = data.get("records", [])
    
    results = []
    total_valid = 0
    total_invalid = 0
    
    for i, record in enumerate(records):
        # 简化检查
        is_valid = (
            "score" in record and 
            record["score"] is not None and
            0 <= record["score"] <= 100 and
            "timestamp" in record
        )
        
        if is_valid:
            total_valid += 1
        else:
            total_invalid += 1
        
        results.append({
            "index": i,
            "valid": is_valid,
            "record_id": record.get("id", f"record_{i}")
        })
    
    QUALITY_INTEGRITY["check_count"] += len(records)
    QUALITY_INTEGRITY["failed_count"] += total_invalid
    
    return {
        "success": True,
        "total_records": len(records),
        "valid_records": total_valid,
        "invalid_records": total_invalid,
        "checked_at": datetime.now().isoformat(),
        "results": results[:100]  # 限制返回数量
    }

@app.post("/api/quality/integrity/checksum")
async def calculate_checksum(request: Request):
    """计算数据校验和"""
    from datetime import datetime
    import hashlib
    import json
    
    data = await request.json()
    
    # 序列化数据
    data_str = json.dumps(data, sort_keys=True)
    
    # 计算校验和
    checksum = hashlib.sha256(data_str.encode()).hexdigest()
    
    return {
        "success": True,
        "checksum": checksum,
        "algorithm": QUALITY_INTEGRITY["checksum_algorithm"],
        "data_length": len(data_str),
        "calculated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/integrity/verify")
async def verify_checksum(request: Request):
    """验证数据校验和"""
    from datetime import datetime
    import hashlib
    import json
    
    data = await request.json()
    data_content = data.get("data", {})
    expected_checksum = data.get("checksum", "")
    
    # 计算实际校验和
    data_str = json.dumps(data_content, sort_keys=True)
    actual_checksum = hashlib.sha256(data_str.encode()).hexdigest()
    
    is_valid = actual_checksum == expected_checksum
    
    return {
        "success": True,
        "valid": is_valid,
        "expected_checksum": expected_checksum,
        "actual_checksum": actual_checksum,
        "verified_at": datetime.now().isoformat()
    }

