@app.post("/api/quality/integrity/repair")
async def repair_data_integrity(request: Request):
    """修复数据完整性问题"""
    from datetime import datetime
    
    data = await request.json()
    repaired_data = data.copy()
    repairs = []
    
    # 修复缺失的必填字段
    if "score" not in repaired_data or repaired_data["score"] is None:
        repaired_data["score"] = 50  # 默认分数
        repairs.append({"field": "score", "action": "set_default", "value": 50})
    
    if "timestamp" not in repaired_data or not repaired_data["timestamp"]:
        repaired_data["timestamp"] = datetime.now().isoformat()
        repairs.append({"field": "timestamp", "action": "set_current", "value": repaired_data["timestamp"]})
    
    if "question_type" not in repaired_data or not repaired_data["question_type"]:
        repaired_data["question_type"] = "general"
        repairs.append({"field": "question_type", "action": "set_default", "value": "general"})
    
    # 修复分数范围
    if "score" in repaired_data:
        score = repaired_data["score"]
        if isinstance(score, (int, float)):
            if score < 0:
                repaired_data["score"] = 0
                repairs.append({"field": "score", "action": "clamp_min", "value": 0})
            elif score > 100:
                repaired_data["score"] = 100
                repairs.append({"field": "score", "action": "clamp_max", "value": 100})
    
    return {
        "success": True,
        "message": "数据已修复",
        "repairs_count": len(repairs),
        "repairs": repairs,
        "repaired_data": repaired_data,
        "repaired_at": datetime.now().isoformat()
    }

@app.post("/api/quality/integrity/compare")
async def compare_data_integrity(request: Request):
    """比较数据完整性"""
    from datetime import datetime
    
    data = await request.json()
    original = data.get("original", {})
    modified = data.get("modified", {})
    
    differences = []
    
    all_keys = set(original.keys()) | set(modified.keys())
    
    for key in all_keys:
        orig_val = original.get(key)
        mod_val = modified.get(key)
        
        if orig_val != mod_val:
            differences.append({
                "field": key,
                "original": orig_val,
                "modified": mod_val,
                "changed": True
            })
    
    return {
        "success": True,
        "identical": len(differences) == 0,
        "differences_count": len(differences),
        "differences": differences,
        "compared_at": datetime.now().isoformat()
    }

