@app.post("/api/quality/integrity/validate-schema")
async def validate_data_schema(request: Request):
    """验证数据模式"""
    from datetime import datetime
    
    data = await request.json()
    schema = data.get("schema", {})
    record = data.get("record", {})
    
    validation_errors = []
    
    # 检查schema中定义的字段
    for field, field_schema in schema.items():
        if field_schema.get("required", False) and field not in record:
            validation_errors.append({
                "field": field,
                "error": "required_field_missing"
            })
        
        if field in record:
            value = record[field]
            
            # 类型检查
            expected_type = field_schema.get("type")
            if expected_type:
                type_map = {
                    "string": str,
                    "number": (int, float),
                    "integer": int,
                    "boolean": bool,
                    "array": list,
                    "object": dict
                }
                if expected_type in type_map:
                    if not isinstance(value, type_map[expected_type]):
                        validation_errors.append({
                            "field": field,
                            "error": "type_mismatch",
                            "expected": expected_type,
                            "actual": type(value).__name__
                        })
            
            # 范围检查
            if "min" in field_schema and isinstance(value, (int, float)):
                if value < field_schema["min"]:
                    validation_errors.append({
                        "field": field,
                        "error": "value_below_min",
                        "min": field_schema["min"],
                        "actual": value
                    })
            
            if "max" in field_schema and isinstance(value, (int, float)):
                if value > field_schema["max"]:
                    validation_errors.append({
                        "field": field,
                        "error": "value_above_max",
                        "max": field_schema["max"],
                        "actual": value
                    })
    
    return {
        "success": True,
        "valid": len(validation_errors) == 0,
        "errors_count": len(validation_errors),
        "errors": validation_errors,
        "validated_at": datetime.now().isoformat()
    }

# 质量评分数据恢复配置
QUALITY_RECOVERY = {
    "enabled": True,
    "backup_dir": "/home/field/.nanobot/data/backups/quality",
    "snapshots": {},
    "recovery_log": [],
    "recovery_count": 0,
    "auto_backup": True,
    "max_snapshots": 10,
    "retention_days": 30
}

@app.post("/api/quality/recovery/create")
async def create_recovery_snapshot(request: Request):
    """创建恢复快照"""
    from datetime import datetime
    import json
    import os
    
    data = await request.json()
    snapshot_name = data.get("name", f"snapshot_{datetime.now().strftime('%Y%m%d_%H%M%S')}")
    
    # 创建快照数据
    snapshot = {
        "name": snapshot_name,
        "created_at": datetime.now().isoformat(),
        "data": {
            "quality_history": QUALITY_HISTORY[-100:] if QUALITY_HISTORY else [],
            "quality_config": QUALITY_CONFIG,
            "quality_thresholds": QUALITY_THRESHOLDS
        }
    }
    
    # 存储快照
    QUALITY_RECOVERY["snapshots"][snapshot_name] = snapshot
    
    # 保存到文件
    os.makedirs(QUALITY_RECOVERY["backup_dir"], exist_ok=True)
    snapshot_path = os.path.join(QUALITY_RECOVERY["backup_dir"], f"{snapshot_name}.json")
    
    with open(snapshot_path, "w") as f:
        json.dump(snapshot, f, indent=2)
    
    # 清理旧快照
    if len(QUALITY_RECOVERY["snapshots"]) > QUALITY_RECOVERY["max_snapshots"]:
        oldest = sorted(QUALITY_RECOVERY["snapshots"].items(), key=lambda x: x[1]["created_at"])[0]
        del QUALITY_RECOVERY["snapshots"][oldest[0]]
        old_path = os.path.join(QUALITY_RECOVERY["backup_dir"], f"{oldest[0]}.json")
        if os.path.exists(old_path):
            os.remove(old_path)
    
    return {
        "success": True,
        "message": "恢复快照已创建",
        "snapshot_name": snapshot_name,
        "created_at": snapshot["created_at"],
        "data_size": len(json.dumps(snapshot["data"])),
        "total_snapshots": len(QUALITY_RECOVERY["snapshots"])
    }

@app.post("/api/quality/recovery/restore")
async def restore_from_snapshot(request: Request):
    """从快照恢复数据"""
    from datetime import datetime
    import json
    import os
    
    global QUALITY_HISTORY, QUALITY_CONFIG, QUALITY_THRESHOLDS
    
    data = await request.json()
    snapshot_name = data.get("name")
    
    if not snapshot_name:
        return {"success": False, "message": "缺少快照名称"}
    
    # 查找快照
    snapshot = QUALITY_RECOVERY["snapshots"].get(snapshot_name)
    
    if not snapshot:
        # 尝试从文件加载
        snapshot_path = os.path.join(QUALITY_RECOVERY["backup_dir"], f"{snapshot_name}.json")
        if os.path.exists(snapshot_path):
            with open(snapshot_path, "r") as f:
                snapshot = json.load(f)
    
    if not snapshot:
        return {"success": False, "message": f"快照不存在: {snapshot_name}"}
    
    # 恢复数据
    restored_items = []
    
    if "quality_history" in snapshot["data"]:
        QUALITY_HISTORY = snapshot["data"]["quality_history"]
        restored_items.append("quality_history")
    
    if "quality_config" in snapshot["data"]:
        QUALITY_CONFIG.update(snapshot["data"]["quality_config"])
        restored_items.append("quality_config")
    
    if "quality_thresholds" in snapshot["data"]:
        QUALITY_THRESHOLDS.update(snapshot["data"]["quality_thresholds"])
        restored_items.append("quality_thresholds")
    
    QUALITY_RECOVERY["recovery_count"] += 1
    QUALITY_RECOVERY["recovery_log"].append({
        "action": "restore",
        "snapshot_name": snapshot_name,
        "restored_items": restored_items,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "数据已从快照恢复",
        "snapshot_name": snapshot_name,
        "snapshot_created_at": snapshot["created_at"],
        "restored_items": restored_items,
        "restored_at": datetime.now().isoformat()
    }

@app.get("/api/quality/recovery/snapshots")
async def list_recovery_snapshots():
    """列出所有恢复快照"""
    from datetime import datetime
    import os
    
    snapshots = []
    for name, snapshot in QUALITY_RECOVERY["snapshots"].items():
        snapshots.append({
            "name": name,
            "created_at": snapshot["created_at"],
            "data_size": len(str(snapshot["data"]))
        })
    
    # 检查文件系统中的快照
    if os.path.exists(QUALITY_RECOVERY["backup_dir"]):
        for filename in os.listdir(QUALITY_RECOVERY["backup_dir"]):
            if filename.endswith(".json"):
                name = filename[:-5]
                if name not in QUALITY_RECOVERY["snapshots"]:
                    filepath = os.path.join(QUALITY_RECOVERY["backup_dir"], filename)
                    stat = os.stat(filepath)
                    snapshots.append({
                        "name": name,
                        "created_at": datetime.fromtimestamp(stat.st_mtime).isoformat(),
                        "file_size": stat.st_size,
                        "loaded": False
                    })
    
    return {
        "success": True,
        "total_snapshots": len(snapshots),
        "snapshots": sorted(snapshots, key=lambda x: x["created_at"], reverse=True)
    }

@app.delete("/api/quality/recovery/snapshots")
async def delete_recovery_snapshot(request: Request):
    """删除恢复快照"""
    from datetime import datetime
    import os
    
    data = await request.json()
    snapshot_name = data.get("name")
    
    if not snapshot_name:
        return {"success": False, "message": "缺少快照名称"}
    
    deleted = False
    
    # 从内存删除
    if snapshot_name in QUALITY_RECOVERY["snapshots"]:
        del QUALITY_RECOVERY["snapshots"][snapshot_name]
        deleted = True
    
    # 从文件系统删除
    snapshot_path = os.path.join(QUALITY_RECOVERY["backup_dir"], f"{snapshot_name}.json")
    if os.path.exists(snapshot_path):
        os.remove(snapshot_path)
        deleted = True
    
    if not deleted:
        return {"success": False, "message": f"快照不存在: {snapshot_name}"}
    
    QUALITY_RECOVERY["recovery_log"].append({
        "action": "delete",
        "snapshot_name": snapshot_name,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "快照已删除",
        "snapshot_name": snapshot_name,
        "deleted_at": datetime.now().isoformat()
    }

@app.post("/api/quality/recovery/rollback")
async def rollback_recovery(request: Request):
    """回滚到上一个快照"""
    from datetime import datetime
    
    snapshots = sorted(
        QUALITY_RECOVERY["snapshots"].items(),
        key=lambda x: x[1]["created_at"],
        reverse=True
    )
    
    if len(snapshots) < 2:
        return {"success": False, "message": "没有足够的快照进行回滚"}
    
    # 获取上一个快照
    previous_snapshot = snapshots[1]  # 跳过最新的
    
    # 恢复
    data = {"name": previous_snapshot[0]}
    return await restore_from_snapshot.__wrapped__(Request("POST", "http://localhost/api/quality/recovery/restore", json=lambda: data))

