@app.post("/api/quality/migration/export")
async def export_migration_data(request: Request):
    """导出数据用于迁移"""
    from datetime import datetime
    import json
    import csv
    import io
    
    data = await request.json()
    export_format = data.get("format", "json")
    include_history = data.get("include_history", True)
    include_config = data.get("include_config", True)
    
    if export_format not in QUALITY_MIGRATION["supported_formats"]:
        return {"success": False, "message": f"不支持的格式: {export_format}"}
    
    export_data = {
        "version": QUALITY_MIGRATION["current_version"],
        "exported_at": datetime.now().isoformat(),
        "data": {}
    }
    
    if include_config:
        export_data["data"]["config"] = {
            "quality_config": QUALITY_CONFIG,
            "quality_thresholds": QUALITY_THRESHOLDS
        }
    
    if include_history:
        export_data["data"]["history"] = QUALITY_HISTORY[-1000:] if QUALITY_HISTORY else []
    
    if export_format == "json":
        result = {
            "success": True,
            "format": "json",
            "data": export_data,
            "exported_at": datetime.now().isoformat()
        }
    elif export_format == "csv":
        # 转换为CSV格式
        output = io.StringIO()
        writer = csv.writer(output)
        
        # 写入历史数据
        if include_history and QUALITY_HISTORY:
            writer.writerow(["timestamp", "score", "question_type", "answer_length"])
            for record in QUALITY_HISTORY[-100:]:
                writer.writerow([
                    record.get("timestamp", ""),
                    record.get("score", ""),
                    record.get("question_type", ""),
                    record.get("answer_length", "")
                ])
        
        result = {
            "success": True,
            "format": "csv",
            "data": output.getvalue(),
            "exported_at": datetime.now().isoformat()
        }
    else:
        result = {
            "success": True,
            "format": export_format,
            "data": export_data,
            "exported_at": datetime.now().isoformat()
        }
    
    QUALITY_MIGRATION["migration_log"].append({
        "action": "export",
        "format": export_format,
        "timestamp": datetime.now().isoformat()
    })
    
    return result

@app.post("/api/quality/migration/import")
async def import_migration_data(request: Request):
    """导入迁移数据"""
    from datetime import datetime
    import json
    
    global QUALITY_HISTORY, QUALITY_CONFIG, QUALITY_THRESHOLDS
    
    data = await request.json()
    import_data = data.get("data")
    merge_mode = data.get("merge_mode", "replace")  # replace, merge, append
    
    if not import_data:
        return {"success": False, "message": "缺少导入数据"}
    
    try:
        # 解析数据
        if isinstance(import_data, str):
            parsed = json.loads(import_data)
        else:
            parsed = import_data
        
        version = parsed.get("version", "1.0")
        migrated_data = parsed.get("data", {})
        
        # 版本迁移
        if version != QUALITY_MIGRATION["current_version"]:
            migrated_data = await migrate_version_data(version, QUALITY_MIGRATION["current_version"], migrated_data)
        
        imported_items = []
        
        # 导入配置
        if "config" in migrated_data:
            config = migrated_data["config"]
            
            if merge_mode == "replace":
                if "quality_config" in config:
                    QUALITY_CONFIG = config["quality_config"]
                if "quality_thresholds" in config:
                    QUALITY_THRESHOLDS = config["quality_thresholds"]
            else:
                if "quality_config" in config:
                    QUALITY_CONFIG.update(config["quality_config"])
                if "quality_thresholds" in config:
                    QUALITY_THRESHOLDS.update(config["quality_thresholds"])
            
            imported_items.append("config")
        
        # 导入历史
        if "history" in migrated_data:
            history = migrated_data["history"]
            
            if merge_mode == "replace":
                QUALITY_HISTORY = history
            elif merge_mode == "append":
                QUALITY_HISTORY.extend(history)
            else:  # merge
                existing_ids = {h.get("id") for h in QUALITY_HISTORY if h.get("id")}
                for record in history:
                    if record.get("id") not in existing_ids:
                        QUALITY_HISTORY.append(record)
            
            imported_items.append("history")
        
        QUALITY_MIGRATION["migration_count"] += 1
        QUALITY_MIGRATION["migration_log"].append({
            "action": "import",
            "version": version,
            "merge_mode": merge_mode,
            "imported_items": imported_items,
            "timestamp": datetime.now().isoformat()
        })
        
        return {
            "success": True,
            "message": "数据导入成功",
            "source_version": version,
            "target_version": QUALITY_MIGRATION["current_version"],
            "imported_items": imported_items,
            "merge_mode": merge_mode,
            "imported_at": datetime.now().isoformat()
        }
    except Exception as e:
        return {"success": False, "message": f"导入失败: {str(e)}"}

async def migrate_version_data(from_version: str, to_version: str, data: dict) -> dict:
    """版本间数据迁移"""
    # 1.0 -> 1.5
    if from_version == "1.0" and to_version in ["1.5", "2.0"]:
        # 添加新字段
        if "history" in data:
            for record in data["history"]:
                if "question_type" not in record:
                    record["question_type"] = "general"
                if "metadata" not in record:
                    record["metadata"] = {}
    
    # 1.5 -> 2.0
    if from_version in ["1.0", "1.5"] and to_version == "2.0":
        # 添加更多新字段
        if "config" in data:
            if "quality_thresholds" not in data["config"]:
                data["config"]["quality_thresholds"] = {
                    "min_score": 60,
                    "warning_threshold": 70
                }
        
        if "history" in data:
            for record in data["history"]:
                if "feedback" not in record:
                    record["feedback"] = None
    
    return data

@app.post("/api/quality/migration/transform")
async def transform_migration_data(request: Request):
    """转换数据格式"""
    from datetime import datetime
    import json
    
    data = await request.json()
    source_data = data.get("data")
    source_format = data.get("source_format", "json")
    target_format = data.get("target_format", "json")
    
    if not source_data:
        return {"success": False, "message": "缺少源数据"}
    
    try:
        # 解析源数据
        if source_format == "json":
            if isinstance(source_data, str):
                parsed = json.loads(source_data)
            else:
                parsed = source_data
        else:
            parsed = source_data
        
        # 转换为目标格式
        if target_format == "json":
            transformed = json.dumps(parsed, indent=2)
        else:
            transformed = parsed
        
        return {
            "success": True,
            "source_format": source_format,
            "target_format": target_format,
            "transformed_data": transformed,
            "transformed_at": datetime.now().isoformat()
        }
    except Exception as e:
        return {"success": False, "message": f"转换失败: {str(e)}"}

@app.post("/api/quality/migration/validate")
async def validate_migration_data(request: Request):
    """验证迁移数据"""
    from datetime import datetime
    import json
    
    data = await request.json()
    migration_data = data.get("data")
    target_version = data.get("target_version", QUALITY_MIGRATION["current_version"])
    
    if not migration_data:
        return {"success": False, "message": "缺少迁移数据"}
    
    validation_results = []
    all_valid = True
    
    try:
        if isinstance(migration_data, str):
            parsed = json.loads(migration_data)
        else:
            parsed = migration_data
        
        # 验证版本
        version = parsed.get("version", "unknown")
        if version not in QUALITY_MIGRATION["supported_versions"]:
            validation_results.append({
                "check": "version",
                "valid": False,
                "message": f"不支持的版本: {version}"
            })
            all_valid = False
        else:
            validation_results.append({
                "check": "version",
                "valid": True,
                "message": f"版本: {version}"
            })
        
        # 验证数据结构
        if "data" not in parsed:
            validation_results.append({
                "check": "data_structure",
                "valid": False,
                "message": "缺少data字段"
            })
            all_valid = False
        else:
            validation_results.append({
                "check": "data_structure",
                "valid": True,
                "message": "数据结构正确"
            })
            
            # 验证数据内容
            inner_data = parsed["data"]
            
            if "config" in inner_data:
                validation_results.append({
                    "check": "config_present",
                    "valid": True,
                    "message": "配置数据存在"
                })
            
            if "history" in inner_data:
                if isinstance(inner_data["history"], list):
                    validation_results.append({
                        "check": "history_format",
                        "valid": True,
                        "message": f"历史记录数量: {len(inner_data['history'])}"
                    })
                else:
                    validation_results.append({
                        "check": "history_format",
                        "valid": False,
                        "message": "历史记录格式错误"
                    })
                    all_valid = False
        
        return {
            "success": True,
            "valid": all_valid,
            "source_version": version,
            "target_version": target_version,
            "validation_results": validation_results,
            "validated_at": datetime.now().isoformat()
        }
    except Exception as e:
        return {
            "success": True,
            "valid": False,
            "validation_results": [{
                "check": "parse",
                "valid": False,
                "message": f"解析失败: {str(e)}"
            }],
            "validated_at": datetime.now().isoformat()
        }

