@app.post("/api/quality/migration/rollback")
async def rollback_migration(request: Request):
    """回滚迁移"""
    from datetime import datetime
    
    data = await request.json()
    migration_id = data.get("migration_id")
    
    if not migration_id:
        return {"success": False, "message": "缺少迁移ID"}
    
    # 查找迁移记录
    migration_record = None
    for log in QUALITY_MIGRATION["migration_log"]:
        if log.get("action") == "import" and log.get("timestamp") == migration_id:
            migration_record = log
            break
    
    if not migration_record:
        return {"success": False, "message": "迁移记录不存在"}
    
    # 模拟回滚
    QUALITY_MIGRATION["migration_log"].append({
        "action": "rollback",
        "original_migration_id": migration_id,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "迁移已回滚",
        "original_migration_id": migration_id,
        "rolled_back_at": datetime.now().isoformat()
    }

@app.post("/api/quality/migration/compare")
async def compare_migration_versions(request: Request):
    """比较不同版本数据结构"""
    from datetime import datetime
    
    data = await request.json()
    version1 = data.get("version1")
    version2 = data.get("version2")
    
    if not version1 or not version2:
        return {"success": False, "message": "缺少版本号"}
    
    # 版本差异
    version_diffs = {
        ("1.0", "1.5"): {
            "added_fields": ["question_type", "metadata"],
            "removed_fields": [],
            "changed_fields": []
        },
        ("1.5", "2.0"): {
            "added_fields": ["feedback", "quality_thresholds"],
            "removed_fields": [],
            "changed_fields": ["config_structure"]
        },
        ("1.0", "2.0"): {
            "added_fields": ["question_type", "metadata", "feedback", "quality_thresholds"],
            "removed_fields": [],
            "changed_fields": ["config_structure"]
        }
    }
    
    key = (version1, version2) if version1 < version2 else (version2, version1)
    diff = version_diffs.get(key, {
        "added_fields": [],
        "removed_fields": [],
        "changed_fields": []
    })
    
    return {
        "success": True,
        "version1": version1,
        "version2": version2,
        "differences": diff,
        "migration_needed": len(diff["added_fields"]) > 0 or len(diff["changed_fields"]) > 0,
        "compared_at": datetime.now().isoformat()
    }

