QUALITY_SYNC = {
    "enabled": True,
    "sync_interval": 60,  # 秒
    "sync_targets": [],  # 同步目标列表
    "sync_log": [],
    "sync_count": 0,
    "last_sync": None,
    "sync_mode": "incremental",  # full, incremental
    "conflict_resolution": "latest_wins"  # latest_wins, source_wins, target_wins
}

@app.post("/api/quality/sync/start")
async def start_data_sync(request: Request):
    """启动数据同步"""
    from datetime import datetime
    import json
    
    data = await request.json()
    target_url = data.get("target_url")
    sync_mode = data.get("sync_mode", QUALITY_SYNC["sync_mode"])
    data_types = data.get("data_types", ["history", "config"])
    
    if not target_url:
        return {"success": False, "message": "缺少目标URL"}
    
    sync_id = f"sync_{datetime.now().strftime('%Y%m%d%H%M%S')}"
    
    # 准备同步数据
    sync_data = {
        "version": QUALITY_MIGRATION["current_version"],
        "sync_id": sync_id,
        "synced_at": datetime.now().isoformat(),
        "source": "local",
        "data": {}
    }
    
    if "history" in data_types:
        sync_data["data"]["history"] = QUALITY_HISTORY[-100:] if QUALITY_HISTORY else []
    
    if "config" in data_types:
        sync_data["data"]["config"] = {
            "quality_config": QUALITY_CONFIG,
            "quality_thresholds": QUALITY_THRESHOLDS
        }
    
    # 记录同步
    QUALITY_SYNC["sync_count"] += 1
    QUALITY_SYNC["last_sync"] = datetime.now().isoformat()
    
    sync_record = {
        "sync_id": sync_id,
        "target_url": target_url,
        "sync_mode": sync_mode,
        "data_types": data_types,
        "status": "started",
        "started_at": datetime.now().isoformat(),
        "data_size": len(json.dumps(sync_data))
    }
    
    QUALITY_SYNC["sync_log"].append(sync_record)
    
    # 添加同步目标
    if target_url not in [t["url"] for t in QUALITY_SYNC["sync_targets"]]:
        QUALITY_SYNC["sync_targets"].append({
            "url": target_url,
            "last_sync": datetime.now().isoformat(),
            "sync_count": 1
        })
    else:
        for target in QUALITY_SYNC["sync_targets"]:
            if target["url"] == target_url:
                target["last_sync"] = datetime.now().isoformat()
                target["sync_count"] += 1
    
    return {
        "success": True,
        "message": "数据同步已启动",
        "sync_id": sync_id,
        "target_url": target_url,
        "sync_mode": sync_mode,
        "data_types": data_types,
        "data_size": len(json.dumps(sync_data)),
        "started_at": datetime.now().isoformat()
    }

@app.post("/api/quality/sync/receive")
async def receive_sync_data(request: Request):
    """接收同步数据"""
    from datetime import datetime
    import json
    
    global QUALITY_HISTORY, QUALITY_CONFIG, QUALITY_THRESHOLDS
    
    data = await request.json()
    sync_data = data.get("data")
    source = data.get("source", "unknown")
    conflict_resolution = data.get("conflict_resolution", QUALITY_SYNC["conflict_resolution"])
    
    if not sync_data:
        return {"success": False, "message": "缺少同步数据"}
    
    try:
        # 解析数据
        if isinstance(sync_data, str):
            parsed = json.loads(sync_data)
        else:
            parsed = sync_data
        
        received_items = []
        conflicts = []
        
        # 接收历史数据
        if "history" in parsed.get("data", {}):
            incoming_history = parsed["data"]["history"]
            
            if conflict_resolution == "latest_wins":
                # 合并，以时间戳为准
                existing_timestamps = {h.get("timestamp") for h in QUALITY_HISTORY}
                for record in incoming_history:
                    if record.get("timestamp") not in existing_timestamps:
                        QUALITY_HISTORY.append(record)
                    else:
                        # 更新现有记录
                        for i, existing in enumerate(QUALITY_HISTORY):
                            if existing.get("timestamp") == record.get("timestamp"):
                                QUALITY_HISTORY[i] = record
                                break
            elif conflict_resolution == "source_wins":
                # 源数据优先
                QUALITY_HISTORY = incoming_history
            # target_wins: 保持本地数据不变
            
            received_items.append("history")
        
        # 接收配置
        if "config" in parsed.get("data", {}):
            config = parsed["data"]["config"]
            
            if conflict_resolution in ["latest_wins", "source_wins"]:
                if "quality_config" in config:
                    QUALITY_CONFIG.update(config["quality_config"])
                if "quality_thresholds" in config:
                    QUALITY_THRESHOLDS.update(config["quality_thresholds"])
            
            received_items.append("config")
        
        sync_id = parsed.get("sync_id", "unknown")
        
        QUALITY_SYNC["sync_log"].append({
            "action": "receive",
            "sync_id": sync_id,
            "source": source,
            "received_items": received_items,
            "conflicts": conflicts,
            "timestamp": datetime.now().isoformat()
        })
        
        return {
            "success": True,
            "message": "同步数据已接收",
            "sync_id": sync_id,
            "source": source,
            "received_items": received_items,
            "conflicts_count": len(conflicts),
            "received_at": datetime.now().isoformat()
        }
    except Exception as e:
        return {"success": False, "message": f"接收失败: {str(e)}"}

