@app.post("/api/quality/sync/conflicts")
async def get_sync_conflicts(request: Request):
    """获取同步冲突"""
    from datetime import datetime
    
    data = await request.json()
    sync_id = data.get("sync_id")
    
    # 模拟冲突检测
    conflicts = []
    
    # 检查历史数据冲突
    if QUALITY_HISTORY:
        # 检测重复时间戳
        timestamps = [h.get("timestamp") for h in QUALITY_HISTORY]
        duplicates = [t for t in timestamps if timestamps.count(t) > 1]
        
        if duplicates:
            conflicts.append({
                "type": "duplicate_timestamp",
                "count": len(set(duplicates)),
                "timestamps": list(set(duplicates))[:10]
            })
    
    return {
        "success": True,
        "sync_id": sync_id,
        "conflicts_count": len(conflicts),
        "conflicts": conflicts,
        "resolution_strategy": QUALITY_SYNC["conflict_resolution"],
        "checked_at": datetime.now().isoformat()
    }

@app.post("/api/quality/sync/resolve")
async def resolve_sync_conflict(request: Request):
    """解决同步冲突"""
    from datetime import datetime
    
    data = await request.json()
    conflict_type = data.get("conflict_type")
    resolution = data.get("resolution")  # keep_local, keep_remote, merge
    
    if not conflict_type or not resolution:
        return {"success": False, "message": "缺少冲突类型或解决方案"}
    
    resolved = False
    
    if conflict_type == "duplicate_timestamp":
        if resolution == "keep_local":
            # 保持本地数据
            resolved = True
        elif resolution == "keep_remote":
            # 保持远程数据（需要重新同步）
            resolved = True
        elif resolution == "merge":
            # 合并数据
            # 去重
            seen = set()
            unique_history = []
            for record in QUALITY_HISTORY:
                ts = record.get("timestamp")
                if ts not in seen:
                    seen.add(ts)
                    unique_history.append(record)
            QUALITY_HISTORY = unique_history
            resolved = True
    
    QUALITY_SYNC["sync_log"].append({
        "action": "resolve_conflict",
        "conflict_type": conflict_type,
        "resolution": resolution,
        "resolved": resolved,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "冲突已解决" if resolved else "冲突解决失败",
        "conflict_type": conflict_type,
        "resolution": resolution,
        "resolved": resolved,
        "resolved_at": datetime.now().isoformat()
    }

