@app.post("/api/quality/backup/strategy/validate")
async def validate_backup_strategy(request: Request):
    """验证备份策略"""
    from datetime import datetime
    import os
    
    data = await request.json()
    strategy_name = data.get("name", "default_strategy")
    
    validation_results = []
    all_valid = True
    
    # 验证备份目录
    backup_dir = QUALITY_BACKUP_STRATEGY["backup_location"]
    if os.path.exists(backup_dir):
        validation_results.append({
            "check": "backup_directory",
            "valid": True,
            "message": f"备份目录存在: {backup_dir}"
        })
    else:
        validation_results.append({
            "check": "backup_directory",
            "valid": False,
            "message": f"备份目录不存在: {backup_dir}"
        })
        all_valid = False
    
    # 验证磁盘空间
    try:
        stat = os.statvfs(backup_dir) if os.path.exists(backup_dir) else None
        if stat:
            free_space = stat.f_bavail * stat.f_frsize
            if free_space > QUALITY_BACKUP_STRATEGY["max_backup_size"]:
                validation_results.append({
                    "check": "disk_space",
                    "valid": True,
                    "message": f"可用空间: {free_space / (1024*1024):.2f}MB"
                })
            else:
                validation_results.append({
                    "check": "disk_space",
                    "valid": False,
                    "message": "磁盘空间不足"
                })
                all_valid = False
    except Exception as e:
        validation_results.append({
            "check": "disk_space",
            "valid": False,
            "message": f"无法检查磁盘空间: {str(e)}"
        })
    
    # 验证保留策略
    retention = QUALITY_BACKUP_STRATEGY["retention_policy"]
    if retention["daily"] > 0 and retention["weekly"] > 0 and retention["monthly"] > 0:
        validation_results.append({
            "check": "retention_policy",
            "valid": True,
            "message": "保留策略配置正确"
        })
    else:
        validation_results.append({
            "check": "retention_policy",
            "valid": False,
            "message": "保留策略配置无效"
        })
        all_valid = False
    
    return {
        "success": True,
        "strategy_name": strategy_name,
        "valid": all_valid,
        "validation_results": validation_results,
        "validated_at": datetime.now().isoformat()
    }

