# 质量评分数据清理配置
QUALITY_CLEANUP = {
    "enabled": True,
    "cleanup_rules": {
        "max_history_age_days": 90,  # 最大历史数据保留天数
        "max_history_records": 10000,  # 最大历史记录数
        "remove_duplicates": True,  # 移除重复记录
        "remove_invalid": True,  # 移除无效记录
        "cleanup_interval": 3600  # 清理间隔（秒）
    },
    "cleanup_log": [],
    "cleanup_count": 0,
    "last_cleanup": None,
    "cleaned_records": 0
}

@app.post("/api/quality/cleanup/execute")
async def execute_cleanup(request: Request):
    """执行数据清理"""
    from datetime import datetime, timedelta
    import json
    
    global QUALITY_HISTORY
    
    data = await request.json()
    cleanup_type = data.get("type", "all")  # all, expired, duplicates, invalid
    dry_run = data.get("dry_run", False)  # 模拟运行
    
    cleanup_id = f"cleanup_{datetime.now().strftime('%Y%m%d%H%M%S')}"
    original_count = len(QUALITY_HISTORY)
    cleaned_count = 0
    cleanup_details = []
    
    # 清理过期数据
    if cleanup_type in ["all", "expired"]:
        max_age_days = QUALITY_CLEANUP["cleanup_rules"]["max_history_age_days"]
        cutoff_date = datetime.now() - timedelta(days=max_age_days)
        
        expired_records = []
        valid_records = []
        
        for record in QUALITY_HISTORY:
            record_time = record.get("timestamp")
            if record_time:
                try:
                    record_date = datetime.fromisoformat(record_time)
                    if record_date < cutoff_date:
                        expired_records.append(record)
                    else:
                        valid_records.append(record)
                except:
                    valid_records.append(record)
            else:
                valid_records.append(record)
        
        if not dry_run:
            QUALITY_HISTORY = valid_records
        
        cleaned_count += len(expired_records)
        cleanup_details.append({
            "type": "expired",
            "removed": len(expired_records),
            "cutoff_date": cutoff_date.isoformat()
        })
    
    # 清理重复数据
    if cleanup_type in ["all", "duplicates"]:
        seen_timestamps = set()
        unique_records = []
        duplicates = []
        
        for record in QUALITY_HISTORY:
            ts = record.get("timestamp")
            if ts:
                if ts not in seen_timestamps:
                    seen_timestamps.add(ts)
                    unique_records.append(record)
                else:
                    duplicates.append(record)
            else:
                unique_records.append(record)
        
        if not dry_run:
            QUALITY_HISTORY = unique_records
        
        cleaned_count += len(duplicates)
        cleanup_details.append({
            "type": "duplicates",
            "removed": len(duplicates)
        })
    
    # 清理无效数据
    if cleanup_type in ["all", "invalid"]:
        valid_records = []
        invalid_records = []
        
        for record in QUALITY_HISTORY:
            # 检查必要字段
            if (record.get("timestamp") and 
                record.get("score") is not None and
                isinstance(record.get("score"), (int, float))):
                valid_records.append(record)
            else:
                invalid_records.append(record)
        
        if not dry_run:
            QUALITY_HISTORY = valid_records
        
        cleaned_count += len(invalid_records)
        cleanup_details.append({
            "type": "invalid",
            "removed": len(invalid_records)
        })
    
    # 限制最大记录数
    max_records = QUALITY_CLEANUP["cleanup_rules"]["max_history_records"]
    if len(QUALITY_HISTORY) > max_records:
        excess = len(QUALITY_HISTORY) - max_records
        if not dry_run:
            QUALITY_HISTORY = QUALITY_HISTORY[-max_records:]
        cleaned_count += excess
        cleanup_details.append({
            "type": "excess",
            "removed": excess,
            "max_records": max_records
        })
    
    QUALITY_CLEANUP["cleanup_count"] += 1
    QUALITY_CLEANUP["last_cleanup"] = datetime.now().isoformat()
    QUALITY_CLEANUP["cleaned_records"] += cleaned_count
    
    QUALITY_CLEANUP["cleanup_log"].append({
        "cleanup_id": cleanup_id,
        "cleanup_type": cleanup_type,
        "dry_run": dry_run,
        "original_count": original_count,
        "cleaned_count": cleaned_count,
        "final_count": len(QUALITY_HISTORY),
        "details": cleanup_details,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "清理模拟完成" if dry_run else "数据清理完成",
        "cleanup_id": cleanup_id,
        "cleanup_type": cleanup_type,
        "dry_run": dry_run,
        "original_count": original_count,
        "cleaned_count": cleaned_count,
        "final_count": len(QUALITY_HISTORY),
        "details": cleanup_details,
        "executed_at": datetime.now().isoformat()
    }

