@app.post("/api/quality/cleanup/preview")
async def preview_cleanup(request: Request):
    """预览清理效果"""
    from datetime import datetime, timedelta
    
    data = await request.json()
    cleanup_type = data.get("type", "all")
    
    preview_result = {
        "expired": 0,
        "duplicates": 0,
        "invalid": 0,
        "excess": 0
    }
    
    # 预览过期数据
    if cleanup_type in ["all", "expired"]:
        max_age_days = QUALITY_CLEANUP["cleanup_rules"]["max_history_age_days"]
        cutoff_date = datetime.now() - timedelta(days=max_age_days)
        
        for record in QUALITY_HISTORY:
            record_time = record.get("timestamp")
            if record_time:
                try:
                    record_date = datetime.fromisoformat(record_time)
                    if record_date < cutoff_date:
                        preview_result["expired"] += 1
                except:
                    pass
    
    # 预览重复数据
    if cleanup_type in ["all", "duplicates"]:
        timestamps = [r.get("timestamp") for r in QUALITY_HISTORY if r.get("timestamp")]
        preview_result["duplicates"] = len(timestamps) - len(set(timestamps))
    
    # 预览无效数据
    if cleanup_type in ["all", "invalid"]:
        for record in QUALITY_HISTORY:
            if not (record.get("timestamp") and 
                    record.get("score") is not None and
                    isinstance(record.get("score"), (int, float))):
                preview_result["invalid"] += 1
    
    # 预览超量数据
    max_records = QUALITY_CLEANUP["cleanup_rules"]["max_history_records"]
    if len(QUALITY_HISTORY) > max_records:
        preview_result["excess"] = len(QUALITY_HISTORY) - max_records
    
    total_to_clean = sum(preview_result.values())
    
    return {
        "success": True,
        "cleanup_type": cleanup_type,
        "current_records": len(QUALITY_HISTORY),
        "preview": preview_result,
        "total_to_clean": total_to_clean,
        "estimated_remaining": len(QUALITY_HISTORY) - total_to_clean,
        "previewed_at": datetime.now().isoformat()
    }

