@app.post("/api/quality/cleanup/rollback")
async def rollback_cleanup(request: Request):
    """回滚清理操作"""
    from datetime import datetime
    
    data = await request.json()
    cleanup_id = data.get("cleanup_id")
    
    if not cleanup_id:
        return {"success": False, "message": "缺少清理ID"}
    
    # 查找清理记录
    cleanup_record = None
    for log in QUALITY_CLEANUP["cleanup_log"]:
        if log.get("cleanup_id") == cleanup_id:
            cleanup_record = log
            break
    
    if not cleanup_record:
        return {"success": False, "message": "未找到清理记录"}
    
    # 注意：实际回滚需要从备份恢复
    QUALITY_CLEANUP["cleanup_log"].append({
        "action": "rollback",
        "cleanup_id": cleanup_id,
        "status": "requested",
        "note": "需要从备份恢复数据",
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "回滚请求已记录，请从备份恢复数据",
        "cleanup_id": cleanup_id,
        "cleanup_record": cleanup_record,
        "requested_at": datetime.now().isoformat()
    }

