@app.post("/api/quality/index/build")
async def build_quality_index(request: Request):
    """构建质量数据索引"""
    from datetime import datetime
    
    data = await request.json()
    index_type = data.get("type", "all")  # all, timestamp, score, type, session
    rebuild = data.get("rebuild", False)
    
    index_id = f"index_{datetime.now().strftime('%Y%m%d%H%M%S')}"
    indexed_count = 0
    
    # 时间戳索引
    if index_type in ["all", "timestamp"]:
        QUALITY_INDEX["indexes"]["timestamp_index"] = {}
        for record in QUALITY_HISTORY:
            ts = record.get("timestamp")
            if ts:
                if ts not in QUALITY_INDEX["indexes"]["timestamp_index"]:
                    QUALITY_INDEX["indexes"]["timestamp_index"][ts] = []
                QUALITY_INDEX["indexes"]["timestamp_index"][ts].append(record)
        indexed_count += len(QUALITY_INDEX["indexes"]["timestamp_index"])
    
    # 分数索引
    if index_type in ["all", "score"]:
        QUALITY_INDEX["indexes"]["score_index"] = {}
        for record in QUALITY_HISTORY:
            score = record.get("score")
            if score is not None:
                score_key = f"score_{int(score)}"
                if score_key not in QUALITY_INDEX["indexes"]["score_index"]:
                    QUALITY_INDEX["indexes"]["score_index"][score_key] = []
                QUALITY_INDEX["indexes"]["score_index"][score_key].append(record)
        indexed_count += len(QUALITY_INDEX["indexes"]["score_index"])
    
    # 问题类型索引
    if index_type in ["all", "type"]:
        QUALITY_INDEX["indexes"]["type_index"] = {}
        for record in QUALITY_HISTORY:
            q_type = record.get("question_type", "unknown")
            if q_type not in QUALITY_INDEX["indexes"]["type_index"]:
                QUALITY_INDEX["indexes"]["type_index"][q_type] = []
            QUALITY_INDEX["indexes"]["type_index"][q_type].append(record)
        indexed_count += len(QUALITY_INDEX["indexes"]["type_index"])
    
    # 会话索引
    if index_type in ["all", "session"]:
        QUALITY_INDEX["indexes"]["session_index"] = {}
        for record in QUALITY_HISTORY:
            session_id = record.get("session_id", "unknown")
            if session_id not in QUALITY_INDEX["indexes"]["session_index"]:
                QUALITY_INDEX["indexes"]["session_index"][session_id] = []
            QUALITY_INDEX["indexes"]["session_index"][session_id].append(record)
        indexed_count += len(QUALITY_INDEX["indexes"]["session_index"])
    
    QUALITY_INDEX["index_stats"]["total_indexed"] = indexed_count
    QUALITY_INDEX["index_stats"]["last_rebuild"] = datetime.now().isoformat()
    
    QUALITY_INDEX["index_log"].append({
        "action": "build_index",
        "index_id": index_id,
        "index_type": index_type,
        "rebuild": rebuild,
        "indexed_count": indexed_count,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "索引构建完成",
        "index_id": index_id,
        "index_type": index_type,
        "indexed_count": indexed_count,
        "total_records": len(QUALITY_HISTORY),
        "built_at": datetime.now().isoformat()
    }

