@app.post("/api/quality/index/range")
async def query_index_range(request: Request):
    """范围查询索引"""
    from datetime import datetime
    
    data = await request.json()
    index_type = data.get("index_type", "score")  # score, timestamp
    start = data.get("start")
    end = data.get("end")
    limit = data.get("limit", 100)
    
    results = []
    
    if index_type == "score":
        start_score = int(float(start)) if start else 0
        end_score = int(float(end)) if end else 100
        
        for score in range(start_score, end_score + 1):
            score_key = f"score_{score}"
            if score_key in QUALITY_INDEX["indexes"]["score_index"]:
                results.extend(QUALITY_INDEX["indexes"]["score_index"][score_key])
    
    elif index_type == "timestamp":
        # 时间范围查询
        for ts, records in QUALITY_INDEX["indexes"]["timestamp_index"].items():
            if start and end:
                if start <= ts <= end:
                    results.extend(records)
            elif start:
                if ts >= start:
                    results.extend(records)
            elif end:
                if ts <= end:
                    results.extend(records)
            else:
                results.extend(records)
    
    return {
        "success": True,
        "index_type": index_type,
        "range": {"start": start, "end": end},
        "total_results": len(results),
        "results": results[:limit],
        "queried_at": datetime.now().isoformat()
    }

@app.post("/api/quality/index/update")
async def update_quality_index(request: Request):
    """更新索引（添加新记录）"""
    from datetime import datetime
    
    data = await request.json()
    record = data.get("record")
    
    if not record:
        return {"success": False, "message": "缺少记录数据"}
    
    # 添加到时间戳索引
    ts = record.get("timestamp")
    if ts:
        if ts not in QUALITY_INDEX["indexes"]["timestamp_index"]:
            QUALITY_INDEX["indexes"]["timestamp_index"][ts] = []
        QUALITY_INDEX["indexes"]["timestamp_index"][ts].append(record)
    
    # 添加到分数索引
    score = record.get("score")
    if score is not None:
        score_key = f"score_{int(score)}"
        if score_key not in QUALITY_INDEX["indexes"]["score_index"]:
            QUALITY_INDEX["indexes"]["score_index"][score_key] = []
        QUALITY_INDEX["indexes"]["score_index"][score_key].append(record)
    
    # 添加到类型索引
    q_type = record.get("question_type", "unknown")
    if q_type not in QUALITY_INDEX["indexes"]["type_index"]:
        QUALITY_INDEX["indexes"]["type_index"][q_type] = []
    QUALITY_INDEX["indexes"]["type_index"][q_type].append(record)
    
    # 添加到会话索引
    session_id = record.get("session_id", "unknown")
    if session_id not in QUALITY_INDEX["indexes"]["session_index"]:
        QUALITY_INDEX["indexes"]["session_index"][session_id] = []
    QUALITY_INDEX["indexes"]["session_index"][session_id].append(record)
    
    QUALITY_INDEX["index_stats"]["total_indexed"] += 1
    
    return {
        "success": True,
        "message": "索引已更新",
        "updated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/index/delete")
async def delete_from_index(request: Request):
    """从索引中删除记录"""
    from datetime import datetime
    
    data = await request.json()
    timestamp = data.get("timestamp")
    
    if not timestamp:
        return {"success": False, "message": "缺少时间戳"}
    
    deleted_count = 0
    
    # 从时间戳索引删除
    if timestamp in QUALITY_INDEX["indexes"]["timestamp_index"]:
        records = QUALITY_INDEX["indexes"]["timestamp_index"][timestamp]
        deleted_count = len(records)
        del QUALITY_INDEX["indexes"]["timestamp_index"][timestamp]
        
        # 从其他索引中删除对应记录
        for record in records:
            score = record.get("score")
            if score is not None:
                score_key = f"score_{int(score)}"
                if score_key in QUALITY_INDEX["indexes"]["score_index"]:
                    QUALITY_INDEX["indexes"]["score_index"][score_key] = [
                        r for r in QUALITY_INDEX["indexes"]["score_index"][score_key]
                        if r.get("timestamp") != timestamp
                    ]
            
            q_type = record.get("question_type", "unknown")
            if q_type in QUALITY_INDEX["indexes"]["type_index"]:
                QUALITY_INDEX["indexes"]["type_index"][q_type] = [
                    r for r in QUALITY_INDEX["indexes"]["type_index"][q_type]
                    if r.get("timestamp") != timestamp
                ]
            
            session_id = record.get("session_id", "unknown")
            if session_id in QUALITY_INDEX["indexes"]["session_index"]:
                QUALITY_INDEX["indexes"]["session_index"][session_id] = [
                    r for r in QUALITY_INDEX["indexes"]["session_index"][session_id]
                    if r.get("timestamp") != timestamp
                ]
    
    QUALITY_INDEX["index_stats"]["total_indexed"] -= deleted_count
    
    return {
        "success": True,
        "message": "记录已从索引中删除",
        "deleted_count": deleted_count,
        "deleted_at": datetime.now().isoformat()
    }

