@app.post("/api/quality/partition/build")
async def build_quality_partition(request: Request):
    """构建数据分区"""
    from datetime import datetime
    
    data = await request.json()
    strategy = data.get("strategy", "time")  # time, score, type, session
    
    partition_id = f"partition_{datetime.now().strftime('%Y%m%d%H%M%S')}"
    partition_count = 0
    
    # 按时间分区
    if strategy in ["all", "time"]:
        QUALITY_PARTITION["partitions"]["by_time"] = {}
        granularity = QUALITY_PARTITION["partition_config"]["time_granularity"]
        
        for record in QUALITY_HISTORY:
            ts = record.get("timestamp")
            if ts:
                try:
                    dt = datetime.fromisoformat(ts)
                    if granularity == "hour":
                        key = dt.strftime("%Y%m%d%H")
                    elif granularity == "day":
                        key = dt.strftime("%Y%m%d")
                    elif granularity == "week":
                        key = dt.strftime("%Y%W")
                    elif granularity == "month":
                        key = dt.strftime("%Y%m")
                    else:
                        key = dt.strftime("%Y%m%d")
                    
                    if key not in QUALITY_PARTITION["partitions"]["by_time"]:
                        QUALITY_PARTITION["partitions"]["by_time"][key] = []
                    QUALITY_PARTITION["partitions"]["by_time"][key].append(record)
                except:
                    pass
        
        partition_count += len(QUALITY_PARTITION["partitions"]["by_time"])
    
    # 按分数分区
    if strategy in ["all", "score"]:
        QUALITY_PARTITION["partitions"]["by_score"] = {}
        score_ranges = QUALITY_PARTITION["partition_config"]["score_ranges"]
        
        for record in QUALITY_HISTORY:
            score = record.get("score")
            if score is not None:
                for low, high in score_ranges:
                    if low <= score < high:
                        key = f"score_{low}_{high}"
                        if key not in QUALITY_PARTITION["partitions"]["by_score"]:
                            QUALITY_PARTITION["partitions"]["by_score"][key] = []
                        QUALITY_PARTITION["partitions"]["by_score"][key].append(record)
                        break
        
        partition_count += len(QUALITY_PARTITION["partitions"]["by_score"])
    
    # 按类型分区
    if strategy in ["all", "type"]:
        QUALITY_PARTITION["partitions"]["by_type"] = {}
        
        for record in QUALITY_HISTORY:
            q_type = record.get("question_type", "unknown")
            if q_type not in QUALITY_PARTITION["partitions"]["by_type"]:
                QUALITY_PARTITION["partitions"]["by_type"][q_type] = []
            QUALITY_PARTITION["partitions"]["by_type"][q_type].append(record)
        
        partition_count += len(QUALITY_PARTITION["partitions"]["by_type"])
    
    # 按会话分区
    if strategy in ["all", "session"]:
        QUALITY_PARTITION["partitions"]["by_session"] = {}
        
        for record in QUALITY_HISTORY:
            session_id = record.get("session_id", "unknown")
            if session_id not in QUALITY_PARTITION["partitions"]["by_session"]:
                QUALITY_PARTITION["partitions"]["by_session"][session_id] = []
            QUALITY_PARTITION["partitions"]["by_session"][session_id].append(record)
        
        partition_count += len(QUALITY_PARTITION["partitions"]["by_session"])
    
    QUALITY_PARTITION["partition_stats"]["total_partitions"] = partition_count
    QUALITY_PARTITION["partition_stats"]["total_records"] = len(QUALITY_HISTORY)
    QUALITY_PARTITION["partition_stats"]["last_rebuild"] = datetime.now().isoformat()
    
    QUALITY_PARTITION["partition_log"].append({
        "action": "build_partition",
        "partition_id": partition_id,
        "strategy": strategy,
        "partition_count": partition_count,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "分区构建完成",
        "partition_id": partition_id,
        "strategy": strategy,
        "partition_count": partition_count,
        "total_records": len(QUALITY_HISTORY),
        "built_at": datetime.now().isoformat()
    }

