@app.post("/api/quality/partition/merge")
async def merge_partitions(request: Request):
    """合并分区"""
    from datetime import datetime
    
    data = await request.json()
    partition_type = data.get("partition_type", "time")
    source_keys = data.get("source_keys", [])
    target_key = data.get("target_key")
    
    if not source_keys or not target_key:
        return {"success": False, "message": "缺少源分区键或目标分区键"}
    
    merged_records = []
    partition_map = {
        "time": "by_time",
        "score": "by_score",
        "type": "by_type",
        "session": "by_session"
    }
    
    partition_key = partition_map.get(partition_type, "by_time")
    
    for src_key in source_keys:
        if src_key in QUALITY_PARTITION["partitions"][partition_key]:
            merged_records.extend(QUALITY_PARTITION["partitions"][partition_key][src_key])
            del QUALITY_PARTITION["partitions"][partition_key][src_key]
    
    if target_key not in QUALITY_PARTITION["partitions"][partition_key]:
        QUALITY_PARTITION["partitions"][partition_key][target_key] = []
    
    QUALITY_PARTITION["partitions"][partition_key][target_key].extend(merged_records)
    
    QUALITY_PARTITION["partition_log"].append({
        "action": "merge_partitions",
        "partition_type": partition_type,
        "source_keys": source_keys,
        "target_key": target_key,
        "merged_count": len(merged_records),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "分区合并完成",
        "partition_type": partition_type,
        "source_keys": source_keys,
        "target_key": target_key,
        "merged_count": len(merged_records),
        "merged_at": datetime.now().isoformat()
    }

@app.post("/api/quality/partition/split")
async def split_partition(request: Request):
    """拆分分区"""
    from datetime import datetime
    
    data = await request.json()
    partition_type = data.get("partition_type", "time")
    source_key = data.get("source_key")
    split_criteria = data.get("split_criteria", {})  # 拆分条件
    
    if not source_key:
        return {"success": False, "message": "缺少源分区键"}
    
    partition_map = {
        "time": "by_time",
        "score": "by_score",
        "type": "by_type",
        "session": "by_session"
    }
    
    partition_key = partition_map.get(partition_type, "by_time")
    
    if source_key not in QUALITY_PARTITION["partitions"][partition_key]:
        return {"success": False, "message": "源分区不存在"}
    
    source_records = QUALITY_PARTITION["partitions"][partition_key][source_key]
    split_count = split_criteria.get("count", 2)  # 拆分成几个分区
    
    # 简单拆分：按记录数量均分
    chunk_size = len(source_records) // split_count
    new_partitions = {}
    
    for i in range(split_count):
        new_key = f"{source_key}_part{i+1}"
        start_idx = i * chunk_size
        end_idx = start_idx + chunk_size if i < split_count - 1 else len(source_records)
        new_partitions[new_key] = source_records[start_idx:end_idx]
    
    # 删除原分区，添加新分区
    del QUALITY_PARTITION["partitions"][partition_key][source_key]
    for new_key, records in new_partitions.items():
        QUALITY_PARTITION["partitions"][partition_key][new_key] = records
    
    QUALITY_PARTITION["partition_log"].append({
        "action": "split_partition",
        "partition_type": partition_type,
        "source_key": source_key,
        "split_count": split_count,
        "new_partitions": list(new_partitions.keys()),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "分区拆分完成",
        "partition_type": partition_type,
        "source_key": source_key,
        "split_count": split_count,
        "new_partitions": list(new_partitions.keys()),
        "split_at": datetime.now().isoformat()
    }

@app.get("/api/quality/partition/log")
async def get_partition_log(limit: int = 100):
    """获取分区日志"""
    logs = QUALITY_PARTITION["partition_log"][-limit:]
    
    return {
        "success": True,
        "total_logs": len(QUALITY_PARTITION["partition_log"]),
        "logs": logs
    }

@app.post("/api/quality/partition/validate")
async def validate_partition(request: Request):
    """验证分区完整性"""
    from datetime import datetime
    
    data = await request.json()
    partition_type = data.get("partition_type", "all")
    
    validation_results = {
        "valid": True,
        "errors": [],
        "warnings": []
    }
    
    total_partitioned = 0
    
    # 验证时间分区
    if partition_type in ["all", "time"]:
        for key, records in QUALITY_PARTITION["partitions"]["by_time"].items():
            total_partitioned += len(records)
            if len(records) > QUALITY_PARTITION["partition_config"]["max_partition_size"]:
                validation_results["warnings"].append(f"时间分区 {key} 超过最大大小限制")
    
    # 验证分数分区
    if partition_type in ["all", "score"]:
        for key, records in QUALITY_PARTITION["partitions"]["by_score"].items():
            total_partitioned += len(records)
    
    # 验证类型分区
    if partition_type in ["all", "type"]:
        for key, records in QUALITY_PARTITION["partitions"]["by_type"].items():
            total_partitioned += len(records)
    
    # 验证会话分区
    if partition_type in ["all", "session"]:
        for key, records in QUALITY_PARTITION["partitions"]["by_session"].items():
            total_partitioned += len(records)
    
    # 检查记录完整性
    if total_partitioned != len(QUALITY_HISTORY) * (4 if partition_type == "all" else 1):
        validation_results["warnings"].append("分区记录数与总记录数不一致")
    
    if validation_results["errors"]:
        validation_results["valid"] = False
    
    return {
        "success": True,
        "validation": validation_results,
        "total_partitioned": total_partitioned,
        "total_records": len(QUALITY_HISTORY),
        "validated_at": datetime.now().isoformat()
    }

# 质量评分数据压缩配置
QUALITY_COMPRESSION = {
    "enabled": True,
    "algorithm": "gzip",  # gzip, zlib, lzma, bz2
    "level": 6,  # 压缩级别 1-9
    "compressed_data": {},
    "compression_stats": {
        "total_compressed": 0,
        "total_original_size": 0,
        "total_compressed_size": 0,
        "compression_ratio": 0,
        "last_compression": None
    },
    "compression_log": []
}

@app.post("/api/quality/compression/compress")
async def compress_quality_data(request: Request):
    """压缩质量数据"""
    from datetime import datetime
    import gzip
    import json
    
    data = await request.json()
    records = data.get("records", QUALITY_HISTORY)
    algorithm = data.get("algorithm", QUALITY_COMPRESSION["algorithm"])
    level = data.get("level", QUALITY_COMPRESSION["level"])
    
    compression_id = f"compression_{datetime.now().strftime('%Y%m%d%H%M%S')}"
    
    # 序列化数据
    json_data = json.dumps(records, ensure_ascii=False)
    original_size = len(json_data.encode('utf-8'))
    
    # 压缩数据
    compressed_data = gzip.compress(json_data.encode('utf-8'), compresslevel=level)
    compressed_size = len(compressed_data)
    
    # 存储压缩数据
    QUALITY_COMPRESSION["compressed_data"][compression_id] = {
        "data": compressed_data,
        "original_size": original_size,
        "compressed_size": compressed_size,
        "algorithm": algorithm,
        "level": level,
        "record_count": len(records),
        "created_at": datetime.now().isoformat()
    }
    
    # 更新统计
    QUALITY_COMPRESSION["compression_stats"]["total_compressed"] += 1
    QUALITY_COMPRESSION["compression_stats"]["total_original_size"] += original_size
    QUALITY_COMPRESSION["compression_stats"]["total_compressed_size"] += compressed_size
    if QUALITY_COMPRESSION["compression_stats"]["total_original_size"] > 0:
        QUALITY_COMPRESSION["compression_stats"]["compression_ratio"] = (
            1 - QUALITY_COMPRESSION["compression_stats"]["total_compressed_size"] / 
            QUALITY_COMPRESSION["compression_stats"]["total_original_size"]
        ) * 100
    QUALITY_COMPRESSION["compression_stats"]["last_compression"] = datetime.now().isoformat()
    
    QUALITY_COMPRESSION["compression_log"].append({
        "action": "compress",
        "compression_id": compression_id,
        "algorithm": algorithm,
        "level": level,
        "original_size": original_size,
        "compressed_size": compressed_size,
        "compression_ratio": (1 - compressed_size / original_size) * 100 if original_size > 0 else 0,
        "record_count": len(records),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "数据压缩完成",
        "compression_id": compression_id,
        "algorithm": algorithm,
        "level": level,
        "original_size": original_size,
        "compressed_size": compressed_size,
        "compression_ratio": (1 - compressed_size / original_size) * 100 if original_size > 0 else 0,
        "record_count": len(records),
        "compressed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/compression/decompress")
async def decompress_quality_data(request: Request):
    """解压质量数据"""
    from datetime import datetime
    import gzip
    import json
    
    data = await request.json()
    compression_id = data.get("compression_id")
    
    if not compression_id or compression_id not in QUALITY_COMPRESSION["compressed_data"]:
        return {"success": False, "message": "压缩数据不存在"}
    
    compressed_record = QUALITY_COMPRESSION["compressed_data"][compression_id]
    
    # 解压数据
    decompressed_data = gzip.decompress(compressed_record["data"])
    json_data = decompressed_data.decode('utf-8')
    records = json.loads(json_data)
    
    QUALITY_COMPRESSION["compression_log"].append({
        "action": "decompress",
        "compression_id": compression_id,
        "record_count": len(records),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "数据解压完成",
        "compression_id": compression_id,
        "record_count": len(records),
        "records": records[:100],  # 限制返回数量
        "decompressed_at": datetime.now().isoformat()
    }

