@app.post("/api/quality/compression/delete")
async def delete_compressed_data(request: Request):
    """删除压缩数据"""
    from datetime import datetime
    
    data = await request.json()
    compression_id = data.get("compression_id")
    
    if not compression_id:
        return {"success": False, "message": "缺少压缩ID"}
    
    if compression_id not in QUALITY_COMPRESSION["compressed_data"]:
        return {"success": False, "message": "压缩数据不存在"}
    
    deleted_record = QUALITY_COMPRESSION["compressed_data"][compression_id]
    del QUALITY_COMPRESSION["compressed_data"][compression_id]
    
    # 更新统计
    QUALITY_COMPRESSION["compression_stats"]["total_compressed"] -= 1
    QUALITY_COMPRESSION["compression_stats"]["total_original_size"] -= deleted_record["original_size"]
    QUALITY_COMPRESSION["compression_stats"]["total_compressed_size"] -= deleted_record["compressed_size"]
    
    QUALITY_COMPRESSION["compression_log"].append({
        "action": "delete",
        "compression_id": compression_id,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "压缩数据已删除",
        "compression_id": compression_id,
        "deleted_at": datetime.now().isoformat()
    }

