@app.post("/api/quality/compression/compare")
async def compare_compression_algorithms(request: Request):
    """比较不同压缩算法"""
    from datetime import datetime
    import gzip
    import zlib
    import json
    
    data = await request.json()
    records = data.get("records", QUALITY_HISTORY[:100])  # 限制比较数据量
    
    json_data = json.dumps(records, ensure_ascii=False)
    original_size = len(json_data.encode('utf-8'))
    
    results = []
    
    # 测试 gzip 不同级别
    for level in [1, 6, 9]:
        compressed = gzip.compress(json_data.encode('utf-8'), compresslevel=level)
        results.append({
            "algorithm": "gzip",
            "level": level,
            "original_size": original_size,
            "compressed_size": len(compressed),
            "compression_ratio": (1 - len(compressed) / original_size) * 100 if original_size > 0 else 0
        })
    
    # 测试 zlib 不同级别
    for level in [1, 6, 9]:
        compressed = zlib.compress(json_data.encode('utf-8'), level)
        results.append({
            "algorithm": "zlib",
            "level": level,
            "original_size": original_size,
            "compressed_size": len(compressed),
            "compression_ratio": (1 - len(compressed) / original_size) * 100 if original_size > 0 else 0
        })
    
    return {
        "success": True,
        "message": "压缩算法比较完成",
        "original_size": original_size,
        "record_count": len(records),
        "results": results,
        "compared_at": datetime.now().isoformat()
    }

@app.post("/api/quality/compression/batch")
async def batch_compress_quality_data(request: Request):
    """批量压缩数据"""
    from datetime import datetime
    
    data = await request.json()
    batch_size = data.get("batch_size", 100)
    
    if len(QUALITY_HISTORY) == 0:
        return {"success": False, "message": "没有数据可压缩"}
    
    compression_results = []
    total_batches = (len(QUALITY_HISTORY) + batch_size - 1) // batch_size
    
    for i in range(total_batches):
        start_idx = i * batch_size
        end_idx = min(start_idx + batch_size, len(QUALITY_HISTORY))
        batch_records = QUALITY_HISTORY[start_idx:end_idx]
        
        # 调用压缩逻辑
        import gzip
        import json
        
        compression_id = f"batch_{datetime.now().strftime('%Y%m%d%H%M%S')}_{i}"
        json_data = json.dumps(batch_records, ensure_ascii=False)
        original_size = len(json_data.encode('utf-8'))
        compressed_data = gzip.compress(json_data.encode('utf-8'), compresslevel=QUALITY_COMPRESSION["level"])
        compressed_size = len(compressed_data)
        
        QUALITY_COMPRESSION["compressed_data"][compression_id] = {
            "data": compressed_data,
            "original_size": original_size,
            "compressed_size": compressed_size,
            "algorithm": QUALITY_COMPRESSION["algorithm"],
            "level": QUALITY_COMPRESSION["level"],
            "record_count": len(batch_records),
            "created_at": datetime.now().isoformat()
        }
        
        compression_results.append({
            "compression_id": compression_id,
            "batch_index": i,
            "record_count": len(batch_records),
            "original_size": original_size,
            "compressed_size": compressed_size,
            "compression_ratio": (1 - compressed_size / original_size) * 100 if original_size > 0 else 0
        })
    
    # 更新统计
    QUALITY_COMPRESSION["compression_stats"]["total_compressed"] += total_batches
    QUALITY_COMPRESSION["compression_stats"]["last_compression"] = datetime.now().isoformat()
    
    return {
        "success": True,
        "message": "批量压缩完成",
        "total_batches": total_batches,
        "batch_size": batch_size,
        "total_records": len(QUALITY_HISTORY),
        "results": compression_results,
        "compressed_at": datetime.now().isoformat()
    }

# 质量评分数据缓存配置
QUALITY_CACHE = {
    "enabled": True,
    "max_size": 1000,  # 最大缓存条目数
    "ttl": 3600,  # 缓存过期时间（秒）
    "cache": {},  # 缓存数据
    "cache_stats": {
        "total_hits": 0,
        "total_misses": 0,
        "total_sets": 0,
        "total_evictions": 0,
        "hit_rate": 0,
        "last_clear": None
    },
    "cache_log": []
}

@app.post("/api/quality/cache/set")
async def set_quality_cache(request: Request):
    """设置缓存"""
    from datetime import datetime
    
    data = await request.json()
    key = data.get("key")
    value = data.get("value")
    ttl = data.get("ttl", QUALITY_CACHE["ttl"])
    
    if not key:
        return {"success": False, "message": "缺少缓存键"}
    
    # 检查缓存大小限制
    if len(QUALITY_CACHE["cache"]) >= QUALITY_CACHE["max_size"]:
        # LRU淘汰：移除最早添加的缓存
        oldest_key = next(iter(QUALITY_CACHE["cache"]))
        del QUALITY_CACHE["cache"][oldest_key]
        QUALITY_CACHE["cache_stats"]["total_evictions"] += 1
    
    # 设置缓存
    QUALITY_CACHE["cache"][key] = {
        "value": value,
        "created_at": datetime.now().isoformat(),
        "expires_at": datetime.now().timestamp() + ttl if ttl > 0 else None,
        "ttl": ttl,
        "hits": 0
    }
    
    QUALITY_CACHE["cache_stats"]["total_sets"] += 1
    
    QUALITY_CACHE["cache_log"].append({
        "action": "set",
        "key": key,
        "ttl": ttl,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "缓存已设置",
        "key": key,
        "ttl": ttl,
        "cache_size": len(QUALITY_CACHE["cache"]),
        "set_at": datetime.now().isoformat()
    }

@app.get("/api/quality/cache/get/{key}")
async def get_quality_cache(key: str):
    """获取缓存"""
    from datetime import datetime
    
    if key not in QUALITY_CACHE["cache"]:
        QUALITY_CACHE["cache_stats"]["total_misses"] += 1
        return {"success": False, "message": "缓存不存在", "key": key}
    
    cached_item = QUALITY_CACHE["cache"][key]
    
    # 检查过期
    if cached_item["expires_at"] and datetime.now().timestamp() > cached_item["expires_at"]:
        del QUALITY_CACHE["cache"][key]
        QUALITY_CACHE["cache_stats"]["total_misses"] += 1
        return {"success": False, "message": "缓存已过期", "key": key}
    
    # 更新命中统计
    cached_item["hits"] += 1
    QUALITY_CACHE["cache_stats"]["total_hits"] += 1
    
    # 更新命中率
    total_requests = QUALITY_CACHE["cache_stats"]["total_hits"] + QUALITY_CACHE["cache_stats"]["total_misses"]
    if total_requests > 0:
        QUALITY_CACHE["cache_stats"]["hit_rate"] = (
            QUALITY_CACHE["cache_stats"]["total_hits"] / total_requests
        ) * 100
    
    return {
        "success": True,
        "key": key,
        "value": cached_item["value"],
        "created_at": cached_item["created_at"],
        "ttl": cached_item["ttl"],
        "hits": cached_item["hits"],
        "retrieved_at": datetime.now().isoformat()
    }

@app.delete("/api/quality/cache/delete/{key}")
async def delete_quality_cache(key: str):
    """删除缓存"""
    from datetime import datetime
    
