@app.post("/api/quality/cache/batch")
async def batch_set_cache(request: Request):
    """批量设置缓存"""
    from datetime import datetime
    
    data = await request.json()
    items = data.get("items", [])
    ttl = data.get("ttl", QUALITY_CACHE["ttl"])
    
    if not items:
        return {"success": False, "message": "缺少缓存数据"}
    
    set_count = 0
    eviction_count = 0
    
    for item in items:
        key = item.get("key")
        value = item.get("value")
        
        if not key:
            continue
        
        # 检查缓存大小限制
        if len(QUALITY_CACHE["cache"]) >= QUALITY_CACHE["max_size"]:
            oldest_key = next(iter(QUALITY_CACHE["cache"]))
            del QUALITY_CACHE["cache"][oldest_key]
            eviction_count += 1
        
        QUALITY_CACHE["cache"][key] = {
            "value": value,
            "created_at": datetime.now().isoformat(),
            "expires_at": datetime.now().timestamp() + ttl if ttl > 0 else None,
            "ttl": ttl,
            "hits": 0
        }
        
        set_count += 1
    
    QUALITY_CACHE["cache_stats"]["total_sets"] += set_count
    QUALITY_CACHE["cache_stats"]["total_evictions"] += eviction_count
    
    return {
        "success": True,
        "message": "批量缓存设置完成",
        "set_count": set_count,
        "eviction_count": eviction_count,
        "cache_size": len(QUALITY_CACHE["cache"]),
        "set_at": datetime.now().isoformat()
    }

@app.post("/api/quality/cache/refresh")
async def refresh_cache_ttl(request: Request):
    """刷新缓存TTL"""
    from datetime import datetime
    
    data = await request.json()
    key = data.get("key")
    ttl = data.get("ttl", QUALITY_CACHE["ttl"])
    
    if not key:
        return {"success": False, "message": "缺少缓存键"}
    
    if key not in QUALITY_CACHE["cache"]:
        return {"success": False, "message": "缓存不存在", "key": key}
    
    QUALITY_CACHE["cache"][key]["expires_at"] = datetime.now().timestamp() + ttl if ttl > 0 else None
    QUALITY_CACHE["cache"][key]["ttl"] = ttl
    
    return {
        "success": True,
        "message": "缓存TTL已刷新",
        "key": key,
        "new_ttl": ttl,
        "refreshed_at": datetime.now().isoformat()
    }

