# 质量评分数据去重配置
QUALITY_DEDUP = {
    "enabled": True,
    "strategy": "hash",  # hash, exact, fuzzy
    "dedup_records": {},  # 去重记录
    "hash_index": {},  # 哈希索引
    "dedup_stats": {
        "total_checked": 0,
        "total_duplicates": 0,
        "total_unique": 0,
        "last_dedup": None
    },
    "dedup_log": []
}

def _compute_record_hash(record: dict) -> str:
    """计算记录哈希"""
    import hashlib
    import json
    
    # 提取关键字段计算哈希
    key_fields = ["question", "answer", "score", "question_type"]
    hash_data = {k: record.get(k, "") for k in key_fields}
    hash_str = json.dumps(hash_data, sort_keys=True, ensure_ascii=False)
    return hashlib.md5(hash_str.encode('utf-8')).hexdigest()

@app.post("/api/quality/dedup/check")
async def check_duplicate_record(request: Request):
    """检查重复记录"""
    from datetime import datetime
    
    data = await request.json()
    record = data.get("record")
    strategy = data.get("strategy", QUALITY_DEDUP["strategy"])
    
    if not record:
        return {"success": False, "message": "缺少记录数据"}
    
    QUALITY_DEDUP["dedup_stats"]["total_checked"] += 1
    
    # 计算哈希
    record_hash = _compute_record_hash(record)
    
    # 检查重复
    is_duplicate = False
    duplicate_of = None
    
    if strategy == "hash":
        if record_hash in QUALITY_DEDUP["hash_index"]:
            is_duplicate = True
            duplicate_of = QUALITY_DEDUP["hash_index"][record_hash]
    
    elif strategy == "exact":
        # 精确匹配检查
        for existing_id, existing_record in QUALITY_DEDUP["dedup_records"].items():
            if existing_record.get("question") == record.get("question") and \
               existing_record.get("answer") == record.get("answer"):
                is_duplicate = True
                duplicate_of = existing_id
                break
    
    if is_duplicate:
        QUALITY_DEDUP["dedup_stats"]["total_duplicates"] += 1
    else:
        QUALITY_DEDUP["dedup_stats"]["total_unique"] += 1
    
    return {
        "success": True,
        "is_duplicate": is_duplicate,
        "record_hash": record_hash,
        "duplicate_of": duplicate_of,
        "strategy": strategy,
        "checked_at": datetime.now().isoformat()
    }

@app.post("/api/quality/dedup/run")
async def run_dedup_process(request: Request):
    """执行去重处理"""
    from datetime import datetime
    
    data = await request.json()
    records = data.get("records", QUALITY_HISTORY)
    strategy = data.get("strategy", QUALITY_DEDUP["strategy"])
    
    unique_records = []
    duplicate_records = []
    processed_hashes = set()
    
    for record in records:
        record_hash = _compute_record_hash(record)
        
        if record_hash in processed_hashes:
            duplicate_records.append(record)
            QUALITY_DEDUP["dedup_stats"]["total_duplicates"] += 1
        else:
            processed_hashes.add(record_hash)
            unique_records.append(record)
            QUALITY_DEDUP["dedup_stats"]["total_unique"] += 1
            QUALITY_DEDUP["hash_index"][record_hash] = record.get("id", record_hash[:8])
        
        QUALITY_DEDUP["dedup_stats"]["total_checked"] += 1
    
    QUALITY_DEDUP["dedup_stats"]["last_dedup"] = datetime.now().isoformat()
    
    QUALITY_DEDUP["dedup_log"].append({
        "action": "run_dedup",
        "strategy": strategy,
        "total_records": len(records),
        "unique_count": len(unique_records),
        "duplicate_count": len(duplicate_records),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "去重处理完成",
        "total_records": len(records),
        "unique_count": len(unique_records),
        "duplicate_count": len(duplicate_records),
        "dedup_rate": (len(duplicate_records) / len(records) * 100) if records else 0,
        "unique_records": unique_records[:50],  # 限制返回数量
        "processed_at": datetime.now().isoformat()
    }

