@app.post("/api/quality/dedup/find")
async def find_duplicates(request: Request):
    """查找重复记录"""
    from datetime import datetime
    
    data = await request.json()
    records = data.get("records", QUALITY_HISTORY)
    threshold = data.get("threshold", 1.0)  # 相似度阈值
    
    # 按问题分组查找重复
    question_groups = {}
    for i, record in enumerate(records):
        question = record.get("question", "")
        if question not in question_groups:
            question_groups[question] = []
        question_groups[question].append({
            "index": i,
            "record": record
        })
    
    # 找出重复组
    duplicates = []
    for question, group in question_groups.items():
        if len(group) > 1:
            duplicates.append({
                "question": question,
                "count": len(group),
                "records": [g["record"] for g in group]
            })
    
    return {
        "success": True,
        "message": "重复记录查找完成",
        "total_records": len(records),
        "duplicate_groups": len(duplicates),
        "duplicates": duplicates[:20],  # 限制返回数量
        "found_at": datetime.now().isoformat()
    }

@app.post("/api/quality/dedup/merge")
async def merge_duplicate_records(request: Request):
    """合并重复记录"""
    from datetime import datetime
    
    data = await request.json()
    duplicate_ids = data.get("ids", [])
    merge_strategy = data.get("strategy", "keep_best")  # keep_best, keep_first, combine
    
    if not duplicate_ids:
        return {"success": False, "message": "缺少记录ID列表"}
    
    # 获取要合并的记录
    records_to_merge = []
    for rid in duplicate_ids:
        if rid in QUALITY_DEDUP["dedup_records"]:
            records_to_merge.append(QUALITY_DEDUP["dedup_records"][rid])
    
    if not records_to_merge:
        return {"success": False, "message": "未找到要合并的记录"}
    
    # 根据策略选择保留记录
    merged_record = None
    if merge_strategy == "keep_best":
        merged_record = max(records_to_merge, key=lambda r: r.get("score", 0))
    elif merge_strategy == "keep_first":
        merged_record = records_to_merge[0]
    else:  # combine
        merged_record = records_to_merge[0].copy()
        merged_record["merged_from"] = [r.get("id") for r in records_to_merge[1:]]
    
    # 删除其他重复记录
    for rid in duplicate_ids:
        if rid in QUALITY_DEDUP["dedup_records"]:
            record = QUALITY_DEDUP["dedup_records"][rid]
            record_hash = _compute_record_hash(record)
            if record_hash in QUALITY_DEDUP["hash_index"]:
                del QUALITY_DEDUP["hash_index"][record_hash]
            del QUALITY_DEDUP["dedup_records"][rid]
    
    # 添加合并后的记录
    merged_id = merged_record.get("id", f"merged_{datetime.now().strftime('%Y%m%d%H%M%S')}")
    QUALITY_DEDUP["dedup_records"][merged_id] = merged_record
    merged_hash = _compute_record_hash(merged_record)
    QUALITY_DEDUP["hash_index"][merged_hash] = merged_id
    
    QUALITY_DEDUP["dedup_log"].append({
        "action": "merge",
        "merged_ids": duplicate_ids,
        "merge_strategy": merge_strategy,
        "result_id": merged_id,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "message": "重复记录已合并",
        "merged_count": len(records_to_merge),
        "merged_record": merged_record,
        "merged_at": datetime.now().isoformat()
    }

