QUALITY_PAGINATION = {
    "default_page_size": 20,
    "max_page_size": 100,
    "pagination_stats": {
        "total_queries": 0,
        "total_pages_served": 0,
        "avg_page_size": 0,
        "last_query": None
    },
    "pagination_log": []
}

@app.get("/api/quality/paginate/list")
async def paginate_quality_data(
    page: int = 1,
    page_size: int = 20,
    sort_by: str = "timestamp",
    sort_order: str = "desc",
    question_type: str = None,
    min_score: float = None,
    max_score: float = None
):
    """分页获取质量数据"""
    from datetime import datetime
    
    # 验证分页参数
    if page < 1:
        page = 1
    
    if page_size < 1 or page_size > QUALITY_PAGINATION["max_page_size"]:
        page_size = QUALITY_PAGINATION["default_page_size"]
    
    # 过滤数据
    filtered_data = QUALITY_HISTORY.copy()
    
    if question_type:
        filtered_data = [r for r in filtered_data if r.get("question_type") == question_type]
    
    if min_score is not None:
        filtered_data = [r for r in filtered_data if r.get("score", 0) >= min_score]
    
    if max_score is not None:
        filtered_data = [r for r in filtered_data if r.get("score", 0) <= max_score]
    
    # 排序
    reverse_order = sort_order.lower() == "desc"
    if sort_by in ["timestamp", "score", "question_type"]:
        filtered_data.sort(key=lambda x: x.get(sort_by, ""), reverse=reverse_order)
    
    # 计算分页
    total_records = len(filtered_data)
    total_pages = (total_records + page_size - 1) // page_size if total_records > 0 else 1
    
    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size
    
    page_data = filtered_data[start_idx:end_idx]
    
    # 更新统计
    QUALITY_PAGINATION["pagination_stats"]["total_queries"] += 1
    QUALITY_PAGINATION["pagination_stats"]["total_pages_served"] += 1
    QUALITY_PAGINATION["pagination_stats"]["last_query"] = datetime.now().isoformat()
    
    QUALITY_PAGINATION["pagination_log"].append({
        "action": "list",
        "page": page,
        "page_size": page_size,
        "total_records": total_records,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "pagination": {
            "current_page": page,
            "page_size": page_size,
            "total_records": total_records,
            "total_pages": total_pages,
            "has_previous": page > 1,
            "has_next": page < total_pages,
            "previous_page": page - 1 if page > 1 else None,
            "next_page": page + 1 if page < total_pages else None
        },
        "filters": {
            "question_type": question_type,
            "min_score": min_score,
            "max_score": max_score,
            "sort_by": sort_by,
            "sort_order": sort_order
        },
        "data": page_data,
        "retrieved_at": datetime.now().isoformat()
    }

@app.get("/api/quality/paginate/search")
async def search_quality_data_paginated(
    query: str,
    page: int = 1,
    page_size: int = 20,
    search_fields: str = "question,answer"
):
    """搜索并分页获取质量数据"""
    from datetime import datetime
    
    if page < 1:
        page = 1
    
    if page_size < 1 or page_size > QUALITY_PAGINATION["max_page_size"]:
        page_size = QUALITY_PAGINATION["default_page_size"]
    
    # 搜索字段
    fields = [f.strip() for f in search_fields.split(",")]
    
    # 执行搜索
    results = []
    query_lower = query.lower()
    
    for record in QUALITY_HISTORY:
        match = False
        for field in fields:
            field_value = str(record.get(field, "")).lower()
            if query_lower in field_value:
                match = True
                break
        
        if match:
            results.append(record)
    
    # 分页
    total_records = len(results)
    total_pages = (total_records + page_size - 1) // page_size if total_records > 0 else 1
    
    start_idx = (page - 1) * page_size
    end_idx = start_idx + page_size
    
    page_data = results[start_idx:end_idx]
    
    QUALITY_PAGINATION["pagination_stats"]["total_queries"] += 1
    QUALITY_PAGINATION["pagination_stats"]["last_query"] = datetime.now().isoformat()
    
    return {
        "success": True,
        "query": query,
        "pagination": {
            "current_page": page,
            "page_size": page_size,
            "total_records": total_records,
            "total_pages": total_pages,
            "has_previous": page > 1,
            "has_next": page < total_pages
        },
        "data": page_data,
        "searched_at": datetime.now().isoformat()
    }

