@app.post("/api/quality/sort/multi")
async def apply_multi_sort(request: Request):
    """多字段排序"""
    from datetime import datetime
    
    data = await request.json()
    sort_rules = data.get("rules", [])
    limit = data.get("limit", 100)
    
    if not sort_rules:
        return {"success": False, "message": "缺少排序规则"}
    
    sorted_data = QUALITY_HISTORY.copy()
    
    # 按规则顺序排序（从最后一个规则开始）
    for rule in reversed(sort_rules):
        field = rule.get("field")
        order = rule.get("order", "asc")
        
        if field not in QUALITY_SORTING["sortable_fields"]:
            continue
        
        reverse_order = order.lower() == "desc"
        
        def make_key(sort_field):
            def key_func(item):
                val = item.get(sort_field, "")
                if sort_field == "score":
                    return float(val) if val else 0.0
                elif sort_field == "answer_length":
                    return len(str(item.get("answer", "")))
                else:
                    return str(val) if val else ""
            return key_func
        
        sorted_data.sort(key=make_key(field), reverse=reverse_order)
    
    result_data = sorted_data[:limit]
    
    QUALITY_SORTING["sorting_stats"]["total_sorts"] += 1
    QUALITY_SORTING["sorting_stats"]["last_sort"] = datetime.now().isoformat()
    
    return {
        "success": True,
        "rules": sort_rules,
        "total_records": len(sorted_data),
        "returned": len(result_data),
        "data": result_data,
        "sorted_at": datetime.now().isoformat()
    }

