@app.post("/api/quality/sort/custom")
async def apply_custom_sort(request: Request):
    """自定义排序表达式"""
    from datetime import datetime
    
    data = await request.json()
    expression = data.get("expression", "")
    limit = data.get("limit", 100)
    
    if not expression:
        return {"success": False, "message": "缺少排序表达式"}
    
    sorted_data = QUALITY_HISTORY.copy()
    
    try:
        # 安全的自定义排序（仅支持简单表达式）
        def custom_key(item):
            # 替换字段名为实际值
            expr = expression
            for field in QUALITY_SORTING["sortable_fields"]:
                if field in expr:
                    val = item.get(field, 0)
                    if field == "score":
                        expr = expr.replace(field, str(float(val) if val else 0))
                    else:
                        expr = expr.replace(field, str(len(str(val)) if val else 0))
            
            # 简单计算（只支持加减乘除）
            try:
                return eval(expr, {"__builtins__": {}}, {})
            except:
                return 0
        
        sorted_data.sort(key=custom_key, reverse=True)
        result_data = sorted_data[:limit]
        
        QUALITY_SORTING["sorting_log"].append({
            "action": "custom",
            "expression": expression,
            "total_records": len(sorted_data),
            "timestamp": datetime.now().isoformat()
        })
        
        return {
            "success": True,
            "expression": expression,
            "total_records": len(sorted_data),
            "returned": len(result_data),
            "data": result_data,
            "sorted_at": datetime.now().isoformat()
        }
    except Exception as e:
        return {"success": False, "message": f"排序表达式错误: {str(e)}"}

@app.get("/api/quality/sort/rank/{record_id}")
async def get_record_rank(record_id: str, sort_by: str = "score"):
    """获取记录排名"""
    from datetime import datetime
    
    if sort_by not in QUALITY_SORTING["sortable_fields"]:
        return {"success": False, "message": f"不支持的排序字段: {sort_by}"}
    
    sorted_data = QUALITY_HISTORY.copy()
    
    def sort_key(item):
        val = item.get(sort_by, "")
        if sort_by == "score":
            return float(val) if val else 0.0
        else:
            return str(val) if val else ""
    
    sorted_data.sort(key=sort_key, reverse=True)
    
    # 查找记录排名
    for rank, item in enumerate(sorted_data, 1):
        if item.get("id") == record_id or item.get("timestamp") == record_id:
            return {
                "success": True,
                "record_id": record_id,
                "rank": rank,
                "total_records": len(sorted_data),
                "percentile": (rank / len(sorted_data)) * 100 if sorted_data else 0,
                "sort_by": sort_by,
                "checked_at": datetime.now().isoformat()
            }
    
    return {"success": False, "message": "未找到记录"}

# 质量评分数据过滤配置
QUALITY_FILTER = {
    "enabled": True,
    "default_filters": {},
    "filter_stats": {
        "total_filters": 0,
        "last_filter": None,
        "popular_filters": {}
    },
    "filter_log": [],
    "saved_filters": {}
}

@app.post("/api/quality/filter/apply")
async def apply_quality_filter(request: Request):
    """应用过滤条件到质量数据"""
    from datetime import datetime
    
    data = await request.json()
    filters = data.get("filters", {})
    limit = data.get("limit", 100)
    
    filtered_data = QUALITY_HISTORY.copy()
    
    # 应用过滤条件
    for field, condition in filters.items():
        if not condition:
            continue
        
        # 支持多种过滤操作
        if isinstance(condition, dict):
            op = condition.get("op", "eq")
            value = condition.get("value")
            
            if op == "eq":
                filtered_data = [r for r in filtered_data if r.get(field) == value]
            elif op == "ne":
                filtered_data = [r for r in filtered_data if r.get(field) != value]
            elif op == "gt":
                filtered_data = [r for r in filtered_data if r.get(field, 0) > value]
            elif op == "gte":
                filtered_data = [r for r in filtered_data if r.get(field, 0) >= value]
            elif op == "lt":
                filtered_data = [r for r in filtered_data if r.get(field, 0) < value]
            elif op == "lte":
                filtered_data = [r for r in filtered_data if r.get(field, 0) <= value]
            elif op == "contains":
                filtered_data = [r for r in filtered_data if value in str(r.get(field, ""))]
            elif op == "startswith":
                filtered_data = [r for r in filtered_data if str(r.get(field, "")).startswith(value)]
            elif op == "endswith":
                filtered_data = [r for r in filtered_data if str(r.get(field, "")).endswith(value)]
            elif op == "in":
                filtered_data = [r for r in filtered_data if r.get(field) in value]
            elif op == "nin":
                filtered_data = [r for r in filtered_data if r.get(field) not in value]
            elif op == "regex":
                import re
                filtered_data = [r for r in filtered_data if re.search(value, str(r.get(field, "")))]
        else:
            # 简单等于过滤
            filtered_data = [r for r in filtered_data if r.get(field) == condition]
    
    result_data = filtered_data[:limit]
    
    # 更新统计
    QUALITY_FILTER["filter_stats"]["total_filters"] += 1
    QUALITY_FILTER["filter_stats"]["last_filter"] = datetime.now().isoformat()
    
    filter_key = str(filters)
    if filter_key not in QUALITY_FILTER["filter_stats"]["popular_filters"]:
        QUALITY_FILTER["filter_stats"]["popular_filters"][filter_key] = 0
    QUALITY_FILTER["filter_stats"]["popular_filters"][filter_key] += 1
    
    QUALITY_FILTER["filter_log"].append({
        "action": "apply",
        "filters": filters,
        "total_records": len(QUALITY_HISTORY),
        "filtered_count": len(filtered_data),
        "returned": len(result_data),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "filters": filters,
        "total_records": len(QUALITY_HISTORY),
        "filtered_count": len(filtered_data),
        "returned": len(result_data),
        "data": result_data,
        "filtered_at": datetime.now().isoformat()
    }

