@app.post("/api/quality/filter/complex")
async def apply_complex_filter(request: Request):
    """复杂过滤（AND/OR组合）"""
    from datetime import datetime
    
    data = await request.json()
    conditions = data.get("conditions", [])
    logic = data.get("logic", "and")  # and 或 or
    limit = data.get("limit", 100)
    
    if not conditions:
        return {"success": False, "message": "缺少过滤条件"}
    
    def matches_condition(record, condition):
        field = condition.get("field")
        op = condition.get("op", "eq")
        value = condition.get("value")
        
        field_value = record.get(field)
        
        if op == "eq":
            return field_value == value
        elif op == "ne":
            return field_value != value
        elif op == "gt":
            return field_value > value if field_value is not None else False
        elif op == "gte":
            return field_value >= value if field_value is not None else False
        elif op == "lt":
            return field_value < value if field_value is not None else False
        elif op == "lte":
            return field_value <= value if field_value is not None else False
        elif op == "contains":
            return value in str(field_value) if field_value else False
        elif op == "in":
            return field_value in value
        elif op == "nin":
            return field_value not in value
        return False
    
    filtered_data = []
    for record in QUALITY_HISTORY:
        if logic == "and":
            if all(matches_condition(record, c) for c in conditions):
                filtered_data.append(record)
        else:  # or
            if any(matches_condition(record, c) for c in conditions):
                filtered_data.append(record)
    
    result_data = filtered_data[:limit]
    
    QUALITY_FILTER["filter_log"].append({
        "action": "complex",
        "conditions": conditions,
        "logic": logic,
        "filtered_count": len(filtered_data),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "conditions": conditions,
        "logic": logic,
        "total_records": len(QUALITY_HISTORY),
        "filtered_count": len(filtered_data),
        "returned": len(result_data),
        "data": result_data,
        "filtered_at": datetime.now().isoformat()
    }

