@app.post("/api/quality/filter/validate")
async def validate_filter(request: Request):
    """验证过滤条件"""
    from datetime import datetime
    
    data = await request.json()
    filters = data.get("filters", {})
    
    valid_fields = ["score", "question_type", "timestamp", "question", "answer"]
    valid_ops = ["eq", "ne", "gt", "gte", "lt", "lte", "contains", "startswith", "endswith", "in", "nin", "regex"]
    
    errors = []
    warnings = []
    
    for field, condition in filters.items():
        if field not in valid_fields:
            errors.append(f"无效字段: {field}")
        
        if isinstance(condition, dict):
            op = condition.get("op", "eq")
            if op not in valid_ops:
                errors.append(f"无效操作符: {op}")
            
            if "value" not in condition:
                errors.append(f"字段 {field} 缺少值")
    
    return {
        "success": len(errors) == 0,
        "valid": len(errors) == 0,
        "errors": errors,
        "warnings": warnings,
        "filters": filters,
        "validated_at": datetime.now().isoformat()
    }

# 质量评分数据聚合配置
QUALITY_AGGREGATION = {
    "enabled": True,
    "aggregation_stats": {
        "total_aggregations": 0,
        "last_aggregation": None
    },
    "aggregation_log": []
}

@app.post("/api/quality/aggregate/group")
async def aggregate_by_field(request: Request):
    """按字段分组聚合"""
    from datetime import datetime
    
    data = await request.json()
    field = data.get("field", "question_type")
    aggregations = data.get("aggregations", ["count", "avg_score"])
    
    groups = {}
    
    for record in QUALITY_HISTORY:
        key = record.get(field, "unknown")
        
        if key not in groups:
            groups[key] = {
                "key": key,
                "count": 0,
                "scores": [],
                "records": []
            }
        
        groups[key]["count"] += 1
        groups[key]["scores"].append(record.get("score", 0))
        groups[key]["records"].append(record)
    
    # 计算聚合值
    result = []
    for key, group in groups.items():
        agg_result = {"key": key, "count": group["count"]}
        
        if "avg_score" in aggregations:
            agg_result["avg_score"] = sum(group["scores"]) / len(group["scores"]) if group["scores"] else 0
        
        if "min_score" in aggregations:
            agg_result["min_score"] = min(group["scores"]) if group["scores"] else 0
        
        if "max_score" in aggregations:
            agg_result["max_score"] = max(group["scores"]) if group["scores"] else 0
        
        if "sum_score" in aggregations:
            agg_result["sum_score"] = sum(group["scores"])
        
        if "std_score" in aggregations:
            import statistics
            agg_result["std_score"] = statistics.stdev(group["scores"]) if len(group["scores"]) > 1 else 0
        
        result.append(agg_result)
    
    # 按count排序
    result.sort(key=lambda x: x["count"], reverse=True)
    
    QUALITY_AGGREGATION["aggregation_stats"]["total_aggregations"] += 1
    QUALITY_AGGREGATION["aggregation_stats"]["last_aggregation"] = datetime.now().isoformat()
    
    return {
        "success": True,
        "field": field,
        "aggregations": aggregations,
        "groups": result,
        "total_groups": len(result),
        "aggregated_at": datetime.now().isoformat()
    }

@app.get("/api/quality/aggregate/stats")
async def get_aggregate_stats():
    """获取整体聚合统计"""
    from datetime import datetime
    
    if not QUALITY_HISTORY:
        return {
            "success": True,
            "stats": {},
            "aggregated_at": datetime.now().isoformat()
        }
    
    scores = [r.get("score", 0) for r in QUALITY_HISTORY]
    
    import statistics
    
    stats = {
        "total_records": len(QUALITY_HISTORY),
        "avg_score": sum(scores) / len(scores) if scores else 0,
        "min_score": min(scores) if scores else 0,
        "max_score": max(scores) if scores else 0,
        "sum_score": sum(scores),
        "std_score": statistics.stdev(scores) if len(scores) > 1 else 0,
        "median_score": statistics.median(scores) if scores else 0,
        "variance_score": statistics.variance(scores) if len(scores) > 1 else 0
    }
    
    # 按问题类型统计
    type_counts = {}
    for r in QUALITY_HISTORY:
        qt = r.get("question_type", "unknown")
        type_counts[qt] = type_counts.get(qt, 0) + 1
    
    stats["by_type"] = type_counts
    
    return {
        "success": True,
        "stats": stats,
        "aggregated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/aggregate/time")
async def aggregate_by_time(request: Request):
    """按时间聚合"""
    from datetime import datetime
    
    data = await request.json()
    interval = data.get("interval", "day")  # hour, day, week, month
    
    groups = {}
    
    for record in QUALITY_HISTORY:
        timestamp = record.get("timestamp", "")
        if not timestamp:
            continue
        
        try:
            dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
            
            if interval == "hour":
                key = dt.strftime("%Y-%m-%d %H:00")
            elif interval == "day":
                key = dt.strftime("%Y-%m-%d")
            elif interval == "week":
                key = dt.strftime("%Y-W%W")
            elif interval == "month":
                key = dt.strftime("%Y-%m")
            else:
                key = dt.strftime("%Y-%m-%d")
            
            if key not in groups:
                groups[key] = {"key": key, "count": 0, "scores": []}
            
            groups[key]["count"] += 1
            groups[key]["scores"].append(record.get("score", 0))
        except:
            continue
    
    result = []
    for key, group in groups.items():
        result.append({
            "key": key,
            "count": group["count"],
            "avg_score": sum(group["scores"]) / len(group["scores"]) if group["scores"] else 0
        })
    
    # 按时间排序
    result.sort(key=lambda x: x["key"])
    
    return {
        "success": True,
        "interval": interval,
        "data": result,
        "total_groups": len(result),
        "aggregated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/aggregate/histogram")
async def create_score_histogram(request: Request):
    """创建分数直方图"""
    from datetime import datetime
    
    data = await request.json()
    bins = data.get("bins", 10)
    min_val = data.get("min", 0)
    max_val = data.get("max", 100)
    
    scores = [r.get("score", 0) for r in QUALITY_HISTORY]
    
    bin_width = (max_val - min_val) / bins
    histogram = [{"range": f"{min_val + i*bin_width:.1f}-{min_val + (i+1)*bin_width:.1f}", "count": 0} for i in range(bins)]
    
    for score in scores:
        if min_val <= score <= max_val:
            bin_idx = min(int((score - min_val) / bin_width), bins - 1)
            histogram[bin_idx]["count"] += 1
    
    return {
        "success": True,
        "bins": bins,
        "range": {"min": min_val, "max": max_val},
        "histogram": histogram,
        "total_records": len(scores),
        "aggregated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/aggregate/percentile")
async def calculate_percentiles(request: Request):
    """计算百分位数"""
    from datetime import datetime
    import statistics
    
    data = await request.json()
    percentiles = data.get("percentiles", [25, 50, 75, 90, 95, 99])
    
    scores = sorted([r.get("score", 0) for r in QUALITY_HISTORY])
    
    if not scores:
        return {"success": True, "percentiles": {}, "aggregated_at": datetime.now().isoformat()}
    
    result = {}
    for p in percentiles:
        idx = int(len(scores) * p / 100)
        idx = min(idx, len(scores) - 1)
        result[f"p{p}"] = scores[idx]
    
    result["median"] = statistics.median(scores)
    
    return {
        "success": True,
        "percentiles": result,
        "total_records": len(scores),
        "aggregated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/aggregate/custom")
async def custom_aggregation(request: Request):
    """自定义聚合"""
    from datetime import datetime
    
    data = await request.json()
    group_by = data.get("group_by")
    metrics = data.get("metrics", ["count"])
    filters = data.get("filters", {})
    
    # 先过滤
    filtered_data = QUALITY_HISTORY.copy()
    for field, value in filters.items():
        filtered_data = [r for r in filtered_data if r.get(field) == value]
    
    # 分组
    if group_by:
        groups = {}
        for record in filtered_data:
            key = record.get(group_by, "unknown")
            if key not in groups:
                groups[key] = []
            groups[key].append(record)
        
        result = []
        for key, records in groups.items():
            agg = {"key": key, "count": len(records)}
            
            if "avg_score" in metrics:
                scores = [r.get("score", 0) for r in records]
                agg["avg_score"] = sum(scores) / len(scores) if scores else 0
            
            if "min_score" in metrics:
                agg["min_score"] = min(r.get("score", 0) for r in records)
            
            if "max_score" in metrics:
                agg["max_score"] = max(r.get("score", 0) for r in records)
            
            result.append(agg)
    else:
        # 无分组，整体聚合
        result = {"count": len(filtered_data)}
        if "avg_score" in metrics:
            scores = [r.get("score", 0) for r in filtered_data]
            result["avg_score"] = sum(scores) / len(scores) if scores else 0
    
    QUALITY_AGGREGATION["aggregation_log"].append({
        "action": "custom",
        "group_by": group_by,
        "metrics": metrics,
        "filters": filters,
        "result_count": len(result) if isinstance(result, list) else 1,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "group_by": group_by,
        "metrics": metrics,
        "filters": filters,
        "result": result,
        "aggregated_at": datetime.now().isoformat()
    }

@app.get("/api/quality/aggregate/summary")
async def get_aggregation_summary():
    """获取聚合摘要"""
    from datetime import datetime
    
    if not QUALITY_HISTORY:
        return {"success": True, "summary": {}, "aggregated_at": datetime.now().isoformat()}
    
    scores = [r.get("score", 0) for r in QUALITY_HISTORY]
    
    # 分数分布
    high_quality = len([s for s in scores if s >= 80])
    medium_quality = len([s for s in scores if 50 <= s < 80])
    low_quality = len([s for s in scores if s < 50])
    
    # 问题类型分布
    type_dist = {}
    for r in QUALITY_HISTORY:
        qt = r.get("question_type", "unknown")
        type_dist[qt] = type_dist.get(qt, 0) + 1
    
    summary = {
        "total_records": len(QUALITY_HISTORY),
        "avg_score": sum(scores) / len(scores) if scores else 0,
        "quality_distribution": {
            "high": high_quality,
            "medium": medium_quality,
            "low": low_quality
        },
        "quality_percentages": {
            "high": (high_quality / len(scores) * 100) if scores else 0,
            "medium": (medium_quality / len(scores) * 100) if scores else 0,
            "low": (low_quality / len(scores) * 100) if scores else 0
        },
        "type_distribution": type_dist,
        "top_types": sorted(type_dist.items(), key=lambda x: x[1], reverse=True)[:5]
    }
    
    return {
        "success": True,
        "summary": summary,
        "aggregated_at": datetime.now().isoformat()
    }

