    data = await request.json()
    formats = data.get("formats", ["json", "csv"])
    filters = data.get("filters", {})
    
    # 应用过滤
    export_data = QUALITY_HISTORY.copy()
    for field, value in filters.items():
        export_data = [r for r in export_data if r.get(field) == value]
    
    results = {}
    
    for fmt in formats:
        if fmt == "json":
            import json
            results["json"] = {
                "data": export_data,
                "size_bytes": len(json.dumps(export_data, ensure_ascii=False))
            }
        elif fmt == "csv":
            import io
            import csv
            output = io.StringIO()
            writer = csv.writer(output)
            writer.writerow(["timestamp", "question", "answer", "score", "question_type"])
            for r in export_data:
                writer.writerow([r.get("timestamp", ""), r.get("question", ""), r.get("answer", ""), r.get("score", 0), r.get("question_type", "")])
            results["csv"] = {
                "content": output.getvalue(),
                "size_bytes": len(output.getvalue())
            }
        elif fmt == "xml":
            xml_lines = ['<?xml version="1.0" encoding="UTF-8"?><quality_records>']
            for r in export_data:
                xml_lines.append('<record>')
                for k, v in r.items():
                    xml_lines.append(f'<{k}>{str(v).replace("&", "&amp;")}</{k}>')
                xml_lines.append('</record>')
            xml_lines.append('</quality_records>')
            xml_str = '\n'.join(xml_lines)
            results["xml"] = {
                "content": xml_str,
                "size_bytes": len(xml_str)
            }
    
    # 更新统计
    QUALITY_EXPORT["export_stats"]["total_exports"] += len(formats)
    QUALITY_EXPORT["export_stats"]["last_export"] = datetime.now().isoformat()
    
    return {
        "success": True,
        "formats": formats,
        "results": results,
        "record_count": len(export_data),
        "exported_at": datetime.now().isoformat()
    }

