@app.post("/api/quality/import/base64")
async def import_quality_base64(request: Request):
    """从Base64编码导入"""
    from datetime import datetime
    import base64
    import json
    
    data = await request.json()
    base64_content = data.get("base64_content", "")
    format_type = data.get("format", "json")  # json, csv
    merge = data.get("merge", True)
    
    if not base64_content:
        return {"success": False, "error": "No base64 content provided"}
    
    try:
        decoded = base64.b64decode(base64_content).decode('utf-8')
    except Exception as e:
        return {"success": False, "error": f"Base64 decode error: {str(e)}"}
    
    valid_records = []
    errors = []
    
    if format_type == "json":
        try:
            json_data = json.loads(decoded)
            if isinstance(json_data, list):
                for record in json_data:
                    if isinstance(record, dict) and record.get("question"):
                        valid_records.append(record)
        except json.JSONDecodeError as e:
            return {"success": False, "error": f"JSON decode error: {str(e)}"}
    elif format_type == "csv":
        import io
        import csv
        reader = csv.DictReader(io.StringIO(decoded))
        for row in reader:
            if row.get("question"):
                valid_records.append({
                    "timestamp": row.get("timestamp", datetime.now().isoformat()),
                    "question": row.get("question", ""),
                    "answer": row.get("answer", ""),
                    "score": float(row.get("score", 0)),
                    "question_type": row.get("question_type", "unknown")
                })
    
    # 导入数据
    if merge:
        QUALITY_HISTORY.extend(valid_records)
    else:
        QUALITY_HISTORY.clear()
        QUALITY_HISTORY.extend(valid_records)
    
    # 更新统计
    QUALITY_IMPORT["import_stats"]["total_imports"] += 1
    QUALITY_IMPORT["import_stats"]["last_import"] = datetime.now().isoformat()
    QUALITY_IMPORT["import_stats"]["total_records_imported"] += len(valid_records)
    
    return {
        "success": True,
        "format": format_type,
        "imported_count": len(valid_records),
        "error_count": len(errors),
        "total_records": len(QUALITY_HISTORY),
        "imported_at": datetime.now().isoformat()
    }

@app.post("/api/quality/import/validate")
async def validate_import_data(request: Request):
    """验证导入数据"""
    from datetime import datetime
    
    data = await request.json()
    records = data.get("data", [])
    
    if not isinstance(records, list):
        return {"success": False, "error": "Data must be a list"}
    
    validation_results = {
        "total_records": len(records),
        "valid_records": 0,
        "invalid_records": 0,
        "errors": [],
        "warnings": []
    }
    
    required_fields = ["question"]
    recommended_fields = ["answer", "score", "question_type", "timestamp"]
    
    for i, record in enumerate(records):
        if not isinstance(record, dict):
            validation_results["invalid_records"] += 1
            validation_results["errors"].append(f"Record {i}: Not a dictionary")
            continue
        
        # 检查必需字段
        missing_required = [f for f in required_fields if f not in record or not record.get(f)]
        if missing_required:
            validation_results["invalid_records"] += 1
            validation_results["errors"].append(f"Record {i}: Missing required fields: {missing_required}")
            continue
        
        # 检查推荐字段
        missing_recommended = [f for f in recommended_fields if f not in record]
        if missing_recommended:
            validation_results["warnings"].append(f"Record {i}: Missing recommended fields: {missing_recommended}")
        
        # 检查分数范围
        if "score" in record:
            try:
                score = float(record["score"])
                if not (0 <= score <= 100):
                    validation_results["warnings"].append(f"Record {i}: Score {score} out of range [0, 100]")
            except (ValueError, TypeError):
                validation_results["errors"].append(f"Record {i}: Invalid score value")
                validation_results["invalid_records"] += 1
                continue
        
        validation_results["valid_records"] += 1
    
    return {
        "success": True,
        "validation": validation_results,
        "can_import": validation_results["valid_records"] > 0,
        "validated_at": datetime.now().isoformat()
    }

