@app.post("/api/quality/transform/json-to-markdown")
async def transform_json_to_markdown(request: Request):
    """JSON转Markdown"""
    from datetime import datetime
    
    data = await request.json()
    json_data = data.get("data", [])
    include_answers = data.get("include_answers", True)
    
    if not isinstance(json_data, list):
        return {"success": False, "error": "Data must be a list"}
    
    # 转换
    md_lines = ['# 质量评分报告\n']
    md_lines.append(f'记录总数: {len(json_data)}\n')
    md_lines.append('\n---\n')
    
    for i, record in enumerate(json_data, 1):
        if isinstance(record, dict):
            md_lines.append(f'\n## 记录 {i}\n')
            md_lines.append(f'- **时间**: {record.get("timestamp", "N/A")}\n')
            md_lines.append(f'- **问题类型**: {record.get("question_type", "N/A")}\n')
            md_lines.append(f'- **评分**: {record.get("score", "N/A")}\n')
            md_lines.append(f'- **问题**: {record.get("question", "N/A")}\n')
            if include_answers:
                answer = record.get("answer", "N/A")
                md_lines.append(f'\n**回答**:\n\n{answer}\n')
            md_lines.append('\n---\n')
    
    md_content = ''.join(md_lines)
    
    # 更新统计
    QUALITY_TRANSFORM["transform_stats"]["total_transforms"] += 1
    QUALITY_TRANSFORM["transform_stats"]["last_transform"] = datetime.now().isoformat()
    if "json_to_markdown" not in QUALITY_TRANSFORM["transform_stats"]["transformations"]:
        QUALITY_TRANSFORM["transform_stats"]["transformations"]["json_to_markdown"] = 0
    QUALITY_TRANSFORM["transform_stats"]["transformations"]["json_to_markdown"] += 1
    
    return {
        "success": True,
        "transformation": "json_to_markdown",
        "markdown_content": md_content,
        "input_records": len(json_data),
        "output_size": len(md_content),
        "transformed_at": datetime.now().isoformat()
    }

