@app.post("/api/quality/transform/batch")
async def batch_transform(request: Request):
    """批量转换多种格式"""
    from datetime import datetime
    
    data = await request.json()
    input_data = data.get("data", [])
    transformations = data.get("transformations", ["json_to_csv", "json_to_xml"])
    
    results = {}
    
    for transform_type in transformations:
        if transform_type == "json_to_csv":
            import io
            import csv
            output = io.StringIO()
            writer = csv.writer(output)
            writer.writerow(["timestamp", "question", "answer", "score", "question_type"])
            for r in input_data:
                writer.writerow([r.get("timestamp", ""), r.get("question", ""), r.get("answer", ""), r.get("score", 0), r.get("question_type", "")])
            results["csv"] = {"content": output.getvalue(), "size": len(output.getvalue())}
        
        elif transform_type == "json_to_xml":
            xml_lines = ['<?xml version="1.0" encoding="UTF-8"?><quality_records>']
            for r in input_data:
                xml_lines.append('<record>')
                for k, v in r.items():
                    xml_lines.append(f'<{k}>{str(v).replace("&", "&amp;")}</{k}>')
                xml_lines.append('</record>')
            xml_lines.append('</quality_records>')
            xml_str = '\n'.join(xml_lines)
            results["xml"] = {"content": xml_str, "size": len(xml_str)}
        
        elif transform_type == "json_to_markdown":
            md_lines = ['# 质量评分报告\n']
            for i, r in enumerate(input_data, 1):
                md_lines.append(f'\n## 记录 {i}\n- **评分**: {r.get("score", 0)}\n- **问题**: {r.get("question", "")}\n')
            md_str = ''.join(md_lines)
            results["markdown"] = {"content": md_str, "size": len(md_str)}
    
    # 更新统计
    QUALITY_TRANSFORM["transform_stats"]["total_transforms"] += len(transformations)
    QUALITY_TRANSFORM["transform_stats"]["last_transform"] = datetime.now().isoformat()
    
    return {
        "success": True,
        "transformations": transformations,
        "results": results,
        "input_records": len(input_data),
        "transformed_at": datetime.now().isoformat()
    }

# 质量评分数据合并配置
QUALITY_MERGE = {
    "enabled": True,
    "merge_stats": {
        "total_merges": 0,
        "last_merge": None,
        "total_records_merged": 0,
        "duplicates_removed": 0
    },
    "merge_log": []
}

@app.post("/api/quality/merge")
async def merge_quality_data(request: Request):
    """合并多个数据源的质量评分数据"""
    from datetime import datetime
    
    data = await request.json()
    sources = data.get("sources", [])
    strategy = data.get("strategy", "append")  # append, replace, dedupe, union
    conflict_resolution = data.get("conflict_resolution", "keep_first")  # keep_first, keep_last, keep_higher_score
    
    if not sources:
        return {"success": False, "error": "No data sources provided"}
    
    merged_data = []
    duplicates = 0
    
    for source_idx, source in enumerate(sources):
        records = source.get("data", [])
        source_name = source.get("name", f"source_{source_idx}")
        
        for record in records:
            if not isinstance(record, dict):
                continue
            
            # 检查是否已存在（基于问题文本）
            question = record.get("question", "")
            existing_idx = None
            
            for idx, existing in enumerate(merged_data):
                if existing.get("question", "") == question:
                    existing_idx = idx
                    break
            
            if existing_idx is not None:
                duplicates += 1
                if conflict_resolution == "keep_last":
                    merged_data[existing_idx] = record
                elif conflict_resolution == "keep_higher_score":
                    if record.get("score", 0) > merged_data[existing_idx].get("score", 0):
                        merged_data[existing_idx] = record
                # keep_first: 不做任何操作
            else:
                record["_source"] = source_name
                merged_data.append(record)
    
    # 应用策略
    if strategy == "replace":
        QUALITY_HISTORY.clear()
        QUALITY_HISTORY.extend(merged_data)
    elif strategy == "append":
        QUALITY_HISTORY.extend(merged_data)
    elif strategy == "dedupe":
        # 去重后追加
        existing_questions = {r.get("question", "") for r in QUALITY_HISTORY}
        for record in merged_data:
            if record.get("question", "") not in existing_questions:
                QUALITY_HISTORY.append(record)
    elif strategy == "union":
        # 并集合并
        QUALITY_HISTORY.extend(merged_data)
    
    # 更新统计
    QUALITY_MERGE["merge_stats"]["total_merges"] += 1
    QUALITY_MERGE["merge_stats"]["last_merge"] = datetime.now().isoformat()
    QUALITY_MERGE["merge_stats"]["total_records_merged"] += len(merged_data)
    QUALITY_MERGE["merge_stats"]["duplicates_removed"] += duplicates
    
    QUALITY_MERGE["merge_log"].append({
        "sources_count": len(sources),
        "strategy": strategy,
        "conflict_resolution": conflict_resolution,
        "records_merged": len(merged_data),
        "duplicates_found": duplicates,
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "strategy": strategy,
        "conflict_resolution": conflict_resolution,
        "merged_records": len(merged_data),
        "duplicates_found": duplicates,
        "total_in_history": len(QUALITY_HISTORY),
        "merged_at": datetime.now().isoformat()
    }

@app.post("/api/quality/merge/preview")
async def preview_merge(request: Request):
    """预览合并结果"""
    from datetime import datetime
    
    data = await request.json()
    sources = data.get("sources", [])
    conflict_resolution = data.get("conflict_resolution", "keep_first")
    
    preview_data = []
    conflicts = []
    
    for source_idx, source in enumerate(sources):
        records = source.get("data", [])
        source_name = source.get("name", f"source_{source_idx}")
        
        for record in records:
            if not isinstance(record, dict):
                continue
            
            question = record.get("question", "")
            existing_idx = None
            
            for idx, existing in enumerate(preview_data):
                if existing.get("question", "") == question:
                    existing_idx = idx
                    break
            
            if existing_idx is not None:
                conflicts.append({
                    "question": question,
                    "existing_source": preview_data[existing_idx].get("_source"),
                    "new_source": source_name,
                    "existing_score": preview_data[existing_idx].get("score"),
                    "new_score": record.get("score")
                })
                
                if conflict_resolution == "keep_last":
                    preview_data[existing_idx] = {**record, "_source": source_name}
                elif conflict_resolution == "keep_higher_score":
                    if record.get("score", 0) > preview_data[existing_idx].get("score", 0):
                        preview_data[existing_idx] = {**record, "_source": source_name}
            else:
                preview_data.append({**record, "_source": source_name})
    
    return {
        "success": True,
        "preview_records": preview_data[:100],  # 限制预览数量
        "total_records": len(preview_data),
        "conflicts_count": len(conflicts),
        "conflicts": conflicts[:20],  # 限制冲突显示
        "previewed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/merge/conflicts")
async def get_merge_conflicts(request: Request):
    """获取合并冲突详情"""
    from datetime import datetime
    
    data = await request.json()
    sources = data.get("sources", [])
    
    conflicts = []
    question_sources = {}  # question -> [sources]
    
    for source_idx, source in enumerate(sources):
        records = source.get("data", [])
        source_name = source.get("name", f"source_{source_idx}")
        
        for record in records:
            if not isinstance(record, dict):
                continue
            
            question = record.get("question", "")
            if question not in question_sources:
                question_sources[question] = []
            question_sources[question].append({
                "source": source_name,
                "score": record.get("score", 0),
                "timestamp": record.get("timestamp", ""),
                "record": record
            })
    
    # 找出有冲突的问题
    for question, source_list in question_sources.items():
        if len(source_list) > 1:
            conflicts.append({
                "question": question,
                "occurrences": len(source_list),
                "sources": source_list
            })
    
    # 按出现次数排序
    conflicts.sort(key=lambda x: x["occurrences"], reverse=True)
    
    return {
        "success": True,
        "total_conflicts": len(conflicts),
        "conflicts": conflicts[:50],
        "checked_at": datetime.now().isoformat()
    }

@app.post("/api/quality/merge/resolve")
async def resolve_merge_conflicts(request: Request):
    """解决合并冲突"""
    from datetime import datetime
    
    data = await request.json()
    resolutions = data.get("resolutions", [])  # [{question: str, keep_source: str}]
    
    resolved_count = 0
    
    for resolution in resolutions:
        question = resolution.get("question", "")
        keep_source = resolution.get("keep_source", "")
        
        # 从历史中移除其他来源的同名问题
        to_remove = []
        for idx, record in enumerate(QUALITY_HISTORY):
            if record.get("question", "") == question and record.get("_source", "") != keep_source:
                to_remove.append(idx)
        
        # 从后往前删除
        for idx in reversed(to_remove):
            del QUALITY_HISTORY[idx]
            resolved_count += 1
    
    return {
        "success": True,
        "resolved_count": resolved_count,
        "resolved_at": datetime.now().isoformat()
    }

