@app.post("/api/quality/merge/undo")
async def undo_last_merge():
    """撤销最后一次合并"""
    from datetime import datetime
    
    if not QUALITY_MERGE["merge_log"]:
        return {"success": False, "error": "No merge operations to undo"}
    
    last_merge = QUALITY_MERGE["merge_log"][-1]
    records_to_remove = last_merge.get("records_merged", 0)
    
    # 移除最后添加的记录
    if records_to_remove > 0 and len(QUALITY_HISTORY) >= records_to_remove:
        for _ in range(records_to_remove):
            QUALITY_HISTORY.pop()
    
    # 更新统计
    QUALITY_MERGE["merge_stats"]["total_merges"] -= 1
    QUALITY_MERGE["merge_stats"]["total_records_merged"] -= records_to_remove
    
    # 移除日志
    QUALITY_MERGE["merge_log"].pop()
    
    return {
        "success": True,
        "removed_records": records_to_remove,
        "remaining_records": len(QUALITY_HISTORY),
        "undone_at": datetime.now().isoformat()
    }

@app.post("/api/quality/merge/compare")
async def compare_sources(request: Request):
    """比较多个数据源"""
    from datetime import datetime
    
    data = await request.json()
    sources = data.get("sources", [])
    
    comparison = {
        "source_stats": [],
        "overlap": {},
        "unique_questions": {}
    }
    
    all_questions = {}  # question -> [sources]
    
    for source_idx, source in enumerate(sources):
        records = source.get("data", [])
        source_name = source.get("name", f"source_{source_idx}")
        
        scores = [r.get("score", 0) for r in records if isinstance(r, dict)]
        
        comparison["source_stats"].append({
            "name": source_name,
            "record_count": len(records),
            "avg_score": sum(scores) / len(scores) if scores else 0,
            "min_score": min(scores) if scores else 0,
            "max_score": max(scores) if scores else 0
        })
        
        for record in records:
            if isinstance(record, dict):
                question = record.get("question", "")
                if question not in all_questions:
                    all_questions[question] = []
                all_questions[question].append(source_name)
    
    # 计算重叠和唯一问题
    for question, source_list in all_questions.items():
        if len(source_list) > 1:
            key = tuple(sorted(set(source_list)))
            if key not in comparison["overlap"]:
                comparison["overlap"][key] = 0
            comparison["overlap"][key] += 1
        else:
            source = source_list[0]
            if source not in comparison["unique_questions"]:
                comparison["unique_questions"][source] = 0
            comparison["unique_questions"][source] += 1
    
    return {
        "success": True,
        "comparison": comparison,
        "total_unique_questions": len(all_questions),
        "compared_at": datetime.now().isoformat()
    }

# 质量评分数据分割配置
QUALITY_SPLIT = {
    "enabled": True,
    "split_stats": {
        "total_splits": 0,
        "last_split": None,
        "total_parts_created": 0
    },
    "split_log": []
}

@app.post("/api/quality/split")
async def split_quality_data(request: Request):
    """分割质量评分数据"""
    from datetime import datetime
    
    data = await request.json()
    split_by = data.get("split_by", "score_range")  # score_range, question_type, time, count
    params = data.get("params", {})
    
    parts = []
    
    if split_by == "score_range":
        # 按分数范围分割
        ranges = params.get("ranges", [(0, 50), (50, 75), (75, 100)])
        for min_score, max_score in ranges:
            part_records = [r for r in QUALITY_HISTORY 
                          if min_score <= r.get("score", 0) < max_score]
            parts.append({
                "name": f"score_{min_score}_{max_score}",
                "count": len(part_records),
                "data": part_records
            })
    
    elif split_by == "question_type":
        # 按问题类型分割
        type_groups = {}
        for record in QUALITY_HISTORY:
            qtype = record.get("question_type", "unknown")
            if qtype not in type_groups:
                type_groups[qtype] = []
            type_groups[qtype].append(record)
        
        for qtype, records in type_groups.items():
            parts.append({
                "name": f"type_{qtype}",
                "count": len(records),
                "data": records
            })
    
    elif split_by == "time":
        # 按时间分割
        interval = params.get("interval", "day")  # day, week, month
        time_groups = {}
        
        for record in QUALITY_HISTORY:
            timestamp = record.get("timestamp", "")
            if not timestamp:
                continue
            
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if interval == "day":
                    key = dt.strftime("%Y-%m-%d")
                elif interval == "week":
                    key = f"{dt.year}-W{dt.isocalendar()[1]}"
                elif interval == "month":
                    key = dt.strftime("%Y-%m")
                else:
                    key = dt.strftime("%Y-%m-%d")
                
                if key not in time_groups:
                    time_groups[key] = []
                time_groups[key].append(record)
            except:
                pass
        
        for key, records in sorted(time_groups.items()):
            parts.append({
                "name": f"time_{key}",
                "count": len(records),
                "data": records
            })
    
    elif split_by == "count":
        # 按数量分割
        chunk_size = params.get("chunk_size", 100)
        for i in range(0, len(QUALITY_HISTORY), chunk_size):
            chunk = QUALITY_HISTORY[i:i + chunk_size]
            parts.append({
                "name": f"part_{i // chunk_size + 1}",
                "count": len(chunk),
                "data": chunk
            })
    
    elif split_by == "random":
        # 随机分割
        import random
        n_parts = params.get("n_parts", 2)
        shuffled = list(QUALITY_HISTORY)
        random.shuffle(shuffled)
        
        part_size = len(shuffled) // n_parts
        for i in range(n_parts):
            start = i * part_size
            end = start + part_size if i < n_parts - 1 else len(shuffled)
            parts.append({
                "name": f"random_part_{i + 1}",
                "count": end - start,
                "data": shuffled[start:end]
            })
    
    # 更新统计
    QUALITY_SPLIT["split_stats"]["total_splits"] += 1
    QUALITY_SPLIT["split_stats"]["last_split"] = datetime.now().isoformat()
    QUALITY_SPLIT["split_stats"]["total_parts_created"] += len(parts)
    
    QUALITY_SPLIT["split_log"].append({
        "split_by": split_by,
        "parts_count": len(parts),
        "total_records": len(QUALITY_HISTORY),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "split_by": split_by,
        "parts_count": len(parts),
        "parts": [{"name": p["name"], "count": p["count"]} for p in parts],
        "total_records": len(QUALITY_HISTORY),
        "split_at": datetime.now().isoformat()
    }

