# 质量评分数据采样配置
QUALITY_SAMPLE = {
    "enabled": True,
    "sample_stats": {
        "total_samples": 0,
        "last_sample": None,
        "total_records_sampled": 0
    },
    "sample_log": []
}

@app.post("/api/quality/sample")
async def sample_quality_data(request: Request):
    """采样质量评分数据"""
    from datetime import datetime
    import random
    
    data = await request.json()
    method = data.get("method", "random")  # random, stratified, systematic, cluster
    sample_size = data.get("sample_size", 100)
    params = data.get("params", {})
    
    sampled_data = []
    
    if method == "random":
        # 简单随机采样
        population = list(QUALITY_HISTORY)
        if sample_size >= len(population):
            sampled_data = population
        else:
            sampled_data = random.sample(population, sample_size)
    
    elif method == "stratified":
        # 分层采样 - 按问题类型分层
        strata = {}
        for record in QUALITY_HISTORY:
            qtype = record.get("question_type", "unknown")
            if qtype not in strata:
                strata[qtype] = []
            strata[qtype].append(record)
        
        # 按比例采样
        total = len(QUALITY_HISTORY)
        for qtype, records in strata.items():
            stratum_size = max(1, int(sample_size * len(records) / total))
            if len(records) <= stratum_size:
                sampled_data.extend(records)
            else:
                sampled_data.extend(random.sample(records, stratum_size))
    
    elif method == "systematic":
        # 系统采样
        population = list(QUALITY_HISTORY)
        if len(population) == 0:
            pass
        elif sample_size >= len(population):
            sampled_data = population
        else:
            step = len(population) // sample_size
            start = random.randint(0, step - 1)
            for i in range(start, len(population), step):
                if len(sampled_data) < sample_size:
                    sampled_data.append(population[i])
    
    elif method == "cluster":
        # 聚类采样 - 按时间聚类
        cluster_by = params.get("cluster_by", "day")
        clusters = {}
        
        for record in QUALITY_HISTORY:
            timestamp = record.get("timestamp", "")
            if not timestamp:
                continue
            
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if cluster_by == "day":
                    key = dt.strftime("%Y-%m-%d")
                elif cluster_by == "week":
                    key = f"{dt.year}-W{dt.isocalendar()[1]}"
                elif cluster_by == "month":
                    key = dt.strftime("%Y-%m")
                else:
                    key = dt.strftime("%Y-%m-%d")
                
                if key not in clusters:
                    clusters[key] = []
                clusters[key].append(record)
            except:
                pass
        
        # 随机选择若干聚类
        cluster_keys = list(clusters.keys())
        n_clusters = params.get("n_clusters", 3)
        if cluster_keys:
            selected_clusters = random.sample(cluster_keys, min(n_clusters, len(cluster_keys)))
            for key in selected_clusters:
                sampled_data.extend(clusters[key])
    
    elif method == "score_based":
        # 按分数分层采样
        score_ranges = params.get("ranges", [(0, 50), (50, 75), (75, 100)])
        samples_per_range = sample_size // len(score_ranges)
        
        for min_score, max_score in score_ranges:
            range_records = [r for r in QUALITY_HISTORY 
                           if min_score <= r.get("score", 0) < max_score]
            if range_records:
                n = min(samples_per_range, len(range_records))
                sampled_data.extend(random.sample(range_records, n))
    
    # 更新统计
    QUALITY_SAMPLE["sample_stats"]["total_samples"] += 1
    QUALITY_SAMPLE["sample_stats"]["last_sample"] = datetime.now().isoformat()
    QUALITY_SAMPLE["sample_stats"]["total_records_sampled"] += len(sampled_data)
    
    QUALITY_SAMPLE["sample_log"].append({
        "method": method,
        "sample_size": sample_size,
        "actual_size": len(sampled_data),
        "total_records": len(QUALITY_HISTORY),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "method": method,
        "sample_size": len(sampled_data),
        "data": sampled_data,
        "total_records": len(QUALITY_HISTORY),
        "sampled_at": datetime.now().isoformat()
    }

@app.post("/api/quality/sample/preview")
async def preview_sample(request: Request):
    """预览采样结果"""
    from datetime import datetime
    import random
    
    data = await request.json()
    method = data.get("method", "random")
    sample_size = data.get("sample_size", 100)
    
    preview_info = {
        "method": method,
        "requested_size": sample_size,
        "total_population": len(QUALITY_HISTORY)
    }
    
    if method == "random":
        preview_info["description"] = "简单随机采样，每个记录有相同概率被选中"
        preview_info["expected_size"] = min(sample_size, len(QUALITY_HISTORY))
    
    elif method == "stratified":
        # 计算各层大小
        strata_counts = {}
        for record in QUALITY_HISTORY:
            qtype = record.get("question_type", "unknown")
            strata_counts[qtype] = strata_counts.get(qtype, 0) + 1
        
        preview_info["description"] = "分层采样，按问题类型比例采样"
        preview_info["strata"] = strata_counts
    
    elif method == "systematic":
        step = max(1, len(QUALITY_HISTORY) // sample_size)
        preview_info["description"] = "系统采样，每隔N个记录采样一个"
        preview_info["step"] = step
    
    elif method == "cluster":
        preview_info["description"] = "聚类采样，随机选择若干时间聚类"
        preview_info["available_clusters"] = len(set(
            r.get("timestamp", "")[:10] for r in QUALITY_HISTORY if r.get("timestamp")
        ))
    
    elif method == "score_based":
        preview_info["description"] = "按分数分层采样"
        score_distribution = {}
        for record in QUALITY_HISTORY:
            score = record.get("score", 0)
            if score < 50:
                score_distribution["low"] = score_distribution.get("low", 0) + 1
            elif score < 75:
                score_distribution["medium"] = score_distribution.get("medium", 0) + 1
            else:
                score_distribution["high"] = score_distribution.get("high", 0) + 1
        preview_info["score_distribution"] = score_distribution
    
    return {
        "success": True,
        "preview": preview_info,
        "previewed_at": datetime.now().isoformat()
    }

