# 质量评分数据洞察配置
QUALITY_INSIGHT = {
    "enabled": True,
    "insight_stats": {
        "total_insights": 0,
        "last_insight": None
    },
    "insight_log": []
}

@app.post("/api/quality/insight")
async def generate_quality_insight(request: Request):
    """生成质量评分数据洞察"""
    from datetime import datetime
    import statistics
    
    data = await request.json()
    insight_type = data.get("insight_type", "auto")  # auto, patterns, outliers, opportunities
    
    insights = []
    
    if insight_type == "auto" or insight_type == "patterns":
        # 模式识别洞察
        scores = [r.get("score", 0) for r in QUALITY_HISTORY]
        
        if len(scores) >= 5:
            # 识别分数分布模式
            avg_score = statistics.mean(scores)
            stdev = statistics.stdev(scores) if len(scores) > 1 else 0
            
            if stdev < 10:
                insights.append({
                    "type": "pattern",
                    "category": "score_consistency",
                    "title": "分数一致性高",
                    "description": f"质量分数标准差仅{stdev:.1f}，回答质量稳定",
                    "impact": "positive",
                    "confidence": 0.8
                })
            elif stdev > 25:
                insights.append({
                    "type": "pattern",
                    "category": "score_volatility",
                    "title": "分数波动较大",
                    "description": f"质量分数标准差达{stdev:.1f}，存在质量不稳定风险",
                    "impact": "warning",
                    "confidence": 0.7
                })
            
            # 识别问题类型模式
            type_scores = {}
            for record in QUALITY_HISTORY:
                qtype = record.get("question_type", "unknown")
                if qtype not in type_scores:
                    type_scores[qtype] = []
                type_scores[qtype].append(record.get("score", 0))
            
            for qtype, tscores in type_scores.items():
                if len(tscores) >= 3:
                    tavg = statistics.mean(tscores)
                    if tavg > avg_score + 10:
                        insights.append({
                            "type": "pattern",
                            "category": "strong_type",
                            "title": f"{qtype}类型表现优异",
                            "description": f"该类型平均分{tavg:.1f}，高于整体{tavg - avg_score:.1f}分",
                            "impact": "positive",
                            "confidence": 0.75
                        })
                    elif tavg < avg_score - 15:
                        insights.append({
                            "type": "pattern",
                            "category": "weak_type",
                            "title": f"{qtype}类型需要改进",
                            "description": f"该类型平均分{tavg:.1f}，低于整体{avg_score - tavg:.1f}分",
                            "impact": "negative",
                            "confidence": 0.8
                        })
    
    if insight_type == "auto" or insight_type == "outliers":
        # 异常值检测洞察
        scores = [r.get("score", 0) for r in QUALITY_HISTORY]
        
        if len(scores) >= 4:
            q1 = statistics.quantiles(scores, n=4)[0]
            q3 = statistics.quantiles(scores, n=4)[2]
            iqr = q3 - q1
            lower_bound = q1 - 1.5 * iqr
            upper_bound = q3 + 1.5 * iqr
            
            outliers_low = [r for r in QUALITY_HISTORY if r.get("score", 0) < lower_bound]
            outliers_high = [r for r in QUALITY_HISTORY if r.get("score", 0) > upper_bound]
            
            if outliers_low:
                insights.append({
                    "type": "outlier",
                    "category": "low_outliers",
                    "title": f"发现{len(outliers_low)}个低分异常点",
                    "description": f"分数低于{lower_bound:.1f}的异常回答需要关注",
                    "impact": "negative",
                    "confidence": 0.85,
                    "affected_records": len(outliers_low)
                })
            
            if outliers_high:
                insights.append({
                    "type": "outlier",
                    "category": "high_outliers",
                    "title": f"发现{len(outliers_high)}个高分亮点",
                    "description": f"分数高于{upper_bound:.1f}的优秀回答可作为参考",
                    "impact": "positive",
                    "confidence": 0.85,
                    "affected_records": len(outliers_high)
                })
    
    if insight_type == "auto" or insight_type == "opportunities":
        # 改进机会洞察
        scores = [r.get("score", 0) for r in QUALITY_HISTORY]
        
        if scores:
            avg_score = statistics.mean(scores)
            
            # 识别改进空间
            low_quality = [r for r in QUALITY_HISTORY if r.get("score", 0) < 50]
            if len(low_quality) > len(QUALITY_HISTORY) * 0.2:
                insights.append({
                    "type": "opportunity",
                    "category": "quality_improvement",
                    "title": "质量提升空间大",
                    "description": f"{len(low_quality)}条回答低于50分，建议针对性优化",
                    "impact": "opportunity",
                    "confidence": 0.9,
                    "potential_gain": len(low_quality) * 25  # 假设每条提升25分
                })
            
            # 时间趋势机会
            if len(QUALITY_HISTORY) >= 10:
                recent = QUALITY_HISTORY[-5:]
                earlier = QUALITY_HISTORY[-10:-5]
                recent_avg = statistics.mean([r.get("score", 0) for r in recent])
                earlier_avg = statistics.mean([r.get("score", 0) for r in earlier])
                
                if recent_avg < earlier_avg - 5:
                    insights.append({
                        "type": "opportunity",
                        "category": "trend_reversal",
                        "title": "近期质量下降趋势",
                        "description": f"最近5条平均分较前5条下降{earlier_avg - recent_avg:.1f}分",
                        "impact": "warning",
                        "confidence": 0.7
                    })
                elif recent_avg > earlier_avg + 5:
                    insights.append({
                        "type": "opportunity",
                        "category": "positive_trend",
                        "title": "质量持续改善",
                        "description": f"最近5条平均分较前5条提升{recent_avg - earlier_avg:.1f}分",
                        "impact": "positive",
                        "confidence": 0.8
                    })
    
    # 更新统计
    QUALITY_INSIGHT["insight_stats"]["total_insights"] += 1
    QUALITY_INSIGHT["insight_stats"]["last_insight"] = datetime.now().isoformat()
    
    QUALITY_INSIGHT["insight_log"].append({
        "insight_type": insight_type,
        "insights_count": len(insights),
        "timestamp": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "insight_type": insight_type,
        "insights": insights,
        "total_insights": len(insights),
        "generated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/insight/recommend")
async def get_insight_recommendations(request: Request):
    """基于洞察获取改进建议"""
    from datetime import datetime
    import statistics
    
    data = await request.json()
    focus_area = data.get("focus_area", "all")  # all, quality, efficiency, coverage
    
    recommendations = []
    
    scores = [r.get("score", 0) for r in QUALITY_HISTORY]
    
    if scores:
        avg_score = statistics.mean(scores)
        
        # 质量相关建议
        if focus_area in ["all", "quality"]:
            if avg_score < 60:
                recommendations.append({
                    "area": "quality",
                    "priority": "high",
                    "title": "整体质量需提升",
                    "description": "当前平均分低于60分，建议系统性优化回答策略",
                    "actions": [
                        "分析低分回答的共同特征",
                        "优化prompt模板",
                        "增加回答验证机制"
                    ],
                    "expected_impact": "预计可提升15-20分"
                })
            elif avg_score < 75:
                recommendations.append({
                    "area": "quality",
                    "priority": "medium",
                    "title": "质量有提升空间",
                    "description": "当前质量处于中等水平，可通过细节优化提升",
                    "actions": [
                        "针对弱项问题类型进行专项优化",
                        "完善回答结构模板"
                    ],
                    "expected_impact": "预计可提升5-10分"
                })
        
        # 效率相关建议
        if focus_area in ["all", "efficiency"]:
            # 分析问题类型分布
            type_counts = {}
            for record in QUALITY_HISTORY:
                qtype = record.get("question_type", "unknown")
                type_counts[qtype] = type_counts.get(qtype, 0) + 1
            
            if type_counts:
                dominant_type = max(type_counts, key=type_counts.get)
                dominant_ratio = type_counts[dominant_type] / len(QUALITY_HISTORY)
                
                if dominant_ratio > 0.5:
                    recommendations.append({
                        "area": "efficiency",
                        "priority": "medium",
                        "title": f"{dominant_type}类型占比较高",
                        "description": f"该类型占比{dominant_ratio*100:.1f}%，可考虑优化专项处理",
                        "actions": [
                            f"为{dominant_type}类型创建专用处理流程",
                            "缓存常见问题的标准答案"
                        ],
                        "expected_impact": "预计可提升响应速度20%"
                    })
        
        # 覆盖相关建议
        if focus_area in ["all", "coverage"]:
            # 分析问题类型覆盖
            known_types = ["factual", "conceptual", "procedural", "analytical", "creative"]
            found_types = set(r.get("question_type", "unknown") for r in QUALITY_HISTORY)
            missing_types = set(known_types) - found_types
            
            if missing_types:
                recommendations.append({
                    "area": "coverage",
                    "priority": "low",
                    "title": "部分问题类型未覆盖",
                    "description": f"缺少的类型: {', '.join(missing_types)}",
                    "actions": [
                        "扩展问题类型识别能力",
                        "补充缺失类型的处理模板"
                    ],
                    "expected_impact": "提升系统全面性"
                })
    
    return {
        "success": True,
        "focus_area": focus_area,
        "recommendations": recommendations,
        "total_recommendations": len(recommendations),
        "generated_at": datetime.now().isoformat()
    }

