@app.post("/api/quality/insight/summary")
async def get_insight_summary(request: Request):
    """获取洞察摘要"""
    from datetime import datetime
    import statistics
    
    data = await request.json()
    period = data.get("period", "all")  # all, day, week, month
    
    # 过滤数据
    filtered_data = QUALITY_HISTORY
    if period != "all":
        now = datetime.now()
        for record in QUALITY_HISTORY:
            timestamp = record.get("timestamp", "")
            if timestamp:
                try:
                    dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                    if period == "day" and (now - dt).days < 1:
                        pass
                    elif period == "week" and (now - dt).days < 7:
                        pass
                    elif period == "month" and (now - dt).days < 30:
                        pass
                    else:
                        continue
                except:
                    pass
    
    scores = [r.get("score", 0) for r in filtered_data]
    
    summary = {
        "period": period,
        "total_records": len(filtered_data),
        "generated_at": datetime.now().isoformat()
    }
    
    if scores:
        avg_score = statistics.mean(scores)
        summary["metrics"] = {
            "avg_score": round(avg_score, 2),
            "median_score": round(statistics.median(scores), 2),
            "min_score": min(scores),
            "max_score": max(scores)
        }
        
        # 质量等级分布
        high = sum(1 for s in scores if s >= 75)
        medium = sum(1 for s in scores if 50 <= s < 75)
        low = sum(1 for s in scores if s < 50)
        
        summary["distribution"] = {
            "high_quality": {"count": high, "percentage": round(high/len(scores)*100, 1)},
            "medium_quality": {"count": medium, "percentage": round(medium/len(scores)*100, 1)},
            "low_quality": {"count": low, "percentage": round(low/len(scores)*100, 1)}
        }
        
        # 关键洞察
        summary["key_insights"] = []
        
        if avg_score >= 75:
            summary["key_insights"].append("整体质量优秀")
        elif avg_score >= 50:
            summary["key_insights"].append("整体质量良好，有提升空间")
        else:
            summary["key_insights"].append("整体质量需要改进")
        
        if low > len(scores) * 0.2:
            summary["key_insights"].append(f"低质量回答占比{round(low/len(scores)*100,1)}%，需要关注")
        
        # 改进建议
        summary["recommendations"] = []
        if avg_score < 70:
            summary["recommendations"].append("建议系统性优化回答策略")
        if low > 0:
            summary["recommendations"].append(f"分析{low}条低分回答的原因")
    
    return {
        "success": True,
        "summary": summary
    }

