@app.post("/api/quality/annotation")
async def create_annotation(request: Request):
    """创建质量评分数据标注"""
    from datetime import datetime
    
    data = await request.json()
    record_id = data.get("record_id")
    labels = data.get("labels", [])
    comment = data.get("comment", "")
    annotator = data.get("annotator", "system")
    
    # 查找记录
    record = None
    for r in QUALITY_HISTORY:
        if r.get("id") == record_id:
            record = r
            break
    
    if not record:
        return {
            "success": False,
            "error": "记录不存在"
        }
    
    # 创建标注
    annotation = {
        "id": len(QUALITY_ANNOTATION["annotation_log"]) + 1,
        "record_id": record_id,
        "labels": labels,
        "comment": comment,
        "annotator": annotator,
        "status": "pending",
        "created_at": datetime.now().isoformat(),
        "updated_at": datetime.now().isoformat()
    }
    
    # 添加到记录
    if "annotations" not in record:
        record["annotations"] = []
    record["annotations"].append(annotation)
    
    # 更新统计
    QUALITY_ANNOTATION["annotation_log"].append(annotation)
    QUALITY_ANNOTATION["annotation_stats"]["total_annotations"] += 1
    QUALITY_ANNOTATION["annotation_stats"]["pending_annotations"] += 1
    
    return {
        "success": True,
        "annotation": annotation,
        "annotated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/annotation/batch")
async def batch_create_annotations(request: Request):
    """批量创建标注"""
    from datetime import datetime
    
    data = await request.json()
    annotations = data.get("annotations", [])
    
    created = []
    for ann in annotations:
        record_id = ann.get("record_id")
        labels = ann.get("labels", [])
        comment = ann.get("comment", "")
        annotator = ann.get("annotator", "system")
        
        # 查找记录
        record = None
        for r in QUALITY_HISTORY:
            if r.get("id") == record_id:
                record = r
                break
        
        if record:
            annotation = {
                "id": len(QUALITY_ANNOTATION["annotation_log"]) + 1,
                "record_id": record_id,
                "labels": labels,
                "comment": comment,
                "annotator": annotator,
                "status": "pending",
                "created_at": datetime.now().isoformat(),
                "updated_at": datetime.now().isoformat()
            }
            
            if "annotations" not in record:
                record["annotations"] = []
            record["annotations"].append(annotation)
            
            QUALITY_ANNOTATION["annotation_log"].append(annotation)
            QUALITY_ANNOTATION["annotation_stats"]["total_annotations"] += 1
            QUALITY_ANNOTATION["annotation_stats"]["pending_annotations"] += 1
            
            created.append(annotation)
    
    return {
        "success": True,
        "total_requested": len(annotations),
        "total_created": len(created),
        "annotations": created,
        "annotated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/annotation/approve")
async def approve_annotation(request: Request):
    """批准标注"""
    from datetime import datetime
    
    data = await request.json()
    annotation_id = data.get("annotation_id")
    reviewer = data.get("reviewer", "system")
    
    # 查找标注
    annotation = None
    for ann in QUALITY_ANNOTATION["annotation_log"]:
        if ann.get("id") == annotation_id:
            annotation = ann
            break
    
    if not annotation:
        return {
            "success": False,
            "error": "标注不存在"
        }
    
    # 更新状态
    if annotation["status"] == "pending":
        QUALITY_ANNOTATION["annotation_stats"]["pending_annotations"] -= 1
    elif annotation["status"] == "rejected":
        QUALITY_ANNOTATION["annotation_stats"]["rejected_annotations"] -= 1
    
    annotation["status"] = "approved"
    annotation["reviewer"] = reviewer
    annotation["reviewed_at"] = datetime.now().isoformat()
    annotation["updated_at"] = datetime.now().isoformat()
    
    QUALITY_ANNOTATION["annotation_stats"]["approved_annotations"] += 1
    
    return {
        "success": True,
        "annotation": annotation,
        "approved_at": datetime.now().isoformat()
    }

@app.post("/api/quality/annotation/reject")
async def reject_annotation(request: Request):
    """拒绝标注"""
    from datetime import datetime
    
    data = await request.json()
    annotation_id = data.get("annotation_id")
    reviewer = data.get("reviewer", "system")
    reason = data.get("reason", "")
    
    # 查找标注
    annotation = None
    for ann in QUALITY_ANNOTATION["annotation_log"]:
        if ann.get("id") == annotation_id:
            annotation = ann
            break
    
    if not annotation:
        return {
            "success": False,
            "error": "标注不存在"
        }
    
    # 更新状态
    if annotation["status"] == "pending":
        QUALITY_ANNOTATION["annotation_stats"]["pending_annotations"] -= 1
    elif annotation["status"] == "approved":
        QUALITY_ANNOTATION["annotation_stats"]["approved_annotations"] -= 1
    
    annotation["status"] = "rejected"
    annotation["reviewer"] = reviewer
    annotation["rejection_reason"] = reason
    annotation["reviewed_at"] = datetime.now().isoformat()
