@app.post("/api/quality/annotation/queue")
async def get_annotation_queue(request: Request):
    """获取待标注队列"""
    from datetime import datetime
    
    data = await request.json()
    limit = data.get("limit", 10)
    priority = data.get("priority", "score")  # score, time, random
    
    # 筛选未标注的记录
    unannotated = [r for r in QUALITY_HISTORY if not r.get("annotations")]
    
    # 排序
    if priority == "score":
        # 低分优先
        unannotated.sort(key=lambda x: x.get("score", 0))
    elif priority == "time":
        # 最新优先
        unannotated.sort(key=lambda x: x.get("timestamp", ""), reverse=True)
    elif priority == "random":
        import random
        random.shuffle(unannotated)
    
    queue = unannotated[:limit]
    
    return {
        "success": True,
        "total_unannotated": len(unannotated),
        "queue": queue,
        "priority": priority,
        "checked_at": datetime.now().isoformat()
    }

@app.post("/api/quality/annotation/export")
async def export_annotations(request: Request):
    """导出标注数据"""
    from datetime import datetime
    
    data = await request.json()
    format = data.get("format", "json")  # json, csv
    status = data.get("status")  # all, approved, rejected, pending
    
    # 筛选标注
    annotations = QUALITY_ANNOTATION["annotation_log"]
    
    if status and status != "all":
        annotations = [a for a in annotations if a.get("status") == status]
    
    if format == "json":
        export_data = {
            "annotations": annotations,
            "stats": QUALITY_ANNOTATION["annotation_stats"],
            "exported_at": datetime.now().isoformat()
        }
    else:
        # CSV格式
        lines = ["id,record_id,labels,comment,annotator,status,created_at"]
        for ann in annotations:
            labels_str = "|".join(ann.get("labels", []))
            lines.append(f"{ann['id']},{ann['record_id']},\"{labels_str}\",\"{ann.get('comment', '')}\",{ann['annotator']},{ann['status']},{ann['created_at']}")
        
        export_data = {
            "format": "csv",
            "content": "\n".join(lines),
            "exported_at": datetime.now().isoformat()
        }
    
    return {
        "success": True,
        "total_annotations": len(annotations),
        "data": export_data,
        "exported_at": datetime.now().isoformat()
    }

@app.post("/api/quality/annotation/summary")
async def get_annotation_summary(request: Request):
    """获取标注摘要"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")  # all, day, week, month
    
    # 筛选时间范围
    now = datetime.now()
    filtered = []
    
    for ann in QUALITY_ANNOTATION["annotation_log"]:
        timestamp = ann.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(ann)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(ann)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(ann)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(ann)
            except:
                pass
    
    # 统计标签使用
    label_counter = Counter()
    for ann in filtered:
        for label in ann.get("labels", []):
            label_counter[label] += 1
    
    # 统计标注者
    annotator_counter = Counter()
    for ann in filtered:
        annotator_counter[ann.get("annotator", "unknown")] += 1
    
    summary = {
        "period": period,
        "total_annotations": len(filtered),
        "by_status": {
            "approved": sum(1 for a in filtered if a.get("status") == "approved"),
            "rejected": sum(1 for a in filtered if a.get("status") == "rejected"),
            "pending": sum(1 for a in filtered if a.get("status") == "pending")
        },
        "by_label": dict(label_counter.most_common(10)),
        "by_annotator": dict(annotator_counter.most_common(10)),
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

