@app.post("/api/quality/classification")
async def classify_record(request: Request):
    """对质量评分数据进行分类"""
    from datetime import datetime
    
    data = await request.json()
    record_id = data.get("record_id")
    category = data.get("category")
    sub_category = data.get("sub_category")
    classifier = data.get("classifier", "manual")
    
    # 查找记录
    record = None
    for r in QUALITY_HISTORY:
        if r.get("id") == record_id:
            record = r
            break
    
    if not record:
        return {
            "success": False,
            "error": "记录不存在"
        }
    
    # 创建分类
    classification = {
        "id": len(QUALITY_CLASSIFICATION["classification_log"]) + 1,
        "record_id": record_id,
        "category": category,
        "sub_category": sub_category,
        "classifier": classifier,
        "classified_at": datetime.now().isoformat()
    }
    
    # 更新记录
    record["classification"] = classification
    
    # 更新统计
    QUALITY_CLASSIFICATION["classification_log"].append(classification)
    QUALITY_CLASSIFICATION["classification_stats"]["total_classifications"] += 1
    if classifier == "auto":
        QUALITY_CLASSIFICATION["classification_stats"]["auto_classified"] += 1
    else:
        QUALITY_CLASSIFICATION["classification_stats"]["manual_classified"] += 1
    
    return {
        "success": True,
        "classification": classification,
        "classified_at": datetime.now().isoformat()
    }

@app.post("/api/quality/classification/auto")
async def auto_classify_records(request: Request):
    """自动分类记录"""
    from datetime import datetime
    
    data = await request.json()
    record_ids = data.get("record_ids", [])
    
    if not record_ids:
        # 如果未指定ID，则分类所有未分类记录
        record_ids = [r.get("id") for r in QUALITY_HISTORY if not r.get("classification")]
    
    classified = []
    for record_id in record_ids:
        # 查找记录
        record = None
        for r in QUALITY_HISTORY:
            if r.get("id") == record_id:
                record = r
                break
        
        if record:
            score = record.get("score", 0)
            question_type = record.get("question_type", "unknown")
            
            # 根据分数确定质量分类
            if score >= 90:
                category = "excellent"
            elif score >= 75:
                category = "good"
            elif score >= 60:
                category = "average"
            else:
                category = "needs_improvement"
            
            # 根据问题类型确定子分类
            type_mapping = {
                "factual": "factual",
                "explanatory": "explanatory",
                "procedural": "procedural",
                "creative": "creative"
            }
            sub_category = type_mapping.get(question_type, "general")
            
            classification = {
                "id": len(QUALITY_CLASSIFICATION["classification_log"]) + 1,
                "record_id": record_id,
                "category": category,
                "sub_category": sub_category,
                "classifier": "auto",
                "classified_at": datetime.now().isoformat()
            }
            
            record["classification"] = classification
            QUALITY_CLASSIFICATION["classification_log"].append(classification)
            QUALITY_CLASSIFICATION["classification_stats"]["total_classifications"] += 1
            QUALITY_CLASSIFICATION["classification_stats"]["auto_classified"] += 1
            
            classified.append(classification)
    
    return {
        "success": True,
        "total_processed": len(record_ids),
        "total_classified": len(classified),
        "classifications": classified,
        "classified_at": datetime.now().isoformat()
    }

