@app.post("/api/quality/classification/distribution")
async def get_classification_distribution(request: Request):
    """获取分类分布"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    dimension = data.get("dimension", "category")  # category, sub_category, score_range
    period = data.get("period", "all")  # all, day, week, month
    
    # 筛选时间范围
    now = datetime.now()
    filtered = []
    
    for cls in QUALITY_CLASSIFICATION["classification_log"]:
        timestamp = cls.get("classified_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(cls)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(cls)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(cls)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(cls)
            except:
                pass
    
    # 计算分布
    if dimension == "category":
        counter = Counter(cls.get("category", "unknown") for cls in filtered)
    elif dimension == "sub_category":
        counter = Counter(cls.get("sub_category", "unknown") for cls in filtered)
    elif dimension == "score_range":
        # 需要查询原始记录获取分数
        counter = Counter()
        for cls in filtered:
            for r in QUALITY_HISTORY:
                if r.get("id") == cls.get("record_id"):
                    score = r.get("score", 0)
                    if score >= 90:
                        counter["90-100"] += 1
                    elif score >= 75:
                        counter["75-89"] += 1
                    elif score >= 60:
                        counter["60-74"] += 1
                    else:
                        counter["0-59"] += 1
                    break
    
    distribution = {
        "dimension": dimension,
        "period": period,
        "total": len(filtered),
        "distribution": dict(counter),
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "distribution": distribution
    }

