@app.post("/api/quality/ranking/percentile")
async def get_percentile_rank(request: Request):
    """获取百分位排名"""
    from datetime import datetime
    
    data = await request.json()
    record_id = data.get("record_id")
    
    # 查找记录
    record = None
    for r in QUALITY_HISTORY:
        if r.get("id") == record_id:
            record = r
            break
    
    if not record:
        return {
            "success": False,
            "error": "记录不存在"
        }
    
    score = record.get("score", 0)
    
    # 计算百分位
    all_scores = [r.get("score", 0) for r in QUALITY_HISTORY]
    if not all_scores:
        percentile = 0
    else:
        lower_count = sum(1 for s in all_scores if s < score)
        percentile = (lower_count / len(all_scores)) * 100
    
    return {
        "success": True,
        "record_id": record_id,
        "score": score,
        "percentile": round(percentile, 2),
        "total_records": len(all_scores),
        "calculated_at": datetime.now().isoformat()
    }

