@app.post("/api/quality/ranking/compare")
async def compare_rankings(request: Request):
    """比较不同排名方法的结果"""
    from datetime import datetime
    
    data = await request.json()
    methods = data.get("methods", ["score", "time", "composite"])
    limit = data.get("limit", 10)
    
    records = QUALITY_HISTORY.copy()
    results = {}
    
    for method in methods:
        method_records = records.copy()
        
        if method == "score":
            method_records.sort(key=lambda x: x.get("score", 0), reverse=True)
        elif method == "time":
            method_records.sort(key=lambda x: x.get("timestamp", ""), reverse=True)
        elif method == "composite":
            now = datetime.now()
            for r in method_records:
                score_norm = r.get("score", 0) / 100.0
                timestamp = r.get("timestamp", "")
                if timestamp:
                    try:
                        dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                        time_norm = 1.0 - min((now - dt).days / 30.0, 1.0)
                    except:
                        time_norm = 0
                else:
                    time_norm = 0
                r["_composite_score"] = score_norm * 0.7 + time_norm * 0.3
            method_records.sort(key=lambda x: x.get("_composite_score", 0), reverse=True)
        
        top_ids = [r.get("id") for r in method_records[:limit]]
        results[method] = top_ids
    
    # 计算方法间重叠度
    overlaps = {}
    for i, m1 in enumerate(methods):
        for m2 in methods[i+1:]:
            set1 = set(results[m1])
            set2 = set(results[m2])
            overlap = len(set1 & set2) / min(len(set1), len(set2)) if set1 and set2 else 0
            overlaps[f"{m1}_vs_{m2}"] = round(overlap, 2)
    
    return {
        "success": True,
        "limit": limit,
        "results": results,
        "overlaps": overlaps,
        "compared_at": datetime.now().isoformat()
    }

@app.post("/api/quality/ranking/summary")
async def get_ranking_summary(request: Request):
    """获取排名摘要"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")  # all, day, week, month
    
    # 筛选时间范围
    now = datetime.now()
    filtered = []
    
    for log in QUALITY_RANKING["ranking_log"]:
        timestamp = log.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(log)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(log)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(log)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(log)
            except:
                pass
    
    # 统计
    method_counter = Counter(log.get("method", "unknown") for log in filtered)
    
    summary = {
        "period": period,
        "total_rankings": len(filtered),
        "by_method": dict(method_counter),
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

