        {"id": "score_correlation", "name": "分数相关性", "description": "分析分数与其他因素的关联"},
        {"id": "type_correlation", "name": "类型相关性", "description": "分析问题类型与质量的关联"},
        {"id": "time_correlation", "name": "时间相关性", "description": "分析时间因素与质量的关联"},
