@app.post("/api/quality/association")
async def create_association(request: Request):
    """创建质量评分数据关联分析"""
    from datetime import datetime
    
    data = await request.json()
    association_type = data.get("type", "score_correlation")
    min_support = data.get("min_support", 0.1)  # 最小支持度
    min_confidence = data.get("min_confidence", 0.5)  # 最小置信度
    
    records = QUALITY_HISTORY.copy()
    associations = []
    
    if association_type == "score_correlation":
        # 分析分数与问题类型的关联
        type_scores = {}
        for r in records:
            qt = r.get("question_type", "unknown")
            score = r.get("score", 0)
            if qt not in type_scores:
                type_scores[qt] = []
            type_scores[qt].append(score)
        
        for qt, scores in type_scores.items():
            if len(scores) >= 3:
                avg_score = sum(scores) / len(scores)
                support = len(scores) / len(records) if records else 0
                if support >= min_support:
                    associations.append({
                        "antecedent": f"问题类型={qt}",
                        "consequent": f"平均分数={round(avg_score, 2)}",
                        "support": round(support, 3),
                        "confidence": round(avg_score / 100, 3),
                        "strength": "strong" if avg_score >= 80 else "weak"
                    })
    
    elif association_type == "type_correlation":
        # 分析问题类型之间的关联
        from collections import Counter
        type_counter = Counter(r.get("question_type", "unknown") for r in records)
        total = len(records)
        
        for qt, count in type_counter.most_common(10):
            support = count / total if total else 0
            if support >= min_support:
                # 找出该类型的高分比例
                type_records = [r for r in records if r.get("question_type") == qt]
                high_score_count = sum(1 for r in type_records if r.get("score", 0) >= 80)
                confidence = high_score_count / count if count else 0
                
                associations.append({
                    "antecedent": f"问题类型={qt}",
                    "consequent": "高质量回答",
                    "support": round(support, 3),
                    "confidence": round(confidence, 3),
                    "strength": "strong" if confidence >= min_confidence else "weak"
                })
    
    elif association_type == "time_correlation":
        # 分析时间段与质量的关联
        time_scores = {"morning": [], "afternoon": [], "evening": [], "night": []}
        
        for r in records:
            timestamp = r.get("timestamp", "")
            if timestamp:
                try:
                    dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                    hour = dt.hour
                    if 6 <= hour < 12:
                        period = "morning"
                    elif 12 <= hour < 18:
                        period = "afternoon"
                    elif 18 <= hour < 22:
                        period = "evening"
                    else:
                        period = "night"
                    time_scores[period].append(r.get("score", 0))
                except:
                    pass
        
        for period, scores in time_scores.items():
            if len(scores) >= 3:
                avg_score = sum(scores) / len(scores)
                support = len(scores) / len(records) if records else 0
                if support >= min_support:
                    associations.append({
                        "antecedent": f"时间段={period}",
                        "consequent": f"平均分数={round(avg_score, 2)}",
                        "support": round(support, 3),
                        "confidence": round(avg_score / 100, 3),
                        "strength": "strong" if avg_score >= 80 else "weak"
                    })
    
    elif association_type == "pattern_mining":
        # 简单的模式挖掘
        # 找出高分回答的共同特征
        high_score_records = [r for r in records if r.get("score", 0) >= 80]
        low_score_records = [r for r in records if r.get("score", 0) < 60]
        
        # 分析高分回答的类型分布
        from collections import Counter
        high_types = Counter(r.get("question_type", "unknown") for r in high_score_records)
        low_types = Counter(r.get("question_type", "unknown") for r in low_score_records)
        
        for qt in set(list(high_types.keys()) + list(low_types.keys())):
            high_count = high_types.get(qt, 0)
            low_count = low_types.get(qt, 0)
            total = high_count + low_count
            
            if total >= 3:
                confidence = high_count / total
                support = total / len(records) if records else 0
                
                if support >= min_support and confidence >= min_confidence:
                    associations.append({
                        "antecedent": f"问题类型={qt}",
                        "consequent": "高分概率高",
                        "support": round(support, 3),
                        "confidence": round(confidence, 3),
                        "lift": round(confidence / (len(high_score_records) / len(records) if records else 1), 3),
                        "strength": "strong"
                    })
    
    # 统计关联强度
    strong_count = sum(1 for a in associations if a.get("strength") == "strong")
    weak_count = len(associations) - strong_count
    
    # 记录关联分析
    association_record = {
        "id": len(QUALITY_ASSOCIATION["association_log"]) + 1,
        "type": association_type,
        "min_support": min_support,
        "min_confidence": min_confidence,
        "total_associations": len(associations),
        "strong_associations": strong_count,
        "weak_associations": weak_count,
        "created_at": datetime.now().isoformat()
    }
    
    QUALITY_ASSOCIATION["association_log"].append(association_record)
    QUALITY_ASSOCIATION["association_stats"]["total_associations"] += len(associations)
    QUALITY_ASSOCIATION["association_stats"]["strong_associations"] += strong_count
    QUALITY_ASSOCIATION["association_stats"]["weak_associations"] += weak_count
    
    return {
        "success": True,
        "type": association_type,
        "associations": associations,
        "stats": {
            "total": len(associations),
            "strong": strong_count,
            "weak": weak_count
        },
        "analyzed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/association/rules")
async def get_association_rules(request: Request):
    """获取关联规则"""
    from datetime import datetime
    
    data = await request.json()
    min_support = data.get("min_support", 0.1)
    min_confidence = data.get("min_confidence", 0.5)
    min_lift = data.get("min_lift", 1.0)
    
    records = QUALITY_HISTORY.copy()
    rules = []
    
    # 生成关联规则
    # 规则1: 问题类型 -> 质量等级
    from collections import Counter
    type_quality = {}
    for r in records:
        qt = r.get("question_type", "unknown")
        score = r.get("score", 0)
        quality = "high" if score >= 80 else ("medium" if score >= 60 else "low")
        key = (qt, quality)
        type_quality[key] = type_quality.get(key, 0) + 1
    
    type_counts = Counter(r.get("question_type", "unknown") for r in records)
    quality_counts = Counter(
        "high" if r.get("score", 0) >= 80 else ("medium" if r.get("score", 0) >= 60 else "low")
        for r in records
    )
    total = len(records)
    
    for (qt, quality), count in type_quality.items():
        support = count / total if total else 0
        confidence = count / type_counts.get(qt, 1) if type_counts.get(qt, 0) > 0 else 0
        lift = confidence / (quality_counts.get(quality, 0) / total if total else 1)
        
        if support >= min_support and confidence >= min_confidence and lift >= min_lift:
            rules.append({
                "rule_id": f"R{len(rules) + 1}",
                "antecedent": {"question_type": qt},
                "consequent": {"quality_level": quality},
                "support": round(support, 3),
                "confidence": round(confidence, 3),
                "lift": round(lift, 3),
                "interestingness": round(support * confidence * lift, 4)
            })
    
    # 按有趣度排序
    rules.sort(key=lambda x: x.get("interestingness", 0), reverse=True)
    
    return {
        "success": True,
        "total_rules": len(rules),
        "rules": rules[:50],  # 返回前50条规则
        "generated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/association/graph")
async def get_association_graph(request: Request):
    """获取关联图数据"""
    from datetime import datetime
    
    data = await request.json()
    min_support = data.get("min_support", 0.05)
    
    records = QUALITY_HISTORY.copy()
    
    # 构建节点
    nodes = []
    edges = []
    node_set = set()
    
    # 问题类型节点
    from collections import Counter
    type_counter = Counter(r.get("question_type", "unknown") for r in records)
    for qt, count in type_counter.items():
        if count / len(records) >= min_support if records else False:
            nodes.append({
                "id": f"type_{qt}",
                "label": qt,
                "type": "question_type",
                "count": count
            })
            node_set.add(f"type_{qt}")
    
    # 质量等级节点
    quality_counter = Counter(
        "high" if r.get("score", 0) >= 80 else ("medium" if r.get("score", 0) >= 60 else "low")
        for r in records
    )
    for quality, count in quality_counter.items():
        nodes.append({
            "id": f"quality_{quality}",
            "label": quality,
            "type": "quality_level",
            "count": count
        })
        node_set.add(f"quality_{quality}")
    
    # 构建边
    type_quality = {}
    for r in records:
        qt = r.get("question_type", "unknown")
        score = r.get("score", 0)
        quality = "high" if score >= 80 else ("medium" if score >= 60 else "low")
        key = (qt, quality)
        type_quality[key] = type_quality.get(key, 0) + 1
    
    for (qt, quality), count in type_quality.items():
        source = f"type_{qt}"
        target = f"quality_{quality}"
        if source in node_set and target in node_set:
            edges.append({
                "source": source,
                "target": target,
                "weight": count,
                "support": round(count / len(records), 3) if records else 0
            })
    
    return {
        "success": True,
        "graph": {
            "nodes": nodes,
            "edges": edges
        },
        "stats": {
            "node_count": len(nodes),
            "edge_count": len(edges)
        },
        "generated_at": datetime.now().isoformat()
    }

