@app.post("/api/quality/association/matrix")
async def get_association_matrix(request: Request):
    """获取关联矩阵"""
    from datetime import datetime
    
    data = await request.json()
    dimensions = data.get("dimensions", ["question_type", "quality_level"])
    
    records = QUALITY_HISTORY.copy()
    
    # 构建矩阵
    dim1_values = set()
    dim2_values = set()
    matrix_data = {}
    
    for r in records:
        # 获取维度值
        if dimensions[0] == "question_type":
            val1 = r.get("question_type", "unknown")
        elif dimensions[0] == "quality_level":
            val1 = "high" if r.get("score", 0) >= 80 else ("medium" if r.get("score", 0) >= 60 else "low")
        else:
            val1 = "unknown"
        
        if dimensions[1] == "question_type":
            val2 = r.get("question_type", "unknown")
        elif dimensions[1] == "quality_level":
            val2 = "high" if r.get("score", 0) >= 80 else ("medium" if r.get("score", 0) >= 60 else "low")
        else:
            val2 = "unknown"
        
        dim1_values.add(val1)
        dim2_values.add(val2)
        
        key = (val1, val2)
        matrix_data[key] = matrix_data.get(key, 0) + 1
    
    # 构建矩阵结构
    matrix = {
        "rows": sorted(list(dim1_values)),
        "columns": sorted(list(dim2_values)),
        "data": []
    }
    
    for row in matrix["rows"]:
        row_data = []
        for col in matrix["columns"]:
            row_data.append(matrix_data.get((row, col), 0))
        matrix["data"].append(row_data)
    
    return {
        "success": True,
        "dimensions": dimensions,
        "matrix": matrix,
        "generated_at": datetime.now().isoformat()
    }

