@app.post("/api/quality/clustering/centers")
async def get_cluster_centers(request: Request):
    """获取聚类中心"""
    from datetime import datetime
    
    data = await request.json()
    method = data.get("method", "score_based")
    n_clusters = data.get("n_clusters", 3)
    
    records = QUALITY_HISTORY.copy()
    centers = []
    
    if method == "score_based":
        step = 100 // n_clusters
        for i in range(n_clusters):
            min_score = i * step
            max_score = (i + 1) * step if i < n_clusters - 1 else 100
            center = (min_score + max_score) / 2
            centers.append({
                "cluster_id": i + 1,
                "center_score": center,
                "range": {"min": min_score, "max": max_score}
            })
    
    elif method == "type_based":
        from collections import Counter
        type_counter = Counter(r.get("question_type", "unknown") for r in records)
        for i, (qt, count) in enumerate(type_counter.most_common(n_clusters)):
            type_records = [r for r in records if r.get("question_type") == qt]
            avg_score = sum(r.get("score", 0) for r in type_records) / len(type_records) if type_records else 0
            centers.append({
                "cluster_id": i + 1,
                "question_type": qt,
                "center_score": round(avg_score, 2),
                "count": count
            })
    
    return {
        "success": True,
        "method": method,
        "n_clusters": n_clusters,
        "centers": centers,
        "retrieved_at": datetime.now().isoformat()
    }

