@app.post("/api/quality/clustering/evaluate")
async def evaluate_clustering(request: Request):
    """评估聚类质量"""
    from datetime import datetime
    
    data = await request.json()
    clusters = data.get("clusters", [])
    
    if not clusters:
        records = QUALITY_HISTORY.copy()
        # 使用默认聚类
        n_clusters = data.get("n_clusters", 3)
        step = 100 // n_clusters
        clusters = []
        for i in range(n_clusters):
            min_s = i * step
            max_s = (i + 1) * step if i < n_clusters - 1 else 100
            cluster_records = [r for r in records if min_s <= r.get("score", 0) < max_s or (i == n_clusters - 1 and r.get("score", 0) == 100)]
            clusters.append(cluster_records)
    
    # 计算聚类评估指标
    # 1. 簇内距离（越小越好）
    intra_distances = []
    for cluster in clusters:
        if cluster and len(cluster) > 1:
            scores = [r.get("score", 0) for r in cluster]
            avg = sum(scores) / len(scores)
            distance = sum((s - avg) ** 2 for s in scores) / len(scores)
            intra_distances.append(distance)
    
    avg_intra = sum(intra_distances) / len(intra_distances) if intra_distances else 0
    
    # 2. 簇间距离（越大越好）
    inter_distances = []
    cluster_avgs = []
    for cluster in clusters:
        if cluster:
            avg = sum(r.get("score", 0) for r in cluster) / len(cluster)
            cluster_avgs.append(avg)
    
    for i in range(len(cluster_avgs)):
        for j in range(i + 1, len(cluster_avgs)):
            inter_distances.append(abs(cluster_avgs[i] - cluster_avgs[j]))
    
    avg_inter = sum(inter_distances) / len(inter_distances) if inter_distances else 0
    
    # 3. 轮廓系数（简化版）
    silhouette = (avg_inter - avg_intra) / max(avg_inter, avg_intra) if max(avg_inter, avg_intra) > 0 else 0
    
    return {
        "success": True,
        "evaluation": {
            "intra_distance": round(avg_intra, 4),
            "inter_distance": round(avg_inter, 4),
            "silhouette": round(silhouette, 4),
            "quality": "good" if silhouette > 0.5 else ("medium" if silhouette > 0 else "poor")
        },
        "evaluated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/clustering/summary")
async def get_clustering_summary(request: Request):
    """获取聚类摘要"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")  # all, day, week, month
    
    # 筛选时间范围
    now = datetime.now()
    filtered = []
    
    for log in QUALITY_CLUSTERING["clustering_log"]:
        timestamp = log.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(log)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(log)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(log)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(log)
            except:
                pass
    
    # 统计
    method_counter = Counter(log.get("method", "unknown") for log in filtered)
    
    summary = {
        "period": period,
        "total_clusterings": len(filtered),
        "by_method": dict(method_counter),
        "total_clusters": sum(log.get("actual_clusters", 0) for log in filtered),
        "total_records_clustered": sum(log.get("total_records", 0) for log in filtered),
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

