@app.post("/api/quality/recommendation")
async def create_recommendation(request: Request):
    """创建质量评分数据推荐"""
    from datetime import datetime
    
    data = await request.json()
    rec_type = data.get("type", "similar_score")  # similar_score, similar_type, high_quality, trending, personalized
    target_id = data.get("target_id")  # 目标记录ID
    limit = data.get("limit", 10)
    
    records = QUALITY_HISTORY.copy()
    recommendations = []
    
    # 查找目标记录
    target_record = None
    if target_id:
        for r in records:
            if r.get("id") == target_id:
                target_record = r
                break
    
    if rec_type == "similar_score" and target_record:
        # 相似分数推荐
        target_score = target_record.get("score", 0)
        similar_records = []
        for r in records:
            if r.get("id") != target_id:
                score_diff = abs(r.get("score", 0) - target_score)
                similar_records.append((r, score_diff))
        
        # 按分数差异排序
        similar_records.sort(key=lambda x: x[1])
        for r, diff in similar_records[:limit]:
            recommendations.append({
                "record_id": r.get("id"),
                "score": r.get("score", 0),
                "question_type": r.get("question_type", "unknown"),
                "similarity": round(1 - diff / 100, 4) if diff <= 100 else 0,
                "reason": f"分数相近(差异: {round(diff, 2)})"
            })
    
    elif rec_type == "similar_type" and target_record:
        # 相似类型推荐
        target_type = target_record.get("question_type", "unknown")
        type_records = [r for r in records if r.get("question_type") == target_type and r.get("id") != target_id]
        
        # 按分数排序
        type_records.sort(key=lambda x: x.get("score", 0), reverse=True)
        for r in type_records[:limit]:
            recommendations.append({
                "record_id": r.get("id"),
                "score": r.get("score", 0),
                "question_type": r.get("question_type", "unknown"),
                "reason": f"相同问题类型: {target_type}"
            })
    
    elif rec_type == "high_quality":
        # 高质量推荐
        high_quality_records = [r for r in records if r.get("score", 0) >= 80]
        high_quality_records.sort(key=lambda x: x.get("score", 0), reverse=True)
        
        for r in high_quality_records[:limit]:
            recommendations.append({
                "record_id": r.get("id"),
                "score": r.get("score", 0),
                "question_type": r.get("question_type", "unknown"),
                "reason": "高质量评分记录"
            })
    
    elif rec_type == "trending":
        # 趋势推荐（近期高分记录）
        now = datetime.now()
        recent_records = []
        for r in records:
            timestamp = r.get("timestamp", "")
            if timestamp:
                try:
                    dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                    days_ago = (now - dt).days
                    if days_ago <= 7:  # 最近7天
                        recent_records.append((r, days_ago))
                except:
                    pass
        
        # 按时间新鲜度和分数排序
        recent_records.sort(key=lambda x: (x[1], -x[0].get("score", 0)))
        for r, days_ago in recent_records[:limit]:
            recommendations.append({
                "record_id": r.get("id"),
                "score": r.get("score", 0),
                "question_type": r.get("question_type", "unknown"),
                "days_ago": days_ago,
                "reason": f"近期热门({days_ago}天前)"
            })
    
    elif rec_type == "personalized":
        # 个性化推荐（基于用户历史偏好）
        user_preferences = data.get("user_preferences", {})
        preferred_types = user_preferences.get("preferred_types", [])
        min_score = user_preferences.get("min_score", 70)
        
        # 筛选符合偏好的记录
        personalized_records = []
        for r in records:
            if r.get("score", 0) >= min_score:
                if not preferred_types or r.get("question_type") in preferred_types:
                    personalized_records.append(r)
        
        # 按分数排序
        personalized_records.sort(key=lambda x: x.get("score", 0), reverse=True)
        for r in personalized_records[:limit]:
            recommendations.append({
                "record_id": r.get("id"),
                "score": r.get("score", 0),
                "question_type": r.get("question_type", "unknown"),
                "reason": "符合您的偏好设置"
            })
    
    # 记录推荐操作
    recommendation_record = {
        "id": len(QUALITY_RECOMMENDATION["recommendation_log"]) + 1,
        "type": rec_type,
        "target_id": target_id,
        "recommendations_count": len(recommendations),
        "created_at": datetime.now().isoformat()
    }
    
    QUALITY_RECOMMENDATION["recommendation_log"].append(recommendation_record)
    QUALITY_RECOMMENDATION["recommendation_stats"]["total_recommendations"] += 1
    QUALITY_RECOMMENDATION["recommendation_stats"]["total_records_recommended"] += len(recommendations)
    
    return {
        "success": True,
        "type": rec_type,
        "target_id": target_id,
        "recommendations": recommendations,
        "stats": {
            "total": len(recommendations)
        },
        "recommended_at": datetime.now().isoformat()
    }

@app.post("/api/quality/recommendation/similar")
async def get_similar_records(request: Request):
    """获取相似记录"""
    from datetime import datetime
    
    data = await request.json()
    record_id = data.get("record_id")
    limit = data.get("limit", 5)
    by = data.get("by", "score")  # score, type, both
    
    records = QUALITY_HISTORY.copy()
    
    # 查找目标记录
    target_record = None
    for r in records:
        if r.get("id") == record_id:
            target_record = r
            break
    
    if not target_record:
        return {
            "success": False,
            "error": "记录不存在"
        }
    
    similar_records = []
    target_score = target_record.get("score", 0)
    target_type = target_record.get("question_type", "unknown")
    
    for r in records:
        if r.get("id") == record_id:
            continue
        
        score_similarity = 1 - abs(r.get("score", 0) - target_score) / 100
        type_similarity = 1 if r.get("question_type") == target_type else 0
        
        if by == "score":
            similarity = score_similarity
        elif by == "type":
            similarity = type_similarity
        else:  # both
            similarity = score_similarity * 0.7 + type_similarity * 0.3
        
        similar_records.append({
            "record": r,
            "similarity": similarity,
            "score_similarity": round(score_similarity, 4),
            "type_similarity": type_similarity
        })
    
    # 按相似度排序
    similar_records.sort(key=lambda x: x["similarity"], reverse=True)
    
    result = []
    for item in similar_records[:limit]:
        result.append({
            "record_id": item["record"].get("id"),
            "score": item["record"].get("score", 0),
            "question_type": item["record"].get("question_type", "unknown"),
            "similarity": round(item["similarity"], 4)
        })
    
    return {
        "success": True,
        "record_id": record_id,
        "by": by,
        "similar_records": result,
        "retrieved_at": datetime.now().isoformat()
    }

@app.post("/api/quality/recommendation/personalized")
async def get_personalized_recommendations(request: Request):
    """获取个性化推荐"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    user_id = data.get("user_id")
    limit = data.get("limit", 10)
    
    # 获取用户历史偏好（简化：基于历史记录分析）
    records = QUALITY_HISTORY.copy()
    
    # 分析用户偏好
    type_counter = Counter(r.get("question_type", "unknown") for r in records)
    preferred_types = [t for t, _ in type_counter.most_common(3)]
    avg_score = sum(r.get("score", 0) for r in records) / len(records) if records else 70
    
    # 生成推荐
    recommendations = []
    for r in records:
        score = r.get("score", 0)
        qt = r.get("question_type", "unknown")
        
        # 计算推荐分数
        rec_score = 0
        if score >= avg_score:
            rec_score += 0.5
        if qt in preferred_types:
            rec_score += 0.3
        rec_score += (score / 100) * 0.2
        
        recommendations.append({
            "record": r,
            "rec_score": rec_score
        })
    
    # 按推荐分数排序
    recommendations.sort(key=lambda x: x["rec_score"], reverse=True)
    
    result = []
    for item in recommendations[:limit]:
        result.append({
            "record_id": item["record"].get("id"),
            "score": item["record"].get("score", 0),
            "question_type": item["record"].get("question_type", "unknown"),
            "rec_score": round(item["rec_score"], 4),
            "reason": "基于您的偏好推荐"
        })
    
    return {
        "success": True,
        "user_id": user_id,
        "user_profile": {
            "preferred_types": preferred_types,
            "avg_score_preference": round(avg_score, 2)
        },
        "recommendations": result,
        "recommended_at": datetime.now().isoformat()
    }

