# 质量评分数据相似度配置
QUALITY_SIMILARITY = {
    "enabled": True,
    "similarity_stats": {
        "total_comparisons": 0,
        "total_similar_pairs": 0,
        "avg_similarity": 0.0
    },
    "similarity_log": [],
    "similarity_metrics": [
        {"id": "euclidean", "name": "欧氏距离", "description": "基于欧氏距离的相似度"},
        {"id": "cosine", "name": "余弦相似度", "description": "基于向量夹角的相似度"},
        {"id": "jaccard", "name": "Jaccard相似度", "description": "基于集合交集的相似度"},
        {"id": "pearson", "name": "皮尔逊相关系数", "description": "基于线性相关的相似度"}
    ]
}

@app.post("/api/quality/similarity")
async def calculate_similarity(request: Request):
    """计算质量评分数据相似度"""
    from datetime import datetime
    
    data = await request.json()
    record_id1 = data.get("record_id1")
    record_id2 = data.get("record_id2")
    metric = data.get("metric", "euclidean")  # euclidean, cosine, jaccard, pearson
    
    records = QUALITY_HISTORY.copy()
    
    # 查找记录
    record1 = None
    record2 = None
    for r in records:
        if r.get("id") == record_id1:
            record1 = r
        if r.get("id") == record_id2:
            record2 = r
    
    if not record1 or not record2:
        return {
            "success": False,
            "error": "记录不存在"
        }
    
    # 计算相似度
    score1 = record1.get("score", 0)
    score2 = record2.get("score", 0)
    type1 = record1.get("question_type", "unknown")
    type2 = record2.get("question_type", "unknown")
    
    similarity = 0.0
    
    if metric == "euclidean":
        # 欧氏距离转换为相似度
        distance = abs(score1 - score2)
        similarity = 1 - (distance / 100)
    
    elif metric == "cosine":
        # 简化余弦相似度（基于分数向量）
        # 使用分数和类型作为特征
        v1 = [score1 / 100, 1 if type1 == type2 else 0]
        v2 = [score2 / 100, 1]
        dot_product = sum(a * b for a, b in zip(v1, v2))
        norm1 = sum(a ** 2 for a in v1) ** 0.5
        norm2 = sum(b ** 2 for b in v2) ** 0.5
        similarity = dot_product / (norm1 * norm2) if norm1 > 0 and norm2 > 0 else 0
    
    elif metric == "jaccard":
        # Jaccard相似度（基于类型和分数区间）
        score_range1 = score1 // 20  # 0-4
        score_range2 = score2 // 20
        set1 = {type1, f"range_{score_range1}"}
        set2 = {type2, f"range_{score_range2}"}
        intersection = len(set1 & set2)
        union = len(set1 | set2)
        similarity = intersection / union if union > 0 else 0
    
    elif metric == "pearson":
        # 皮尔逊相关系数（简化：基于分数差异）
        # 由于只有两个点，使用分数差异的倒数
        diff = abs(score1 - score2)
        similarity = 1 - (diff / 50)  # 50分差异为0相似度
        similarity = max(0, min(1, similarity))
    
    # 更新统计
    QUALITY_SIMILARITY["similarity_stats"]["total_comparisons"] += 1
    if similarity >= 0.7:
        QUALITY_SIMILARITY["similarity_stats"]["total_similar_pairs"] += 1
    
    # 记录操作
    similarity_record = {
        "id": len(QUALITY_SIMILARITY["similarity_log"]) + 1,
        "record_id1": record_id1,
        "record_id2": record_id2,
        "metric": metric,
        "similarity": round(similarity, 4),
        "created_at": datetime.now().isoformat()
    }
    QUALITY_SIMILARITY["similarity_log"].append(similarity_record)
    
    return {
        "success": True,
        "record_id1": record_id1,
        "record_id2": record_id2,
        "metric": metric,
        "similarity": round(similarity, 4),
        "details": {
            "score1": score1,
            "score2": score2,
            "type1": type1,
            "type2": type2,
            "same_type": type1 == type2
        },
        "calculated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/similarity/batch")
async def calculate_batch_similarity(request: Request):
    """批量计算相似度"""
    from datetime import datetime
    
    data = await request.json()
    record_ids = data.get("record_ids", [])
    metric = data.get("metric", "euclidean")
    
    if len(record_ids) < 2:
        return {
            "success": False,
            "error": "至少需要2条记录"
        }
    
    records = QUALITY_HISTORY.copy()
    records_map = {r.get("id"): r for r in records}
    
    # 计算所有配对
    similarities = []
    for i in range(len(record_ids)):
        for j in range(i + 1, len(record_ids)):
            id1, id2 = record_ids[i], record_ids[j]
            r1, r2 = records_map.get(id1), records_map.get(id2)
            
            if r1 and r2:
                score1, score2 = r1.get("score", 0), r2.get("score", 0)
                type1, type2 = r1.get("question_type", "unknown"), r2.get("question_type", "unknown")
                
                if metric == "euclidean":
                    sim = 1 - abs(score1 - score2) / 100
                elif metric == "jaccard":
                    set1 = {type1, f"range_{score1 // 20}"}
                    set2 = {type2, f"range_{score2 // 20}"}
                    sim = len(set1 & set2) / len(set1 | set2) if set1 | set2 else 0
                else:
                    sim = 1 - abs(score1 - score2) / 100
                
                similarities.append({
                    "record_id1": id1,
                    "record_id2": id2,
                    "similarity": round(sim, 4)
                })
    
    # 统计
    avg_sim = sum(s["similarity"] for s in similarities) / len(similarities) if similarities else 0
    
    return {
        "success": True,
        "metric": metric,
        "total_pairs": len(similarities),
        "similarities": similarities,
        "stats": {
            "avg_similarity": round(avg_sim, 4),
            "max_similarity": max(s["similarity"] for s in similarities) if similarities else 0,
            "min_similarity": min(s["similarity"] for s in similarities) if similarities else 0
        },
        "calculated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/similarity/matrix")
async def get_similarity_matrix(request: Request):
    """获取相似度矩阵"""
    from datetime import datetime
    
    data = await request.json()
    record_ids = data.get("record_ids", [])
    metric = data.get("metric", "euclidean")
    
    if len(record_ids) < 2:
        return {
            "success": False,
            "error": "至少需要2条记录"
        }
    
    records = QUALITY_HISTORY.copy()
    records_map = {r.get("id"): r for r in records}
    
    # 构建矩阵
    n = len(record_ids)
    matrix = [[0.0] * n for _ in range(n)]
    
    for i in range(n):
        matrix[i][i] = 1.0  # 对角线为1
        for j in range(i + 1, n):
            r1, r2 = records_map.get(record_ids[i]), records_map.get(record_ids[j])
            if r1 and r2:
                score1, score2 = r1.get("score", 0), r2.get("score", 0)
                sim = 1 - abs(score1 - score2) / 100
                matrix[i][j] = round(sim, 4)
                matrix[j][i] = round(sim, 4)
    
    return {
        "success": True,
        "metric": metric,
        "record_ids": record_ids,
        "matrix": matrix,
        "generated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/similarity/neighbors")
async def find_similar_neighbors(request: Request):
    """查找相似邻居"""
    from datetime import datetime
    
    data = await request.json()
    record_id = data.get("record_id")
    k = data.get("k", 5)  # 返回k个最近邻
    metric = data.get("metric", "euclidean")
    threshold = data.get("threshold", 0.5)  # 相似度阈值
    
    records = QUALITY_HISTORY.copy()
    
    # 查找目标记录
    target = None
    for r in records:
        if r.get("id") == record_id:
            target = r
            break
    
    if not target:
        return {
            "success": False,
            "error": "记录不存在"
        }
    
    target_score = target.get("score", 0)
    target_type = target.get("question_type", "unknown")
    
    # 计算与所有其他记录的相似度
    neighbors = []
    for r in records:
        if r.get("id") == record_id:
            continue
        
        score = r.get("score", 0)
        qt = r.get("question_type", "unknown")
        
        if metric == "euclidean":
            sim = 1 - abs(score - target_score) / 100
        elif metric == "jaccard":
            set1 = {target_type, f"range_{target_score // 20}"}
            set2 = {qt, f"range_{score // 20}"}
            sim = len(set1 & set2) / len(set1 | set2) if set1 | set2 else 0
        else:
            sim = 1 - abs(score - target_score) / 100
        
        if sim >= threshold:
            neighbors.append({
                "record_id": r.get("id"),
                "score": score,
                "question_type": qt,
                "similarity": round(sim, 4)
            })
    
    # 按相似度排序
    neighbors.sort(key=lambda x: x["similarity"], reverse=True)
    neighbors = neighbors[:k]
    
    return {
        "success": True,
        "record_id": record_id,
        "metric": metric,
        "threshold": threshold,
        "neighbors": neighbors,
        "total_found": len(neighbors),
        "found_at": datetime.now().isoformat()
    }

