@app.post("/api/quality/pattern")
async def detect_pattern(request: Request):
    """检测质量评分数据模式"""
    from datetime import datetime
    
    data = await request.json()
    pattern_type = data.get("type", "sequential")  # sequential, cyclical, trending, anomaly, cluster
    min_support = data.get("min_support", 0.1)  # 最小支持度
    
    records = QUALITY_HISTORY.copy()
    
    if len(records) < 5:
        return {
            "success": False,
            "error": "数据不足，至少需要5条记录"
        }
    
    # 按时间排序
    sorted_records = sorted(records, key=lambda x: x.get("timestamp", ""))
    scores = [r.get("score", 0) for r in sorted_records]
    
    patterns = []
    
    if pattern_type == "sequential":
        # 序列模式：识别连续上升/下降
        direction = None
        count = 0
        start_idx = 0
        
        for i in range(1, len(scores)):
            if scores[i] > scores[i-1]:
                current_dir = "上升"
            elif scores[i] < scores[i-1]:
                current_dir = "下降"
            else:
                current_dir = "稳定"
            
            if direction is None:
                direction = current_dir
                count = 1
                start_idx = i - 1
            elif current_dir == direction:
                count += 1
            else:
                if count >= 3:
                    patterns.append({
                        "type": "sequential",
                        "direction": direction,
                        "length": count + 1,
                        "start_index": start_idx,
                        "end_index": i - 1,
                        "confidence": round(min(1.0, count / 10), 2)
                    })
                direction = current_dir
                count = 1
                start_idx = i - 1
        
        # 检查最后一个序列
        if count >= 3:
            patterns.append({
                "type": "sequential",
                "direction": direction,
                "length": count + 1,
                "start_index": start_idx,
                "end_index": len(scores) - 1,
                "confidence": round(min(1.0, count / 10), 2)
            })
    
    elif pattern_type == "cyclical":
        # 周期模式：识别周期性重复
        # 使用自相关方法检测周期
        n = len(scores)
        mean_score = sum(scores) / n
        
        for period in range(2, min(10, n // 2)):
            correlation = 0
            count = 0
            for i in range(n - period):
                correlation += (scores[i] - mean_score) * (scores[i + period] - mean_score)
                count += 1
            
            if count > 0:
                correlation /= count
                if correlation > 100:  # 阈值
                    patterns.append({
                        "type": "cyclical",
                        "period": period,
                        "correlation": round(correlation, 2),
                        "confidence": round(min(1.0, correlation / 500), 2)
                    })
    
    elif pattern_type == "trending":
        # 趋势模式：识别整体趋势
        n = len(scores)
        x = list(range(n))
        x_mean = sum(x) / n
        y_mean = sum(scores) / n
        
        numerator = sum((x[i] - x_mean) * (scores[i] - y_mean) for i in range(n))
        denominator = sum((x[i] - x_mean) ** 2 for i in range(n))
        
        slope = numerator / denominator if denominator != 0 else 0
        
        if abs(slope) > 0.5:
            trend_type = "上升趋势" if slope > 0 else "下降趋势"
            patterns.append({
                "type": "trending",
                "trend": trend_type,
                "slope": round(slope, 4),
                "confidence": round(min(1.0, abs(slope) / 5), 2)
            })
        else:
            patterns.append({
                "type": "trending",
                "trend": "平稳趋势",
                "slope": round(slope, 4),
                "confidence": round(1 - abs(slope) / 5, 2)
            })
    
    elif pattern_type == "anomaly":
        # 异常模式：识别异常值
        mean_score = sum(scores) / len(scores)
        variance = sum((s - mean_score) ** 2 for s in scores) / len(scores)
        std_dev = variance ** 0.5
        
        threshold = 2 * std_dev
        
        for i, score in enumerate(scores):
            deviation = abs(score - mean_score)
            if deviation > threshold:
                patterns.append({
                    "type": "anomaly",
                    "index": i,
                    "score": score,
                    "deviation": round(deviation, 2),
                    "z_score": round(deviation / std_dev, 2) if std_dev > 0 else 0,
                    "confidence": round(min(1.0, deviation / (3 * std_dev)), 2) if std_dev > 0 else 0
                })
    
    elif pattern_type == "cluster":
        # 聚类模式：识别分数聚类
        # 简单的区间聚类
        ranges = [(0, 20), (20, 40), (40, 60), (60, 80), (80, 100)]
        clusters = []
        
        for low, high in ranges:
            count = sum(1 for s in scores if low <= s < high)
            if count > 0:
                clusters.append({
                    "range": f"{low}-{high}",
                    "count": count,
                    "percentage": round(count / len(scores) * 100, 2)
                })
        
        # 找出主要聚类
        if clusters:
            max_cluster = max(clusters, key=lambda x: x["count"])
            patterns.append({
                "type": "cluster",
                "clusters": clusters,
                "dominant_cluster": max_cluster["range"],
                "confidence": round(max_cluster["percentage"] / 100, 2)
            })
    
    # 更新统计
    QUALITY_PATTERN["pattern_stats"]["total_patterns_found"] += len(patterns)
    
    # 记录操作
    pattern_record = {
        "id": len(QUALITY_PATTERN["pattern_log"]) + 1,
        "type": pattern_type,
        "patterns_found": len(patterns),
        "created_at": datetime.now().isoformat()
    }
    QUALITY_PATTERN["pattern_log"].append(pattern_record)
    
    return {
        "success": True,
        "pattern_type": pattern_type,
        "patterns": patterns,
        "stats": {
            "total_found": len(patterns),
            "data_points": len(scores)
        },
        "detected_at": datetime.now().isoformat()
    }

@app.post("/api/quality/pattern/match")
async def match_pattern(request: Request):
    """匹配特定模式"""
    from datetime import datetime
    
    data = await request.json()
    pattern_def = data.get("pattern", {})  # 模式定义
    threshold = data.get("threshold", 0.7)  # 匹配阈值
    
    records = QUALITY_HISTORY.copy()
    
    if len(records) < 3:
        return {
            "success": False,
            "error": "数据不足"
        }
    
    scores = [r.get("score", 0) for r in records]
    
    # 简单模式匹配
    matches = []
    pattern_type = pattern_def.get("type", "unknown")
    
    if pattern_type == "range":
        # 范围匹配
        min_val = pattern_def.get("min", 0)
        max_val = pattern_def.get("max", 100)
        
        for i, r in enumerate(records):
            score = r.get("score", 0)
            if min_val <= score <= max_val:
                matches.append({
                    "record_id": r.get("id"),
                    "score": score,
                    "match_score": 1.0
                })
    
    elif pattern_type == "sequence":
        # 序列匹配
        expected_seq = pattern_def.get("sequence", [])
        if len(expected_seq) > 0:
            for i in range(len(scores) - len(expected_seq) + 1):
                match_count = 0
                for j, expected in enumerate(expected_seq):
                    if abs(scores[i + j] - expected) < 10:  # 容差10分
                        match_count += 1
                
                match_score = match_count / len(expected_seq)
                if match_score >= threshold:
                    matches.append({
                        "start_index": i,
                        "end_index": i + len(expected_seq) - 1,
                        "match_score": round(match_score, 2)
                    })
    
    # 更新统计
    QUALITY_PATTERN["pattern_stats"]["total_patterns_matched"] += len(matches)
    
    return {
        "success": True,
        "pattern": pattern_def,
        "matches": matches,
        "total_matches": len(matches),
        "matched_at": datetime.now().isoformat()
    }

@app.post("/api/quality/pattern/mine")
async def mine_patterns(request: Request):
    """挖掘隐藏模式"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    min_support = data.get("min_support", 0.1)
    min_confidence = data.get("min_confidence", 0.5)
    
    records = QUALITY_HISTORY.copy()
    
    if len(records) < 10:
        return {
            "success": False,
            "error": "数据不足，至少需要10条记录"
        }
    
    # 挖掘关联模式
    mined_patterns = []
    
    # 1. 分数区间关联
    scores = [r.get("score", 0) for r in records]
    types = [r.get("question_type", "unknown") for r in records]
    
    # 分数区间
    score_ranges = [s // 20 for s in scores]  # 0-4
    range_counter = Counter(score_ranges)
    
    for range_val, count in range_counter.items():
        support = count / len(records)
        if support >= min_support:
            mined_patterns.append({
                "type": "score_range_frequent",
                "range": f"{range_val * 20}-{(range_val + 1) * 20}",
                "support": round(support, 4),
                "count": count
            })
    
    # 2. 类型关联
    type_counter = Counter(types)
    for qt, count in type_counter.items():
        support = count / len(records)
        if support >= min_support:
            mined_patterns.append({
                "type": "question_type_frequent",
                "question_type": qt,
                "support": round(support, 4),
                "count": count
            })
    
    # 3. 分数-类型关联
    combined = [(s // 20, t) for s, t in zip(scores, types)]
    combined_counter = Counter(combined)
    
    for (range_val, qt), count in combined_counter.items():
        support = count / len(records)
        if support >= min_support:
            # 计算置信度
            type_count = type_counter.get(qt, 0)
            confidence = count / type_count if type_count > 0 else 0
            
            if confidence >= min_confidence:
                mined_patterns.append({
                    "type": "score_type_association",
                    "score_range": f"{range_val * 20}-{(range_val + 1) * 20}",
                    "question_type": qt,
                    "support": round(support, 4),
                    "confidence": round(confidence, 4),
                    "count": count
                })
    
    return {
        "success": True,
        "mined_patterns": mined_patterns,
        "stats": {
            "total_patterns": len(mined_patterns),
            "min_support": min_support,
            "min_confidence": min_confidence
        },
        "mined_at": datetime.now().isoformat()
    }

