@app.post("/api/quality/feature")
async def extract_features(request: Request):
    """提取质量评分数据特征"""
    from datetime import datetime
    
    data = await request.json()
    feature_type = data.get("type", "statistical")  # statistical, temporal, textual, behavioral, composite
    record_ids = data.get("record_ids", [])  # 指定记录ID，为空则处理所有
    
    records = QUALITY_HISTORY.copy()
    
    if record_ids:
        records = [r for r in records if r.get("id") in record_ids]
    
    if len(records) == 0:
        return {
            "success": False,
            "error": "没有可处理的记录"
        }
    
    features = []
    
    for record in records:
        record_features = {
            "record_id": record.get("id"),
            "extracted_features": []
        }
        
        score = record.get("score", 0)
        
        if feature_type == "statistical":
            # 统计特征
            record_features["extracted_features"] = [
                {"name": "score_raw", "value": score, "type": "numeric"},
                {"name": "score_normalized", "value": round(score / 100, 4), "type": "numeric"},
                {"name": "score_level", "value": "high" if score >= 80 else "medium" if score >= 60 else "low", "type": "categorical"},
                {"name": "score_deviation", "value": abs(score - 75), "type": "numeric"},  # 与基准的偏差
                {"name": "score_quartile", "value": 4 if score >= 75 else 3 if score >= 50 else 2 if score >= 25 else 1, "type": "ordinal"}
            ]
        
        elif feature_type == "temporal":
            # 时间特征
            timestamp = record.get("timestamp", "")
            hour = 0
            day_of_week = 0
            
            if timestamp:
                try:
                    dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                    hour = dt.hour
                    day_of_week = dt.weekday()
                except:
                    pass
            
            record_features["extracted_features"] = [
                {"name": "hour_of_day", "value": hour, "type": "numeric"},
                {"name": "day_of_week", "value": day_of_week, "type": "numeric"},
                {"name": "is_peak_hour", "value": 1 if 9 <= hour <= 18 else 0, "type": "binary"},
                {"name": "is_weekend", "value": 1 if day_of_week >= 5 else 0, "type": "binary"},
                {"name": "time_period", "value": "morning" if 6 <= hour < 12 else "afternoon" if 12 <= hour < 18 else "evening" if 18 <= hour < 22 else "night", "type": "categorical"}
            ]
        
        elif feature_type == "textual":
            # 文本特征
            question = record.get("question", "")
            answer = record.get("answer", "")
            
            record_features["extracted_features"] = [
                {"name": "question_length", "value": len(question), "type": "numeric"},
                {"name": "answer_length", "value": len(answer), "type": "numeric"},
                {"name": "question_word_count", "value": len(question.split()), "type": "numeric"},
                {"name": "answer_word_count", "value": len(answer.split()), "type": "numeric"},
                {"name": "answer_question_ratio", "value": round(len(answer) / max(len(question), 1), 2), "type": "numeric"},
                {"name": "has_code", "value": 1 if "```" in answer or "def " in answer else 0, "type": "binary"},
                {"name": "has_list", "value": 1 if "\n-" in answer or "\n*" in answer else 0, "type": "binary"}
            ]
        
        elif feature_type == "behavioral":
            # 行为特征
            question_type = record.get("question_type", "unknown")
            
            record_features["extracted_features"] = [
                {"name": "question_type_encoded", "value": hash(question_type) % 100, "type": "numeric"},
                {"name": "is_code_question", "value": 1 if question_type in ["code", "debugging", "algorithm"] else 0, "type": "binary"},
                {"name": "is_concept_question", "value": 1 if question_type in ["concept", "explanation", "definition"] else 0, "type": "binary"},
                {"name": "is_practical_question", "value": 1 if question_type in ["howto", "tutorial", "example"] else 0, "type": "binary"},
                {"name": "interaction_complexity", "value": "simple" if len(record.get("question", "")) < 50 else "medium" if len(record.get("question", "")) < 200 else "complex", "type": "categorical"}
            ]
        
        elif feature_type == "composite":
            # 复合特征
            timestamp = record.get("timestamp", "")
            question = record.get("question", "")
            answer = record.get("answer", "")
            question_type = record.get("question_type", "unknown")
            
            # 计算复合分数
            length_score = min(100, len(answer) / 5)  # 基于答案长度
            quality_ratio = score / max(length_score, 1)  # 质量与长度的比率
            
            record_features["extracted_features"] = [
                {"name": "quality_efficiency", "value": round(quality_ratio, 4), "type": "numeric"},
                {"name": "content_density", "value": round(len(answer.split()) / max(len(answer), 1) * 100, 2), "type": "numeric"},
                {"name": "comprehensive_score", "value": round((score * 0.7 + min(100, len(answer) / 5) * 0.3), 2), "type": "numeric"},
                {"name": "type_score_interaction", "value": f"{question_type}_{score // 20 * 20}", "type": "categorical"},
                {"name": "feature_hash", "value": hash(f"{question_type}_{score}_{len(answer)}") % 10000, "type": "numeric"}
            ]
        
        features.append(record_features)
    
    # 更新统计
    total_features = sum(len(f["extracted_features"]) for f in features)
    QUALITY_FEATURE["feature_stats"]["total_extractions"] += 1
    QUALITY_FEATURE["feature_stats"]["total_features"] += total_features
    QUALITY_FEATURE["feature_stats"]["avg_features_per_record"] = round(
        QUALITY_FEATURE["feature_stats"]["total_features"] / max(QUALITY_FEATURE["feature_stats"]["total_extractions"], 1),
        2
    )
    
    # 记录操作
    feature_record = {
        "id": len(QUALITY_FEATURE["feature_log"]) + 1,
        "type": feature_type,
        "records_processed": len(records),
        "features_extracted": total_features,
        "created_at": datetime.now().isoformat()
    }
    QUALITY_FEATURE["feature_log"].append(feature_record)
    
    return {
        "success": True,
        "feature_type": feature_type,
        "features": features,
        "stats": {
            "records_processed": len(records),
            "total_features": total_features,
            "avg_per_record": round(total_features / len(records), 2)
        },
        "extracted_at": datetime.now().isoformat()
    }

@app.post("/api/quality/feature/select")
async def select_features(request: Request):
    """特征选择"""
    from datetime import datetime
    
    data = await request.json()
    feature_names = data.get("feature_names", [])  # 要选择的特征名
    threshold = data.get("threshold", 0)  # 特征值阈值
    
    records = QUALITY_HISTORY.copy()
    
    if len(records) == 0:
        return {
            "success": False,
            "error": "没有可处理的记录"
        }
    
    selected_features = []
    
    for record in records:
        score = record.get("score", 0)
        question = record.get("question", "")
        answer = record.get("answer", "")
        question_type = record.get("question_type", "unknown")
        
        # 计算所有可能的特征
        all_features = {
            "score": score,
            "score_normalized": round(score / 100, 4),
            "question_length": len(question),
            "answer_length": len(answer),
            "question_word_count": len(question.split()),
            "answer_word_count": len(answer.split()),
            "has_code": 1 if "```" in answer else 0,
            "has_list": 1 if "\n-" in answer else 0,
            "is_code_question": 1 if question_type in ["code", "debugging"] else 0
        }
        
        # 筛选特征
        selected = {}
        for name in feature_names:
            if name in all_features:
                value = all_features[name]
                if isinstance(value, (int, float)) and value >= threshold:
                    selected[name] = value
                elif isinstance(value, str):
                    selected[name] = value
        
        if selected:
            selected_features.append({
                "record_id": record.get("id"),
                "features": selected
            })
    
    return {
        "success": True,
        "selected_features": selected_features,
        "total_selected": len(selected_features),
        "selected_at": datetime.now().isoformat()
    }

@app.post("/api/quality/feature/transform")
async def transform_features(request: Request):
    """特征转换"""
    from datetime import datetime
    
    data = await request.json()
    transform_type = data.get("transform", "normalize")  # normalize, standardize, binarize, discretize
    feature_values = data.get("values", [])
    
    if not feature_values:
        return {
            "success": False,
            "error": "没有提供特征值"
        }
    
    transformed = []
    
    if transform_type == "normalize":
        # 归一化到[0,1]
        min_val = min(feature_values)
        max_val = max(feature_values)
        range_val = max_val - min_val
        
        if range_val > 0:
            transformed = [(v - min_val) / range_val for v in feature_values]
        else:
            transformed = [0.5 for _ in feature_values]
    
    elif transform_type == "standardize":
        # 标准化 (z-score)
        mean_val = sum(feature_values) / len(feature_values)
        variance = sum((v - mean_val) ** 2 for v in feature_values) / len(feature_values)
        std_dev = variance ** 0.5 if variance > 0 else 1
        
        transformed = [(v - mean_val) / std_dev for v in feature_values]
    
    elif transform_type == "binarize":
        # 二值化
        threshold = data.get("threshold", 50)
        transformed = [1 if v >= threshold else 0 for v in feature_values]
    
    elif transform_type == "discretize":
        # 离散化
        bins = data.get("bins", 5)
        min_val = min(feature_values)
        max_val = max(feature_values)
        bin_width = (max_val - min_val) / bins
        
        if bin_width > 0:
            transformed = [min(int((v - min_val) / bin_width), bins - 1) for v in feature_values]
        else:
            transformed = [0 for _ in feature_values]
    
    return {
        "success": True,
        "transform_type": transform_type,
        "original_values": feature_values[:10],  # 只返回前10个
        "transformed_values": transformed[:10],
        "total_values": len(feature_values),
        "transformed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/feature/importance")
async def calculate_feature_importance(request: Request):
    """计算特征重要性"""
    from datetime import datetime
    
    data = await request.json()
    target = data.get("target", "score")  # 目标变量
    
    records = QUALITY_HISTORY.copy()
    
    if len(records) < 5:
        return {
            "success": False,
            "error": "数据不足，至少需要5条记录"
        }
    
    # 计算各特征与目标的相关性作为重要性
    features_data = {
        "question_length": [],
        "answer_length": [],
        "question_word_count": [],
        "answer_word_count": [],
        "has_code": [],
        "has_list": [],
        "target_values": []
    }
    
    for record in records:
        question = record.get("question", "")
        answer = record.get("answer", "")
        score = record.get("score", 0)
        
        features_data["question_length"].append(len(question))
        features_data["answer_length"].append(len(answer))
        features_data["question_word_count"].append(len(question.split()))
        features_data["answer_word_count"].append(len(answer.split()))
        features_data["has_code"].append(1 if "```" in answer else 0)
        features_data["has_list"].append(1 if "\n-" in answer else 0)
        features_data["target_values"].append(score)
    
    # 计算皮尔逊相关系数
    def pearson_correlation(x, y):
        n = len(x)
        if n == 0:
            return 0
        
        x_mean = sum(x) / n
        y_mean = sum(y) / n
        
        numerator = sum((x[i] - x_mean) * (y[i] - y_mean) for i in range(n))
        denominator_x = sum((x[i] - x_mean) ** 2 for i in range(n)) ** 0.5
        denominator_y = sum((y[i] - y_mean) ** 2 for i in range(n)) ** 0.5
        
        if denominator_x * denominator_y == 0:
            return 0
        
        return numerator / (denominator_x * denominator_y)
    
    importance_scores = []
    target_values = features_data["target_values"]
    
    for feature_name, feature_values in features_data.items():
        if feature_name != "target_values":
            correlation = pearson_correlation(feature_values, target_values)
            importance_scores.append({
                "feature": feature_name,
                "importance": round(abs(correlation), 4),
                "correlation": round(correlation, 4),
                "direction": "positive" if correlation >= 0 else "negative"
            })
    
    # 按重要性排序
    importance_scores.sort(key=lambda x: x["importance"], reverse=True)
    
    return {
        "success": True,
        "target": target,
        "importance_scores": importance_scores,
        "calculated_at": datetime.now().isoformat()
    }

