        {"id": "svd", "name": "SVD奇异值分解", "description": "矩阵分解降维方法"},
        {"id": "tsne", "name": "t-SNE", "description": "非线性降维，适合可视化"},
        {"id": "umap", "name": "UMAP", "description": "流形学习降维方法"},
