@app.post("/api/quality/dimension/summary")
async def get_dimension_summary(request: Request):
    """获取降维摘要"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")  # all, day, week, month
    
    # 筛选时间范围
    now = datetime.now()
    filtered = []
    
    for log in QUALITY_DIMENSION["dimension_log"]:
        timestamp = log.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(log)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(log)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(log)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(log)
            except:
                pass
    
    # 统计
    method_counter = Counter(log.get("method", "unknown") for log in filtered)
    total_variance = sum(log.get("variance_explained", 0) for log in filtered)
    
    summary = {
        "period": period,
        "total_reductions": len(filtered),
        "by_method": dict(method_counter),
        "avg_variance_explained": round(total_variance / len(filtered), 4) if filtered else 0,
        "total_records_processed": QUALITY_DIMENSION["dimension_stats"]["total_records_processed"],
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

# 质量评分数据标准化配置
QUALITY_STANDARD = {
    "enabled": True,
    "standard_stats": {
        "total_standardizations": 0,
        "total_records_processed": 0,
        "avg_compliance": 0.0
    },
    "standard_log": [],
    "standard_types": [
        {"id": "z_score", "name": "Z-Score标准化", "description": "转换为均值为0、标准差为1的分布"},
        {"id": "min_max", "name": "Min-Max标准化", "description": "缩放到[0,1]区间"},
        {"id": "decimal", "name": "小数定标标准化", "description": "通过移动小数点标准化"},
        {"id": "log", "name": "对数标准化", "description": "对数变换标准化"},
        {"id": "robust", "name": "鲁棒标准化", "description": "基于中位数和四分位距标准化"}
    ]
}

@app.post("/api/quality/standard")
async def standardize_data(request: Request):
    """执行数据标准化"""
    from datetime import datetime
    import math
    
    data = await request.json()
    method = data.get("method", "z_score")  # z_score, min_max, decimal, log, robust
    record_ids = data.get("record_ids", [])  # 指定记录ID
    fields = data.get("fields", ["score"])  # 要标准化的字段
    
    records = QUALITY_HISTORY.copy()
    
    if record_ids:
        records = [r for r in records if r.get("id") in record_ids]
    
    if len(records) < 2:
        return {
            "success": False,
            "error": "数据不足，至少需要2条记录"
        }
    
    standardized_records = []
    compliance_scores = []
    
    for field in fields:
        # 提取字段值
        values = []
        for record in records:
            if field == "score":
                values.append(record.get("score", 0))
            elif field == "question_length":
                values.append(len(record.get("question", "")))
            elif field == "answer_length":
                values.append(len(record.get("answer", "")))
            else:
                values.append(0)
        
        n = len(values)
        
        # 计算统计量
        mean_val = sum(values) / n
        variance = sum((v - mean_val) ** 2 for v in values) / n
        std_val = math.sqrt(variance) if variance > 0 else 1
        
        sorted_values = sorted(values)
        median = sorted_values[n // 2] if n % 2 == 1 else (sorted_values[n // 2 - 1] + sorted_values[n // 2]) / 2
        q1 = sorted_values[n // 4]
        q3 = sorted_values[3 * n // 4]
        iqr = q3 - q1 if q3 > q1 else 1
        
        min_val = min(values)
        max_val = max(values)
        range_val = max_val - min_val if max_val > min_val else 1
        
        # 根据方法标准化
        standardized_values = []
        
        if method == "z_score":
            # Z-Score: (x - mean) / std
            for v in values:
                standardized_values.append((v - mean_val) / std_val)
        
        elif method == "min_max":
            # Min-Max: (x - min) / (max - min)
            for v in values:
                standardized_values.append((v - min_val) / range_val)
        
        elif method == "decimal":
            # 小数定标: x / 10^k, k是使|标准化值|<1的最小整数
            max_abs = max(abs(v) for v in values)
            k = math.ceil(math.log10(max_abs)) if max_abs > 0 else 1
            for v in values:
                standardized_values.append(v / (10 ** k))
        
        elif method == "log":
            # 对数标准化: log(x + 1) / log(max + 1)
            log_max = math.log(max_val + 1) if max_val >= 0 else 1
            for v in values:
                if v >= 0:
                    standardized_values.append(math.log(v + 1) / log_max)
                else:
                    standardized_values.append(0)
        
        elif method == "robust":
            # 鲁棒标准化: (x - median) / IQR
            for v in values:
                standardized_values.append((v - median) / iqr)
        
        # 计算合规性分数
        std_mean = sum(standardized_values) / n
        std_variance = sum((v - std_mean) ** 2 for v in standardized_values) / n
        
        # 合规性检查
        compliance = 1.0
        if method == "z_score":
            # 检查均值接近0，标准差接近1
            compliance = 1.0 - (abs(std_mean) + abs(math.sqrt(std_variance) - 1)) / 2
        elif method == "min_max":
            # 检查值在[0,1]范围内
            in_range = sum(1 for v in standardized_values if 0 <= v <= 1) / n
            compliance = in_range
        
        compliance_scores.append(compliance)
        
        # 添加到结果
        for i, record in enumerate(records):
            if i == len(standardized_records):
                standardized_records.append({
                    "record_id": record.get("id"),
                    "original": {},
                    "standardized": {}
                })
            standardized_records[i]["original"][field] = values[i]
            standardized_records[i]["standardized"][field] = round(standardized_values[i], 4)
    
    avg_compliance = sum(compliance_scores) / len(compliance_scores) if compliance_scores else 0
    
    # 更新统计
    QUALITY_STANDARD["standard_stats"]["total_standardizations"] += 1
    QUALITY_STANDARD["standard_stats"]["total_records_processed"] += len(records)
    QUALITY_STANDARD["standard_stats"]["avg_compliance"] = round(
        (QUALITY_STANDARD["standard_stats"]["avg_compliance"] * (QUALITY_STANDARD["standard_stats"]["total_standardizations"] - 1) + avg_compliance) / QUALITY_STANDARD["standard_stats"]["total_standardizations"],
        4
    )
    
    # 记录操作
    standard_record = {
        "id": len(QUALITY_STANDARD["standard_log"]) + 1,
        "method": method,
        "fields": fields,
        "records_processed": len(records),
        "compliance": round(avg_compliance, 4),
        "created_at": datetime.now().isoformat()
    }
    QUALITY_STANDARD["standard_log"].append(standard_record)
    
    return {
        "success": True,
        "method": method,
        "fields": fields,
        "standardized_data": standardized_records,
        "compliance": round(avg_compliance, 4),
        "stats": {
            "n_records": len(records),
            "n_fields": len(fields),
            "compliance_by_field": {fields[i]: round(compliance_scores[i], 4) for i in range(len(fields))}
        },
        "standardized_at": datetime.now().isoformat()
    }

@app.post("/api/quality/standard/batch")
async def batch_standardize(request: Request):
    """批量标准化多个字段"""
    from datetime import datetime
    
    data = await request.json()
    operations = data.get("operations", [])  # [{field: "score", method: "z_score"}, ...]
    record_ids = data.get("record_ids", [])
    
    if not operations:
        return {
            "success": False,
            "error": "没有提供标准化操作"
        }
    
    results = []
    for op in operations:
        field = op.get("field", "score")
        method = op.get("method", "z_score")
        
        # 调用单个标准化
        single_result = await standardize_data(type('Request', (), {
            'json': lambda: {
                "method": method,
                "record_ids": record_ids,
                "fields": [field]
            }
        })())
        
        results.append({
            "field": field,
            "method": method,
            "success": single_result.get("success", False),
            "compliance": single_result.get("compliance", 0)
        })
    
    return {
        "success": True,
        "total_operations": len(operations),
        "results": results,
        "processed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/standard/inverse")
async def inverse_standardize(request: Request):
    """反向标准化（还原原始值）"""
    from datetime import datetime
    import math
    
    data = await request.json()
    standardized_values = data.get("standardized_values", [])
    method = data.get("method", "z_score")
    original_stats = data.get("original_stats", {})  # {mean: 0, std: 1, min: 0, max: 1, ...}
    
    if not standardized_values:
        return {
            "success": False,
            "error": "没有提供标准化值"
        }
    
    original_values = []
    
    mean_val = original_stats.get("mean", 0)
    std_val = original_stats.get("std", 1)
    min_val = original_stats.get("min", 0)
    max_val = original_stats.get("max", 1)
    median = original_stats.get("median", 0)
    iqr = original_stats.get("iqr", 1)
    k = original_stats.get("decimal_k", 1)
    
    for sv in standardized_values:
        if method == "z_score":
            original = sv * std_val + mean_val
        elif method == "min_max":
            original = sv * (max_val - min_val) + min_val
        elif method == "decimal":
            original = sv * (10 ** k)
        elif method == "log":
            log_max = math.log(max_val + 1) if max_val >= 0 else 1
            original = math.exp(sv * log_max) - 1
        elif method == "robust":
            original = sv * iqr + median
        else:
            original = sv
        
        original_values.append(round(original, 2))
    
    return {
        "success": True,
        "method": method,
        "original_values": original_values,
        "restored_at": datetime.now().isoformat()
    }

@app.post("/api/quality/standard/validate")
async def validate_standardization(request: Request):
    """验证标准化结果"""
    from datetime import datetime
    import math
    
    data = await request.json()
    standardized_values = data.get("standardized_values", [])
    method = data.get("method", "z_score")
    
    if not standardized_values:
        return {
            "success": False,
            "error": "没有提供标准化值"
        }
    
    n = len(standardized_values)
    mean_val = sum(standardized_values) / n
    variance = sum((v - mean_val) ** 2 for v in standardized_values) / n
    std_val = math.sqrt(variance) if variance > 0 else 0
    
    min_val = min(standardized_values)
    max_val = max(standardized_values)
    
    # 验证规则
    validation_results = []
    is_valid = True
    
    if method == "z_score":
        # 检查均值接近0，标准差接近1
        mean_check = abs(mean_val) < 0.1
        std_check = abs(std_val - 1) < 0.1
        is_valid = mean_check and std_check
        validation_results = [
            {"check": "mean_near_zero", "passed": mean_check, "value": round(mean_val, 4)},
            {"check": "std_near_one", "passed": std_check, "value": round(std_val, 4)}
        ]
    
    elif method == "min_max":
        # 检查值在[0,1]范围内
        in_range = all(0 <= v <= 1 for v in standardized_values)
        is_valid = in_range
        validation_results = [
            {"check": "values_in_range", "passed": in_range, "min": round(min_val, 4), "max": round(max_val, 4)}
        ]
    
    elif method == "decimal":
        # 检查值在[-1, 1]范围内
        in_range = all(-1 <= v <= 1 for v in standardized_values)
        is_valid = in_range
        validation_results = [
            {"check": "values_in_range", "passed": in_range, "min": round(min_val, 4), "max": round(max_val, 4)}
        ]
    
    elif method == "log":
        # 检查值非负
        non_negative = all(v >= 0 for v in standardized_values)
        is_valid = non_negative
        validation_results = [
            {"check": "values_non_negative", "passed": non_negative, "min": round(min_val, 4)}
        ]
    
    elif method == "robust":
        # 检查中位数接近0
        sorted_values = sorted(standardized_values)
        median = sorted_values[n // 2] if n % 2 == 1 else (sorted_values[n // 2 - 1] + sorted_values[n // 2]) / 2
        median_check = abs(median) < 0.1
        is_valid = median_check
        validation_results = [
            {"check": "median_near_zero", "passed": median_check, "value": round(median, 4)}
        ]
    
    return {
        "success": True,
        "method": method,
        "is_valid": is_valid,
        "validation_results": validation_results,
        "statistics": {
            "mean": round(mean_val, 4),
            "std": round(std_val, 4),
            "min": round(min_val, 4),
            "max": round(max_val, 4),
            "n": n
        },
        "validated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/standard/compare")
async def compare_standardization(request: Request):
    """比较不同标准化方法"""
    from datetime import datetime
    import math
    
    data = await request.json()
    record_ids = data.get("record_ids", [])
    field = data.get("field", "score")
    
    records = QUALITY_HISTORY.copy()
    
    if record_ids:
        records = [r for r in records if r.get("id") in record_ids]
    
    if len(records) < 2:
        return {
            "success": False,
            "error": "数据不足，至少需要2条记录"
        }
    
    # 提取值
    values = []
    for record in records:
        if field == "score":
            values.append(record.get("score", 0))
        elif field == "question_length":
            values.append(len(record.get("question", "")))
        elif field == "answer_length":
            values.append(len(record.get("answer", "")))
        else:
            values.append(0)
    
    n = len(values)
    mean_val = sum(values) / n
    variance = sum((v - mean_val) ** 2 for v in values) / n
    std_val = math.sqrt(variance) if variance > 0 else 1
    
    min_val = min(values)
    max_val = max(values)
    range_val = max_val - min_val if max_val > min_val else 1
    
    sorted_values = sorted(values)
    median = sorted_values[n // 2] if n % 2 == 1 else (sorted_values[n // 2 - 1] + sorted_values[n // 2]) / 2
    q1 = sorted_values[n // 4]
    q3 = sorted_values[3 * n // 4]
    iqr = q3 - q1 if q3 > q1 else 1
    
    max_abs = max(abs(v) for v in values)
    k = math.ceil(math.log10(max_abs)) if max_abs > 0 else 1
    
    # 应用所有方法
    methods_comparison = []
    
    # Z-Score
    z_values = [(v - mean_val) / std_val for v in values]
    methods_comparison.append({
        "method": "z_score",
        "mean": round(sum(z_values) / n, 4),
        "std": round(math.sqrt(sum((v - sum(z_values) / n) ** 2 for v in z_values) / n), 4),
        "min": round(min(z_values), 4),
        "max": round(max(z_values), 4),
        "sample_values": [round(v, 4) for v in z_values[:5]]
    })
    
    # Min-Max
    mm_values = [(v - min_val) / range_val for v in values]
    methods_comparison.append({
        "method": "min_max",
        "mean": round(sum(mm_values) / n, 4),
        "std": round(math.sqrt(sum((v - sum(mm_values) / n) ** 2 for v in mm_values) / n), 4),
        "min": round(min(mm_values), 4),
        "max": round(max(mm_values), 4),
        "sample_values": [round(v, 4) for v in mm_values[:5]]
    })
    
    # Decimal
    d_values = [v / (10 ** k) for v in values]
    methods_comparison.append({
        "method": "decimal",
        "mean": round(sum(d_values) / n, 4),
        "std": round(math.sqrt(sum((v - sum(d_values) / n) ** 2 for v in d_values) / n), 4),
        "min": round(min(d_values), 4),
        "max": round(max(d_values), 4),
        "sample_values": [round(v, 4) for v in d_values[:5]]
    })
    
    # Log
    log_max = math.log(max_val + 1) if max_val >= 0 else 1
    l_values = [math.log(v + 1) / log_max if v >= 0 else 0 for v in values]
    methods_comparison.append({
        "method": "log",
        "mean": round(sum(l_values) / n, 4),
        "std": round(math.sqrt(sum((v - sum(l_values) / n) ** 2 for v in l_values) / n), 4),
        "min": round(min(l_values), 4),
        "max": round(max(l_values), 4),
        "sample_values": [round(v, 4) for v in l_values[:5]]
    })
    
    # Robust
    r_values = [(v - median) / iqr for v in values]
    methods_comparison.append({
        "method": "robust",
        "mean": round(sum(r_values) / n, 4),
        "std": round(math.sqrt(sum((v - sum(r_values) / n) ** 2 for v in r_values) / n), 4),
        "min": round(min(r_values), 4),
        "max": round(max(r_values), 4),
        "sample_values": [round(v, 4) for v in r_values[:5]]
    })
    
    return {
        "success": True,
        "field": field,
        "original_stats": {
            "mean": round(mean_val, 4),
            "std": round(std_val, 4),
            "min": round(min_val, 4),
            "max": round(max_val, 4),
            "median": round(median, 4)
        },
        "methods_comparison": methods_comparison,
        "compared_at": datetime.now().isoformat()
    }

