@app.post("/api/quality/normalize")
async def normalize_data(request: Request):
    """执行数据归一化"""
    from datetime import datetime
    import math
    
    data = await request.json()
    method = data.get("method", "l2")  # l1, l2, max, sum, softmax
    record_ids = data.get("record_ids", [])  # 指定记录ID
    
    records = QUALITY_HISTORY.copy()
    
    if record_ids:
        records = [r for r in records if r.get("id") in record_ids]
    
    if len(records) < 1:
        return {
            "success": False,
            "error": "数据不足，至少需要1条记录"
        }
    
    # 构建特征向量
    vectors = []
    for record in records:
        vector = [
            record.get("score", 0),
            len(record.get("question", "")),
            len(record.get("answer", "")),
            len(record.get("question", "").split()),
            len(record.get("answer", "").split())
        ]
        vectors.append(vector)
    
    n = len(vectors)
    dim = len(vectors[0]) if vectors else 0
    
    normalized_vectors = []
    normalization_scores = []
    
    for vector in vectors:
        if method == "l1":
            # L1归一化: x / sum(|x|)
            l1_norm = sum(abs(v) for v in vector)
            if l1_norm > 0:
                normalized = [v / l1_norm for v in vector]
            else:
                normalized = [0] * dim
            score = 1.0 if abs(sum(normalized) - 1) < 0.01 else 0.5
        
        elif method == "l2":
            # L2归一化: x / sqrt(sum(x^2))
            l2_norm = math.sqrt(sum(v ** 2 for v in vector))
            if l2_norm > 0:
                normalized = [v / l2_norm for v in vector]
            else:
                normalized = [0] * dim
            score = 1.0 if abs(math.sqrt(sum(v ** 2 for v in normalized)) - 1) < 0.01 else 0.5
        
        elif method == "max":
            # 最大值归一化: x / max(|x|)
            max_val = max(abs(v) for v in vector)
            if max_val > 0:
                normalized = [v / max_val for v in vector]
            else:
                normalized = [0] * dim
            score = 1.0 if max(abs(v) for v in normalized) <= 1 else 0.5
        
        elif method == "sum":
            # 总和归一化: x / sum(x)
            total = sum(vector)
            if total > 0:
                normalized = [v / total for v in vector]
            else:
                normalized = [0] * dim
            score = 1.0 if abs(sum(normalized) - 1) < 0.01 else 0.5
        
        elif method == "softmax":
            # Softmax归一化: exp(x) / sum(exp(x))
            max_val = max(vector)  # 数值稳定性
            exp_vals = [math.exp(v - max_val) for v in vector]
            exp_sum = sum(exp_vals)
            if exp_sum > 0:
                normalized = [e / exp_sum for e in exp_vals]
            else:
                normalized = [1 / dim] * dim
            score = 1.0 if abs(sum(normalized) - 1) < 0.01 else 0.5
        
        else:
            normalized = vector
            score = 0
        
        normalized_vectors.append([round(v, 6) for v in normalized])
        normalization_scores.append(score)
    
    avg_score = sum(normalization_scores) / len(normalization_scores) if normalization_scores else 0
    
    # 更新统计
    QUALITY_NORMALIZE["normalize_stats"]["total_normalizations"] += 1
    QUALITY_NORMALIZE["normalize_stats"]["total_records_processed"] += n
    QUALITY_NORMALIZE["normalize_stats"]["avg_score"] = round(
        (QUALITY_NORMALIZE["normalize_stats"]["avg_score"] * (QUALITY_NORMALIZE["normalize_stats"]["total_normalizations"] - 1) + avg_score) / QUALITY_NORMALIZE["normalize_stats"]["total_normalizations"],
        4
    )
    
    # 记录操作
    normalize_record = {
        "id": len(QUALITY_NORMALIZE["normalize_log"]) + 1,
        "method": method,
        "records_processed": n,
        "avg_score": round(avg_score, 4),
        "created_at": datetime.now().isoformat()
    }
    QUALITY_NORMALIZE["normalize_log"].append(normalize_record)
    
    # 格式化结果
    results = []
    for i, record in enumerate(records):
        results.append({
            "record_id": record.get("id"),
            "original_vector": vectors[i],
            "normalized_vector": normalized_vectors[i],
            "score": round(normalization_scores[i], 4)
        })
    
    return {
        "success": True,
        "method": method,
        "normalized_data": results,
        "avg_score": round(avg_score, 4),
        "stats": {
            "n_records": n,
            "dimension": dim
        },
        "normalized_at": datetime.now().isoformat()
    }

@app.post("/api/quality/normalize/batch")
async def batch_normalize(request: Request):
    """批量归一化"""
    from datetime import datetime
    
    data = await request.json()
    vectors = data.get("vectors", [])  # [[1,2,3], [4,5,6], ...]
    method = data.get("method", "l2")
    
    if not vectors:
        return {
            "success": False,
            "error": "没有提供向量数据"
        }
    
    import math
    
    normalized_vectors = []
    
    for vector in vectors:
        if method == "l1":
            l1_norm = sum(abs(v) for v in vector)
            normalized = [v / l1_norm for v in vector] if l1_norm > 0 else [0] * len(vector)
        elif method == "l2":
            l2_norm = math.sqrt(sum(v ** 2 for v in vector))
            normalized = [v / l2_norm for v in vector] if l2_norm > 0 else [0] * len(vector)
        elif method == "max":
            max_val = max(abs(v) for v in vector)
            normalized = [v / max_val for v in vector] if max_val > 0 else [0] * len(vector)
        elif method == "sum":
            total = sum(vector)
            normalized = [v / total for v in vector] if total > 0 else [0] * len(vector)
        elif method == "softmax":
            max_val = max(vector)
            exp_vals = [math.exp(v - max_val) for v in vector]
            exp_sum = sum(exp_vals)
            normalized = [e / exp_sum for e in exp_vals] if exp_sum > 0 else [1 / len(vector)] * len(vector)
        else:
            normalized = vector
        
        normalized_vectors.append([round(v, 6) for v in normalized])
    
    return {
        "success": True,
        "method": method,
        "total_vectors": len(vectors),
        "normalized_vectors": normalized_vectors,
        "processed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/normalize/matrix")
async def normalize_matrix(request: Request):
    """矩阵归一化"""
    from datetime import datetime
    import math
    
    data = await request.json()
    matrix = data.get("matrix", [])  # 2D数组
    method = data.get("method", "l2")
    axis = data.get("axis", 1)  # 0=列归一化, 1=行归一化
    
    if not matrix or not matrix[0]:
        return {
            "success": False,
            "error": "没有提供矩阵数据"
        }
    
    rows = len(matrix)
    cols = len(matrix[0])
    
    normalized_matrix = [[0] * cols for _ in range(rows)]
    
    if axis == 1:
        # 行归一化
        for i in range(rows):
            row = matrix[i]
            if method == "l2":
                norm = math.sqrt(sum(v ** 2 for v in row))
            elif method == "l1":
                norm = sum(abs(v) for v in row)
            else:
                norm = max(abs(v) for v in row) if max(abs(v) for v in row) > 0 else 1
            
            if norm > 0:
                normalized_matrix[i] = [round(v / norm, 6) for v in row]
            else:
                normalized_matrix[i] = [0] * cols
    else:
        # 列归一化
        for j in range(cols):
            col = [matrix[i][j] for i in range(rows)]
            if method == "l2":
                norm = math.sqrt(sum(v ** 2 for v in col))
            elif method == "l1":
                norm = sum(abs(v) for v in col)
            else:
                norm = max(abs(v) for v in col) if max(abs(v) for v in col) > 0 else 1
            
            if norm > 0:
                for i in range(rows):
                    normalized_matrix[i][j] = round(col[i] / norm, 6)
            else:
                for i in range(rows):
                    normalized_matrix[i][j] = 0
    
    return {
        "success": True,
        "method": method,
        "axis": axis,
        "shape": {"rows": rows, "cols": cols},
        "normalized_matrix": normalized_matrix,
        "processed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/normalize/distance")
async def compute_normalized_distance(request: Request):
    """计算归一化后的距离"""
    from datetime import datetime
    import math
    
    data = await request.json()
    vector1 = data.get("vector1", [])
    vector2 = data.get("vector2", [])
    method = data.get("method", "l2")
    distance_type = data.get("distance_type", "euclidean")  # euclidean, cosine, manhattan
    
    if not vector1 or not vector2:
        return {
            "success": False,
            "error": "没有提供向量数据"
        }
    
    if len(vector1) != len(vector2):
        return {
            "success": False,
            "error": "向量维度不匹配"
        }
    
    # 归一化
    def normalize(v, m):
        if m == "l2":
            norm = math.sqrt(sum(x ** 2 for x in v))
            return [x / norm for x in v] if norm > 0 else v
        elif m == "l1":
            norm = sum(abs(x) for x in v)
            return [x / norm for x in v] if norm > 0 else v
        return v
    
    nv1 = normalize(vector1, method)
    nv2 = normalize(vector2, method)
    
    # 计算距离
    if distance_type == "euclidean":
        distance = math.sqrt(sum((nv1[i] - nv2[i]) ** 2 for i in range(len(nv1))))
    elif distance_type == "cosine":
        dot = sum(nv1[i] * nv2[i] for i in range(len(nv1)))
        distance = 1 - dot  # 余弦距离
    elif distance_type == "manhattan":
        distance = sum(abs(nv1[i] - nv2[i]) for i in range(len(nv1)))
    else:
        distance = 0
    
    return {
        "success": True,
        "method": method,
        "distance_type": distance_type,
        "distance": round(distance, 6),
        "normalized_vector1": [round(v, 6) for v in nv1],
        "normalized_vector2": [round(v, 6) for v in nv2],
        "computed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/normalize/similarity")
async def compute_normalized_similarity(request: Request):
    """计算归一化后的相似度"""
    from datetime import datetime
    import math
    
    data = await request.json()
    vector1 = data.get("vector1", [])
    vector2 = data.get("vector2", [])
    method = data.get("method", "l2")
    similarity_type = data.get("similarity_type", "cosine")  # cosine, dot, jaccard
    
    if not vector1 or not vector2:
        return {
            "success": False,
            "error": "没有提供向量数据"
        }
    
    if len(vector1) != len(vector2):
        return {
            "success": False,
            "error": "向量维度不匹配"
        }
    
    # 归一化
    def normalize(v, m):
        if m == "l2":
            norm = math.sqrt(sum(x ** 2 for x in v))
            return [x / norm for x in v] if norm > 0 else v
        elif m == "l1":
            norm = sum(abs(x) for x in v)
            return [x / norm for x in v] if norm > 0 else v
        return v
    
    nv1 = normalize(vector1, method)
    nv2 = normalize(vector2, method)
    
    # 计算相似度
    if similarity_type == "cosine":
        similarity = sum(nv1[i] * nv2[i] for i in range(len(nv1)))
    elif similarity_type == "dot":
        similarity = sum(vector1[i] * vector2[i] for i in range(len(vector1)))
        # 归一化点积
        norm1 = math.sqrt(sum(v ** 2 for v in vector1))
        norm2 = math.sqrt(sum(v ** 2 for v in vector2))
        if norm1 > 0 and norm2 > 0:
            similarity = similarity / (norm1 * norm2)
    elif similarity_type == "jaccard":
        # 二值化后计算Jaccard
        b1 = [1 if v > 0 else 0 for v in nv1]
        b2 = [1 if v > 0 else 0 for v in nv2]
        intersection = sum(1 for i in range(len(b1)) if b1[i] == 1 and b2[i] == 1)
        union = sum(1 for i in range(len(b1)) if b1[i] == 1 or b2[i] == 1)
        similarity = intersection / union if union > 0 else 0
    else:
        similarity = 0
    
    return {
        "success": True,
        "method": method,
        "similarity_type": similarity_type,
        "similarity": round(similarity, 6),
        "normalized_vector1": [round(v, 6) for v in nv1],
        "normalized_vector2": [round(v, 6) for v in nv2],
        "computed_at": datetime.now().isoformat()
    }

