@app.post("/api/quality/regular")
async def regularize_data(request: Request):
    """执行数据正则化"""
    from datetime import datetime
    import math
    
    data = await request.json()
    method = data.get("method", "l2")  # l1, l2, elastic, dropout, early_stop
    weights = data.get("weights", [])  # 权重向量
    lambda_val = data.get("lambda", 0.1)  # 正则化系数
    alpha = data.get("alpha", 0.5)  # 弹性网络中L1的比例
    
    if not weights:
        return {
            "success": False,
            "error": "没有提供权重数据"
        }
    
    n = len(weights)
    penalty = 0.0
    regularized_weights = weights.copy()
    
    if method == "l1":
        # L1正则化: lambda * sum(|w|)
        penalty = lambda_val * sum(abs(w) for w in weights)
        # L1不直接修改权重，但在优化中会产生稀疏解
        
    elif method == "l2":
        # L2正则化: lambda * sum(w^2)
        penalty = lambda_val * sum(w ** 2 for w in weights)
        # L2权重衰减: w = w * (1 - lambda)
        regularized_weights = [w * (1 - lambda_val) for w in weights]
        
    elif method == "elastic":
        # 弹性网络: alpha * L1 + (1-alpha) * L2
        l1_penalty = alpha * lambda_val * sum(abs(w) for w in weights)
        l2_penalty = (1 - alpha) * lambda_val * sum(w ** 2 for w in weights)
        penalty = l1_penalty + l2_penalty
        regularized_weights = [w * (1 - lambda_val * (1 - alpha)) for w in weights]
        
    elif method == "dropout":
        # Dropout: 随机置零部分权重
        drop_rate = lambda_val  # 使用lambda作为丢弃率
        import random
        random.seed(42)
        mask = [1 if random.random() > drop_rate else 0 for _ in range(n)]
        regularized_weights = [w * m for w, m in zip(weights, mask)]
        penalty = drop_rate * n  # 期望丢弃数量
        
    elif method == "early_stop":
        # 早停：返回当前权重的范数作为监控指标
        l2_norm = math.sqrt(sum(w ** 2 for w in weights))
        penalty = l2_norm
        # 早停不修改权重
    
    # 更新统计
    QUALITY_REGULAR["regular_stats"]["total_regularizations"] += 1
    QUALITY_REGULAR["regular_stats"]["total_records_processed"] += n
    QUALITY_REGULAR["regular_stats"]["avg_penalty"] = round(
        (QUALITY_REGULAR["regular_stats"]["avg_penalty"] * (QUALITY_REGULAR["regular_stats"]["total_regularizations"] - 1) + penalty) / QUALITY_REGULAR["regular_stats"]["total_regularizations"],
        4
    )
    
    # 记录操作
    regular_record = {
        "id": len(QUALITY_REGULAR["regular_log"]) + 1,
        "method": method,
        "n_weights": n,
        "lambda": lambda_val,
        "penalty": round(penalty, 6),
        "created_at": datetime.now().isoformat()
    }
    QUALITY_REGULAR["regular_log"].append(regular_record)
    
    return {
        "success": True,
        "method": method,
        "original_weights": weights,
        "regularized_weights": [round(w, 6) for w in regularized_weights],
        "penalty": round(penalty, 6),
        "lambda": lambda_val,
        "alpha": alpha if method == "elastic" else None,
        "stats": {
            "n_weights": n,
            "l1_norm": round(sum(abs(w) for w in weights), 6),
            "l2_norm": round(math.sqrt(sum(w ** 2 for w in weights)), 6)
        },
        "regularized_at": datetime.now().isoformat()
    }

@app.post("/api/quality/regular/optimize")
async def optimize_regularization(request: Request):
    """优化正则化参数"""
    from datetime import datetime
    import math
    
    data = await request.json()
    weights = data.get("weights", [])
    method = data.get("method", "l2")
    lambda_range = data.get("lambda_range", [0.001, 0.01, 0.1, 1.0, 10.0])
    
    if not weights:
        return {
            "success": False,
            "error": "没有提供权重数据"
        }
    
    results = []
    best_lambda = None
    best_score = float('inf')
    
    for lam in lambda_range:
        if method == "l1":
            penalty = lam * sum(abs(w) for w in weights)
        elif method == "l2":
            penalty = lam * sum(w ** 2 for w in weights)
        else:
            penalty = lam * sum(w ** 2 for w in weights)
        
        # 计算有效权重（正则化后）
        effective_norm = math.sqrt(sum((w * (1 - lam)) ** 2 for w in weights))
        
        # 评分：平衡模型复杂度和拟合能力
        # 这里使用简化的评分：penalty + effective_norm
        score = penalty + effective_norm
        
        results.append({
            "lambda": lam,
            "penalty": round(penalty, 6),
            "effective_norm": round(effective_norm, 6),
            "score": round(score, 6)
        })
        
        if score < best_score:
            best_score = score
            best_lambda = lam
    
    return {
        "success": True,
        "method": method,
        "optimization_results": results,
        "best_lambda": best_lambda,
        "best_score": round(best_score, 6),
        "optimized_at": datetime.now().isoformat()
    }

@app.post("/api/quality/regular/cross_validate")
async def cross_validate_regularization(request: Request):
    """交叉验证正则化参数"""
    from datetime import datetime
    import math
    import random
    
    data = await request.json()
    weights = data.get("weights", [])
    scores = data.get("scores", [])  # 对应的评分数据
    method = data.get("method", "l2")
    k_folds = data.get("k_folds", 5)
    lambda_candidates = data.get("lambda_candidates", [0.001, 0.01, 0.1, 1.0])
    
    if not weights or not scores:
        return {
            "success": False,
            "error": "没有提供权重或评分数据"
        }
    
    n = min(len(weights), len(scores))
    indices = list(range(n))
    random.seed(42)
    random.shuffle(indices)
    
    fold_size = n // k_folds
    cv_results = []
    
    for lam in lambda_candidates:
        fold_scores = []
        
        for fold in range(k_folds):
            # 划分训练集和验证集
            val_start = fold * fold_size
            val_end = val_start + fold_size
            val_indices = indices[val_start:val_end]
            train_indices = indices[:val_start] + indices[val_end:]
            
            # 计算训练集上的正则化惩罚
            train_weights = [weights[i] for i in train_indices]
            train_scores = [scores[i] for i in train_indices]
            
            if method == "l1":
                penalty = lam * sum(abs(w) for w in train_weights)
            else:
                penalty = lam * sum(w ** 2 for w in train_weights)
            
            # 计算验证集上的误差
            val_scores = [scores[i] for i in val_indices]
            if val_scores:
                mean_score = sum(val_scores) / len(val_scores)
                variance = sum((s - mean_score) ** 2 for s in val_scores) / len(val_scores)
                fold_score = variance + penalty  # 简化的验证分数
            else:
                fold_score = penalty
            
            fold_scores.append(fold_score)
        
        avg_score = sum(fold_scores) / len(fold_scores)
        cv_results.append({
            "lambda": lam,
            "fold_scores": [round(s, 6) for s in fold_scores],
            "avg_score": round(avg_score, 6),
            "std_score": round(math.sqrt(sum((s - avg_score) ** 2 for s in fold_scores) / len(fold_scores)), 6)
        })
    
    # 选择最佳lambda
    best_result = min(cv_results, key=lambda x: x["avg_score"])
    
    return {
        "success": True,
        "method": method,
        "k_folds": k_folds,
        "cv_results": cv_results,
        "best_lambda": best_result["lambda"],
        "best_score": best_result["avg_score"],
        "validated_at": datetime.now().isoformat()
    }

@app.post("/api/quality/regular/penalty")
async def compute_regularization_penalty(request: Request):
    """计算正则化惩罚"""
    from datetime import datetime
    import math
    
    data = await request.json()
    weights = data.get("weights", [])
    method = data.get("method", "l2")
    lambda_val = data.get("lambda", 0.1)
    
    if not weights:
        return {
            "success": False,
            "error": "没有提供权重数据"
        }
    
    n = len(weights)
    penalties = {}
    
    # L1惩罚
    penalties["l1"] = lambda_val * sum(abs(w) for w in weights)
    
    # L2惩罚
    penalties["l2"] = lambda_val * sum(w ** 2 for w in weights)
    
    # 弹性网络惩罚
    alpha = 0.5
    penalties["elastic"] = alpha * penalties["l1"] + (1 - alpha) * penalties["l2"]
    
    # 范数统计
    norms = {
        "l1_norm": sum(abs(w) for w in weights),
        "l2_norm": math.sqrt(sum(w ** 2 for w in weights)),
        "l_inf_norm": max(abs(w) for w in weights),
        "n_nonzero": sum(1 for w in weights if abs(w) > 1e-10),
        "sparsity": 1 - sum(1 for w in weights if abs(w) > 1e-10) / n
    }
    
    return {
        "success": True,
        "method": method,
        "lambda": lambda_val,
        "penalties": {k: round(v, 6) for k, v in penalties.items()},
        "selected_penalty": round(penalties.get(method, 0), 6),
        "norms": {k: round(v, 6) if isinstance(v, float) else v for k, v in norms.items()},
        "computed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/regular/sparsity")
async def analyze_sparsity(request: Request):
    """分析权重稀疏性"""
    from datetime import datetime
    import math
    
    data = await request.json()
    weights = data.get("weights", [])
    threshold = data.get("threshold", 1e-4)
    
    if not weights:
        return {
            "success": False,
            "error": "没有提供权重数据"
        }
    
    n = len(weights)
    
    # 计算稀疏性指标
    zero_count = sum(1 for w in weights if abs(w) < threshold)
    nonzero_count = n - zero_count
    sparsity = zero_count / n
    
    # 权重分布统计
    abs_weights = [abs(w) for w in weights]
    mean_abs = sum(abs_weights) / n
    variance = sum((w - mean_abs) ** 2 for w in abs_weights) / n
    
    # 分位数
    sorted_weights = sorted(abs_weights)
    percentiles = {
        "p10": sorted_weights[int(n * 0.1)] if n > 0 else 0,
        "p25": sorted_weights[int(n * 0.25)] if n > 0 else 0,
        "p50": sorted_weights[int(n * 0.5)] if n > 0 else 0,
        "p75": sorted_weights[int(n * 0.75)] if n > 0 else 0,
        "p90": sorted_weights[int(n * 0.9)] if n > 0 else 0
    }
    
    return {
        "success": True,
        "threshold": threshold,
        "sparsity_analysis": {
            "total_weights": n,
            "zero_weights": zero_count,
            "nonzero_weights": nonzero_count,
            "sparsity_ratio": round(sparsity, 4),
            "mean_absolute_weight": round(mean_abs, 6),
            "std_absolute_weight": round(math.sqrt(variance), 6)
        },
        "percentiles": {k: round(v, 6) for k, v in percentiles.items()},
        "analyzed_at": datetime.now().isoformat()
    }

