@app.post("/api/quality/regular/summary")
async def get_regular_summary(request: Request):
    """获取正则化摘要"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")  # all, day, week, month
    
    # 筛选时间范围
    now = datetime.now()
    filtered = []
    
    for log in QUALITY_REGULAR["regular_log"]:
        timestamp = log.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(log)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(log)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(log)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(log)
            except:
                pass
    
    # 统计
    method_counter = Counter(log.get("method", "unknown") for log in filtered)
    total_penalty = sum(log.get("penalty", 0) for log in filtered)
    
    summary = {
        "period": period,
        "total_regularizations": len(filtered),
        "by_method": dict(method_counter),
        "avg_penalty": round(total_penalty / len(filtered), 6) if filtered else 0,
        "total_weights_processed": QUALITY_REGULAR["regular_stats"]["total_records_processed"],
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

# 质量评分数据离散化配置
QUALITY_DISCRETIZE = {
    "enabled": True,
    "discretize_stats": {
        "total_discretizations": 0,
        "total_records_processed": 0,
        "avg_bins": 0
    },
    "discretize_log": [],
    "discretize_types": [
        {"id": "equal_width", "name": "等宽离散化", "description": "将值域分成等宽区间"},
        {"id": "equal_freq", "name": "等频离散化", "description": "每个区间样本数相等"},
        {"id": "kmeans", "name": "K-Means离散化", "description": "基于聚类中心划分"},
        {"id": "decision_tree", "name": "决策树离散化", "description": "基于信息增益划分"},
        {"id": "custom", "name": "自定义离散化", "description": "用户指定分界点"}
    ]
}

@app.post("/api/quality/discretize")
async def discretize_data(request: Request):
    """执行数据离散化"""
    from datetime import datetime
    import math
    
    data = await request.json()
    method = data.get("method", "equal_width")  # equal_width, equal_freq, kmeans, decision_tree, custom
    values = data.get("values", [])  # 数值列表
    n_bins = data.get("n_bins", 5)  # 分箱数
    boundaries = data.get("boundaries", [])  # 自定义边界
    
    if not values:
        return {
            "success": False,
            "error": "没有提供数值数据"
        }
    
    n = len(values)
    discretized = []
    bin_edges = []
    bin_labels = []
    
    if method == "equal_width":
        # 等宽离散化
        min_val = min(values)
        max_val = max(values)
        width = (max_val - min_val) / n_bins if n_bins > 0 else 1
        
        bin_edges = [min_val + i * width for i in range(n_bins + 1)]
        
        for v in values:
            bin_idx = min(int((v - min_val) / width), n_bins - 1) if width > 0 else 0
            discretized.append(bin_idx)
        
        bin_labels = [f"[{bin_edges[i]:.2f}, {bin_edges[i+1]:.2f})" for i in range(n_bins)]
        
    elif method == "equal_freq":
        # 等频离散化
        sorted_values = sorted(values)
        per_bin = n // n_bins if n_bins > 0 else 1
        
        bin_edges = [sorted_values[0]]
        for i in range(1, n_bins):
            idx = min(i * per_bin, n - 1)
            bin_edges.append(sorted_values[idx])
        bin_edges.append(sorted_values[-1])
        
        for v in values:
            bin_idx = 0
            for i in range(len(bin_edges) - 1):
                if v >= bin_edges[i] and v < bin_edges[i + 1]:
                    bin_idx = i
                    break
                if i == len(bin_edges) - 2:
                    bin_idx = i
            discretized.append(bin_idx)
        
        bin_labels = [f"Bin {i}" for i in range(n_bins)]
        
    elif method == "kmeans":
        # K-Means离散化（简化版）
        # 初始化聚类中心
        min_val = min(values)
        max_val = max(values)
        step = (max_val - min_val) / (n_bins + 1)
        centers = [min_val + (i + 1) * step for i in range(n_bins)]
        
        # 迭代优化（简化：仅迭代3次）
        for _ in range(3):
            # 分配点到最近的中心
            clusters = [[] for _ in range(n_bins)]
            for v in values:
                distances = [abs(v - c) for c in centers]
                closest = distances.index(min(distances))
                clusters[closest].append(v)
            
            # 更新中心
            for i in range(n_bins):
                if clusters[i]:
                    centers[i] = sum(clusters[i]) / len(clusters[i])
        
        # 确定边界
        sorted_centers = sorted(centers)
        bin_edges = [min_val]
        for i in range(n_bins - 1):
            bin_edges.append((sorted_centers[i] + sorted_centers[i + 1]) / 2)
        bin_edges.append(max_val)
        
        # 离散化
        for v in values:
            bin_idx = 0
            for i in range(len(bin_edges) - 1):
                if v <= bin_edges[i + 1]:
                    bin_idx = i
                    break
            discretized.append(bin_idx)
        
        bin_labels = [f"Cluster {i} (center={sorted_centers[i]:.2f})" for i in range(n_bins)]
        
    elif method == "decision_tree":
        # 决策树离散化（简化：基于信息增益）
        # 使用中位数分割
        sorted_values = sorted(values)
        
        # 递归分割
        def split(vals, depth=0, max_depth=3):
            if depth >= max_depth or len(vals) < 2:
                return [min(vals), max(vals)] if vals else [0, 0]
            
            mid = len(vals) // 2
            left = vals[:mid]
            right = vals[mid:]
            
            threshold = vals[mid]
            left_bounds = split(left, depth + 1, max_depth)
            right_bounds = split(right, depth + 1, max_depth)
            
            return [left_bounds[0], threshold, right_bounds[1]]
        
        bin_edges = sorted(set(split(sorted_values)))
        
        # 离散化
        for v in values:
            bin_idx = 0
            for i in range(len(bin_edges) - 1):
                if v >= bin_edges[i] and v < bin_edges[i + 1]:
                    bin_idx = i
                    break
                if i == len(bin_edges) - 2:
                    bin_idx = i
            discretized.append(bin_idx)
        
        bin_labels = [f"Bin {i}" for i in range(len(bin_edges) - 1)]
        
    elif method == "custom":
        # 自定义离散化
        if not boundaries:
            boundaries = [0, 0.3, 0.6, 0.8, 1.0]
        
        bin_edges = boundaries
        
        for v in values:
            bin_idx = 0
            for i in range(len(bin_edges) - 1):
                if v >= bin_edges[i] and v < bin_edges[i + 1]:
                    bin_idx = i
                    break
                if i == len(bin_edges) - 2:
                    bin_idx = i
            discretized.append(bin_idx)
        
        bin_labels = [f"[{bin_edges[i]}, {bin_edges[i+1]})" for i in range(len(bin_edges) - 1)]
    
    # 统计每个bin的数量
    from collections import Counter
    bin_counts = Counter(discretized)
    
    # 更新统计
    QUALITY_DISCRETIZE["discretize_stats"]["total_discretizations"] += 1
    QUALITY_DISCRETIZE["discretize_stats"]["total_records_processed"] += n
    QUALITY_DISCRETIZE["discretize_stats"]["avg_bins"] = round(
        (QUALITY_DISCRETIZE["discretize_stats"]["avg_bins"] * (QUALITY_DISCRETIZE["discretize_stats"]["total_discretizations"] - 1) + n_bins) / QUALITY_DISCRETIZE["discretize_stats"]["total_discretizations"],
        2
    )
    
    # 记录操作
    discretize_record = {
        "id": len(QUALITY_DISCRETIZE["discretize_log"]) + 1,
        "method": method,
        "n_values": n,
        "n_bins": n_bins,
        "bin_edges": [round(e, 4) for e in bin_edges],
        "created_at": datetime.now().isoformat()
    }
    QUALITY_DISCRETIZE["discretize_log"].append(discretize_record)
    
    return {
        "success": True,
        "method": method,
        "original_values": values[:10] + (["..."] if n > 10 else []),
        "discretized": discretized[:10] + (["..."] if n > 10 else []),
        "bin_edges": [round(e, 4) for e in bin_edges],
        "bin_labels": bin_labels,
        "bin_counts": {str(k): v for k, v in sorted(bin_counts.items())},
        "n_bins": len(bin_labels),
        "stats": {
            "n_values": n,
            "min": round(min(values), 4),
            "max": round(max(values), 4),
            "mean": round(sum(values) / n, 4)
        },
        "discretized_at": datetime.now().isoformat()
    }

@app.post("/api/quality/discretize/batch")
async def batch_discretize(request: Request):
    """批量离散化多个字段"""
    from datetime import datetime
    
    data = await request.json()
    fields = data.get("fields", {})  # {"field1": [values], "field2": [values]}
    method = data.get("method", "equal_width")
    n_bins = data.get("n_bins", 5)
    
    if not fields:
        return {
            "success": False,
            "error": "没有提供字段数据"
        }
    
    results = {}
    
    for field_name, values in fields.items():
        if not values:
            results[field_name] = {"error": "没有数据"}
            continue
        
        min_val = min(values)
        max_val = max(values)
        width = (max_val - min_val) / n_bins if n_bins > 0 else 1
        
        discretized = []
        for v in values:
            bin_idx = min(int((v - min_val) / width), n_bins - 1) if width > 0 else 0
            discretized.append(bin_idx)
        
        results[field_name] = {
            "discretized": discretized[:20] + (["..."] if len(discretized) > 20 else []),
            "n_bins": n_bins,
            "bin_edges": [round(min_val + i * width, 4) for i in range(n_bins + 1)]
        }
    
    return {
        "success": True,
        "method": method,
        "fields_processed": len(results),
        "results": results,
        "processed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/discretize/optimal")
async def find_optimal_bins(request: Request):
    """寻找最优分箱数"""
    from datetime import datetime
    import math
    
    data = await request.json()
    values = data.get("values", [])
    max_bins = data.get("max_bins", 10)
    criterion = data.get("criterion", "variance")  # variance, entropy, silhouette
    
    if not values:
        return {
            "success": False,
            "error": "没有提供数值数据"
        }
    
    n = len(values)
    min_val = min(values)
    max_val = max(values)
    
    results = []
    best_n_bins = 2
    best_score = float('inf') if criterion == "variance" else 0
    
    for n_bins in range(2, max_bins + 1):
        width = (max_val - min_val) / n_bins
        
        # 离散化
        discretized = []
        for v in values:
            bin_idx = min(int((v - min_val) / width), n_bins - 1) if width > 0 else 0
            discretized.append(bin_idx)
        
        # 计算评分
        if criterion == "variance":
            # 计算组内方差
            bins = {}
            for i, d in enumerate(discretized):
                if d not in bins:
                    bins[d] = []
                bins[d].append(values[i])
            
            total_variance = 0
            for bin_vals in bins.values():
                if bin_vals:
                    mean = sum(bin_vals) / len(bin_vals)
                    variance = sum((v - mean) ** 2 for v in bin_vals)
                    total_variance += variance
            
            score = total_variance
            if score < best_score:
                best_score = score
                best_n_bins = n_bins
        
        elif criterion == "entropy":
            # 计算信息熵
            from collections import Counter
            counts = Counter(discretized)
            total = len(discretized)
            entropy = -sum((c / total) * math.log2(c / total) for c in counts.values() if c > 0)
            score = entropy
            
            if score > best_score:
                best_score = score
                best_n_bins = n_bins
        
        results.append({
            "n_bins": n_bins,
            "score": round(score, 4)
        })
    
    return {
        "success": True,
        "criterion": criterion,
        "evaluation_results": results,
        "optimal_n_bins": best_n_bins,
        "best_score": round(best_score, 4),
        "found_at": datetime.now().isoformat()
    }

@app.post("/api/quality/discretize/merge")
async def merge_bins(request: Request):
    """合并相邻分箱"""
    from datetime import datetime
    
    data = await request.json()
    discretized = data.get("discretized", [])  # 已离散化的数据
    bin_edges = data.get("bin_edges", [])  # 分箱边界
    merge_strategy = data.get("merge_strategy", "adjacent")  # adjacent, low_freq, similarity
    threshold = data.get("threshold", 0.1)  # 合并阈值
    
    if not discretized or not bin_edges:
        return {
            "success": False,
            "error": "没有提供离散化数据或边界"
        }
    
    from collections import Counter
    bin_counts = Counter(discretized)
    n = len(discretized)
    
    new_bin_edges = bin_edges.copy()
    merged_bins = []
    
    if merge_strategy == "adjacent":
        # 合并相邻的低频bin
        i = 0
        while i < len(new_bin_edges) - 2:
            bin_idx = i
            freq = bin_counts.get(bin_idx, 0) / n
            next_freq = bin_counts.get(bin_idx + 1, 0) / n
            
            if freq < threshold or next_freq < threshold:
                # 合并
                merged_bins.append({
                    "merged": [bin_idx, bin_idx + 1],
                    "new_edge": new_bin_edges[i + 1]
                })
                new_bin_edges.pop(i + 1)
            else:
                i += 1
    
    elif merge_strategy == "low_freq":
        # 合并所有低频bin
        low_freq_bins = [b for b, c in bin_counts.items() if c / n < threshold]
        
        for b in sorted(low_freq_bins, reverse=True):
            if b < len(new_bin_edges) - 1:
                new_bin_edges.pop(b)
                merged_bins.append({"removed_bin": b})
    
    # 重新映射离散化结果
    new_discretized = []
    for d in discretized:
        new_d = d
        for merge in merged_bins:
            if "merged" in merge and d in merge["merged"]:
                new_d = merge["merged"][0]
        new_discretized.append(new_d)
    
    return {
        "success": True,
        "merge_strategy": merge_strategy,
        "original_n_bins": len(bin_edges) - 1,
        "new_n_bins": len(new_bin_edges) - 1,
        "merged_bins": merged_bins,
        "new_bin_edges": [round(e, 4) for e in new_bin_edges],
        "processed_at": datetime.now().isoformat()
    }

@app.post("/api/quality/discretize/split")
async def split_bin(request: Request):
    """拆分分箱"""
    from datetime import datetime
    
    data = await request.json()
    bin_idx = data.get("bin_idx", 0)  # 要拆分的bin索引
    bin_edges = data.get("bin_edges", [])  # 分箱边界
    split_point = data.get("split_point", None)  # 拆分点（None则取中点）
    
    if not bin_edges or bin_idx >= len(bin_edges) - 1:
        return {
            "success": False,
            "error": "无效的分箱索引或边界"
        }
    
    # 确定拆分点
    if split_point is None:
        split_point = (bin_edges[bin_idx] + bin_edges[bin_idx + 1]) / 2
    else:
        # 确保拆分点在bin范围内
        split_point = max(bin_edges[bin_idx], min(split_point, bin_edges[bin_idx + 1]))
    
    # 创建新的边界
    new_bin_edges = bin_edges.copy()
    new_bin_edges.insert(bin_idx + 1, split_point)
    
    return {
        "success": True,
        "split_bin_idx": bin_idx,
        "split_point": round(split_point, 4),
        "original_n_bins": len(bin_edges) - 1,
        "new_n_bins": len(new_bin_edges) - 1,
        "new_bin_edges": [round(e, 4) for e in new_bin_edges],
        "processed_at": datetime.now().isoformat()
    }

