@app.post("/api/quality/discretize/summary")
async def get_discretize_summary(request: Request):
    """获取离散化摘要"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")  # all, day, week, month
    
    # 筛选时间范围
    now = datetime.now()
    filtered = []
    
    for log in QUALITY_DISCRETIZE["discretize_log"]:
        timestamp = log.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(log)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(log)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(log)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(log)
            except:
                pass
    
    # 统计
    method_counter = Counter(log.get("method", "unknown") for log in filtered)
    total_bins = sum(log.get("n_bins", 0) for log in filtered)
    
    summary = {
        "period": period,
        "total_discretizations": len(filtered),
        "by_method": dict(method_counter),
        "avg_bins": round(total_bins / len(filtered), 2) if filtered else 0,
        "total_values_processed": QUALITY_DISCRETIZE["discretize_stats"]["total_records_processed"],
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

