@app.post("/api/snn/temporal")
async def process_temporal_sequence(request: Request):
    """处理时序序列"""
    from datetime import datetime
    import math
    import random
    
    data = await request.json()
    sequence = data.get("sequence", [])  # 时序数据
    model_type = data.get("model_type", "spike_rnn")
    time_window = data.get("time_window", 100)  # 时间窗口（ms）
    threshold = data.get("threshold", 0.5)  # 脉冲阈值
    
    if not sequence:
        return {
            "success": False,
            "error": "没有提供时序数据"
        }
    
    n = len(sequence)
    
    # 模拟SNN时序处理
    membrane_potential = 0.0
    spikes = []
    attention_values = []
    semantic_strengths = []
    
    for i, val in enumerate(sequence):
        # 更新膜电位
        membrane_potential += val * 0.1
        
        # 泄露
        membrane_potential *= 0.9
        
        # 脉冲生成
        spike = 1 if membrane_potential >= threshold else 0
        spikes.append(spike)
        
        # 计算注意力（基于脉冲频率）
        window_start = max(0, i - 10)
        recent_spikes = sum(spikes[window_start:i+1])
        attention = min(1.0, recent_spikes / 10.0)
        attention_values.append(attention)
        
        # 计算语义强度（基于序列变化）
        if i > 0:
            delta = abs(sequence[i] - sequence[i-1])
            semantic_strength = min(1.0, delta * 10)
        else:
            semantic_strength = 0.0
        semantic_strengths.append(semantic_strength)
        
        # 重置膜电位
        if spike:
            membrane_potential = 0.0
    
    # 计算统计指标
    total_spikes = sum(spikes)
    spike_rate = total_spikes / n if n > 0 else 0
    avg_attention = sum(attention_values) / n if n > 0 else 0
    avg_semantic = sum(semantic_strengths) / n if n > 0 else 0
    
    # 更新统计
    SNN_TEMPORAL["temporal_stats"]["total_models"] += 1
    SNN_TEMPORAL["temporal_stats"]["total_sequences_processed"] += n
    SNN_TEMPORAL["temporal_stats"]["avg_attention"] = round(
        (SNN_TEMPORAL["temporal_stats"]["avg_attention"] * (SNN_TEMPORAL["temporal_stats"]["total_models"] - 1) + avg_attention) / SNN_TEMPORAL["temporal_stats"]["total_models"],
        4
    )
    SNN_TEMPORAL["temporal_stats"]["avg_semantic_strength"] = round(
        (SNN_TEMPORAL["temporal_stats"]["avg_semantic_strength"] * (SNN_TEMPORAL["temporal_stats"]["total_models"] - 1) + avg_semantic) / SNN_TEMPORAL["temporal_stats"]["total_models"],
        6
    )
    
    # 记录操作
    temporal_record = {
        "id": len(SNN_TEMPORAL["temporal_log"]) + 1,
        "model_type": model_type,
        "sequence_length": n,
        "time_window": time_window,
        "spike_rate": round(spike_rate, 4),
        "avg_attention": round(avg_attention, 4),
        "avg_semantic_strength": round(avg_semantic, 6),
        "created_at": datetime.now().isoformat()
    }
    SNN_TEMPORAL["temporal_log"].append(temporal_record)
    
    return {
        "success": True,
        "model_type": model_type,
        "sequence_length": n,
        "time_window": time_window,
        "results": {
            "spikes": spikes[:20] + (["..."] if n > 20 else []),
            "attention_values": [round(a, 4) for a in attention_values[:20]] + (["..."] if n > 20 else []),
            "semantic_strengths": [round(s, 6) for s in semantic_strengths[:20]] + (["..."] if n > 20 else [])
        },
        "metrics": {
            "total_spikes": total_spikes,
            "spike_rate": round(spike_rate, 4),
            "avg_attention": round(avg_attention, 4),
            "avg_semantic_strength": round(avg_semantic, 6),
            "activation_level": round(avg_attention * avg_semantic, 4)
        },
        "processed_at": datetime.now().isoformat()
    }

@app.post("/api/snn/temporal/train")
async def train_temporal_model(request: Request):
    """训练时序模型"""
    from datetime import datetime
    import math
    
    data = await request.json()
    sequences = data.get("sequences", [])  # 多个训练序列
    labels = data.get("labels", [])  # 对应标签
    model_type = data.get("model_type", "spike_rnn")
    epochs = data.get("epochs", 10)
    learning_rate = data.get("learning_rate", 0.01)
    
    if not sequences:
        return {
            "success": False,
            "error": "没有提供训练数据"
        }
    
    n_sequences = len(sequences)
    
    # 模拟训练过程
    training_history = []
    initial_loss = 1.0
    
    for epoch in range(epochs):
        # 模拟损失下降
        loss = initial_loss * math.exp(-learning_rate * epoch)
        accuracy = 1 - loss * 0.5
        
        training_history.append({
            "epoch": epoch + 1,
            "loss": round(loss, 4),
            "accuracy": round(accuracy, 4)
        })
    
    final_loss = training_history[-1]["loss"]
    final_accuracy = training_history[-1]["accuracy"]
    
    return {
        "success": True,
        "model_type": model_type,
        "training_config": {
            "n_sequences": n_sequences,
            "epochs": epochs,
            "learning_rate": learning_rate
        },
        "training_history": training_history,
        "final_metrics": {
            "loss": final_loss,
            "accuracy": final_accuracy
        },
        "trained_at": datetime.now().isoformat()
    }

@app.post("/api/snn/temporal/predict")
async def predict_temporal(request: Request):
    """时序预测"""
    from datetime import datetime
    import math
    import random
    
    data = await request.json()
    sequence = data.get("sequence", [])
    horizon = data.get("horizon", 5)  # 预测步数
    model_type = data.get("model_type", "spike_rnn")
    
    if not sequence:
        return {
            "success": False,
            "error": "没有提供时序数据"
        }
    
    n = len(sequence)
    
    # 基于历史数据的简单预测
    predictions = []
    last_val = sequence[-1]
    
    # 计算趋势
    if n >= 2:
        trend = (sequence[-1] - sequence[-2])
    else:
        trend = 0
    
    for i in range(horizon):
        # 添加趋势和随机噪声
        pred = last_val + trend * (i + 1) * 0.8
        noise = random.gauss(0, 0.05)
        pred += noise
        predictions.append(round(pred, 4))
    
    # 计算预测置信度
    confidence = max(0.1, 1.0 - horizon * 0.1)
    
    return {
        "success": True,
        "model_type": model_type,
        "input_length": n,
        "horizon": horizon,
        "predictions": predictions,
        "confidence": round(confidence, 4),
        "predicted_at": datetime.now().isoformat()
    }

@app.post("/api/snn/temporal/attention")
async def compute_temporal_attention(request: Request):
    """计算时序注意力"""
    from datetime import datetime
    import math
    
    data = await request.json()
    sequence = data.get("sequence", [])
    attention_type = data.get("attention_type", "self")  # self, cross, local
    
    if not sequence:
        return {
            "success": False,
            "error": "没有提供时序数据"
        }
    
    n = len(sequence)
    
    # 计算注意力权重
    attention_matrix = []
    
    for i in range(n):
        weights = []
        for j in range(n):
            if attention_type == "self":
                # 自注意力：基于值相似度
                sim = 1 / (1 + abs(sequence[i] - sequence[j]))
            elif attention_type == "local":
                # 局部注意力：距离衰减
                distance = abs(i - j)
                sim = math.exp(-distance / 5.0)
            else:
                # 交叉注意力：随机模拟
                sim = 0.5
            
            weights.append(round(sim, 4))
        
        # 归一化
        total = sum(weights)
        weights = [round(w / total, 4) for w in weights]
        attention_matrix.append(weights)
    
    # 找出高注意力位置
    high_attention_positions = []
    for i in range(n):
        max_weight = max(attention_matrix[i])
        max_pos = attention_matrix[i].index(max_weight)
        if max_weight > 0.3:
            high_attention_positions.append({
                "position": i,
                "attends_to": max_pos,
                "weight": max_weight
            })
    
    return {
        "success": True,
        "attention_type": attention_type,
        "sequence_length": n,
        "attention_matrix": attention_matrix[:5] if n > 5 else attention_matrix,  # 只返回前5行
        "high_attention_positions": high_attention_positions[:10],
        "computed_at": datetime.now().isoformat()
    }

@app.post("/api/snn/temporal/memory")
async def manage_temporal_memory(request: Request):
    """管理时序记忆"""
    from datetime import datetime
    
    data = await request.json()
    action = data.get("action", "store")  # store, retrieve, consolidate
    memory_data = data.get("memory_data", {})
    memory_id = data.get("memory_id", None)
    
    # 初始化记忆存储
    if not hasattr(manage_temporal_memory, "memory_store"):
        manage_temporal_memory.memory_store = {}
        manage_temporal_memory.memory_counter = 0
    
    if action == "store":
        manage_temporal_memory.memory_counter += 1
        mem_id = f"mem_{manage_temporal_memory.memory_counter}"
        manage_temporal_memory.memory_store[mem_id] = {
            "data": memory_data,
            "created_at": datetime.now().isoformat(),
            "access_count": 0
        }
        
        return {
            "success": True,
            "action": "store",
            "memory_id": mem_id,
            "stored_at": datetime.now().isoformat()
        }
    
    elif action == "retrieve":
        if memory_id and memory_id in manage_temporal_memory.memory_store:
            manage_temporal_memory.memory_store[memory_id]["access_count"] += 1
            return {
                "success": True,
                "action": "retrieve",
                "memory_id": memory_id,
                "memory_data": manage_temporal_memory.memory_store[memory_id]["data"],
                "access_count": manage_temporal_memory.memory_store[memory_id]["access_count"]
            }
        else:
            return {
                "success": False,
                "error": "记忆ID不存在"
            }
    
    elif action == "consolidate":
        # 记忆巩固：合并相似记忆
        consolidated = []
        for mem_id, mem_data in manage_temporal_memory.memory_store.items():
            if mem_data["access_count"] > 2:
                consolidated.append(mem_id)
        
        return {
            "success": True,
            "action": "consolidate",
            "consolidated_memories": consolidated,
            "total_memories": len(manage_temporal_memory.memory_store)
        }
    
    return {
        "success": False,
        "error": "未知操作"
    }

