# 工作记忆扩展配置
WORKING_MEMORY = {
    "enabled": True,
    "memory_stats": {
        "total_operations": 0,
        "total_items_stored": 0,
        "avg_capacity_used": 0.0,
        "consolidation_count": 0
    },
    "memory_log": [],
    "memory_types": [
        {"id": "episodic", "name": "情景记忆", "description": "事件序列和经历"},
        {"id": "semantic", "name": "语义记忆", "description": "概念和知识"},
        {"id": "procedural", "name": "程序记忆", "description": "技能和操作"},
        {"id": "working", "name": "工作记忆", "description": "临时处理和推理"},
        {"id": "long_term", "name": "长期记忆", "description": "持久化存储"}
    ],
    "capacity_limit": 7,  # Miller's magic number 7±2
    "decay_rate": 0.1
}

@app.post("/api/memory/store")
async def store_memory(request: Request):
    """存储记忆"""
    from datetime import datetime
    import hashlib
    
    data = await request.json()
    content = data.get("content", "")
    memory_type = data.get("memory_type", "working")
    importance = data.get("importance", 0.5)  # 0-1
    associations = data.get("associations", [])  # 关联记忆ID
    
    if not content:
        return {
            "success": False,
            "error": "没有提供记忆内容"
        }
    
    # 生成记忆ID
    content_hash = hashlib.md5(f"{content}{datetime.now().isoformat()}".encode()).hexdigest()[:8]
    memory_id = f"mem_{memory_type}_{content_hash}"
    
    # 计算初始强度
    initial_strength = importance * 0.5 + 0.5
    
    # 存储记忆
    memory_entry = {
        "id": memory_id,
        "content": content,
        "memory_type": memory_type,
        "importance": importance,
        "associations": associations,
        "strength": initial_strength,
        "access_count": 0,
        "created_at": datetime.now().isoformat(),
        "last_accessed": datetime.now().isoformat()
    }
    
    # 初始化存储
    if not hasattr(store_memory, "memory_bank"):
        store_memory.memory_bank = {}
    
    store_memory.memory_bank[memory_id] = memory_entry
    
    # 更新统计
    WORKING_MEMORY["memory_stats"]["total_operations"] += 1
    WORKING_MEMORY["memory_stats"]["total_items_stored"] += 1
    
    # 记录操作
    WORKING_MEMORY["memory_log"].append({
        "id": len(WORKING_MEMORY["memory_log"]) + 1,
        "operation": "store",
        "memory_id": memory_id,
        "memory_type": memory_type,
        "created_at": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "memory_id": memory_id,
        "memory_type": memory_type,
        "initial_strength": round(initial_strength, 4),
        "capacity_remaining": WORKING_MEMORY["capacity_limit"] - len([m for m in store_memory.memory_bank.values() if m["memory_type"] == "working"]),
        "stored_at": datetime.now().isoformat()
    }

@app.post("/api/memory/retrieve")
async def retrieve_memory(request: Request):
    """检索记忆"""
    from datetime import datetime
    
    data = await request.json()
    query = data.get("query", "")
    memory_type = data.get("memory_type", None)
    limit = data.get("limit", 5)
    
    # 初始化存储
    if not hasattr(store_memory, "memory_bank"):
        store_memory.memory_bank = {}
    
    # 搜索记忆
    results = []
    query_lower = query.lower()
    
    for mem_id, mem_data in store_memory.memory_bank.items():
        # 类型过滤
        if memory_type and mem_data["memory_type"] != memory_type:
            continue
        
        # 内容匹配
        content_lower = mem_data["content"].lower()
        relevance = 0.0
        
        if query_lower in content_lower:
            relevance = 1.0
        else:
            # 部分匹配
            query_words = set(query_lower.split())
            content_words = set(content_lower.split())
            overlap = len(query_words & content_words)
            if overlap > 0:
                relevance = overlap / len(query_words)
        
        if relevance > 0:
            # 更新访问计数和强度
            mem_data["access_count"] += 1
            mem_data["last_accessed"] = datetime.now().isoformat()
            mem_data["strength"] = min(1.0, mem_data["strength"] + 0.1)
            
            results.append({
                "memory_id": mem_id,
                "content": mem_data["content"],
                "memory_type": mem_data["memory_type"],
                "relevance": round(relevance, 4),
                "strength": round(mem_data["strength"], 4),
                "access_count": mem_data["access_count"]
            })
    
    # 按相关性和强度排序
    results.sort(key=lambda x: (x["relevance"], x["strength"]), reverse=True)
    results = results[:limit]
    
    # 更新统计
    WORKING_MEMORY["memory_stats"]["total_operations"] += 1
    
    return {
        "success": True,
        "query": query,
        "results_count": len(results),
        "results": results,
        "retrieved_at": datetime.now().isoformat()
    }

@app.post("/api/memory/consolidate")
async def consolidate_memory(request: Request):
    """记忆巩固"""
    from datetime import datetime
    
    data = await request.json()
    threshold = data.get("threshold", 0.7)  # 巩固阈值
    min_access = data.get("min_access", 3)  # 最小访问次数
    
    # 初始化存储
    if not hasattr(store_memory, "memory_bank"):
        store_memory.memory_bank = {}
    
    consolidated = []
    promoted = []
    
    for mem_id, mem_data in list(store_memory.memory_bank.items()):
        # 检查是否满足巩固条件
        if mem_data["strength"] >= threshold and mem_data["access_count"] >= min_access:
            if mem_data["memory_type"] == "working":
                # 工作记忆提升为长期记忆
                mem_data["memory_type"] = "long_term"
                mem_data["strength"] = 1.0
                promoted.append(mem_id)
            consolidated.append(mem_id)
    
    # 更新统计
    WORKING_MEMORY["memory_stats"]["total_operations"] += 1
    WORKING_MEMORY["memory_stats"]["consolidation_count"] += len(consolidated)
    
    # 记录操作
    WORKING_MEMORY["memory_log"].append({
        "id": len(WORKING_MEMORY["memory_log"]) + 1,
        "operation": "consolidate",
        "consolidated_count": len(consolidated),
        "promoted_count": len(promoted),
        "created_at": datetime.now().isoformat()
    })
    
    return {
        "success": True,
        "consolidated_memories": consolidated,
        "promoted_to_long_term": promoted,
        "total_consolidated": len(consolidated),
        "consolidated_at": datetime.now().isoformat()
    }

@app.post("/api/memory/forget")
async def forget_memory(request: Request):
    """遗忘记忆"""
    from datetime import datetime
    
    data = await request.json()
    memory_id = data.get("memory_id", None)
    decay = data.get("decay", False)  # 是否使用衰减遗忘
    decay_factor = data.get("decay_factor", 0.1)
    
    # 初始化存储
    if not hasattr(store_memory, "memory_bank"):
        store_memory.memory_bank = {}
    
    if decay:
        # 衰减所有记忆
        forgotten = []
        for mem_id, mem_data in list(store_memory.memory_bank.items()):
            mem_data["strength"] *= (1 - decay_factor)
            if mem_data["strength"] < 0.1:
                forgotten.append(mem_id)
                del store_memory.memory_bank[mem_id]
        
        return {
            "success": True,
            "operation": "decay",
            "forgotten_count": len(forgotten),
            "forgotten_ids": forgotten,
            "forgotten_at": datetime.now().isoformat()
        }
    
    elif memory_id:
        # 遗忘特定记忆
        if memory_id in store_memory.memory_bank:
            del store_memory.memory_bank[memory_id]
            
            WORKING_MEMORY["memory_stats"]["total_operations"] += 1
            
            return {
                "success": True,
                "operation": "forget",
                "memory_id": memory_id,
                "forgotten_at": datetime.now().isoformat()
            }
        else:
            return {
                "success": False,
                "error": "记忆ID不存在"
            }
    
    return {
        "success": False,
        "error": "请指定memory_id或设置decay=true"
    }

@app.post("/api/memory/associate")
async def associate_memories(request: Request):
    """关联记忆"""
    from datetime import datetime
    
    data = await request.json()
    memory_id_1 = data.get("memory_id_1", "")
    memory_id_2 = data.get("memory_id_2", "")
    association_type = data.get("association_type", "related")  # related, causal, temporal
    
    # 初始化存储
    if not hasattr(store_memory, "memory_bank"):
        store_memory.memory_bank = {}
    
    if memory_id_1 not in store_memory.memory_bank or memory_id_2 not in store_memory.memory_bank:
        return {
            "success": False,
            "error": "一个或两个记忆ID不存在"
        }
    
    # 添加关联
    if memory_id_2 not in store_memory.memory_bank[memory_id_1]["associations"]:
        store_memory.memory_bank[memory_id_1]["associations"].append({
            "target": memory_id_2,
            "type": association_type,
            "created_at": datetime.now().isoformat()
        })
    
    if memory_id_1 not in store_memory.memory_bank[memory_id_2]["associations"]:
        store_memory.memory_bank[memory_id_2]["associations"].append({
            "target": memory_id_1,
            "type": association_type,
            "created_at": datetime.now().isoformat()
        })
    
    # 更新统计
    WORKING_MEMORY["memory_stats"]["total_operations"] += 1
    
    return {
        "success": True,
        "memory_id_1": memory_id_1,
        "memory_id_2": memory_id_2,
        "association_type": association_type,
        "associated_at": datetime.now().isoformat()
    }

@app.post("/api/memory/capacity")
async def check_memory_capacity(request: Request):
    """检查记忆容量"""
    from datetime import datetime
    
    # 初始化存储
    if not hasattr(store_memory, "memory_bank"):
        store_memory.memory_bank = {}
    
    # 统计各类型记忆数量
    type_counts = {}
    for mem_data in store_memory.memory_bank.values():
        mem_type = mem_data["memory_type"]
        type_counts[mem_type] = type_counts.get(mem_type, 0) + 1
    
    # 计算工作记忆使用率
    working_count = type_counts.get("working", 0)
    capacity_used = working_count / WORKING_MEMORY["capacity_limit"]
    
    # 更新统计
    WORKING_MEMORY["memory_stats"]["avg_capacity_used"] = round(
        (WORKING_MEMORY["memory_stats"]["avg_capacity_used"] * WORKING_MEMORY["memory_stats"]["total_operations"] + capacity_used) / (WORKING_MEMORY["memory_stats"]["total_operations"] + 1),
        4
    )
    
    return {
        "success": True,
        "capacity_limit": WORKING_MEMORY["capacity_limit"],
        "working_memory_used": working_count,
        "capacity_percentage": round(capacity_used * 100, 2),
        "by_type": type_counts,
        "total_memories": len(store_memory.memory_bank),
        "checked_at": datetime.now().isoformat()
    }

@app.post("/api/memory/replay")
async def replay_memory(request: Request):
    """记忆重放"""
    from datetime import datetime
    
    data = await request.json()
    memory_type = data.get("memory_type", "episodic")
    start_time = data.get("start_time", None)
    end_time = data.get("end_time", None)
    
    # 初始化存储
    if not hasattr(store_memory, "memory_bank"):
        store_memory.memory_bank = {}
    
    # 筛选记忆
    replay_sequence = []
    
    for mem_id, mem_data in store_memory.memory_bank.items():
        if mem_data["memory_type"] != memory_type:
            continue
        
        # 时间过滤
        mem_time = datetime.fromisoformat(mem_data["created_at"])
        if start_time:
            if mem_time < datetime.fromisoformat(start_time):
                continue
        if end_time:
            if mem_time > datetime.fromisoformat(end_time):
                continue
        
        replay_sequence.append({
            "memory_id": mem_id,
            "content": mem_data["content"],
            "created_at": mem_data["created_at"],
            "strength": mem_data["strength"]
        })
    
    # 按时间排序
    replay_sequence.sort(key=lambda x: x["created_at"])
    
    # 重放时增强记忆
    for item in replay_sequence:
        mem_id = item["memory_id"]
        if mem_id in store_memory.memory_bank:
            store_memory.memory_bank[mem_id]["strength"] = min(1.0, store_memory.memory_bank[mem_id]["strength"] + 0.05)
    
    return {
        "success": True,
        "memory_type": memory_type,
        "sequence_length": len(replay_sequence),
        "replay_sequence": replay_sequence[:20] + (["..."] if len(replay_sequence) > 20 else []),
        "replayed_at": datetime.now().isoformat()
    }

