@app.post("/api/memory/summary")
async def get_memory_summary(request: Request):
    """获取记忆摘要"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")
    
    now = datetime.now()
    filtered = []
    
    for log in WORKING_MEMORY["memory_log"]:
        timestamp = log.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(log)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(log)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(log)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(log)
            except:
                pass
    
    operation_counter = Counter(log.get("operation", "unknown") for log in filtered)
    
    summary = {
        "period": period,
        "total_operations": len(filtered),
        "by_operation": dict(operation_counter),
        "total_memories_stored": WORKING_MEMORY["memory_stats"]["total_items_stored"],
        "consolidation_count": WORKING_MEMORY["memory_stats"]["consolidation_count"],
        "avg_capacity_used": WORKING_MEMORY["memory_stats"]["avg_capacity_used"],
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

