@app.post("/api/tool/call")
async def call_tool(request: Request):
    """调用工具"""
    from datetime import datetime
    import time
    import json
    
    data = await request.json()
    tool_id = data.get("tool_id", "")
    params = data.get("params", {})
    timeout = data.get("timeout", 30)
    
    # 查找工具
    tool_info = None
    for tool in TOOL_INTEGRATION["available_tools"]:
        if tool["id"] == tool_id:
            tool_info = tool
            break
    
    if not tool_info:
        return {
            "success": False,
            "error": f"工具 {tool_id} 不存在"
        }
    
    start_time = time.time()
    
    # 模拟工具调用
    result = {}
    success = True
    
    try:
        if tool_id == "web_search":
            query = params.get("query", "")
            result = {
                "query": query,
                "results": [
                    {"title": f"搜索结果 {i+1}", "url": f"https://example.com/{i+1}", "snippet": f"关于 {query} 的结果..."}
                    for i in range(5)
                ],
                "total_results": 5
            }
        
        elif tool_id == "code_exec":
            code = params.get("code", "")
            # 模拟代码执行
            result = {
                "code": code[:100] + ("..." if len(code) > 100 else ""),
                "output": "执行成功",
                "return_value": None,
                "execution_time": 0.05
            }
        
        elif tool_id == "file_ops":
            operation = params.get("operation", "read")
            path = params.get("path", "")
            result = {
                "operation": operation,
                "path": path,
                "content": "文件内容示例" if operation == "read" else None,
                "success": True
            }
        
        elif tool_id == "api_call":
            url = params.get("url", "")
            method = params.get("method", "GET")
            result = {
                "url": url,
                "method": method,
                "status_code": 200,
                "response": {"data": "示例响应"}
            }
        
        elif tool_id == "database":
            query = params.get("query", "")
            result = {
                "query": query,
                "rows_affected": 1,
                "results": [{"id": 1, "name": "示例数据"}]
            }
        
        elif tool_id == "image_gen":
            prompt = params.get("prompt", "")
            result = {
                "prompt": prompt,
                "image_url": "https://example.com/generated_image.png",
                "width": 512,
                "height": 512
            }
        
        elif tool_id == "translation":
            text = params.get("text", "")
            source_lang = params.get("source_lang", "auto")
            target_lang = params.get("target_lang", "en")
            result = {
                "original_text": text,
                "translated_text": f"[翻译结果: {text}]",
                "source_lang": source_lang,
                "target_lang": target_lang
            }
        
        elif tool_id == "sentiment":
            text = params.get("text", "")
            result = {
                "text": text,
                "sentiment": "positive",
                "confidence": 0.85,
                "scores": {
                    "positive": 0.85,
                    "negative": 0.10,
                    "neutral": 0.05
                }
            }
        
        elif tool_id == "summarize":
            text = params.get("text", "")
            max_length = params.get("max_length", 100)
            result = {
                "original_length": len(text),
                "summary": text[:max_length] + ("..." if len(text) > max_length else ""),
                "summary_length": min(len(text), max_length)
            }
        
        elif tool_id == "ocr":
            image_url = params.get("image_url", "")
            result = {
                "image_url": image_url,
                "text": "识别出的文字内容",
                "confidence": 0.92,
                "language": "zh"
            }
        
        else:
            result = {"message": "工具调用完成"}
    
    except Exception as e:
        success = False
        result = {"error": str(e)}
    
    response_time = time.time() - start_time
    
    # 更新统计
    TOOL_INTEGRATION["tool_stats"]["total_calls"] += 1
    if success:
        TOOL_INTEGRATION["tool_stats"]["successful_calls"] += 1
    else:
        TOOL_INTEGRATION["tool_stats"]["failed_calls"] += 1
    
    TOOL_INTEGRATION["tool_stats"]["avg_response_time"] = round(
        (TOOL_INTEGRATION["tool_stats"]["avg_response_time"] * (TOOL_INTEGRATION["tool_stats"]["total_calls"] - 1) + response_time) / TOOL_INTEGRATION["tool_stats"]["total_calls"],
        4
    )
    
    # 记录操作
    TOOL_INTEGRATION["tool_log"].append({
        "id": len(TOOL_INTEGRATION["tool_log"]) + 1,
        "tool_id": tool_id,
        "tool_name": tool_info["name"],
        "success": success,
        "response_time": round(response_time, 4),
        "created_at": datetime.now().isoformat()
    })
    
    return {
        "success": success,
        "tool_id": tool_id,
        "tool_name": tool_info["name"],
        "result": result,
        "response_time": round(response_time, 4),
        "called_at": datetime.now().isoformat()
    }

@app.post("/api/tool/batch")
async def batch_call_tools(request: Request):
    """批量调用工具"""
    from datetime import datetime
    import time
    
    data = await request.json()
    calls = data.get("calls", [])  # [{tool_id, params}, ...]
    parallel = data.get("parallel", True)
    
    if not calls:
        return {
            "success": False,
            "error": "没有提供工具调用列表"
        }
    
    results = []
    start_time = time.time()
    
    for call in calls:
        tool_id = call.get("tool_id", "")
        params = call.get("params", {})
        
        # 查找工具
        tool_info = None
        for tool in TOOL_INTEGRATION["available_tools"]:
            if tool["id"] == tool_id:
                tool_info = tool
                break
        
        if tool_info:
            results.append({
                "tool_id": tool_id,
                "tool_name": tool_info["name"],
                "success": True,
                "result": {"message": "调用成功"}
            })
        else:
            results.append({
                "tool_id": tool_id,
                "success": False,
                "error": "工具不存在"
            })
    
    total_time = time.time() - start_time
    
    # 更新统计
    TOOL_INTEGRATION["tool_stats"]["total_calls"] += len(calls)
    TOOL_INTEGRATION["tool_stats"]["successful_calls"] += sum(1 for r in results if r.get("success"))
    TOOL_INTEGRATION["tool_stats"]["failed_calls"] += sum(1 for r in results if not r.get("success"))
    
    return {
        "success": True,
        "total_calls": len(calls),
        "successful": sum(1 for r in results if r.get("success")),
        "failed": sum(1 for r in results if not r.get("success")),
        "results": results,
        "total_time": round(total_time, 4),
        "executed_at": datetime.now().isoformat()
    }

@app.post("/api/tool/chain")
async def chain_call_tools(request: Request):
    """链式调用工具"""
    from datetime import datetime
    import time
    
    data = await request.json()
    chain = data.get("chain", [])  # [{tool_id, params, output_key}, ...]
    initial_context = data.get("context", {})
    
    if not chain:
        return {
            "success": False,
            "error": "没有提供工具调用链"
        }
    
    context = initial_context.copy()
    results = []
    start_time = time.time()
    
    for step in chain:
        tool_id = step.get("tool_id", "")
        params = step.get("params", {})
        output_key = step.get("output_key", None)
        
        # 替换参数中的上下文引用
        processed_params = {}
        for key, value in params.items():
            if isinstance(value, str) and value.startswith("$"):
                # 引用上下文中的值
                ref_key = value[1:]
                processed_params[key] = context.get(ref_key, value)
            else:
                processed_params[key] = value
        
        # 查找工具
        tool_info = None
        for tool in TOOL_INTEGRATION["available_tools"]:
            if tool["id"] == tool_id:
                tool_info = tool
                break
        
        if tool_info:
            result = {"success": True, "data": "调用结果"}
            
            if output_key:
                context[output_key] = result
            
            results.append({
                "tool_id": tool_id,
                "tool_name": tool_info["name"],
                "success": True,
                "output_key": output_key
            })
        else:
            results.append({
                "tool_id": tool_id,
                "success": False,
                "error": "工具不存在"
            })
            break
    
    total_time = time.time() - start_time
    
    return {
        "success": all(r.get("success") for r in results),
        "chain_length": len(chain),
        "completed_steps": len(results),
        "results": results,
        "final_context": context,
        "total_time": round(total_time, 4),
        "executed_at": datetime.now().isoformat()
    }

@app.post("/api/tool/register")
async def register_tool(request: Request):
    """注册新工具"""
    from datetime import datetime
    
    data = await request.json()
    tool_id = data.get("id", "")
    name = data.get("name", "")
    description = data.get("description", "")
    endpoint = data.get("endpoint", "")
    auth_type = data.get("auth_type", "none")  # none, api_key, oauth
    
    if not tool_id or not name:
        return {
            "success": False,
            "error": "工具ID和名称不能为空"
        }
    
    # 检查是否已存在
    for tool in TOOL_INTEGRATION["available_tools"]:
        if tool["id"] == tool_id:
            return {
                "success": False,
                "error": f"工具 {tool_id} 已存在"
            }
    
    # 添加新工具
    new_tool = {
        "id": tool_id,
        "name": name,
        "description": description,
        "endpoint": endpoint,
        "auth_type": auth_type,
        "registered_at": datetime.now().isoformat()
    }
    
    TOOL_INTEGRATION["available_tools"].append(new_tool)
    
    return {
        "success": True,
        "tool_id": tool_id,
        "name": name,
        "registered_at": datetime.now().isoformat()
    }

@app.post("/api/tool/unregister")
async def unregister_tool(request: Request):
    """注销工具"""
    from datetime import datetime
    
    data = await request.json()
    tool_id = data.get("tool_id", "")
    
    for i, tool in enumerate(TOOL_INTEGRATION["available_tools"]):
        if tool["id"] == tool_id:
            TOOL_INTEGRATION["available_tools"].pop(i)
            return {
                "success": True,
                "tool_id": tool_id,
                "unregistered_at": datetime.now().isoformat()
            }
    
    return {
        "success": False,
        "error": f"工具 {tool_id} 不存在"
    }

@app.post("/api/tool/validate")
async def validate_tool_params(request: Request):
    """验证工具参数"""
    from datetime import datetime
    
    data = await request.json()
    tool_id = data.get("tool_id", "")
    params = data.get("params", {})
    
    # 查找工具
    tool_info = None
    for tool in TOOL_INTEGRATION["available_tools"]:
        if tool["id"] == tool_id:
            tool_info = tool
            break
    
    if not tool_info:
        return {
            "success": False,
            "error": f"工具 {tool_id} 不存在"
        }
    
    # 验证参数
    validation_errors = []
    validation_warnings = []
    
    # 根据工具类型验证
    if tool_id == "web_search":
        if "query" not in params:
            validation_errors.append("缺少必需参数: query")
        elif not params["query"]:
            validation_errors.append("查询内容不能为空")
    
    elif tool_id == "code_exec":
        if "code" not in params:
            validation_errors.append("缺少必需参数: code")
        elif len(params.get("code", "")) > 10000:
            validation_warnings.append("代码长度超过10000字符，可能影响性能")
    
    elif tool_id == "api_call":
        if "url" not in params:
            validation_errors.append("缺少必需参数: url")
    
    return {
        "success": len(validation_errors) == 0,
        "tool_id": tool_id,
        "tool_name": tool_info["name"],
        "params": params,
        "validation_errors": validation_errors,
        "validation_warnings": validation_warnings,
        "validated_at": datetime.now().isoformat()
    }

