    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")
    
    now = datetime.now()
    filtered = []
    
    for log in TOOL_INTEGRATION["tool_log"]:
        timestamp = log.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(log)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(log)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(log)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(log)
            except:
                pass
    
    tool_counter = Counter(log.get("tool_name", "unknown") for log in filtered)
    success_rate = sum(1 for log in filtered if log.get("success")) / len(filtered) * 100 if filtered else 0
    
    summary = {
        "period": period,
        "total_calls": len(filtered),
        "by_tool": dict(tool_counter),
        "success_rate": round(success_rate, 2),
        "avg_response_time": TOOL_INTEGRATION["tool_stats"]["avg_response_time"],
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

