@app.post("/api/test/summary")
async def get_test_summary(request: Request):
    """获取测试摘要"""
    from datetime import datetime
    from collections import Counter
    
    data = await request.json()
    period = data.get("period", "all")
    
    now = datetime.now()
    filtered = []
    
    for log in SYSTEM_TEST["test_log"]:
        timestamp = log.get("created_at", "")
        if timestamp:
            try:
                dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
                if period == "all":
                    filtered.append(log)
                elif period == "day" and (now - dt).days < 1:
                    filtered.append(log)
                elif period == "week" and (now - dt).days < 7:
                    filtered.append(log)
                elif period == "month" and (now - dt).days < 30:
                    filtered.append(log)
            except:
                pass
    
    category_counter = Counter(log.get("category", "unknown") for log in filtered)
    total_passed = sum(log.get("passed", 0) for log in filtered)
    total_failed = sum(log.get("failed", 0) for log in filtered)
    
    summary = {
        "period": period,
        "total_test_runs": len(filtered),
        "by_category": dict(category_counter),
        "total_passed": total_passed,
        "total_failed": total_failed,
        "pass_rate": round(total_passed / (total_passed + total_failed) * 100, 2) if (total_passed + total_failed) > 0 else 0,
        "avg_score": SYSTEM_TEST["test_stats"]["avg_score"],
        "generated_at": datetime.now().isoformat()
    }
    
    return {
        "success": True,
        "summary": summary
    }

@app.middleware("http")
async def rate_limit_middleware(request: Request, call_next):
    """请求限流中间件 + 请求ID追踪"""
    # 生成请求ID
    request_id = str(uuid.uuid4())[:8]
    
    # 获取客户端IP
    client_ip = request.client.host if request.client else "unknown"
    
    # 记录请求开始
    REQUEST_TRACKING[request_id] = {
        "path": request.url.path,
        "method": request.method,
        "start_time": time.time(),
        "client_ip": client_ip
    }
    
    # ── 限流豁免 ──
    # 1. Localhost 豁免：本地开发环境不应受限流影响
    _LOCALHOST_IPS = {"127.0.0.1", "::1", "localhost"}
    # 2. 轮询端点豁免：前端每隔几秒自动轮询的只读端点
    _POLLING_PREFIXES = (
        "/api/status", "/api/tasks/status", "/api/sessions/",
        "/api/changes/pending", "/api/fix/scan", "/api/rate-limit/",
        "/api/ratelimit/", "/api/requests/tracking",
        "/static/", "/favicon.ico",
    )
    path = request.url.path
    _exempt = client_ip in _LOCALHOST_IPS or path in ("/", "") or path.startswith(_POLLING_PREFIXES)
    remaining = -1  # default for exempt requests
    
    if not _exempt:
        # 确定端点类型
        if "/chat" in path and "/stream" in path:
            endpoint_type = "stream"
        elif "/chat" in path:
            endpoint_type = "chat"
        else:
            endpoint_type = "default"
        
        # 检查限流
        rate_result = check_rate_limit(client_ip, endpoint_type)
        allowed = rate_result["allowed"]
        remaining = rate_result["remaining"]
        
        if not allowed:
            # 清理追踪记录
            REQUEST_TRACKING.pop(request_id, None)
            return JSONResponse(
                status_code=429,
                content={
                    "success": False,
                    "request_id": request_id,
                    "error": {
                        "type": "rate_limit",
                        "title": "🚫 请求过于频繁",
                        "message": f"请求已达到限制，请稍后重试",
                        "strategy": rate_result["strategy"],
                        "limit": rate_result["limit"]
                    }
                },
                headers={"Retry-After": "60"}
            )
    
    response = await call_next(request)
    response.headers["X-RateLimit-Remaining"] = str(remaining)
    response.headers["X-Request-ID"] = request_id
    
    # 计算耗时
    duration_ms = round((time.time() - REQUEST_TRACKING[request_id]["start_time"]) * 1000, 2) if request_id in REQUEST_TRACKING else 0
    
    # 更新请求追踪记录
    if request_id in REQUEST_TRACKING:
        REQUEST_TRACKING[request_id]["duration_ms"] = duration_ms
        REQUEST_TRACKING[request_id]["status"] = "completed"
    
    # 添加审计日志
    add_audit_entry(request_id, request, response.status_code, duration_ms)
    
    return response

@app.get("/api/requests/tracking")
async def get_request_tracking():
    """获取请求追踪状态"""
    # 清理超过60秒的记录
    now = time.time()
    to_remove = [rid for rid, data in REQUEST_TRACKING.items() if now - data["start_time"] > 60]
    for rid in to_remove:
        REQUEST_TRACKING.pop(rid, None)
    
    return {
        "success": True,
        "active_requests": len(REQUEST_TRACKING),
        "requests": dict(list(REQUEST_TRACKING.items())[-20:])  # 最近20个
    }

@app.get("/api/rate-limit/status")
async def get_rate_limit_status(request: Request):
    """获取限流状态"""
    client_ip = request.client.host if request.client else "unknown"
    
    status = {}
    for endpoint_type, config in RATE_LIMITS.items():
        now = time.time()
        window_start = now - config["window"]
        count = len([t for t in rate_limit_store[client_ip] if t > window_start])
        status[endpoint_type] = {
            "limit": config["requests"],
            "remaining": max(0, config["requests"] - count),
            "window_seconds": config["window"]
        }
    
    return {"success": True, "client_ip": client_ip, "limits": status}

