# ========== WebSocket实时通信 ==========

class ConnectionManager:
    """WebSocket连接管理器"""
    
    def __init__(self):
        self.active_connections: Dict[str, List[WebSocket]] = {}
        self._lock = asyncio.Lock()
    
    async def connect(self, websocket: WebSocket, channel: str = "default"):
        """接受连接"""
        await websocket.accept()
        async with self._lock:
            if channel not in self.active_connections:
                self.active_connections[channel] = []
            self.active_connections[channel].append(websocket)
    
    async def disconnect(self, websocket: WebSocket, channel: str = "default"):
        """断开连接"""
        async with self._lock:
            if channel in self.active_connections:
                if websocket in self.active_connections[channel]:
                    self.active_connections[channel].remove(websocket)
    
    async def send_personal(self, message: str, websocket: WebSocket):
        """发送个人消息"""
        await websocket.send_text(message)
    
    async def broadcast(self, message: str, channel: str = "default"):
        """广播消息"""
        async with self._lock:
            connections = self.active_connections.get(channel, [])
            for connection in connections:
                try:
                    await connection.send_text(message)
                except:
                    pass
    
    async def broadcast_json(self, data: dict, channel: str = "default"):
        """广播JSON消息"""
        await self.broadcast(json.dumps(data, ensure_ascii=False), channel)
    
    def get_stats(self) -> dict:
        """获取连接统计"""
        stats = {
            "total_connections": sum(len(conns) for conns in self.active_connections.values()),
            "channels": {}
        }
        for channel, conns in self.active_connections.items():
            stats["channels"][channel] = len(conns)
        return stats

WS_MANAGER = ConnectionManager()

@app.websocket("/ws/{channel}")
async def websocket_endpoint(websocket: WebSocket, channel: str):
    """WebSocket端点"""
    await WS_MANAGER.connect(websocket, channel)
    try:
        while True:
            data = await websocket.receive_text()
            # 处理接收的消息
            try:
                message = json.loads(data)
                msg_type = message.get("type", "message")
                
                if msg_type == "ping":
                    await WS_MANAGER.send_personal(json.dumps({"type": "pong"}), websocket)
                elif msg_type == "broadcast":
                    await WS_MANAGER.broadcast_json(message.get("data", {}), channel)
                else:
                    # 回显消息
                    await WS_MANAGER.send_personal(json.dumps({
                        "type": "echo",
                        "data": message
                    }), websocket)
            except json.JSONDecodeError:
                await WS_MANAGER.send_personal(json.dumps({
                    "type": "error",
                    "message": "无效的JSON格式"
                }), websocket)
    except WebSocketDisconnect:
        await WS_MANAGER.disconnect(websocket, channel)

@app.get("/api/ws/stats")
async def get_ws_stats():
    """获取WebSocket连接统计"""
    return {"success": True, "stats": WS_MANAGER.get_stats()}

