@app.get("/health/detailed")
async def detailed_health_check():
    """详细健康检查"""
    issues = []
    
    # 检查Agentic Loop可用性
    if not AGENTIC_LOOP_AVAILABLE:
        issues.append({"component": "agentic_loop", "status": "critical", "message": "Agentic loop未加载，核心功能不可用"})

    # 检查SNN状态
    if not _snn_mod.SNN_ENABLED or _snn_mod.SNN_PROCESSOR is None:
        issues.append({"component": "snn", "status": "warning", "message": "SNN未初始化"})
    
    # 检查内存
    import psutil
    memory = psutil.virtual_memory()
    if memory.percent > 90:
        issues.append({"component": "memory", "status": "warning", "message": f"内存使用过高: {memory.percent}%"})
    
    # 检查磁盘
    disk = psutil.disk_usage('/')
    if disk.percent > 90:
        issues.append({"component": "disk", "status": "warning", "message": f"磁盘使用过高: {disk.percent}%"})
    
    # R7: Expose SQLite PRAGMA state for automated monitoring
    # R8: Use read-only URI mode as defense-in-depth (prevents implicit file creation
    # even if is_file() TOCTOU race occurs; also prevents accidental writes).
    _sqlite_status = {"status": "ok", "pragmas": {}}
    try:
        import sqlite3 as _h_sqlite3
        from pathlib import Path as _h_Path
        for _db_label, _db_path in [("rag_vectors", _h_Path.home() / ".nanobot" / "rag_vectors.db"),
                                     ("knowledge_graph", _h_Path.home() / ".nanobot" / "knowledge_graph.db")]:
            if _db_path.is_file():
                _h_conn = _h_sqlite3.connect(f"file:{_db_path}?mode=ro", uri=True, timeout=2.0)
                try:
                    _h_jm = _h_conn.execute("PRAGMA journal_mode").fetchone()[0]
                    _h_bt = _h_conn.execute("PRAGMA busy_timeout").fetchone()[0]
                    _h_av = _h_conn.execute("PRAGMA auto_vacuum").fetchone()[0]
                    # R9: Report WAL file size for disk growth monitoring
                    _h_wal_path = _h_Path(str(_db_path) + "-wal")
                    _h_wal_bytes = _h_wal_path.stat().st_size if _h_wal_path.is_file() else 0
                    # R10: Include WAL maintenance observability from agentic_loop
                    from agentic_loop import _db_maint_fail_count, _db_maint_last_success, _DB_MAINT_LOCK
                    with _DB_MAINT_LOCK:
                        _h_maint_fails = _db_maint_fail_count.get(str(_db_path), 0)
                        _h_maint_last_ok = _db_maint_last_success.get(str(_db_path))
                    _pragmas = {"journal_mode": _h_jm, "busy_timeout": _h_bt, "auto_vacuum": _h_av,
                                "wal_size_bytes": _h_wal_bytes,
                                "maintenance_fail_count": _h_maint_fails,
                                "maintenance_last_success": _h_maint_last_ok}
                    _sqlite_status["pragmas"][_db_label] = _pragmas
                    if _h_maint_fails > 5:
                        issues.append({"component": f"sqlite_{_db_label}", "status": "warning",
                                       "message": f"WAL maintenance failing: {_h_maint_fails} consecutive failures"})
                    if _h_wal_bytes > 10 * 1024 * 1024:  # 10 MB threshold
                        issues.append({"component": f"sqlite_{_db_label}", "status": "warning",
                                       "message": f"WAL file large: {_h_wal_bytes / 1024 / 1024:.1f} MB"})
                    if _h_jm != "wal" or _h_bt != 5000:
                        _sqlite_status["status"] = "degraded"
                        issues.append({"component": f"sqlite_{_db_label}", "status": "warning",
                                       "message": f"PRAGMA degraded: journal_mode={_h_jm}, busy_timeout={_h_bt}"})
                finally:
                    _h_conn.close()
    except Exception as _h_exc:
        _sqlite_status["status"] = "error"
        _sqlite_status["error"] = str(_h_exc)[:200]

    return {
        "status": "healthy" if not issues else "degraded",
        "timestamp": datetime.now().isoformat(),
        "uptime_seconds": int(time.time() - PERFORMANCE_METRICS["start_time"]),
        "components": {
            "snn": {"status": "ok" if _snn_mod.SNN_ENABLED else "disabled"},
            "memory": {"percent": memory.percent, "available_gb": round(memory.available / (1024**3), 2)},
            "disk": {"percent": disk.percent, "free_gb": round(disk.free / (1024**3), 2)},
            "websocket": {"connections": WS_MANAGER.get_stats()["total_connections"]},
            "sqlite": _sqlite_status
        },
        "issues": issues if issues else None
    }

