@app.post("/api/tasks/chunk")
async def create_chunked_task(request: Request):
    """创建分片任务 - 将大任务拆分为多个小任务。

    This endpoint now integrates with TaskStore: it creates a root Task
    representing the overall chunked job and one child Task per chunk.
    The child task IDs are stored in the session dict under `_chunk_child_ids`
    so that `/api/tasks/chunk/{task_id}/process` can transition them.
    """
    data = await request.json()
    task_name = data.get("task_name", "unnamed_task")
    items = data.get("items", [])  # 要处理的项目列表
    chunk_size = data.get("chunk_size", 10)  # 每批大小
    session_id = data.get("session_id", "default")
    
    if not items:
        raise HTTPException(400, "Items list is required")
    
    total_items = len(items)
    chunks = [items[i:i + chunk_size] for i in range(0, total_items, chunk_size)]
    
    # 创建任务状态
    task_id = f"{task_name}_{int(time.time())}"

    # ── TaskStore integration: create root + child tasks ──
    ts_root_id = ""
    ts_child_ids: list = []
    try:
        from task_store import get_task_store, create_child_task as _ts_create_child

        store = get_task_store(session_id, WORKSPACE)
        root = store.create_task(
            id=f"chunk-root-{task_id}",
            title=f"Chunked task: {task_name}",
            objective=f"Process {total_items} items in {len(chunks)} chunks (size={chunk_size})",
            state="created",
            owner="chunk_api",
            metadata={"chunk_task_id": task_id, "total_chunks": len(chunks)},
        )
        ts_root_id = root.id
        # Transition root to in_progress immediately
        store.transition(root.id, "in_progress",
                         source="create_chunked_task",
                         reason="chunked task created with children")

        for idx in range(len(chunks)):
            child = _ts_create_child(
                workspace, session_id, root.id,
                title=f"Chunk {idx + 1}/{len(chunks)}",
                objective=f"Process chunk {idx + 1}: {len(chunks[idx])} items",
                owner="chunk_api",
                state="created",
                metadata={"chunk_index": idx},
            )
            ts_child_ids.append(child.id)
        logger.info("[ChunkAPI] Created TaskStore root=%s with %d children", ts_root_id, len(ts_child_ids))
    except Exception as exc:
        logger.warning("[ChunkAPI] TaskStore integration failed (non-fatal): %s", exc)

    task_status = {
        "task_id": task_id,
        "task_name": task_name,
        "total_items": total_items,
        "chunk_size": chunk_size,
        "total_chunks": len(chunks),
        "completed_chunks": 0,
        "chunks": chunks,
        "results": [],
        "status": "created",
        "created_at": datetime.now().isoformat(),
        "session_id": session_id,
        "_ts_root_id": ts_root_id,
        "_chunk_child_ids": ts_child_ids,
    }
    
    # 保存到会话
    if session_id not in sessions:
        sessions[session_id] = {"history": [], "tasks": {}}
    if "tasks" not in sessions[session_id]:
        sessions[session_id]["tasks"] = {}
    sessions[session_id]["tasks"][task_id] = task_status
    
    # 记录初始进度
    save_task_progress(session_id, task_name, 0, total_items, f"任务分片完成，共 {len(chunks)} 批")
    
    return {
        "success": True,
        "task_id": task_id,
        "ts_root_id": ts_root_id,
        "total_chunks": len(chunks),
        "chunk_size": chunk_size,
        "message": f"任务已分片，共 {len(chunks)} 批，每批 {chunk_size} 项"
    }

@app.post("/api/tasks/chunk/{task_id}/process")
async def process_chunk(task_id: str, request: Request):
    """处理任务的下一批分片。

    After processing each chunk, the corresponding TaskStore child task is
    transitioned to `completed`.  When all chunks are done the root task
    is promoted via `promote_root_state_from_children` which will move it
    to `verifying` (if in `in_progress`) or `completed`.
    """
    data = await request.json()
    session_id = data.get("session_id", "default")
    
    if session_id not in sessions or "tasks" not in sessions[session_id]:
        raise HTTPException(404, "Session or tasks not found")
    
    if task_id not in sessions[session_id]["tasks"]:
        raise HTTPException(404, "Task not found")
    
    task = sessions[session_id]["tasks"][task_id]
    
    if task["status"] == "completed":
        return {"success": True, "status": "completed", "message": "任务已完成"}
    
    current_chunk_idx = task["completed_chunks"]
    if current_chunk_idx >= len(task["chunks"]):
        task["status"] = "completed"
        return {"success": True, "status": "completed", "message": "所有分片已处理"}
    
    # 获取当前批次
    current_chunk = task["chunks"][current_chunk_idx]
    
    # 记录资源使用
    resources = log_resources(f"处理分片 {current_chunk_idx + 1}/{task['total_chunks']}")
    
    # 这里可以添加实际的处理逻辑
    # 例如：调用 nanobot 分析这批项目
    
    # 模拟处理（实际使用时应替换为真实处理）
    chunk_result = {
        "chunk_index": current_chunk_idx,
        "items_processed": len(current_chunk),
        "items": current_chunk,
        "processed_at": datetime.now().isoformat()
    }
    
    task["results"].append(chunk_result)
    task["completed_chunks"] += 1
    
    # ── TaskStore integration: transition child task ──
    ts_root_id = task.get("_ts_root_id", "")
    ts_child_ids = task.get("_chunk_child_ids", [])
    ts_root_state = ""
    try:
        if ts_root_id and current_chunk_idx < len(ts_child_ids):
            from task_store import get_task_store

            store = get_task_store(session_id, WORKSPACE)
            child_id = ts_child_ids[current_chunk_idx]
            # Transition child: created → in_progress → completed
            child = store.get_task(child_id)
            if child and child.state == "created":
                store.transition(child_id, "in_progress",
                                 source="process_chunk",
                                 reason=f"processing chunk {current_chunk_idx + 1}")
            store.transition(child_id, "completed",
                             result_summary=f"Processed {len(current_chunk)} items",
                             source="process_chunk",
                             reason=f"chunk {current_chunk_idx + 1} completed")

            # When all chunks done, promote root (will go to verifying or completed)
            if task["completed_chunks"] >= task["total_chunks"]:
                root = store.promote_root_state_from_children(ts_root_id)
                ts_root_state = root.state if root else ""
                logger.info("[ChunkAPI] All chunks done, root %s promoted to %s",
                            ts_root_id, ts_root_state)
    except Exception as exc:
        logger.warning("[ChunkAPI] TaskStore child transition failed (non-fatal): %s", exc)

    # 保存进度
    progress = task["completed_chunks"]
    total = task["total_chunks"]
    is_all_done = progress >= total
    if is_all_done:
        task["status"] = "completed"
    save_task_progress(session_id, task["task_name"], progress, total, 
                      f"完成第 {current_chunk_idx + 1} 批，共 {total} 批")
    
    return {
        "success": True,
        "status": "completed" if is_all_done else "processing",
        "chunk_index": current_chunk_idx,
        "completed": task["completed_chunks"],
        "total": task["total_chunks"],
        "progress_percent": int((task["completed_chunks"] / task["total_chunks"]) * 100),
        "items_in_chunk": len(current_chunk),
        "ts_root_state": ts_root_state,
        "resources": resources
    }

@app.post("/api/tasks/chunk/{task_id}/run")
async def run_all_chunks(task_id: str, request: Request):
    """Auto-process all remaining chunks for a chunked task.

    This endpoint drives the full lifecycle: for each unprocessed chunk it
    transitions the TaskStore child task through created → in_progress →
    completed, then promotes the root task when all chunks are done.
    """
    data = await request.json() if request.headers.get("content-type", "").startswith("application/json") else {}
    session_id = data.get("session_id", "default")

    if session_id not in sessions or "tasks" not in sessions[session_id]:
        raise HTTPException(404, "Session or tasks not found")
    if task_id not in sessions[session_id]["tasks"]:
        raise HTTPException(404, "Task not found")

    task = sessions[session_id]["tasks"][task_id]
    if task["status"] == "completed":
        return {"success": True, "status": "completed", "message": "任务已完成", "processed": 0}

    ts_root_id = task.get("_ts_root_id", "")
    ts_child_ids = task.get("_chunk_child_ids", [])
    processed = 0
    ts_root_state = ""

    store = None
    if ts_root_id:
        try:
            from task_store import get_task_store
            store = get_task_store(session_id, WORKSPACE)
        except Exception as exc:
            logger.warning("[ChunkRun] TaskStore init failed: %s", exc)

    while task["completed_chunks"] < task["total_chunks"]:
        idx = task["completed_chunks"]
        current_chunk = task["chunks"][idx]

        chunk_result = {
            "chunk_index": idx,
            "items_processed": len(current_chunk),
            "items": current_chunk,
            "processed_at": datetime.now().isoformat(),
        }
        task["results"].append(chunk_result)
        task["completed_chunks"] += 1
        processed += 1

        # TaskStore child transition
        if store and idx < len(ts_child_ids):
            try:
                child_id = ts_child_ids[idx]
                child = store.get_task(child_id)
                if child and child.state == "created":
                    store.transition(child_id, "in_progress",
                                     source="run_all_chunks",
                                     reason=f"processing chunk {idx + 1}")
                store.transition(child_id, "completed",
                                 result_summary=f"Processed {len(current_chunk)} items",
                                 source="run_all_chunks",
                                 reason=f"chunk {idx + 1} completed")
            except Exception as exc:
                logger.warning("[ChunkRun] Child %d transition failed: %s", idx, exc)

        save_task_progress(session_id, task["task_name"],
                          task["completed_chunks"], task["total_chunks"],
                          f"完成第 {idx + 1} 批，共 {task['total_chunks']} 批")

    task["status"] = "completed"

    # Promote root
    if store and ts_root_id:
        try:
            root = store.promote_root_state_from_children(ts_root_id)
            ts_root_state = root.state if root else ""
            logger.info("[ChunkRun] All %d chunks done, root %s → %s",
                        processed, ts_root_id, ts_root_state)
        except Exception as exc:
            logger.warning("[ChunkRun] Root promotion failed: %s", exc)

    return {
        "success": True,
        "status": "completed",
        "processed": processed,
        "total": task["total_chunks"],
        "ts_root_id": ts_root_id,
        "ts_root_state": ts_root_state,
        "message": f"已处理 {processed} 个分片，任务完成",
    }


@app.get("/api/tasks/{task_id}")
async def get_task_status(task_id: str, session_id: str = "default"):
    """获取任务状态和进度"""
    if session_id not in sessions or "tasks" not in sessions[session_id]:
        raise HTTPException(404, "Session or tasks not found")
    
    if task_id not in sessions[session_id]["tasks"]:
        raise HTTPException(404, "Task not found")
    
    task = sessions[session_id]["tasks"][task_id]
    ts_root_id = task.get("_ts_root_id", "")
    ts_root_state = ""
    ts_children = []
    if ts_root_id:
        try:
            from task_store import get_task_store

            store = get_task_store(session_id, WORKSPACE)
            root = store.get_task(ts_root_id)
            if root is not None:
                ts_root_state = root.state
                ts_children = [
                    {
                        "id": child.id,
                        "title": child.title,
                        "state": child.state,
                    }
                    for child in store.get_children(ts_root_id)
                ]
        except Exception as exc:
            logger.debug("[ChunkAPI] Failed to load TaskStore status for %s: %s", task_id, exc)
    
    return {
        "success": True,
        "task": {
            "task_id": task["task_id"],
            "task_name": task["task_name"],
            "status": task["status"],
            "total_chunks": task["total_chunks"],
            "completed_chunks": task["completed_chunks"],
            "progress_percent": int((task["completed_chunks"] / task["total_chunks"]) * 100),
            "total_items": task["total_items"],
            "created_at": task["created_at"],
            "ts_root_id": ts_root_id,
            "ts_root_state": ts_root_state,
            "ts_children": ts_children,
        }
    }

