# ========== 深度推理系统 API ==========

@app.post("/api/inference/query")
async def inference_query(request: Request):
    """执行深度多跳推理"""
    try:
        data = await request.json()
        query = data.get("query", "")
        target = data.get("target")
        hops = data.get("hops", 3)
        strategy = data.get("strategy", "beam")
        
        if not query:
            return {"success": False, "error": "查询内容不能为空"}
        
        import sys
        sys.path.insert(0, str(WORKSPACE / "core"))
        from inference_engine import MultiHopInferenceEngine, InferenceStrategy
        
        engine = MultiHopInferenceEngine(WORKSPACE)
        
        # 加载知识图谱
        kg_file = WORKSPACE / "knowledge_graph.json"
        if kg_file.exists():
            kg_data = json.loads(kg_file.read_text())
            engine.load_from_knowledge_graph(kg_data)
        
        # 选择推理策略
        strategy_map = {
            "bfs": InferenceStrategy.BFS,
            "dfs": InferenceStrategy.DFS,
            "beam": InferenceStrategy.BEAM_SEARCH,
            "causal": InferenceStrategy.CAUSAL_CHAIN
        }
        selected_strategy = strategy_map.get(strategy, InferenceStrategy.BEAM_SEARCH)
        
        result = engine.infer(query, target, hops, selected_strategy)
        
        return {
            "success": True,
            "query": query,
            "target": target,
            "confidence": result.confidence_score,
            "depth": result.reasoning_depth,
            "processing_time_ms": result.processing_time_ms,
            "paths_found": len(result.paths),
            "causal_chains_found": len(result.causal_chains),
            "paths": [
                {
                    "id": p.path_id,
                    "start": p.start_node,
                    "end": p.end_node,
                    "length": p.path_length,
                    "confidence": p.total_confidence,
                    "verified": p.verified,
                    "steps": [
                        {
                            "step": s.step_number,
                            "from": s.from_node,
                            "to": s.to_node,
                            "relation": s.relation.value,
                            "reasoning": s.reasoning,
                            "confidence": s.confidence
                        }
                        for s in p.steps
                    ]
                }
                for p in result.paths[:10]
            ],
            "causal_chains": [
                {
                    "id": c.chain_id,
                    "cause": c.cause,
                    "effects": c.effects,
                    "root_cause": c.root_cause,
                    "confidence": c.confidence,
                    "intermediate_steps": c.intermediate_steps[:5]
                }
                for c in result.causal_chains[:5]
            ],
            "inferred_knowledge": result.inferred_knowledge[:5]
        }
    except Exception as e:
        logger.error(f"深度推理失败: {e}")
        return {"success": False, "error": str(e)}

@app.post("/api/inference/causal")
async def causal_analysis(request: Request):
    """执行因果链分析"""
    try:
        data = await request.json()
        event = data.get("event", "")
        
        if not event:
            return {"success": False, "error": "事件描述不能为空"}
        
        import sys
        sys.path.insert(0, str(WORKSPACE / "core"))
        from inference_engine import MultiHopInferenceEngine
        
        engine = MultiHopInferenceEngine(WORKSPACE)
        
        # 加载知识图谱
        kg_file = WORKSPACE / "knowledge_graph.json"
        if kg_file.exists():
            kg_data = json.loads(kg_file.read_text())
            engine.load_from_knowledge_graph(kg_data)
        
        chains = engine.analyze_causality(event)
        
        return {
            "success": True,
            "event": event,
            "chains_found": len(chains),
            "chains": [
                {
                    "id": c.chain_id,
                    "root_cause": c.root_cause,
                    "cause": c.cause,
                    "effects": c.effects,
                    "confidence": c.confidence,
                    "intermediate_steps": c.intermediate_steps,
                    "temporal_order": c.temporal_order
                }
                for c in chains
            ],
            "summary": f"发现 {len(chains)} 条与 '{event}' 相关的因果链"
        }
    except Exception as e:
        logger.error(f"因果分析失败: {e}")
        return {"success": False, "error": str(e)}

@app.get("/api/inference/stats")
async def inference_stats():
    """获取推理引擎统计"""
    try:
        import sys
        sys.path.insert(0, str(WORKSPACE / "core"))
        from inference_engine import MultiHopInferenceEngine
        
        engine = MultiHopInferenceEngine(WORKSPACE)
        
        # 加载知识图谱
        kg_file = WORKSPACE / "knowledge_graph.json"
        if kg_file.exists():
            kg_data = json.loads(kg_file.read_text())
            engine.load_from_knowledge_graph(kg_data)
        
        # 统计关系类型
        relation_counts = {}
        for edges in engine.edges.values():
            for edge in edges:
                rel_type = edge.relation_type.value
                relation_counts[rel_type] = relation_counts.get(rel_type, 0) + 1
        
        return {
            "success": True,
            "knowledge_graph": {
                "nodes": len(engine.nodes),
                "edges": sum(len(e) for e in engine.edges.values()),
                "relation_types": relation_counts
            },
            "inference_history": len(engine.inference_history),
            "max_reasoning_depth": engine.max_depth
        }
    except Exception as e:
        logger.error(f"获取推理统计失败: {e}")
        return {"success": False, "error": str(e)}

