if __name__ == "__main__":
    import signal
    import asyncio
    import os
    
    # ========== Nanobot 自动修复检查 ==========
    # 检查并修复 Qwen3.5 Jinja 模板错误
    try:
        patches_dir = Path(__file__).parent.parent / "patches"
        fix_script = patches_dir / "fix_nanobot_jinja.py"
        if fix_script.exists():
            import subprocess
            result = subprocess.run(
                [sys.executable, str(fix_script), "--check"],
                capture_output=True, text=True, timeout=5
            )
            if result.returncode == 2:  # 需要修复
                print("🔧 检测到 nanobot 需要修复，正在应用...")
                apply_result = subprocess.run(
                    [sys.executable, str(fix_script)],
                    capture_output=True, text=True, timeout=10
                )
                if apply_result.returncode == 0:
                    print("✅ nanobot 修复成功")
                else:
                    print(f"⚠️ nanobot 修复失败: {apply_result.stdout}")
    except Exception as e:
        print(f"⚠️ nanobot 修复检查跳过: {e}")

    # ========== 安全拦截器安装 ==========
    # 检查环境变量强制安全模式
    enforce_security = os.environ.get('NANOBOT_ENFORCE_SECURITY', '1') == '1'
    
    if enforce_security:
        try:
            # 添加当前目录到路径（确保能找到同目录模块）
            import sys
            current_dir = Path(__file__).parent
            if str(current_dir) not in sys.path:
                sys.path.insert(0, str(current_dir))
            
            from secure_interceptor import (
                install_interceptors, is_interceptors_installed,
                set_permission_check, security_check, SecurityDecision
            )
            
            # 设置权限检查回调，允许安全的系统操作
            def _permission_check_callback(operation: str, params: dict) -> bool:
                """权限检查回调：允许安全的系统操作（Phase 2 升级）"""
                
                # Phase 2: 首先使用新的安全检查
                decision = security_check(operation, params, strict_mode=True)
                
                if decision == SecurityDecision.DENY:
                    return False
                
                # 允许 multiprocessing 和 threading 导入（标准库）
                if operation == 'plugin_load' and params.get('module') in ('multiprocessing', 'threading'):
                    return True
                
                # 允许 nanobot --version 命令（获取版本信息）
                if operation == 'shell_execute':
                    command = params.get('command', '')
                    if 'nanobot --version' in command or 'nanobotProjects' in command:
                        return True
                
                # 允许 .nanobot 工作区的文件操作
                if operation in ('file_read', 'file_write'):
                    file_path = params.get('path', '')
                    nanobot_workspace = str(WORKSPACE)
                    nanobot_home = str(Path.home() / '.nanobot')
                    
                    # 允许访问 .nanobot 目录下的所有文件
                    if file_path.startswith(nanobot_workspace) or file_path.startswith(nanobot_home):
                        # 但排除敏感文件
                        sensitive = ['.ssh', '.gnupg', '.netrc', '.pgpass', 'credentials', 'secrets', '.env']
                        if not any(s in file_path for s in sensitive):
                            return True
                
                # 其他操作默认拒绝（可扩展集成 PermissionManager）
                return False
            
            set_permission_check(_permission_check_callback)
            
            if not is_interceptors_installed():
                print("🔒 安装安全拦截器...")
                install_interceptors(
                    intercept_subprocess=True,
                    intercept_os=True,
                    intercept_eval_exec=True,
                    intercept_open=True,
                    intercept_import=True,
                )
                print("✅ 安全拦截器已安装")
        except ImportError as e:
            print(f"⚠️ 安全拦截器模块导入失败: {e}")
            if enforce_security:
                print("❌ NANOBOT_ENFORCE_SECURITY=1 但安全模块不可用，退出")
                import sys
                sys.exit(1)
    else:
        print("⚠️ 安全拦截器未启用 (NANOBOT_ENFORCE_SECURITY != 1)")
    
    SHUTDOWN_EVENT = {"in_progress": False, "active_requests": 0}
    
    def signal_handler(signum, frame):
        """信号处理：优雅关闭"""
        print(f"\n🛑 收到关闭信号 ({signum})...")
        SHUTDOWN_EVENT["in_progress"] = True
        
        # 等待活跃请求完成
        timeout = 10
        start = time.time()
        while SHUTDOWN_EVENT["active_requests"] > 0 and (time.time() - start) < timeout:
            print(f"⏳ 等待 {SHUTDOWN_EVENT['active_requests']} 个活跃请求完成...")
            time.sleep(0.5)
        
        print("✅ 优雅关闭完成")
        import sys
        sys.exit(0)
    
    # 注册信号处理
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)
    
    # ========== 🚀 Phase 1: 初始化全局单例 ==========
    initialize_global_singletons()
    
    # ========== 🚀 Phase 1: 日志级别优化（融合 claw）==========
    log_level = os.environ.get('NANOBOT_LOG_LEVEL', 'WARNING').upper()
    logging.basicConfig(
        level=getattr(logging, log_level, logging.WARNING),
        format='%(asctime)s [%(levelname)s] %(name)s: %(message)s'
    )
    # 抑制第三方库的 INFO 日志
    logging.getLogger('httpx').setLevel(logging.WARNING)
    logging.getLogger('httpcore').setLevel(logging.WARNING)
    logging.getLogger('LiteLLM').setLevel(logging.WARNING)
    logging.getLogger('urllib3').setLevel(logging.WARNING)
    print(f"📝 [Phase1] 日志级别设置为: {log_level}")
    
    print("=" * 50)
    print("🌐 Nanobot Web UI v3.2 (Phase1 Fusion)")
    print("=" * 50)
    print(f"📁 目录: {APP_DIR}")
    print(f"🐍 Python: {PYTHON}")
    print(f"🔗 http://localhost:8080")
    print("=" * 50)
    print("\n按 Ctrl+C 停止服务\n")
    
    # 多 worker 需要通过 CLI 启动，不能在 uvicorn.run() 中使用
    # 生产环境启动命令: uvicorn server_final:app --workers 4 --host 127.0.0.1 --port 8080
    # 当前使用单 worker 模式（适合开发），只监听本地
    uvicorn.run(app, host="127.0.0.1", port=8080)
